    protected void onDestroy(){if(uiResponsivenessMonitor!=null)uiResponsivenessMonitor.stop();
        if(localTableServer!=null)localTableServer.stop();
        if(activeCharonRequest!=null){activeCharonRequest.cancel();activeCharonRequest=null;}
        if(maintenance!=null)maintenance.stop();
        if(isFinishing()){if(narrativeAudio!=null)narrativeAudio.stopAll();try{stopService(new Intent(this,AudioPlaybackService.class));}catch(Exception e){AppLog.w("MainActivity","Falha ao encerrar serviço de áudio.",e);}}
        nativeTtsInitGeneration++;
        if(nativeTts!=null){nativeTts.stop();nativeTts.shutdown();}
        if(narrativeAudio!=null)narrativeAudio.shutdown();
        if(smartAudio!=null)smartAudio.shutdown();
        if(audioDiagnostics!=null)audioDiagnostics.shutdown();
        if(audio!=null)audio.shutdown();
        if(taskQueue!=null)taskQueue.shutdown();
        if(mapView!=null)mapView.releaseResources();if(sceneHexMiniMapView!=null)sceneHexMiniMapView.releaseResources();AppLog.i("MainActivity","Activity destruída. finishing="+isFinishing());super.onDestroy();
    }
    private synchronized void ensureNativeTtsInitialized(){
        long now=System.currentTimeMillis();
        // FL Kokoro parity: do not tear down a heavy neural engine while OnInit is still pending.
        if(nativeTtsInitializing||(nativeTts!=null&&nativeTtsReady))return;
        if(nativeTtsInitAttempts>=3&&now-nativeTtsLastInitAt<30000L)return;
        nativeTtsLastInitAt=now;nativeTtsInitAttempts++;nativeTtsInitializing=true;
        String selected=AndroidTtsBackend.resolveSavedEngine(this,prefs);
        nativeTtsRequestedEnginePackage=selected==null?"":selected;
        try{
            if(nativeTts!=null){try{nativeTts.shutdown();}catch(Throwable ignored){AppLog.ignored("MainActivity","Falha tolerada ao trocar engine TTS.",ignored);}}
            nativeTtsReady=false;nativeTtsLanguageReady=false;nativeTtsActiveEnginePackage="";
            nativeTts=createNativeTts(nativeTtsRequestedEnginePackage);
        }catch(Throwable error){nativeTtsInitializing=false;nativeTts=null;nativeTtsReady=false;nativeTtsLanguageReady=false;AppLog.e("NativeTts","Não foi possível criar o mecanismo de voz Android.",error);}
    }

    private synchronized TextToSpeech createNativeTts(String requestedPackage){
        final String packageSnapshot=requestedPackage==null?"":requestedPackage.trim();
        final long generation=++nativeTtsInitGeneration;
        TextToSpeech.OnInitListener listener=new TextToSpeech.OnInitListener(){public void onInit(final int status){ui.post(new Runnable(){public void run(){handleNativeTtsInit(generation,packageSnapshot,status);}});}};
        return packageSnapshot.length()>0?new TextToSpeech(this,listener,packageSnapshot):new TextToSpeech(this,listener);
    }

    private synchronized void switchNativeTtsEngine(String packageName){
        String requested=packageName==null?"":packageName.trim();
        if(requested.length()==0)return;
        if(requested.equals(nativeTtsActiveEnginePackage)&&nativeTts!=null&&nativeTtsReady)return;
        prefs.edit().putString(AndroidTtsBackend.PREF_ENGINE_PACKAGE,requested).apply();
        nativeTtsRequestedEnginePackage=requested;nativeTtsRefreshAudioOnReady=true;nativeTtsInitAttempts=0;nativeTtsLastInitAt=0L;
        try{if(nativeTts!=null){nativeTts.stop();nativeTts.shutdown();}}catch(Throwable ignored){AppLog.ignored("MainActivity","Falha tolerada ao encerrar engine TTS anterior.",ignored);}
        nativeTtsInitGeneration++;
        nativeTts=null;nativeTtsReady=false;nativeTtsInitializing=false;nativeTtsLanguageReady=false;nativeTtsActiveEnginePackage="";
        ensureNativeTtsInitialized();
    }

    private boolean isNativeKokoroEngine(){
        String pkg=nativeTtsActiveEnginePackage.length()>0?nativeTtsActiveEnginePackage:nativeTtsRequestedEnginePackage;
        return AndroidTtsBackend.isKokoroPackage(pkg);
    }

    public void onInit(int status){handleNativeTtsInit(nativeTtsInitGeneration,nativeTtsRequestedEnginePackage,status);}

    /* package */ synchronized void handleNativeTtsInit(final long generation,final String requestedPackage,int status){
        if(generation!=nativeTtsInitGeneration||!requestedPackage.equals(nativeTtsRequestedEnginePackage)){AppLog.i("NativeTts","Callback de inicialização obsoleto ignorado para "+requestedPackage+" • geração "+generation);return;}
        nativeTtsInitializing=false;
        if(nativeTts==null&&status==TextToSpeech.SUCCESS){try{nativeTts=createNativeTts(requestedPackage);}catch(Throwable ignored){}}
        nativeTtsReady=status==TextToSpeech.SUCCESS && nativeTts!=null;
        nativeTtsLanguageReady=false;
        if(!nativeTtsReady){
            setStatus("A voz do Android não pôde ser iniciada. Uma nova tentativa será feita sem travar o app.");
            if(activeFallbackSession!=-1L){abortNativeNarrationAfterTtsError("A voz do Android não pôde ser iniciada.");}
            final int attempt=nativeTtsInitAttempts;final long failedGeneration=generation;if(attempt<3&&ui!=null)ui.postDelayed(new Runnable(){public void run(){if(failedGeneration==nativeTtsInitGeneration)ensureNativeTtsInitialized();}},3800L);
            return;
        }
        if(requestedPackage.length()>0)nativeTtsActiveEnginePackage=requestedPackage;
        else{try{nativeTtsActiveEnginePackage=nativeTts.getDefaultEngine();}catch(Throwable ignored){nativeTtsActiveEnginePackage="";}}
        if(nativeTtsActiveEnginePackage==null)nativeTtsActiveEnginePackage="";
        if(nativeTtsActiveEnginePackage.length()>0)prefs.edit().putString(AndroidTtsBackend.PREF_ENGINE_PACKAGE,nativeTtsActiveEnginePackage).apply();

        int languageResult=TextToSpeech.LANG_NOT_SUPPORTED;
        try{languageResult=nativeTts.setLanguage(new Locale("pt","BR"));}catch(Throwable error){AppLog.w("NativeTts","Falha ao selecionar pt-BR.",error);}
        nativeTtsLanguageReady=languageResult!=TextToSpeech.LANG_MISSING_DATA&&languageResult!=TextToSpeech.LANG_NOT_SUPPORTED;
        if(!nativeTtsLanguageReady&&!isNativeKokoroEngine()){
            try{languageResult=nativeTts.setLanguage(new Locale("pt"));nativeTtsLanguageReady=languageResult!=TextToSpeech.LANG_MISSING_DATA&&languageResult!=TextToSpeech.LANG_NOT_SUPPORTED;}catch(Throwable ignored){AppLog.ignored("MainActivity","Falha tolerada ao selecionar idioma TTS.",ignored);}
        }
        // Sherpa/Kokoro fornece as vozes reais pelo próprio TextToSpeech.voices;
        // setLanguage pode não refletir o modelo instalado e não deve invalidar o backend neural.
        if(isNativeKokoroEngine()&&!AndroidTtsBackend.realVoices(nativeTts).isEmpty())nativeTtsLanguageReady=true;
        if(!nativeTtsLanguageReady){
            setStatus("A engine TTS selecionada não oferece voz utilizável em português.");
            if(activeFallbackSession!=-1L){abortNativeNarrationAfterTtsError("A engine TTS selecionada não oferece voz utilizável em português.");}
            return;
        }
        configureNativeTtsVoice();
        nativeTtsInitAttempts=0;
        if(nativeTts!=null){
            nativeUtteranceProgressListener = new UtteranceProgressListener(){
                public void onStart(final String id){ui.post(new Runnable(){public void run(){String sentence;synchronized(nativeVoiceSentenceByUtterance){sentence=nativeVoiceSentenceByUtterance.get(id);if(sentence!=null)nativeVoiceStartedUtterances.add(id);}if(sentence==null)return;if(narrativeAudio!=null)narrativeAudio.onNativeUtteranceStart(id,sentence,Build.VERSION.SDK_INT>=26);if(id.equals("narracao_"+nativeNarrationSession+"_0"))setStatus((isNativeKokoroEngine()?"Braseiro Kokoro PT-BR":"Voz do Android")+" narrando • áudio inteligente sincronizado.");}});}
                public void onRangeStart(final String id,final int start,final int end,final int frame){ui.post(new Runnable(){public void run(){String sentence;synchronized(nativeVoiceSentenceByUtterance){sentence=nativeVoiceSentenceByUtterance.get(id);}if(sentence==null)return;if(narrativeAudio!=null)narrativeAudio.onNativeRange(id,sentence,start,end);}});}
                public void onDone(final String id){ui.post(new Runnable(){public void run(){String completed;synchronized(nativeVoiceSentenceByUtterance){completed=nativeVoiceSentenceByUtterance.remove(id);nativeVoiceStartedUtterances.remove(id);if(completed!=null)nativeVoicePendingChunks=Math.max(0,nativeNarrationQueue.size()-nativeNarrationQueueIndex-1);}if(completed==null)return;if(narrativeAudio!=null)narrativeAudio.onUtteranceDone(id);nativeNarrationQueueIndex++;if(nativeNarrationQueueIndex>=nativeNarrationQueue.size()){finishNativeNarration();}else if(isNativeKokoroEngine()){speakNextNativeNarrationChunk();}else{long pause=narrativePauseMs(nativeChapterStartIndexes.contains(nativeNarrationQueueIndex));ui.postDelayed(new Runnable(){public void run(){speakNextNativeNarrationChunk();}},pause);}}});}
                public void onError(final String id){ui.post(new Runnable(){public void run(){String failed;synchronized(nativeVoiceSentenceByUtterance){failed=nativeVoiceSentenceByUtterance.remove(id);nativeVoiceStartedUtterances.remove(id);}if(failed==null)return;abortNativeNarrationAfterTtsError("A voz Android reportou erro. A narração foi interrompida neste trecho.");}});}
            };
            nativeTts.setOnUtteranceProgressListener(nativeUtteranceProgressListener);
        }
        final String pending=pendingRequestedNativeNarration;pendingRequestedNativeNarration="";
        if(nativeTtsRefreshAudioOnReady){nativeTtsRefreshAudioOnReady=false;if("Áudio".equals(currentScreen))ui.postDelayed(new Runnable(){public void run(){showAudio();}},100L);}
        if(pending.trim().length()>0){
            if(activeFallbackSession!=-1L){
                final long fallbackSession=activeFallbackSession;
                ui.post(new Runnable(){public void run(){
                    if(fallbackSession!=activeFallbackSession||fallbackSession!=charonNarrationGeneration)return;
                    continuePlaybackWithNativeTts(pending,fallbackSession,true);
                }});
            }else{
                ui.postDelayed(new Runnable(){public void run(){speakNativeNarrationWithSfx(pending);}},80L);
            }
        }
    }

    private void configureNativeTtsVoice(){
        if(nativeTts==null)return;
        try{
            String saved=AndroidTtsBackend.savedVoiceName(prefs,nativeTtsActiveEnginePackage);
            Voice selected=AndroidTtsBackend.findVoice(nativeTts,saved);
            if(selected==null)selected=AndroidTtsBackend.bestVoice(nativeTts);
            if(selected!=null){
                int result=nativeTts.setVoice(selected);
                if(result==TextToSpeech.SUCCESS)AndroidTtsBackend.persistVoice(prefs,nativeTtsActiveEnginePackage,selected.getName());
            }
            if(isNativeKokoroEngine()){nativeTts.setSpeechRate(1.00f);nativeTts.setPitch(1.00f);}
            else{nativeTts.setSpeechRate(NarrationPlaybackPolicy.ANDROID_SPEECH_RATE);nativeTts.setPitch(NarrationPlaybackPolicy.ANDROID_PITCH);}
            AppLog.i("NativeTts","Engine="+nativeTtsActiveEnginePackage+" • voz="+(selected==null?"padrão real":selected.getName())+" • neural="+isNativeKokoroEngine());
        }catch(Throwable error){AppLog.w("NativeTts","A seleção da voz real retornada pela engine falhou; mantendo a voz atual.",error);}
    }

    private boolean selectNativeTtsVoiceByName(String exactVoiceName){
        if(nativeTts==null||!nativeTtsReady)return false;
        try{
            Voice real=AndroidTtsBackend.findVoice(nativeTts,exactVoiceName);
            if(real==null)return false;
            int result=nativeTts.setVoice(real);
            if(result!=TextToSpeech.SUCCESS)return false;
            AndroidTtsBackend.persistVoice(prefs,nativeTtsActiveEnginePackage,real.getName());
            return true;
        }catch(Throwable error){AppLog.w("NativeTts","selectTtsVoice falhou sem propagar exceção Java.",error);return false;}
    }

    private float narrativeSpeechRate(){
        float base=NarrationPlaybackPolicy.ANDROID_SPEECH_RATE;JSONObject plan=lastAudioPlan==null?new JSONObject():lastAudioPlan;String delivery=plan.optString("delivery","normal").trim().toLowerCase(Locale.ROOT);int intensity=Math.max(0,Math.min(5,plan.optInt("intensity",1)));
        if("baixo".equals(delivery))return Math.max(0.72f,base*0.90f);
        if("calmo".equals(delivery))return Math.max(0.76f,base*0.94f);
        if("urgente".equals(delivery))return Math.min(1.28f,base*(1.03f+0.012f*intensity));
        return base;
    }
    private long narrativePauseMs(boolean chapter){
        JSONObject plan=lastAudioPlan==null?new JSONObject():lastAudioPlan;String profile=plan.optString("pause_profile","normal").trim().toLowerCase(Locale.ROOT);
        if("curto".equals(profile)||"curta".equals(profile))return chapter?260L:80L;
        if("longo".equals(profile)||"longa".equals(profile))return chapter?720L:260L;
        return chapter?420L:120L;
    }
    private void applyNativeNarrativeDelivery(){if(nativeTts==null||isNativeKokoroEngine())return;try{nativeTts.setSpeechRate(narrativeSpeechRate());nativeTts.setPitch(NarrationPlaybackPolicy.ANDROID_PITCH);}catch(Throwable error){AppLog.w("NativeTts","Falha ao aplicar direção narrativa de voz; mantendo o padrão.",error);}}

    private String startAudioServiceSafely(){
        // O serviço legado é encerrado uma única vez na criação da Activity. Fazer
        // stopService a cada PLAY executava trabalho de Binder na UI e causava ANR.
        return "";
    }

    /**
     * Lê a chave Gemini exclusivamente do armazenamento cifrado.
     * O método havia sido removido por engano na refatoração do áudio 3.7.0,
     * embora oito fluxos da Activity ainda dependessem dele.
     */
    private String geminiKey(){
        return secrets==null?"":secrets.get("gemini_key");
    }
    private String geminiPaidKey(){
        return secrets==null?"":secrets.get("gemini_paid_key");
    }

    /** Grava as duas chaves como uma única alteração lógica e restaura o estado anterior em qualquer falha. */
    private boolean saveGeminiSecretsAtomically(String primary,String paid){
        if(secrets==null)return false;
        String oldPrimary=geminiKey(),oldPaid=geminiPaidKey();
        if(!secrets.put("gemini_key",primary))return false;
        if(secrets.put("gemini_paid_key",paid))return true;
        boolean rollbackPrimary=secrets.put("gemini_key",oldPrimary);
        boolean rollbackPaid=secrets.put("gemini_paid_key",oldPaid);
        AppLog.e("SecureSecretStore","A chave alternativa falhou; o estado anterior foi restaurado="+(rollbackPrimary&&rollbackPaid),null);
        return false;
    }

    /**
     * Migra apenas preferências legadas e idempotentes.
     * Não toca no banco da campanha, nos mapas, nos manuais ou na biblioteca de áudio.
     */
    private void migrateLegacyModels(){
        String textModel=prefs.getString("text_model","").trim();
        String imageModel=prefs.getString("image_model","").trim();
        SharedPreferences.Editor edit=null;

        // Nunca substitua silenciosamente um modelo que o usuário digitou. Builds antigas
        // tratavam todo gemini-2.5 como "legado" em TODA inicialização e podiam regravar a
        // preferência visível para gemini-3.5-flash-lite. A migração agora só fornece padrão
        // quando o campo realmente está vazio; qualquer nome explícito é tentado exatamente.
        if(textModel.length()==0){
            edit=prefs.edit();
            edit.putString("text_model","gemini-3.5-flash-lite");
        }

        // 6.2.8: havia uma preferência oculta narrator_text_model que podia ignorar o
        // modelo escolhido na tela de Configurações. O Narrador passa a obedecer exclusivamente
        // text_model; removemos o valor legado para que upgrades preservem a escolha visível.
        if(prefs.contains("narrator_text_model")){
            if(edit==null)edit=prefs.edit();
            edit.remove("narrator_text_model");
        }

        if(imageModel.length()==0){
            if(edit==null)edit=prefs.edit();
            edit.putString("image_model","gemini-3.1-flash-image");
        }

        if(!prefs.contains("sfx_multilayer_migrated")){
            if(edit==null)edit=prefs.edit();
            edit.putInt("sfx_global_gap_seconds",3)
                    .putBoolean("sfx_multilayer_migrated",true);
        }

        // 6.0.1 — temas passam a ser independentes por mundo.
        if(!prefs.contains("theme_mode_dnd")){
            if(edit==null)edit=prefs.edit();
            edit.putString("theme_mode_dnd",prefs.getString("theme_mode","classic"));
        }
        if(!prefs.contains("theme_mode_mystara")){
            if(edit==null)edit=prefs.edit();
            edit.putString("theme_mode_mystara","mystara_oldschool");
        }

        if(edit!=null)edit.apply();
    }

