    private void confirmExitStrixhavenToFaerun(){
        final StrixhavenAdventureProfile profile=strixhavenProfile();AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(profile.canGraduate()?"Concluir Strixhaven?":"Sair para Faerûn?")
                .setMessage(profile.canGraduate()?"Você está no Ano 4 • Semestre 2 e possui colégio. Pode se formar agora e continuar a MESMA campanha em Faerûn, preservando herói, relações, memória e Atlas. Também pode apenas sair temporariamente.":"O estado de Strixhaven será preservado. O Atlas de Faerûn será reativado exatamente com a posição, câmera, névoa e POIs que estavam salvos.")
                .setNegativeButton("FICAR EM STRIXHAVEN",null)
                .setPositiveButton(profile.canGraduate()?"FORMAR-SE E IR A FAERÛN":"ABRIR FAERÛN",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){boolean graduated=profile.canGraduate()&&profile.graduate();if(!graduated)profile.exitToFaerun();db.addAuditEvent("strixhaven",graduated?"Graduação concluída":"Saída para Faerûn",graduated?("Ex-aluno de "+profile.academicHistory().optString("college")):"Saída temporária; estado acadêmico preservado","{}",profile.academicHistory().toString(),true);screenCache.clear();screenCacheTime.clear();ensureBundledMapForProfileAsync(WORLD_DND);buildShell();currentScreen="Mapa";showMap();setStatus(graduated?"Graduação concluída. Faerûn reativado com o histórico de Strixhaven preservado.":"Faerûn reativado. Strixhaven foi preservada.");}});
        if(profile.canGraduate())b.setNeutralButton("SAIR TEMPORARIAMENTE",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){profile.exitToFaerun();screenCache.clear();screenCacheTime.clear();ensureBundledMapForProfileAsync(WORLD_DND);buildShell();currentScreen="Mapa";showMap();setStatus("Faerûn reativado; graduação ainda não concluída.");}});b.show();
    }

    private String strixhavenTemporalBarText(){
        JSONObject scene=db.getSceneState();
        int day=Math.max(1,scene.optInt("day_number",1));double hour=scene.optDouble("clock_hour",sceneHour(scene.optString("time_of_day","Manhã")));
        int hh=(int)Math.floor(hour),mm=(int)Math.round((hour-Math.floor(hour))*60d)%60;
        int elapsed=Math.max(0,scene.optInt("elapsed_minutes_total",0));int last=Math.max(0,scene.optInt("last_travel_minutes",0));
        StringBuilder out=new StringBuilder();out.append("DIA ").append(day).append(" • ").append(String.format(Locale.US,"%02d:%02d",hh,mm)).append(" • ").append(sceneTimeLabel(hour).toUpperCase(new Locale("pt","BR")));
        out.append("  ⏱ ").append(formatElapsedMinutes(elapsed));if(last>0)out.append(" • ÚLT. DESLOC. +").append(last).append(" min");
        return out.toString();
    }

    private static String formatElapsedMinutes(int total){
        int safe=Math.max(0,total),days=safe/1440,hours=(safe%1440)/60,minutes=safe%60;StringBuilder out=new StringBuilder();
        if(days>0)out.append(days).append(days==1?" dia":" dias");if(hours>0){if(out.length()>0)out.append(" ");out.append(hours).append("h");}if(minutes>0||out.length()==0){if(out.length()>0)out.append(" ");out.append(minutes).append("min");}return out.toString();
    }

    private void showStrixhavenFreeExploreDialog(final float x,final float y,final StrixhavenAdventureProfile profile){
        if(profile==null)return;if(db.getCombatState().optInt("running",0)==1){toast("Finalize ou saia do encontro tático antes de explorar o campus.");return;}
        final int minutes=estimateStrixhavenFreeTravelMinutes(profile,x,y);
        String message="Este ponto não é um POI catalogado. Você pode caminhar até ele e explorar livremente; os marcadores do mapa são atalhos para lugares conhecidos, não trilhos obrigatórios.\n\nDeslocamento estimado: "+minutes+" min. O tempo avançará no relógio da campanha.";
        new AlertDialog.Builder(this).setTitle("Explorar este ponto?").setMessage(message).setNegativeButton("CANCELAR",null).setPositiveButton("EXPLORAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){commitStrixhavenFreeTravel(x,y,profile,minutes);}}).show();
    }

    private int estimateStrixhavenFreeTravelMinutes(StrixhavenAdventureProfile profile,float x,float y){
        if(profile==null)return 5;float dx=x-profile.positionX(),dy=y-profile.positionY();double d=Math.sqrt(dx*dx+dy*dy);return Math.max(3,Math.min(30,3+(int)Math.round(d*34d)));
    }

    private void commitStrixhavenFreeTravel(final float x,final float y,final StrixhavenAdventureProfile profile,final int minutes){
        if(aiBusy){toast("Aguarde a narração atual antes de se deslocar.");return;}
        final String fromLabel=profile.currentPoiLabel().length()>0?profile.currentPoiLabel():profile.currentMapLabel();
        if(strixhavenCampusView!=null){strixhavenCampusView.select(x,y);strixhavenCampusView.animateTokenTo(x,y);setStatus("Explorando o campus…");ui.postDelayed(new Runnable(){public void run(){finishStrixhavenFreeTravel(x,y,profile,minutes,fromLabel);}},560L);}
        else finishStrixhavenFreeTravel(x,y,profile,minutes,fromLabel);
    }

    private void finishStrixhavenFreeTravel(float x,float y,StrixhavenAdventureProfile profile,int minutes,String fromLabel){
        advanceSceneHours(minutes/60d);profile.setPosition(profile.currentMapId(),x,y,"","");
        try{JSONObject scene=db.getSceneState();scene.put("location","Strixhaven • "+profile.currentMapLabel()+" • área explorada");scene.remove("hex_id");scene.put("strixhaven_map_id",profile.currentMapId());scene.remove("strixhaven_poi_id");scene.put("strixhaven_exploration_x",x);scene.put("strixhaven_exploration_y",y);scene.put("last_travel_minutes",minutes);scene.put("last_travel_from",fromLabel);scene.put("last_travel_to","área explorada em "+profile.currentMapLabel());scene.put("last_travel_kind","free_exploration");db.saveSceneState(StrixhavenSceneBoundary.enterNewLocation(scene));}catch(Exception ignored){AppLog.ignored("StrixhavenTravel","Falha tolerada ao salvar exploração livre.",ignored);}
        clearTravelSceneDisplay("área explorada em "+profile.currentMapLabel());
        db.addAuditEvent("strixhaven","Exploração livre",fromLabel+" → área não catalogada de "+profile.currentMapLabel()+" • "+minutes+" min","{}",profile.mapProjection().toString(),true);
        screenCache.remove("Mestre IA");screenCacheTime.remove("Mestre IA");showStrixhavenSession();
        if(db.getStoryState().optInt("started",0)==1&&!aiBusy){String arrival=profile.masterInstruction()+" EXPLORAÇÃO LIVRE CONFIRMADA PELO MAPA: o jogador caminhou por cerca de "+minutes+" minutos até um ponto NÃO CATALOGADO do mapa de "+profile.currentMapLabel()+". Narre o que é imediatamente perceptível em 1–3 parágrafos. Não invente um nome oficial para esse ponto e não trate um POI conhecido como destino se o jogador não o escolheu.";sendAi("Narrador",arrival);}
        else setStatus("Strixhaven • exploração livre • "+minutes+" min avançados.");
    }

    private void showStrixhavenDestinationDialog(final StrixhavenLocationCatalog.Hotspot hotspot,final StrixhavenAdventureProfile profile){
        if(hotspot==null)return;
        if(db.getCombatState().optInt("running",0)==1){toast("Finalize ou saia do encontro tático antes de atravessar o campus.");return;}
        StringBuilder message=new StringBuilder();message.append(hotspot.description);
        if(hotspot.college){
            if(profile.year()==1)message.append("\n\nAno 1: o programa é geral. Você pode visitar este colégio, mas a matrícula só será oferecida a partir do Ano 2.");
            else if(profile.hasCollege())message.append("\n\nColégio atual: ").append(profile.collegeLabel()).append(".");
            else message.append("\n\nA escolha de colégio está disponível neste ano.");
        }
        int minutes=estimateStrixhavenTravelMinutes(profile,hotspot);
        message.append("\n\nDeslocamento estimado pelo app: ").append(minutes).append(" min. Esta estimativa organiza o relógio da cena; não é uma regra mecânica inventada de D&D.");
        AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle(hotspot.label).setMessage(message.toString()).setNegativeButton("CANCELAR",null);
        if(hotspot.college&&profile.enrollmentAvailable()&&!profile.hasCollege()){
            builder.setNeutralButton("MATRICULAR-SE",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showStrixhavenEnrollmentConfirm(hotspot,profile);}});
        }
        builder.setPositiveButton(hotspot.targetMapId.length()>0?"VISITAR":"IR ATÉ AQUI",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){commitStrixhavenTravel(hotspot,profile);}});
        builder.show();
    }

    private void showStrixhavenEnrollmentConfirm(final StrixhavenLocationCatalog.Hotspot hotspot,final StrixhavenAdventureProfile profile){
        new AlertDialog.Builder(this).setTitle("Matricular-se em "+hotspot.label+"?")
                .setMessage("Esta escolha fica persistida na campanha. Visitar um colégio no primeiro ano nunca realiza matrícula automaticamente.")
                .setNegativeButton("CANCELAR",null)
                .setPositiveButton("MATRICULAR-SE",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){if(profile.enroll(hotspot.targetMapId)){db.addAuditEvent("strixhaven","Colégio escolhido",hotspot.label,"{}",profile.descriptor().toString(),true);toast("Matrícula registrada: "+hotspot.label+".");commitStrixhavenTravel(hotspot,profile);}else toast("A matrícula ainda não está disponível.");}})
                .show();
    }

    private int estimateStrixhavenTravelMinutes(StrixhavenAdventureProfile profile,StrixhavenLocationCatalog.Hotspot hotspot){
        if(profile==null||hotspot==null)return 10;
        float dx=hotspot.x-profile.positionX(),dy=hotspot.y-profile.positionY();double d=Math.sqrt(dx*dx+dy*dy);
        if(hotspot.targetMapId.length()>0)return Math.max(10,Math.min(30,10+(int)Math.round(d*30d)));
        return Math.max(5,Math.min(25,5+(int)Math.round(d*28d)));
    }

    private void commitStrixhavenTravel(final StrixhavenLocationCatalog.Hotspot hotspot,final StrixhavenAdventureProfile profile){
        if(aiBusy){toast("Aguarde a narração atual antes de se deslocar.");return;}
        final int minutes=estimateStrixhavenTravelMinutes(profile,hotspot);
        final String fromLabel=profile.currentPoiLabel().length()>0?profile.currentPoiLabel():profile.currentMapLabel();
        if(strixhavenCampusView!=null){
            strixhavenCampusView.select(hotspot.x,hotspot.y);
            strixhavenCampusView.animateTokenTo(hotspot.x,hotspot.y);
            setStatus("Caminhando até "+hotspot.label+"…");
            ui.postDelayed(new Runnable(){public void run(){finishStrixhavenTravel(hotspot,profile,minutes,fromLabel);}},560L);
        }else finishStrixhavenTravel(hotspot,profile,minutes,fromLabel);
    }

    private void finishStrixhavenTravel(final StrixhavenLocationCatalog.Hotspot hotspot,final StrixhavenAdventureProfile profile,final int minutes,final String fromLabel){
        advanceSceneHours(minutes/60d);
        if(hotspot.targetMapId.length()>0){
            // O token chega primeiro ao destino na visão geral; só depois o app
            // entra no mapa local. Assim o meeple realmente se move em vez de
            // parecer um teleporte entre telas.
            profile.setPosition("university",hotspot.x,hotspot.y,hotspot.id,hotspot.label);
            profile.setPosition(hotspot.targetMapId,.50f,.86f,"",hotspot.label);
        }else profile.setPosition(profile.currentMapId(),hotspot.x,hotspot.y,hotspot.id,hotspot.label);
        try{JSONObject scene=db.getSceneState();scene.put("location","Strixhaven • "+profile.currentMapLabel()+(profile.currentPoiLabel().length()>0?" • "+profile.currentPoiLabel():""));scene.remove("hex_id");scene.put("strixhaven_map_id",profile.currentMapId());scene.put("strixhaven_poi_id",profile.currentPoiId());scene.remove("strixhaven_exploration_x");scene.remove("strixhaven_exploration_y");scene.put("last_travel_minutes",minutes);scene.put("last_travel_from",fromLabel);scene.put("last_travel_to",profile.currentPoiLabel().length()>0?profile.currentPoiLabel():profile.currentMapLabel());scene.put("last_travel_kind","poi");db.saveSceneState(StrixhavenSceneBoundary.enterNewLocation(scene));}catch(Exception ignored){AppLog.ignored("StrixhavenTravel","Falha tolerada ao salvar posição narrativa.",ignored);}
        clearTravelSceneDisplay(profile.currentPoiLabel().length()>0?profile.currentPoiLabel():profile.currentMapLabel());
        db.addAuditEvent("strixhaven","Deslocamento no campus",fromLabel+" → "+(profile.currentPoiLabel().length()>0?profile.currentPoiLabel():profile.currentMapLabel())+" • "+minutes+" min","{}",profile.mapProjection().toString(),true);
        screenCache.remove("Mestre IA");screenCacheTime.remove("Mestre IA");
        showStrixhavenSession();
        if(db.getStoryState().optInt("started",0)==1&&!aiBusy){
            String arrival=profile.masterInstruction()+" DESLOCAMENTO CONFIRMADO PELO MAPA: o jogador saiu de "+fromLabel+" e chegou a "+(profile.currentPoiLabel().length()>0?profile.currentPoiLabel():profile.currentMapLabel())+" após cerca de "+minutes+" minutos de deslocamento do campus. Narre a chegada em 1–3 parágrafos, respeite horário/compromissos e NPCs persistentes, e não peça teste apenas por caminhar.";
            sendAi("Narrador",arrival);
        }else setStatus("Strixhaven • "+profile.currentMapLabel()+(profile.currentPoiLabel().length()>0?" • "+profile.currentPoiLabel():"")+" • "+minutes+" min avançados.");
    }

    private void beginAdventure(final boolean reset){
        if(adventureStartRunning||adventurePreflightRunning){toast("A nova aventura já está sendo preparada.");return;}
        adventurePreflightRunning=true;
        adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.VALIDATING,"Validando campanha, banco e Atlas");
        setStatus("Validando a campanha e o Atlas sem bloquear a interface…");
        final boolean strixhaven=isStrixhavenAdventure();
        AppExecutors.io().execute(new Runnable(){public void run(){
            int activeCount=0;String packageId="";boolean needsBundledMap=false;boolean databaseOk=true;boolean contractAtlas=false;List<JSONObject> candidates=new ArrayList<JSONObject>();Throwable failure=null;
            try{
                activeCount=db.listActiveCharacters().size();
                if(activeCount>0&&!strixhaven){
                    JSONObject state=db.getMapState();packageId=state.optString("map_package_id","");
                    if(packageId.length()==0)needsBundledMap=true;
                    else if(db.hasAtlasContractMetadata(packageId)&&!isAtlasContractRuntime(packageId))needsBundledMap=true;
                    else{
                        JSONObject startup=adventureStartupCoordinator.preflight(db);databaseOk=startup.optBoolean("database",true);
                        if(databaseOk){candidates=db.listAdventureStartHexes(packageId,"",1000);contractAtlas=isAtlasContractRuntime(packageId);}
                    }
                }
            }catch(Throwable error){failure=error;AppLog.e("AdventureStartup","Falha no preflight assíncrono da aventura.",error);}
            final int readyActiveCount=activeCount;final String readyPackageId=packageId;final boolean readyNeedsBundledMap=needsBundledMap;final boolean readyDatabaseOk=databaseOk;final boolean readyContractAtlas=contractAtlas;final List<JSONObject> readyCandidates=candidates;final Throwable readyFailure=failure;
            ui.post(new Runnable(){public void run(){
                adventurePreflightRunning=false;
                if(readyFailure!=null){adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.BLOCKED,safeMessage(readyFailure));setStatus("Não foi possível validar o início da aventura.");toast("Falha ao validar: "+safeMessage(readyFailure));return;}
                if(readyActiveCount==0){toast("Crie ou marque ao menos um herói como Em jogo.");navigate("Heróis");return;}
                if(strixhaven){launchStrixhavenAdventure(reset);return;}
                if(readyNeedsBundledMap){pendingAdventureStartFromMap=true;pendingAdventureStartReset=reset;ensureBundledMapForProfileAsync(activeWorldProfile());setStatus("Preparando o Atlas integrado automaticamente; depois toque no hex onde a aventura começará.");navigate("Mapa");return;}
                if(!readyDatabaseOk){toast("O banco local não passou na verificação de integridade.");return;}
                if(readyCandidates==null||readyCandidates.isEmpty()){recoverAtlasForAdventureStart(reset,readyPackageId);return;}
                final int startCandidateCount=readyCandidates.size();
                if(!canShowDialog()){launchAdventure(reset,"");return;}
                String startMessage=readyContractAtlas
                        ?"O Atlas oficial aceita qualquer hex existente, inclusive hex vazio. O sorteio usa uma amostra de "+startCandidateCount+" hexes do dataset e pode começar fora de cidades ou POIs. Você também pode escolher diretamente qualquer hex no Atlas."
                        :"Há "+startCandidateCount+" pontos narrativos aptos. O sorteio é ponderado e variável: cidades e vilas têm prioridade, mas portos, fortalezas, ruínas, masmorras, templos, cavernas, marcos e terrenos catalogados também podem ser escolhidos.";
                new AlertDialog.Builder(MainActivity.this)
                        .setTitle("Onde a aventura começa?")
                        .setMessage(startMessage)
                        .setNegativeButton("CANCELAR",null)
                        .setNeutralButton("ESCOLHER NO ATLAS",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){pendingAdventureStartFromMap=true;pendingAdventureStartReset=reset;navigate("Mapa");setStatus(readyContractAtlas?"Toque em qualquer hex válido do Atlas para iniciar.":"Toque em um local nomeado ou terreno catalogado para iniciar.");}})
                        .setPositiveButton("SORTEAR COM VARIEDADE",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){launchAdventure(reset,"");}})
                        .show();
            }});
        }});
    }

    private void showAdventureStartingScreen(String message){
        currentScreen="Mestre IA";navigationInProgress=false;lastSuccessfulScreen="Mestre IA";
        if(shellNavScroll!=null)shellNavScroll.setVisibility(View.VISIBLE);
        screenCache.remove("Mestre IA");screenCacheTime.remove("Mestre IA");
        if(content==null){setStatus(message);return;}
        content.removeAllViews();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER_HORIZONTAL);box.setPadding(dp(22),dp(34),dp(22),dp(34));
        TextView title=text(worldHeading("Mestre IA"),28,GOLD,true);title.setGravity(Gravity.CENTER);box.addView(title,new LinearLayout.LayoutParams(-1,-2));
        ProgressBar progress=new ProgressBar(this);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(54),dp(54));pp.setMargins(0,dp(28),0,dp(20));box.addView(progress,pp);
        adventureStartupMessage=text(message,15,TEXT,false);adventureStartupMessage.setGravity(Gravity.CENTER);adventureStartupMessage.setLineSpacing(0,1.16f);box.addView(adventureStartupMessage,new LinearLayout.LayoutParams(-1,-2));
        TextView hint=text("A interface continua disponível enquanto Atlas, regras e contexto são preparados em segundo plano.",12,MUTED,false);hint.setGravity(Gravity.CENTER);hint.setPadding(0,dp(16),0,0);box.addView(hint,new LinearLayout.LayoutParams(-1,-2));
        content.addView(box,new FrameLayout.LayoutParams(-1,-1));setStatus(message);
    }

    private void updateAdventureStartupMessage(String message){
        setStatus(message);if(adventureStartupMessage!=null&&"Mestre IA".equals(currentScreen))adventureStartupMessage.setText(message);
    }

    private void updateNarratorBusyUi(){
        try{if(narratorProgress!=null){narratorProgress.setVisibility(aiBusy?View.VISIBLE:View.GONE);ViewGroup.LayoutParams lp=narratorProgress.getLayoutParams();if(lp!=null){lp.height=aiBusy?dp(34):0;narratorProgress.setLayoutParams(lp);}}if(narratorInput!=null)narratorInput.setEnabled(!aiBusy);}catch(Throwable ignored){AppLog.ignored("MestreIA","Atualização leve do estado ocupado foi ignorada.",ignored);}
    }

    private void launchAdventure(final boolean reset,final String requestedHex){
        if(adventureStartRunning){toast("A nova aventura já está sendo preparada.");return;}
        adventureStartRunning=true;adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.LOCATION,"Definindo posição inicial no Atlas");pendingAdventureStartFromMap=false;cancelNarrationAudio();audio.stopSfx();audio.stopAmbience();audio.stopMusic();showAdventureStartingScreen("Definindo o local, consultando regras e preparando a primeira cena…");
        AppExecutors.io().execute(new Runnable(){public void run(){try{
            if(reset){safety.beforeDestructiveChange("começar uma nova aventura");db.clearStoryState();lastNarration="";lastVisualPrompt="";currentOptions=new JSONArray();pendingTest=new JSONObject();lastMasterSupport=new JSONObject();sharedImageUri=null;prefs.edit().remove(PREF_SCENE_IMAGE_URI).remove(PREF_SCENE_IMAGE_FINGERPRINT).remove(PREF_PENDING_IMAGE_FINGERPRINT).remove(PREF_RECENT_SCENE_OPTIONS).remove("last_master_support_json").apply();db.saveSceneOptionHistory("[]");db.addAuditEvent("campanha","Nova aventura iniciada","História anterior preservada em snapshot","{}","{}",true);}
            final JSONObject startingPoint=prepareAdventureStartingPoint(requestedHex);adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.RULES,"Recuperando regras para a abertura");final String startingHex=startingPoint.optString("hex_id","");
            if(reset)resetSceneClock();else initializeSceneClock();
            final JSONObject campaign=db.getCampaign();
            final String openingHistoryKey="recent_opening_archetypes_"+activeWorldProfile();
            final AdventureOpeningPlanner.Plan openingPlan=AdventureOpeningPlanner.choose(activeWorldProfile(),campaign.optString("name"),campaign.optString("tone"),startingHex,prefs.getString(openingHistoryKey,"[]"),prefs.getString("recent_opening_texts_"+activeWorldProfile(),"[]"),System.nanoTime());
            prefs.edit().putString(openingHistoryKey,AdventureOpeningPlanner.remember(prefs.getString(openingHistoryKey,"[]"),openingPlan.id)).apply();
            final String startContext=buildAdventureStartContext(startingPoint);
            final String opening=(isMystaraWorld()?"MUNDO ATIVO: MYSTARA. SISTEMA ATIVO: D&D Rules Cyclopedia/BECMI. Use CA descendente, cinco Jogadas de Proteção, iniciativa 1d6 por lado, classes clássicas e viagem por terreno. Não use mecânicas de D&D 5e. ":"")+startContext+"FOCO DE REGRAS PARA A ABERTURA: "+openingPlan.rulesFocus+". A CENA DEVE SER ANCORADA NAS PASSAGENS LOCAIS RECUPERADAS, sem impor teste ou consequência antes da primeira ação do jogador. INÍCIO AUTOMÁTICO — ABERTURA DE HISTÓRIA. "+openingPlan.instruction+" Todo personagem ou grupo visível, falante ou agente deve constar em scene_state.present_npcs. NPCs nomeados, persistentes ou individualmente relevantes também devem constar em npc_updates, com name, role, present=true e visual_description concreta. Figurantes sem nome próprio recebem apenas rótulo descritivo de cena, sem identidade inventada, com anonymous=true e transient=true; grupos podem usar count e não entram em npc_updates até se tornarem individualmente relevantes. Nunca deixe pessoas visíveis apenas no texto. As duas opções devem responder diretamente ao conflito, documento, pessoa, ameaça ou objetivo desta cena; nunca proponha travessia, porta, rastros ou investigação genérica se esses elementos não estiverem presentes.";
            ui.post(new Runnable(){public void run(){adventureStartRunning=false;String label=startingPoint.optString("start_location_name","");updateAdventureStartupMessage((label.length()>0?label+" • ":"")+"hex "+startingHex+" sorteado. Consultando o índice local de regras…");adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.RULES,"Consultando índice local e cache essencial");sendAi("Narrador",opening);}});
        }catch(final Exception e){ui.post(new Runnable(){public void run(){adventureStartRunning=false;adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.BLOCKED,String.valueOf(e.getMessage()));setStatus("Não foi possível preparar a aventura.");toast("Falha ao iniciar: "+String.valueOf(e.getMessage()));showCampaign();}});}}});
    }

    private boolean isEligibleAdventureStartHex(String hexId){
        if(hexId==null||hexId.trim().length()==0)return false;JSONObject state=db.getMapState();String packageId=state.optString("map_package_id","");
        if(packageId.length()==0)return false;
        // A seleção inicial depende do índice canônico, não da flag transitória
        // atlas_ready. Se metadados + hex persistido existem, o toque é válido;
        // o bootstrap pode reparar as flags em paralelo sem bloquear a aventura.
        if(db.hasAtlasContractMetadata(packageId))return db.isValidMapHex(packageId,hexId.trim());
        return db.isCatalogedAdventureStartHex(packageId,hexId.trim());
    }

    private JSONObject nearestCatalogedAdventureStart(String touchedHex){
        JSONObject state=db.getMapState();String packageId=state.optString("map_package_id","");if(packageId.length()==0)return new JSONObject();
        List<JSONObject> nearest=db.findNearestAdventureStartCandidates(packageId,touchedHex,1);return nearest.isEmpty()?new JSONObject():nearest.get(0);
    }

    /**
     * 6.2.9: recuperação automática do Atlas no início da aventura.
     * O jogador não deve conhecer versões de migração, estados internos do banco
     * ou precisar apertar um botão técnico para continuar jogando. Somente
     * posições verificáveis são reaplicadas e todo o trabalho pesado roda fora
     * da thread da interface.
     */
    private void recoverAtlasForAdventureStart(final boolean resetStart,final String packageId){
        if(adventureStartCatalogMigrationRunning){setStatus("Preparando o Atlas para a aventura…");return;}
        adventureStartCatalogMigrationRunning=true;
        setStatus("Preparando o Atlas automaticamente…");
        AppExecutors.io().execute(new Runnable(){public void run(){
            final boolean contractAtlas=isAtlasContractRuntime(packageId);
            final int seeded=contractAtlas?0:db.applyBundledResolvedLocations(packageId);
            final int migrated=contractAtlas?0:db.migrateConfirmedLocationPlacementsToPackage(packageId);
            final List<JSONObject> repaired=db.listAdventureStartHexes(packageId,"",1000);
            ui.post(new Runnable(){public void run(){
                adventureStartCatalogMigrationRunning=false;
                db.addAuditEvent("mapa","Recuperação automática do Atlas",seeded+" posições verificadas • "+migrated+" legadas confirmadas • "+repaired.size()+" pontos de abertura","{}","{}",true);
                if(!repaired.isEmpty()){
                    screenCache.remove("Mapa");screenCacheTime.remove("Mapa");
                    setStatus(contractAtlas?"Atlas pronto. Escolhendo um hex inicial válido…":"Atlas pronto. Escolhendo o ponto inicial…");
                    beginAdventure(resetStart);
                    return;
                }
                pendingAdventureStartFromMap=true;pendingAdventureStartReset=resetStart;
                setStatus(contractAtlas?"Escolha no Atlas qualquer hex válido para começar a aventura.":"Escolha no Atlas um ponto confirmado para começar a aventura.");
                if(!canShowDialog()){navigate("Mapa");return;}
                new AlertDialog.Builder(MainActivity.this)
                        .setTitle("Escolha o ponto inicial")
                        .setMessage(contractAtlas?"O Atlas não devolveu uma amostra de hexes válidos. Abra o Atlas e escolha diretamente um hex existente.":"Este mapa ainda não tem um local ou terreno confirmado para uma abertura automática. Abra o Atlas e escolha o ponto onde o grupo está.")
                        .setNegativeButton("CANCELAR",null)
                        .setPositiveButton("ABRIR ATLAS",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){navigate("Mapa");}})
                        .show();
            }});
        }});
    }

    private void explicitRepairAtlasForStartup(final boolean resetStart){
        if(adventureStartCatalogMigrationRunning){toast("O reparo do Atlas já está em execução.");return;}final String packageId=db.getMapState().optString("map_package_id","");if(packageId.length()==0){toast("Nenhum Atlas ativo.");return;}adventureStartCatalogMigrationRunning=true;setStatus("Reparando posições verificáveis do Atlas…");AppExecutors.io().execute(new Runnable(){public void run(){final boolean contractAtlas=isAtlasContractRuntime(packageId);final int seeded=contractAtlas?0:db.applyBundledResolvedLocations(packageId);final int migrated=contractAtlas?0:db.migrateConfirmedLocationPlacementsToPackage(packageId);final int after=db.countMapPositionedLocations(packageId);ui.post(new Runnable(){public void run(){adventureStartCatalogMigrationRunning=false;db.addAuditEvent("mapa","Reparo explícito do Atlas 5.0",seeded+" posições embarcadas • "+migrated+" legadas • "+after+" totais","{}","{}",true);setStatus("Atlas reparado: "+after+" locais posicionados.");beginAdventure(resetStart);}});}});
    }

    private void explicitRepairActiveAtlas(){
        if(adventureStartCatalogMigrationRunning){toast("O reparo do Atlas já está em execução.");return;}
        final String packageId=db.getMapState().optString("map_package_id","");if(packageId.length()==0){toast("Nenhum Atlas ativo.");return;}
        adventureStartCatalogMigrationRunning=true;setStatus("Reparando somente posições verificáveis do Atlas…");
        AppExecutors.io().execute(new Runnable(){public void run(){
            final int before=db.countMapPositionedLocations(packageId);
            final boolean contractAtlas=isAtlasContractRuntime(packageId);
            final int seeded=contractAtlas?0:db.applyBundledResolvedLocations(packageId);
            final int migrated=contractAtlas?0:db.migrateConfirmedLocationPlacementsToPackage(packageId);
            final int after=db.countMapPositionedLocations(packageId);
            ui.post(new Runnable(){public void run(){adventureStartCatalogMigrationRunning=false;screenCache.remove("Mapa");screenCacheTime.remove("Mapa");db.addAuditEvent("mapa","Reparo explícito do Atlas 5.0",before+" → "+after+" posições • "+seeded+" embarcadas verificadas • "+migrated+" legadas recuperadas","{}","{}",true);setStatus("Atlas reparado: "+after+" locais posicionados; nenhuma coordenada foi inventada.");if("Mapa".equals(currentScreen))showMap();}});
        }});
    }

    private String adventureStartPointLabel(JSONObject point){
        if(point==null||point.length()==0)return "hex do Atlas";
        String name=point.optString("start_location_name","").trim();String type=locationTypePt(point.optString("start_location_type","")).trim();String terrain=terrainPt(point.optString("terrain_primary","")).trim();String region=point.optString("start_region_name","").trim();String kind=point.optString("start_kind","");
        String label=name.length()>0?name:(region.length()>0?region:(terrain.length()>0?terrain:("empty_hex".equals(kind)?"hex sem POI":"hex do Atlas")));
        if(type.length()>0&&name.length()>0)label+=" — "+type;return label;
    }

    private void confirmCatalogedAdventureStart(final String chosenHex,final String touchedHex,final boolean resetStart){
        String packageId=db.getMapState().optString("map_package_id","");final boolean contractAtlas=isAtlasContractRuntime(packageId);final JSONObject point=db.describeCatalogedAdventureStart(packageId,chosenHex);if(point.length()==0){toast(contractAtlas?"O Atlas mudou; escolha outro hex.":"O catálogo mudou; escolha outro ponto.");return;}
        String label=adventureStartPointLabel(point);String message;
        if(contractAtlas)message=label+" • hex "+chosenHex+". Este hex existente no dataset será fixado como posição inicial, mesmo que não contenha cidade ou POI. Em seguida o aplicativo consultará as regras e escreverá a primeira cena ancorada na região/terreno realmente conhecidos.";
        else if(touchedHex!=null&&touchedHex.length()>0&&!touchedHex.equalsIgnoreCase(chosenHex))message="O hex "+touchedHex+" não possui conteúdo catalogado para uma abertura. O ponto catalogado mais próximo é "+label+", no hex "+chosenHex+". Iniciar ali?";
        else message=label+" • hex "+chosenHex+". Este ponto catalogado será fixado como início. Em seguida o aplicativo consultará as regras e escreverá a primeira cena ancorada nele.";
        new AlertDialog.Builder(MainActivity.this).setTitle("Iniciar neste ponto do Atlas?").setMessage(message).setNegativeButton("OUTRO PONTO",null).setNeutralButton("CANCELAR INÍCIO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){pendingAdventureStartFromMap=false;pendingAdventureStartReset=false;setStatus("Início da aventura cancelado.");}}).setPositiveButton("CONFIRMAR E INICIAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){pendingAdventureStartFromMap=false;pendingAdventureStartReset=false;launchAdventure(resetStart,chosenHex);}}).show();
    }

    private JSONObject prepareAdventureStartingPoint(String requestedHex)throws Exception{
        JSONObject state=db.getMapState();String packageId=state.optString("map_package_id","");if(packageId.length()==0)throw new IllegalStateException("Nenhum pacote de mapa está ativo.");
        boolean contractAtlas=isAtlasContractRuntime(packageId);int reconciledBundledLocations=contractAtlas?0:db.applyBundledResolvedLocations(packageId);if(reconciledBundledLocations>0)db.addAuditEvent("mapa","Posições canônicas reconciliadas antes da abertura",reconciledBundledLocations+" locais verificados reaplicados","{}","{}",true);
        String requested=requestedHex==null?"":requestedHex.trim();List<JSONObject> candidates=db.listAdventureStartHexes(packageId,"",1000);
        JSONObject chosen;
        if(requested.length()>0){chosen=db.describeCatalogedAdventureStart(packageId,requested);if(chosen.length()==0)throw new IllegalArgumentException(contractAtlas?"O hex "+requested+" não é um hex válido do Atlas ativo.":"O hex "+requested+" não contém cidade, local nomeado ou terreno catalogado para uma abertura.");try{chosen.put("selection_mode","manual");}catch(Exception ignored){AppLog.ignored("AdventureStart","Falha tolerada ao registrar modo de seleção.",ignored);}}
        else{
            if(candidates.isEmpty())throw new IllegalStateException(contractAtlas?"O Atlas ativo não devolveu nenhum hex válido do dataset.":"O Atlas ativo não possui cidade, local nomeado ou terreno catalogado com posição confirmada.");
            String historyKey="recent_adventure_start_points_"+activeWorldProfile();chosen=AdventureStartSelector.choose(candidates,prefs.getString(historyKey,"[]"),System.nanoTime()^UUID.randomUUID().getMostSignificantBits());if(chosen.length()==0)throw new IllegalStateException(contractAtlas?"O sorteio não encontrou um hex válido do Atlas.":"O sorteio não encontrou um ponto narrativo válido.");try{chosen.put("selection_mode","weighted_random");}catch(Exception ignored){AppLog.ignored("AdventureStart","Falha tolerada ao registrar modo de seleção.",ignored);}
            prefs.edit().putString(historyKey,AdventureStartSelector.remember(prefs.getString(historyKey,"[]"),chosen)).apply();
        }
        String hex=chosen.optString("hex_id","");if(hex.length()==0)throw new IllegalStateException("O Atlas devolveu um ponto inicial sem identidade.");String previous=state.optString("current_hex_id","");
        String reveals=new JSONObject().put("hexIds",new JSONArray().put(hex)).put("points",new JSONArray()).toString();
        if(contractAtlas){if(!commitAtlasCurrentHex(packageId,hex,"início confirmado da aventura"))throw new IllegalStateException("O Atlas não conseguiu persistir o hex inicial.");db.saveMapViewExtras(hex,state.optInt("overlay_visible",1)==1,reveals);}
        else db.saveMapPackageState(state.optString("image_uri"),state.optString("overlay_uri"),state.optString("manifest_json"),packageId,hex,state.optInt("overlay_visible",1)==1,reveals,state.optString("grid_type","Quadrada"),(float)state.optDouble("grid_size",64),state.optInt("fog_enabled",0)==1,(float)state.optDouble("token_x",.5),(float)state.optDouble("token_y",.5),(float)state.optDouble("scale",1),(float)state.optDouble("offset_x",0),(float)state.optDouble("offset_y",0));
        db.saveMapTravelState(true,"","[]","Jogador");prefs.edit().putString("last_adventure_start_hex_"+activeWorldProfile(),hex).apply();String label=chosen.optString("start_location_name",chosen.optString("terrain_primary","terreno catalogado"));db.addAuditEvent("mapa",requested.length()>0?"Ponto catalogado escolhido para nova aventura":"Ponto catalogado sorteado com variedade",previous+" → "+hex+" • "+label,"{}",chosen.toString(),true);return chosen;
    }

    private String buildAdventureStartContext(JSONObject point){
        String hex=point.optString("hex_id","");String kind=point.optString("start_kind","");JSONObject state=db.getMapState();String packageId=state.optString("map_package_id","");boolean contractAtlas=isAtlasContractRuntime(packageId);StringBuilder out=new StringBuilder(contractAtlas?"POSIÇÃO INICIAL CANÔNICA DO ATLAS: hex ":"PONTO INICIAL CATALOGADO DESTA AVENTURA: hex ").append(hex).append(". ");
        JSONObject hexRow=db.getRawMapHex(packageId,hex);boolean localWater=hasConfirmedWaterwayNear(packageId,hex);String hydro=confirmedWaterwayContext(packageId,hex);
        if("location".equals(kind)){
            String name=cleanJsonText(point.optString("start_location_name"),"Local catalogado"),type=locationTypePt(point.optString("start_location_type")),region=cleanJsonText(point.optString("start_location_region"),"");String description="";
            try{JSONObject raw=new JSONObject(point.optString("start_location_raw","{}"));description=cleanJsonText(raw.optString("description"),cleanJsonText(raw.optString("descricao_linha_1"),""));String second=cleanJsonText(raw.optString("descricao_linha_2"),"");if(second.length()>0)description+=(description.length()>0?" ":"")+second;}catch(Exception ignored){AppLog.ignored("AdventureStart","Descrição catalogada ausente.",ignored);}
            description=sanitizeCatalogGeography(description,localWater);
            out.append("LOCAL CANÔNICO NOMEADO: ").append(name).append("; categoria: ").append(type.length()>0?type:"ponto de interesse");if(region.length()>0)out.append("; região: ").append(region);out.append(". ");if(description.length()>0)out.append("REFERÊNCIA DO CATÁLOGO (LORE, NÃO GEOMETRIA LOCAL): ").append(promptTail(description,520)).append(". ");out.append("Use este local como âncora concreta da cena, sem deslocar o grupo para outra cidade ou hex. ");
        }else if(contractAtlas){
            List<JSONObject> areas=db.getMapAreasForHex(packageId,hex);String terrain=terrainPt(point.optString("terrain_primary",hexRow.optString("terrain_primary","")));
            if("empty_hex".equals(kind))out.append("HEX SEM POI CANÔNICO OBRIGATÓRIO: ausência de cidade/local oficial é válida e NÃO autoriza inventar assentamento. ");
            if(terrain.length()>0)out.append("TERRENO VISUAL DO DATASET: ").append(terrain).append(". É evidência cartográfica para ambientação, não autoridade mecânica automática. ");
            if(!areas.isEmpty()){out.append("REGIÕES MULTI-HEX: ");for(int i=0;i<areas.size();i++){if(i>0)out.append(", ");out.append(cleanJsonText(areas.get(i).optString("name"),"região"));}out.append(". ");}
            if(hexRow.optInt("road_present",0)==1)out.append("ESTRADA CARTOGRÁFICA PRESENTE neste hex; ela pode influenciar viagem, comércio e geração de mundo conforme as regras D&D. ");
            List<JSONObject> visiblePois=db.getVisibleAtlasPoisForHex(packageId,hex,false);boolean added=false;for(JSONObject poi:visiblePois){String name=cleanJsonText(poi.optString("name"),"");if(name.length()==0)continue;String source=poi.has("origin")?("procedural".equalsIgnoreCase(poi.optString("origin"))?"PROCEDURAL DESCOBERTO":"CAMPAIGN"):"CANONICAL";if(!added){out.append("POIS PÚBLICOS NO HEX: ");added=true;}else out.append("; ");out.append(source).append(" ").append(name); }if(added)out.append(". ");
            if(!added&&"empty_hex".equals(kind))out.append("Não há POI público conhecido neste hex; narre wilderness/região/terreno sem fabricar cidade. ");
        }else{
            String terrain=terrainPt(point.optString("terrain_primary",""));out.append("TERRENO CATALOGADO E CONFIRMADO: ").append(terrain.length()>0?terrain:"terreno revisado").append(". Construa a abertura a partir das condições reais desse terreno, das rotas e dos elementos cartográficos confirmados. ");
        }
        if(localWater)out.append("HIDROGRAFIA LOCAL EXPLICITAMENTE REGISTRADA: ").append(hydro.length()>0?hydro:"curso d'água registrado").append(". ");
        else if(contractAtlas)out.append("HIDROGRAFIA: o contrato do Atlas deste hex não declara curso d'água específico; não trate ausência de registro como prova de inexistência e não invente hidrografia local como fato. ");
        else out.append("HIDROGRAFIA LOCAL CONFIRMADA PELO ATLAS: NENHUMA no hex atual nem nos hexes adjacentes. NÃO mencione rio, riacho, córrego, canal, margem, cais, porto fluvial, travessia ou som de água como parte da cena local. ");
        out.append("PRECEDÊNCIA ESPACIAL OBRIGATÓRIA: posição canônica/hex > regiões e POIs públicos do Atlas > descrição histórica do catálogo > conhecimento geral do modelo. Câmera, busca e pan nunca movem o grupo. ");
        out.append(contractAtlas?"A seleção automática escolheu somente entre hexes existentes no dataset; hex vazio é válido. ":"A seleção automática foi aleatória e ponderada entre os pontos válidos, com redução de repetição por hex, tipo e região. ");
        return out.toString();
    }

    private boolean hasConfirmedWaterwayNear(String packageId,String hexId){return confirmedWaterwayContext(packageId,hexId).length()>0;}
    private String confirmedWaterwayContext(String packageId,String hexId){
        if(packageId==null||packageId.length()==0||hexId==null||hexId.length()==0)return "";LinkedHashSet<String> found=new LinkedHashSet<String>();ArrayList<String> ids=new ArrayList<String>();ids.add(hexId);JSONObject state=db.getMapState();MapManifestGeometry geometry=mapGeometryFromState(state);List<String> neighbors=isAtlasContractRuntime(packageId)?db.getMapHexNeighbors(packageId,hexId):(geometry==null?flatTopNeighbors(hexId,295,165):geometry.neighbors(hexId));ids.addAll(neighbors);
        for(String id:ids){JSONObject hex=db.getMapHex(packageId,id);if(hex.length()==0||!isReliableMapHex(hex))continue;try{JSONArray routes=new JSONArray(hex.optString("waterways_json","[]"));for(int i=0;i<routes.length();i++){Object raw=routes.opt(i);if(raw instanceof JSONObject){JSONObject route=(JSONObject)raw;if(route.optBoolean("needsReview",false))continue;String status=cleanJsonText(route.optString("status"),"").toLowerCase(Locale.US);if(status.contains("review")||status.contains("candidate")||status.contains("approx"))continue;String name=cleanJsonText(route.optString("name"),"");String kind=routeKindPt(cleanJsonText(route.optString("kind"),""));String label=name.length()>0?name:kind;if(label.length()>0)found.add(label+" ["+id+"]");}else{String label=cleanJsonText(String.valueOf(raw),"");if(label.length()>0&&!"null".equalsIgnoreCase(label))found.add(label+" ["+id+"]");}}}catch(Exception ignored){AppLog.ignored("AdventureStart","Hidrografia local inválida.",ignored);}}
        StringBuilder b=new StringBuilder();for(String item:found){if(b.length()>0)b.append(", ");b.append(item);if(b.length()>280)break;}return b.toString();
    }
    private String sanitizeCatalogGeography(String description,boolean localWater){
        String d=cleanJsonText(description,"");if(d.length()==0||localWater)return d;StringBuilder keep=new StringBuilder();for(String sentence:d.split("(?<=[.!?])\\s+")){String n=sentence.toLowerCase(new Locale("pt","BR"));boolean hydro=n.matches(".*\\b(rio|rios|riacho|riachos|c[oó]rrego|c[oó]rregos|canal|canais|margem|margens|costa|costeiro|costeira|lago|lagos|mar|mares|delta|estu[aá]rio|porto|portos|doca|docas|navega[cç][aã]o|chionthar)\\b.*");if(hydro)continue;if(keep.length()>0)keep.append(' ');keep.append(sentence.trim());}return cleanJsonText(keep.toString(),"");
    }



