    private JSONObject mystaraSheet(JSONObject ch){
        try{String raw=ch==null?"":ch.optString("sheet_json","");if(raw.trim().startsWith("{")){JSONObject o=new JSONObject(raw);if(MystaraRulesEngine.SYSTEM_ID.equals(o.optString("system")))return mystaraRules.normalize(o);}}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
        try{JSONObject o=new JSONObject();o.put("system",MystaraRulesEngine.SYSTEM_ID);o.put("name",ch.optString("name","Aventureiro"));o.put("species",ch.optString("species","Humano"));o.put("class_name",ch.optString("class_name","Guerreiro"));o.put("level",ch.optInt("level",1));o.put("alignment","Neutro");o.put("str",ch.optInt("str",10));o.put("dex",ch.optInt("dex",10));o.put("con",ch.optInt("con",10));o.put("int_score",ch.optInt("int_score",10));o.put("wis",ch.optInt("wis",10));o.put("cha",ch.optInt("cha",10));o.put("hp",ch.optInt("hp",1));o.put("max_hp",ch.optInt("max_hp",1));o.put("armor",mystaraRules.defaultArmor(o.optString("class_name")));o.put("shield",mystaraRules.defaultShield(o.optString("class_name")));o.put("equipment",ch.optString("equipment"));o.put("spells",ch.optString("spells"));o.put("notes",ch.optString("notes"));return mystaraRules.normalize(o);}catch(Exception e){return new JSONObject();}
    }

