            Button view=smallButton("FICHA",GOLD);view.setTextColor(Color.BLACK);Button token=smallButton("TOKEN",GREEN);Button export=smallButton("JSON",PANEL2);Button edit=smallButton("EDITAR",PANEL2);Button damage=smallButton("− PV",RED);Button heal=smallButton("+ PV",GREEN);Button del=smallButton("EXCLUIR",RED);
            view.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showMystaraCharacterSheetDialogRc(record);}});token.setOnClickListener(new View.OnClickListener(){public void onClick(View v){selectPendingTokenCharacter(id);navigate("Tokens");}});export.setOnClickListener(new View.OnClickListener(){public void onClick(View v){beginCharacterExport(mystaraExportSheet(record),record.optInt("active",1)==1);}});edit.setOnClickListener(new View.OnClickListener(){public void onClick(View v){mystaraCharacterDialog(record,null);}});damage.setOnClickListener(new View.OnClickListener(){public void onClick(View v){numberDialog("Dano","Pontos de dano",new NumberAction(){public void run(int n){db.adjustCharacterHp(id,-n);showMystaraHeroes();}});}});heal.setOnClickListener(new View.OnClickListener(){public void onClick(View v){numberDialog("Cura","Pontos recuperados",new NumberAction(){public void run(int n){db.adjustCharacterHp(id,n);showMystaraHeroes();}});}});del.setOnClickListener(new View.OnClickListener(){public void onClick(View v){confirm("Excluir "+record.optString("name")+"?",new Runnable(){public void run(){try{safety.beforeDestructiveChange("excluir aventureiro de Mystara");}catch(Exception e){toast("Exclusão bloqueada: "+e.getMessage());return;}db.deleteCharacter(id);showMystaraHeroes();}});}});
            LinearLayout primaryActions=new LinearLayout(this);primaryActions.setOrientation(LinearLayout.HORIZONTAL);primaryActions.setPadding(0,dp(8),0,0);primaryActions.addView(view,new LinearLayout.LayoutParams(0,dp(46),1));primaryActions.addView(token,new LinearLayout.LayoutParams(0,dp(46),1));primaryActions.addView(export,new LinearLayout.LayoutParams(0,dp(46),1));primaryActions.addView(edit,new LinearLayout.LayoutParams(0,dp(46),1));c.addView(primaryActions);
