    private static final class MystaraFormRefs{EditText name,level,formerClericLevel,str,intel,wis,dex,con,cha,hp,maxHp,xp,gold,encumbrance,equipment,spells,notes;Spinner cls,alignment,armor;CheckBox shield,active;TextView ruleInfo,skillsInfo,masteryInfo;JSONArray skills=new JSONArray(),mastery=new JSONArray();}
    private EditText mystaraStepper(LinearLayout parent,String label,int value,int min,int max){
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(7),dp(6),dp(7),dp(6));box.setBackground(makeBg(PANEL,CARD_STROKE,8));box.addView(text(label,12,GOLD,true));
        LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER);final EditText e=input(label,String.valueOf(value),false);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);e.setGravity(Gravity.CENTER);Button minus=smallButton("−",PANEL2),plus=smallButton("+",PANEL2);minus.setOnClickListener(new View.OnClickListener(){public void onClick(View v){e.setText(String.valueOf(Math.max(min,num(e,value)-1)));}});plus.setOnClickListener(new View.OnClickListener(){public void onClick(View v){e.setText(String.valueOf(Math.min(max,num(e,value)+1)));}});row.addView(minus,new LinearLayout.LayoutParams(dp(62),dp(50)));row.addView(e,new LinearLayout.LayoutParams(0,dp(50),1));row.addView(plus,new LinearLayout.LayoutParams(dp(62),dp(50)));box.addView(row);
        if(parent.getOrientation()==LinearLayout.VERTICAL)parent.addView(box,new LinearLayout.LayoutParams(-1,-2));else parent.addView(box,new LinearLayout.LayoutParams(0,-2,1));return e;
    }

    private JSONArray copyJsonArray(JSONArray src){try{return src==null?new JSONArray():new JSONArray(src.toString());}catch(Exception e){return new JSONArray();}}
    private void refreshMystaraSelections(MystaraFormRefs f){if(f==null)return;if(f.skillsInfo!=null)f.skillsInfo.setText(f.skills==null||f.skills.length()==0?"Nenhuma perícia selecionada.":mystaraRules.joinJsonArray(f.skills));if(f.masteryInfo!=null)f.masteryInfo.setText(f.mastery==null||f.mastery.length()==0?"Nenhuma especialização registrada.":mystaraRules.masteryDisplay(f.mastery));}
    private int mystaraMasteryCost(JSONArray arr,String cls){if(arr==null)return 0;boolean semi="Anão".equals(cls)||"Elfo".equals(cls)||"Halfling".equals(cls);int sum=0;for(int i=0;i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o==null)continue;int idx=Math.max(1,Arrays.asList(MystaraRulesEngine.MASTERY_LEVELS).indexOf(o.optString("level","Básico")));sum+=semi?Math.max(0,idx-1):idx;}return sum;}
    private void chooseMystaraSkills(final MystaraFormRefs f){final String[] all=MystaraRulesEngine.GENERAL_SKILLS;final boolean[] checked=new boolean[all.length];for(int i=0;i<all.length;i++)for(int j=0;j<f.skills.length();j++)if(all[i].equals(f.skills.optString(j)))checked[i]=true;new AlertDialog.Builder(this).setTitle("Perícias gerais — selecione as lacunas").setMultiChoiceItems(all,checked,new DialogInterface.OnMultiChoiceClickListener(){public void onClick(DialogInterface d,int which,boolean value){checked[which]=value;}}).setNegativeButton("Cancelar",null).setPositiveButton("APLICAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){JSONArray a=new JSONArray();for(int i=0;i<all.length;i++)if(checked[i])a.put(all[i]);f.skills=a;refreshMystaraSelections(f);updateMystaraFormRules(f);}}).show();}
    private void chooseMystaraWeaponMastery(final MystaraFormRefs f){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),0,dp(12),0);final Spinner weapon=spinner(MystaraRulesEngine.WEAPONS,MystaraRulesEngine.WEAPONS[0]);final Spinner level=spinner(MystaraRulesEngine.MASTERY_LEVELS,"Básico");box.addView(cardWithLabel("ARMA E ESTILO",weapon));box.addView(cardWithLabel("NÍVEL DE ESPECIALIZAÇÃO",level));new AlertDialog.Builder(this).setTitle("Especialização em arma").setView(box).setNegativeButton("Cancelar",null).setNeutralButton("REMOVER ARMA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){String name=String.valueOf(weapon.getSelectedItem());JSONArray a=new JSONArray();for(int i=0;i<f.mastery.length();i++){JSONObject o=f.mastery.optJSONObject(i);if(o!=null&&!name.equals(o.optString("weapon")))a.put(o);}f.mastery=a;refreshMystaraSelections(f);updateMystaraFormRules(f);}}).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){String name=String.valueOf(weapon.getSelectedItem()),lv=String.valueOf(level.getSelectedItem());JSONArray a=new JSONArray();for(int i=0;i<f.mastery.length();i++){JSONObject o=f.mastery.optJSONObject(i);if(o!=null&&!name.equals(o.optString("weapon")))a.put(o);}try{a.put(new JSONObject().put("weapon",name).put("level",lv));}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}f.mastery=a;refreshMystaraSelections(f);updateMystaraFormRules(f);}}).show();}

