        addCharacterFormSection(form,"3. PONTOS DE VIDA, OURO E EQUIPAMENTO");LinearLayout hp=new LinearLayout(this);hp.setOrientation(LinearLayout.VERTICAL);f.hp=mystaraStepper(hp,"PV ATUAL",initial.optInt("hp",1),0,999);f.maxHp=mystaraStepper(hp,"PV MÁXIMO",initial.optInt("max_hp",1),1,999);form.addView(hp);Button rollHp=button("ROLAR PV PELO DADO DE VIDA DA CLASSE",PANEL2);rollHp.setOnClickListener(new View.OnClickListener(){public void onClick(View v){String cls=String.valueOf(f.cls.getSelectedItem());int rolled=Math.max(1,mystaraRules.rollDie(mystaraRules.hitDie(cls))+mystaraRules.abilityModifier(num(f.con,10)));f.maxHp.setText(String.valueOf(rolled));f.hp.setText(String.valueOf(rolled));updateMystaraFormRules(f);}});form.addView(rollHp);f.armor=spinner(MystaraRulesEngine.ARMORS,initial.optString("armor",mystaraRules.defaultArmor(initial.optString("class_name"))));form.addView(cardWithLabel("ARMADURA — OPÇÕES ILEGAIS SÃO BLOQUEADAS AO SALVAR",f.armor));f.shield=check("Usa escudo",initial.optBoolean("shield",false));form.addView(f.shield);LinearLayout money=new LinearLayout(this);money.setOrientation(LinearLayout.VERTICAL);f.gold=mystaraStepper(money,"OURO INICIAL (po)",initial.optInt("gold",0),0,999999);f.encumbrance=mystaraStepper(money,"CARGA TOTAL (mos)",initial.optInt("encumbrance_mos",0),0,9999);form.addView(money);Button rollGold=button("ROLAR OURO — 3d6 × 10",PANEL2);rollGold.setOnClickListener(new View.OnClickListener(){public void onClick(View v){f.gold.setText(String.valueOf(mystaraRules.roll3d6()*10));}});form.addView(rollGold);f.equipment=labeledField(form,"Equipamento",initial.optString("equipment"),true);Button equipment=button("APLICAR PACOTE LEGAL DA CLASSE",PANEL2);equipment.setOnClickListener(new View.OnClickListener(){public void onClick(View v){String cls=String.valueOf(f.cls.getSelectedItem()),armor=String.valueOf(f.armor.getSelectedItem());f.equipment.setText(mystaraRules.defaultEquipment(cls,armor,f.shield.isChecked(),num(f.gold,0)));}});