        if(prefs.getBoolean("mystara_optional_skills",true)){addCharacterFormSection(form,"4. PERÍCIAS GERAIS — REGRA OPCIONAL");f.skillsInfo=text("",13,TEXT,false);form.addView(f.skillsInfo);Button chooseSkills=button("SELECIONAR PERÍCIAS DENTRO DAS LACUNAS",PANEL2);chooseSkills.setOnClickListener(new View.OnClickListener(){public void onClick(View v){chooseMystaraSkills(f);}});form.addView(chooseSkills);}else f.skills=new JSONArray();
