    private String[] mystaraGroupPhaseLabels(int party,int enemies){
        if(party<=0&&enemies<=0)return new String[]{"0. Rolar iniciativa"};
        if(party==enemies)return new String[]{"0. Iniciativa simultânea","1. Ambos: Moral e proteções contínuas","2. Ambos: Movimento","3. Ambos: Combate à distância","4. Ambos: Magia","5. Ambos: Combate corpo a corpo","6. Resultados especiais"};
        String first=party>enemies?"Grupo":"Oponentes",second=party>enemies?"Oponentes":"Grupo";
        return new String[]{"0. Iniciativa resolvida","1. "+first+": Moral e proteções contínuas","2. "+first+": Movimento","3. "+first+": Combate à distância","4. "+first+": Magia","5. "+first+": Combate corpo a corpo","6. "+second+": Moral e proteções contínuas","7. "+second+": Movimento","8. "+second+": Combate à distância","9. "+second+": Magia","10. "+second+": Combate corpo a corpo","11. Resultados especiais"};
    }

    private static final class MystaraInitiativeEntry{final JSONObject combatant;int primary;MystaraInitiativeEntry(JSONObject c){combatant=c;}}
    private void rollMystaraIndividualInitiative(int round){List<JSONObject> combatants=db.listCombatants();if(combatants.isEmpty()){toast("Adicione os combatentes primeiro.");return;}ArrayList<MystaraInitiativeEntry> pending=new ArrayList<MystaraInitiativeEntry>();for(JSONObject c:combatants)pending.add(new MystaraInitiativeEntry(c));ArrayList<MystaraInitiativeEntry> ordered=new ArrayList<MystaraInitiativeEntry>();resolveMystaraInitiativeTies(pending,ordered,0);for(int i=0;i<ordered.size();i++){MystaraInitiativeEntry e=ordered.get(i);db.updateMystaraIndividualInitiative(e.combatant.optLong("id"),ordered.size()-i,e.primary);}db.beginMystaraIndividualRound(round);toast("Iniciativa individual resolvida; empates foram rolados novamente.");}
    private void resolveMystaraInitiativeTies(List<MystaraInitiativeEntry> group,List<MystaraInitiativeEntry> ordered,int depth){if(group.size()<=1){ordered.addAll(group);return;}if(depth>64){Collections.sort(group,new Comparator<MystaraInitiativeEntry>(){public int compare(MystaraInitiativeEntry a,MystaraInitiativeEntry b){return Long.compare(a.combatant.optLong("id"),b.combatant.optLong("id"));}});ordered.addAll(group);return;}ArrayList<MystaraInitiativeEntry>[] buckets=new ArrayList[7];for(int i=1;i<=6;i++)buckets[i]=new ArrayList<MystaraInitiativeEntry>();for(MystaraInitiativeEntry e:group){int roll=mystaraRules.rollDie(6);if(depth==0)e.primary=roll;buckets[roll].add(e);}for(int roll=6;roll>=1;roll--){if(buckets[roll].size()==1)ordered.add(buckets[roll].get(0));else if(buckets[roll].size()>1)resolveMystaraInitiativeTies(buckets[roll],ordered,depth+1);}}

