        new AlertDialog.Builder(this).setTitle("Adicionar monstro ou PNJ — Rules Cyclopedia").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("Adicionar",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){JSONObject state=db.getCombatState();int init=prefs.getBoolean("mystara_individual_initiative",false)?0:state.optInt("enemy_initiative",0);long id=db.addCombatant(name.getText().toString(),init,num(hp,1),num(hp,1),num(ac,9),"",false);db.setCombatRunning(true);try{JSONObject resources=new JSONObject();resources.put("morale",Math.max(2,Math.min(12,num(morale,7))));resources.put("hit_dice",value(hitDice));resources.put("attacks",value(attacks));db.updateCombatantAdvanced(id,0,"",false,0,0,"","[]","","","",resources.toString());}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}showMystaraCombat();}}).show();
