        addSheetSection(body,"SALVAGUARDAS",s.optString("saving_throws"));addSheetSection(body,"PERÍCIAS",s.optString("skills"));addSheetSection(body,"SENTIDOS PASSIVOS",s.optString("passive_senses"));addSheetSection(body,"IDIOMAS",s.optString("languages"));addSheetSection(body,"PROFICIÊNCIAS E FERRAMENTAS",s.optString("proficiencies")+"\nFerramentas: "+s.optString("tools")+"\nCarga: "+s.optString("carrying_capacity"));
