    private String[] xanatharAbilityOptions(String feat){String n=mechanicNorm(feat);if(n.equals("agachamento agil"))return new String[]{"Força","Destreza"};if(n.equals("chamas de phlegethos"))return new String[]{"Inteligência","Carisma"};if(n.equals("constituicao infernal")||n.equals("fortitude ana"))return new String[]{"Constituição"};if(n.equals("couro de dragao")||n.equals("temor draconico"))return new String[]{"Força","Constituição","Carisma"};if(n.equals("desvanecer"))return new String[]{"Destreza","Inteligência"};if(n.equals("furia orc"))return new String[]{"Força","Constituição"};if(n.equals("precisao elfica"))return new String[]{"Destreza","Inteligência","Sabedoria","Carisma"};if(n.equals("segunda chance"))return new String[]{"Constituição","Carisma"};if(n.equals("teleporte das fadas"))return new String[]{"Inteligência","Carisma"};return new String[0];}

    private EditText abilityField(CharacterFormRefs f,String ability){String n=mechanicNorm(ability);if(n.equals("forca"))return f.str;if(n.equals("destreza"))return f.dex;if(n.equals("constituicao"))return f.con;if(n.equals("inteligencia"))return f.intel;if(n.equals("sabedoria"))return f.wis;if(n.equals("carisma"))return f.cha;return null;}
    private void moveFeatAbilityBonus(CharacterFormRefs f,String oldAbility,String newAbility){if(oldAbility!=null&&oldAbility.length()>0&&!mechanicNorm(oldAbility).equals(mechanicNorm(newAbility))){EditText old=abilityField(f,oldAbility);if(old!=null)old.setText(String.valueOf(Math.max(1,num(old,10)-1)));}if(newAbility!=null&&newAbility.length()>0&&!mechanicNorm(oldAbility).equals(mechanicNorm(newAbility))){EditText now=abilityField(f,newAbility);if(now!=null)now.setText(String.valueOf(Math.min(20,num(now,10)+1)));}}

    private void showXanatharFeatConfigurator(final CharacterFormRefs f,final String profile,final String feat){
        final JSONObject root=featSelectionRoot(value(f.featChoicesJson));JSONArray list=root.optJSONArray("xanathar");JSONObject previous=null;if(list!=null)for(int i=0;i<list.length();i++){JSONObject q=list.optJSONObject(i);if(q!=null&&mechanicNorm(q.optString("feat")).equals(mechanicNorm(feat))){previous=q;break;}}final JSONObject old=previous==null?new JSONObject():previous;final JSONObject oldChoices=old.optJSONObject("choices")==null?new JSONObject():old.optJSONObject("choices");
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(14),dp(8),dp(14),dp(16));box.addView(text(feat,15,GOLD,true));box.addView(text("Xanathar — escolhas são explícitas; nenhuma rolagem ou opção é decidida automaticamente.",12,MUTED,false));
        final String[] abilities=xanatharAbilityOptions(feat);final Spinner ability=abilities.length>0?spinner(abilities,oldChoices.optString("ability",abilities[0])):null;if(ability!=null)box.addView(ability);
        final Spinner skill=mechanicNorm(feat).equals("agachamento agil")?spinner(new String[]{"Acrobacia","Atletismo"},oldChoices.optString("skill","Acrobacia")):null;if(skill!=null)box.addView(skill);
        final EditText prodSkill=mechanicNorm(feat).equals("prodigio")?input("Perícia adquirida",oldChoices.optString("skill",""),false):null;if(prodSkill!=null)box.addView(prodSkill);
        final EditText prodTool=mechanicNorm(feat).equals("prodigio")?input("Ferramenta adquirida",oldChoices.optString("tool",""),false):null;if(prodTool!=null)box.addView(prodTool);
        final EditText prodLanguage=mechanicNorm(feat).equals("prodigio")?input("Idioma adquirido",oldChoices.optString("language",""),false):null;if(prodLanguage!=null)box.addView(prodLanguage);
        final EditText prodExpert=mechanicNorm(feat).equals("prodigio")?input("Perícia já proficiente para Especialização",oldChoices.optString("expertise_skill",""),false):null;if(prodExpert!=null)box.addView(prodExpert);
        final EditText druidCantrip=mechanicNorm(feat).equals("magia do elfo da floresta")?input("Truque de druida escolhido",oldChoices.optString("druid_cantrip",""),false):null;if(druidCantrip!=null)box.addView(druidCantrip);
        new AlertDialog.Builder(this).setTitle("Talento racial — Xanathar").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("APLICAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject choices=new JSONObject();String newAbility="";if(ability!=null){newAbility=String.valueOf(ability.getSelectedItem());choices.put("ability",newAbility).put("ability_applied_to_editor",true);}String lineage=root.optString("species_lineage","");if(lineage.length()>0)choices.put("lineage",lineage);if(skill!=null)choices.put("skill",String.valueOf(skill.getSelectedItem()));if(prodSkill!=null){if(value(prodSkill).length()==0||value(prodTool).length()==0||value(prodLanguage).length()==0||value(prodExpert).length()==0){toast("Prodígio exige perícia, ferramenta, idioma e perícia para Especialização.");return;}choices.put("skill",value(prodSkill)).put("tool",value(prodTool)).put("language",value(prodLanguage)).put("expertise_skill",value(prodExpert));}if(druidCantrip!=null){if(value(druidCantrip).length()==0){toast("Escolha o truque de druida.");return;}choices.put("druid_cantrip",value(druidCantrip));}
                String oldAbility=oldChoices.optString("ability","");if(abilities.length>0)moveFeatAbilityBonus(f,oldAbility,newAbility);
                JSONArray next=new JSONArray();JSONArray cur=root.optJSONArray("xanathar");if(cur!=null)for(int i=0;i<cur.length();i++){JSONObject q=cur.optJSONObject(i);if(q!=null&&!mechanicNorm(q.optString("feat")).equals(mechanicNorm(feat)))next.put(q);}next.put(new JSONObject().put("feat",feat).put("choices",choices));root.put("xanathar",next);f.featChoicesJson.setText(root.toString());rebuildSupplementFeatSummary(f,root);toast("Talento de Xanathar registrado e será aplicado ao salvar a ficha.");}catch(Exception e){toast("Não foi possível registrar o talento: "+e.getMessage());}}}).show();
    }

    private String voloFeatAbility(String feat){String n=mechanicNorm(feat);if(n.equals("windcaller"))return "Sabedoria";if(n.equals("piercing horns")||n.equals("oversized grip"))return "Força";if(n.equals("commander s shout"))return "Carisma";if(n.equals("master artisan"))return "Sabedoria";return "";}
    private void showVoloFeatConfigurator(final CharacterFormRefs f,final String feat){
        final JSONObject root=featSelectionRoot(value(f.featChoicesJson));JSONArray list=root.optJSONArray("volo");JSONObject previous=null;if(list!=null)for(int i=0;i<list.length();i++){JSONObject q=list.optJSONObject(i);if(q!=null&&mechanicNorm(q.optString("feat")).equals(mechanicNorm(feat))){previous=q;break;}}final JSONObject old=previous==null?new JSONObject():previous;final JSONObject oldChoices=old.optJSONObject("choices")==null?new JSONObject():old.optJSONObject("choices");
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(14),dp(8),dp(14),dp(16));box.addView(text(feat,15,GOLD,true));box.addView(text("Volo’s Complete Subrace Handbook — pré-requisito verificado pela espécie/nível. Nenhuma rolagem é feita automaticamente.",12,MUTED,false));
        final EditText artisan=mechanicNorm(feat).equals("master artisan")?input("Ferramenta de artesão escolhida",oldChoices.optString("artisan_tool",""),false):null;if(artisan!=null)box.addView(artisan);
        String fixed=voloFeatAbility(feat);if(fixed.length()>0)box.addView(text("Bônus fixo do talento: +1 "+fixed+".",12,TEXT,false));
        new AlertDialog.Builder(this).setTitle("Talento racial — Volo Handbook").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("APLICAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject choices=new JSONObject();if(artisan!=null){if(value(artisan).length()==0){toast("Escolha a ferramenta de artesão.");return;}choices.put("artisan_tool",value(artisan));}String ability=voloFeatAbility(feat);boolean already=oldChoices.optBoolean("ability_applied_to_editor",false);if(ability.length()>0){if(!already){EditText e=abilityField(f,ability);if(e!=null)e.setText(String.valueOf(Math.min(20,num(e,10)+1)));}choices.put("ability_applied_to_editor",true).put("fixed_ability",ability);}JSONArray next=new JSONArray();JSONArray cur=root.optJSONArray("volo");if(cur!=null)for(int i=0;i<cur.length();i++){JSONObject q=cur.optJSONObject(i);if(q!=null&&!mechanicNorm(q.optString("feat")).equals(mechanicNorm(feat)))next.put(q);}next.put(new JSONObject().put("feat",feat).put("choices",choices));root.put("volo",next);f.featChoicesJson.setText(root.toString());rebuildSupplementFeatSummary(f,root);toast("Talento do Volo Handbook registrado e será aplicado ao salvar a ficha.");}catch(Exception e){toast("Não foi possível registrar o talento: "+e.getMessage());}}}).show();
    }

    private void showRun141FeatConfigurator(final CharacterFormRefs f,final String feat){
        final JSONObject root=featSelectionRoot(value(f.featChoicesJson));JSONArray list=root.optJSONArray("run141");JSONObject previous=null;if(list!=null)for(int i=0;i<list.length();i++){JSONObject q=list.optJSONObject(i);if(q!=null&&mechanicNorm(q.optString("feat")).equals(mechanicNorm(feat))){previous=q;break;}}final JSONObject old=previous==null?new JSONObject():previous;final JSONObject oldChoices=old.optJSONObject("choices")==null?new JSONObject():old.optJSONObject("choices");
        final String[] abilities={"Força","Constituição","Carisma"};LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(14),dp(8),dp(14),dp(16));box.addView(text(feat,15,GOLD,true));box.addView(text("Talento racial de Meio-Dragão — escolha explicitamente o atributo +1. O app não escolhe nem rola resultados.",12,MUTED,false));final Spinner ability=spinner(abilities,oldChoices.optString("ability","Força"));box.addView(ability);
        new AlertDialog.Builder(this).setTitle("Talento racial — Meio-Dragão").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("APLICAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{String newAbility=String.valueOf(ability.getSelectedItem()),oldAbility=oldChoices.optString("ability","");boolean already=oldChoices.optBoolean("ability_applied_to_editor",false);if(already)moveFeatAbilityBonus(f,oldAbility,newAbility);else{EditText e=abilityField(f,newAbility);if(e!=null)e.setText(String.valueOf(Math.min(20,num(e,10)+1)));}JSONObject choices=new JSONObject().put("ability",newAbility).put("ability_applied_to_editor",true);JSONArray next=new JSONArray();JSONArray cur=root.optJSONArray("run141");if(cur!=null)for(int i=0;i<cur.length();i++){JSONObject q=cur.optJSONObject(i);if(q!=null&&!mechanicNorm(q.optString("feat")).equals(mechanicNorm(feat)))next.put(q);}next.put(new JSONObject().put("feat",feat).put("choices",choices));root.put("run141",next);f.featChoicesJson.setText(root.toString());rebuildSupplementFeatSummary(f,root);toast("Talento de Meio-Dragão registrado.");}catch(Exception e){toast("Não foi possível registrar o talento: "+e.getMessage());}}}).show();
    }

    private void rebuildSupplementFeatSummary(CharacterFormRefs f,JSONObject root){StringBuilder b=new StringBuilder();JSONObject s=root.optJSONObject("strixhaven");if(s!=null){b.append("Strixhaven Initiate");if(s.optBoolean("mascot",false))b.append("\nStrixhaven Mascot");}JSONArray x=root.optJSONArray("xanathar");if(x!=null)for(int i=0;i<x.length();i++){JSONObject q=x.optJSONObject(i);if(q==null)continue;if(b.length()>0)b.append("\n");b.append(q.optString("feat"));}JSONArray v=root.optJSONArray("volo");if(v!=null)for(int i=0;i<v.length();i++){JSONObject q=v.optJSONObject(i);if(q==null)continue;if(b.length()>0)b.append("\n");b.append(q.optString("feat"));}JSONArray q141=root.optJSONArray("run141");if(q141!=null)for(int i=0;i<q141.length();i++){JSONObject q=q141.optJSONObject(i);if(q==null)continue;if(b.length()>0)b.append("\n");b.append(q.optString("feat"));}JSONObject r=root.optJSONObject("run136");if(r!=null){JSONObject bg=r.optJSONObject("origin_feat_background");if(bg!=null){if(b.length()>0)b.append("\n");b.append(bg.optString("feat"));}JSONObject hu=r.optJSONObject("origin_feat_human");if(hu!=null){if(b.length()>0)b.append("\n");b.append(hu.optString("feat"));}}f.feats.setText(b.toString());}

    private void applyCrossBookFeatChoices(JSONObject o,String raw){
        if(o==null||raw==null||raw.trim().isEmpty())return;try{JSONObject root=featSelectionRoot(raw);if(root.has("species_lineage"))o.put("species_lineage",root.optString("species_lineage"));JSONObject cfg=root.optJSONObject("strixhaven");if(cfg!=null){String locked=o.optString("strixhaven_initiate_college_locked","");String college=cfg.optString("college","");if(locked.length()==0||!mechanicNorm(locked).equals(mechanicNorm(college))){o.put("feat_validation_error","Strixhaven Initiate não foi aplicado: o colégio configurado não corresponde ao antecedente atual.");}else{JSONArray cantrips=new JSONArray().put(cfg.optString("cantrip1")).put(cfg.optString("cantrip2"));JSONObject applied=CrossBookFeatRuntimeEngine.applyInitiate(o,college,cantrips,cfg.optString("first_level_spell"),cfg.optString("ability"));if(!applied.optBoolean("ok",false))o.put("feat_validation_error",applied.optString("message"));else if(cfg.optBoolean("mascot",false)){JSONObject mascot=CrossBookFeatRuntimeEngine.applyMascot(o);if(!mascot.optBoolean("ok",false))o.put("feat_validation_error",mascot.optString("message"));}}}
            JSONArray xs=root.optJSONArray("xanathar");if(xs!=null)for(int i=0;i<xs.length();i++){JSONObject entry=xs.optJSONObject(i);if(entry==null)continue;JSONObject choices=entry.optJSONObject("choices");if(choices==null)choices=new JSONObject();JSONObject result=XanatharRacialFeatRuntimeEngine.applyFeat(o,entry.optString("feat"),choices);if(!result.optBoolean("ok",false))o.put("feat_validation_error","Xanathar — "+entry.optString("feat")+": "+result.optString("reason"));}
            JSONArray vs=root.optJSONArray("volo");if(vs!=null)for(int i=0;i<vs.length();i++){JSONObject entry=vs.optJSONObject(i);if(entry==null)continue;JSONObject choices=entry.optJSONObject("choices");if(choices==null)choices=new JSONObject();JSONObject result=VoloRacialFeatRuntimeEngine.applyFeat(o,entry.optString("feat"),choices);if(!result.optBoolean("volo_feat_apply_ok",false))o.put("feat_validation_error","Volo Handbook — "+entry.optString("feat")+": "+result.optString("volo_feat_apply_reason"));else o=result;}
            JSONArray r141=root.optJSONArray("run141");if(r141!=null)for(int i=0;i<r141.length();i++){JSONObject entry=r141.optJSONObject(i);if(entry==null)continue;JSONObject choices=entry.optJSONObject("choices");if(choices==null)choices=new JSONObject();JSONObject result=Run141CompactCharacterOptionEngine.applyFeat(o,entry.optString("feat"),choices);if(!result.optBoolean("run141_feat_apply_ok",false))o.put("feat_validation_error","Meio-Dragão — "+entry.optString("feat")+": "+result.optString("run141_feat_apply_reason"));else o=result;}
            o.put("feat_selection_json",root.toString());}catch(Exception e){try{o.put("feat_validation_error","Configuração de talento inválida: "+e.getMessage());}catch(Exception ignored){}}
    }


    private JSONObject run136Config(JSONObject root){try{JSONObject r=root.optJSONObject("run136");if(r==null){r=new JSONObject();root.put("run136",r);}return r;}catch(Exception e){return new JSONObject();}}
    private JSONObject captureAbilityScores(CharacterFormRefs f){JSONObject o=new JSONObject();try{o.put("Força",num(f.str,10)).put("Destreza",num(f.dex,10)).put("Constituição",num(f.con,10)).put("Inteligência",num(f.intel,10)).put("Sabedoria",num(f.wis,10)).put("Carisma",num(f.cha,10));}catch(Exception ignored){}return o;}
    private void restoreAbilityScores(CharacterFormRefs f,JSONObject base){if(base==null)return;for(String a:new String[]{"Força","Destreza","Constituição","Inteligência","Sabedoria","Carisma"}){EditText e=abilityField(f,a);if(e!=null&&base.has(a))e.setText(String.valueOf(base.optInt(a,num(e,10))));}}
    private void addEditorAbility(CharacterFormRefs f,String ability,int delta){EditText e=abilityField(f,ability);if(e!=null)e.setText(String.valueOf(Math.min(20,Math.max(1,num(e,10)+delta))));}

    private void showRun136CharacterOptionSelector(final CharacterFormRefs f,final String profile){
        ArrayList<String> opts=new ArrayList<String>();String species=String.valueOf(f.species.getSelectedItem()),bg=String.valueOf(f.background.getSelectedItem());
        if(rulesEngine.is2024(profile)){opts.add("Atributos do antecedente 2024 (+2/+1)");opts.add("Talento de Origem do antecedente — "+Core2024EberronCharacterEngine.originFeatForBackground(bg));String sn=mechanicNorm(species);if(sn.equals("aasimar")||sn.equals("draconato")||sn.equals("elfo")||sn.equals("gnomo")||sn.equals("golias")||sn.equals("humano")||sn.equals("tiefling")||sn.equals("tiferino"))opts.add("Configurar traços da espécie 2024 — "+species);if(sn.equals("humano"))opts.add("Talento de Origem adicional do Humano");}
        if(Core2024EberronCharacterEngine.isDragonmarkVariant(species))opts.add("Configurar dracossinal — "+species);
        if(mechanicNorm(bg).equals("agente das casas"))opts.add("Escolher Casa do Agente das Casas");
        if(opts.isEmpty()){toast("Nenhuma escolha 2024/Eberron pendente para esta ficha.");return;}final String[] arr=opts.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Opções 2024 / Eberron").setItems(arr,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){String x=arr[which];if(x.startsWith("Atributos")){show2024BackgroundAbilitySelector(f);return;}if(x.startsWith("Talento de Origem do antecedente")){showBackgroundOriginFeatConfigurator(f);return;}if(x.startsWith("Configurar traços")){show2024SpeciesConfigurator(f);return;}if(x.startsWith("Talento de Origem adicional")){showHumanExtraOriginFeatPicker(f);return;}if(x.startsWith("Configurar dracossinal")){showDragonmarkConfigurator(f);return;}if(x.startsWith("Escolher Casa")){showHouseAgentSelector(f);}}}).show();
    }

    private void show2024BackgroundAbilitySelector(final CharacterFormRefs f){
        final JSONObject root=featSelectionRoot(value(f.featChoicesJson)),r=run136Config(root);
        final JSONObject old=r.optJSONObject("origin_ability");
        final JSONArray allowed=Core2024EberronCharacterEngine.allowedBackgroundAbilities(String.valueOf(f.background.getSelectedItem()));
        final String[] abilities=new String[allowed.length()];for(int i=0;i<abilities.length;i++)abilities[i]=allowed.optString(i);
        if(abilities.length<2){toast("Antecedente sem opções de atributos disponíveis.");return;}
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);
        box.addView(text("Escolha +2 e +1 em dois atributos diferentes permitidos pelo antecedente.",12,MUTED,false));
        final Spinner plus2=spinner(abilities,old==null?abilities[0]:old.optString("plus2",abilities[0]));
        final Spinner plus1=spinner(abilities,old==null?abilities[1]:old.optString("plus1",abilities[1]));
        plus2.setContentDescription("Atributo +2 do antecedente");plus1.setContentDescription("Atributo +1 do antecedente");
        box.addView(cardWithLabel("+2",plus2));box.addView(cardWithLabel("+1",plus1));
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Atributos do antecedente 2024").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("APLICAR",null).create();
        showBoundDialog(dialog,new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            if(!dialog.isShowing())return;
            try{
                String p2=String.valueOf(plus2.getSelectedItem()),p1=String.valueOf(plus1.getSelectedItem());
                JSONObject candidate=new JSONObject().put("rules_source",DndRulesEngine.PROFILE_2024).put("background",String.valueOf(f.background.getSelectedItem()));
                JSONObject gate=Core2024EberronCharacterEngine.applyOriginAbilityChoice(candidate,p2,p1,true);
                if(!gate.optBoolean("ok",false)){toast(gate.optString("reason"));return;}
                JSONObject base=captureAbilityScores(f);
                if(old!=null&&old.optBoolean("applied_to_editor",false)){
                    String old2=old.optString("plus2"),old1=old.optString("plus1");
                    base.put(old2,base.optInt(old2,10)-2);base.put(old1,base.optInt(old1,10)-1);
                }
                if(base.optInt(p2,10)+2>20||base.optInt(p1,10)+1>20){toast("O bônus do antecedente não pode elevar um atributo acima de 20.");return;}
                restoreAbilityScores(f,base);addEditorAbility(f,p2,2);addEditorAbility(f,p1,1);
                r.put("origin_ability",new JSONObject().put("plus2",p2).put("plus1",p1).put("base_scores",base).put("applied_to_editor",true));
                root.put("run136",r);f.featChoicesJson.setText(root.toString());dialog.dismiss();
            }catch(Exception e){toast("Não foi possível registrar +2/+1: "+e.getMessage());}
        }});}});
    }

    private void showBackgroundOriginFeatConfigurator(final CharacterFormRefs f){String feat=Core2024EberronCharacterEngine.originFeatForBackground(String.valueOf(f.background.getSelectedItem()));showOriginFeatConfigurator(f,"origin_feat_background",feat,false);}
    private void showHumanExtraOriginFeatPicker(final CharacterFormRefs f){JSONArray a=Core2024EberronCharacterEngine.allOriginFeats();final String[] opts=new String[a.length()];for(int i=0;i<opts.length;i++)opts[i]=a.optString(i);new AlertDialog.Builder(this).setTitle("Talento de Origem adicional do Humano").setItems(opts,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){showOriginFeatConfigurator(f,"origin_feat_human",opts[which],true);}}).show();}

    private void showOriginFeatConfigurator(final CharacterFormRefs f,final String key,final String featLabel,boolean humanExtra){
        final JSONObject root=featSelectionRoot(value(f.featChoicesJson));final JSONObject r=run136Config(root);JSONObject previous=r.optJSONObject(key);final JSONObject old=previous==null?new JSONObject():previous;final String baseFeat=featLabel.contains(" (")?featLabel.substring(0,featLabel.indexOf(" (")):featLabel;
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(14),dp(8),dp(14),dp(16));box.addView(text(featLabel,15,GOLD,true));box.addView(text("Toda escolha é fornecida por você. O runtime só valida e aplica efeitos persistentes.",12,MUTED,false));
        final EditText t1,t2,t3,spell;final Spinner list,ability;
        String n=mechanicNorm(baseFeat);if(n.equals("artifista")){t1=input("Ferramenta de Artesão 1",old.optString("choice1",""),false);t2=input("Ferramenta de Artesão 2",old.optString("choice2",""),false);t3=input("Ferramenta de Artesão 3",old.optString("choice3",""),false);spell=null;list=null;ability=null;box.addView(t1);box.addView(t2);box.addView(t3);}else if(n.equals("habilidoso")){t1=input("Perícia ou ferramenta 1",old.optString("choice1",""),false);t2=input("Perícia ou ferramenta 2",old.optString("choice2",""),false);t3=input("Perícia ou ferramenta 3",old.optString("choice3",""),false);spell=null;list=null;ability=null;box.addView(t1);box.addView(t2);box.addView(t3);}else if(n.equals("musico")){t1=input("Instrumento 1",old.optString("choice1",""),false);t2=input("Instrumento 2",old.optString("choice2",""),false);t3=input("Instrumento 3",old.optString("choice3",""),false);spell=null;list=null;ability=null;box.addView(t1);box.addView(t2);box.addView(t3);}else if(n.equals("iniciado em magia")){String forced=featLabel.contains("Clérigo")?"Clérigo":featLabel.contains("Druida")?"Druida":featLabel.contains("Mago")?"Mago":"";String[] lists=forced.length()>0?new String[]{forced}:new String[]{"Clérigo","Druida","Mago"};list=spinner(lists,old.optString("list",lists[0]));ability=spinner(new String[]{"Inteligência","Sabedoria","Carisma"},old.optString("ability","Inteligência"));t1=input("Truque 1",old.optString("choice1",""),false);t2=input("Truque 2",old.optString("choice2",""),false);t3=null;spell=input("Magia de 1º círculo",old.optString("spell",""),false);box.addView(cardWithLabel("LISTA",list));box.addView(cardWithLabel("ATRIBUTO",ability));box.addView(t1);box.addView(t2);box.addView(spell);}else{t1=t2=t3=spell=null;list=ability=null;box.addView(text("Este talento não exige escolha adicional. Confirmar apenas registra o benefício; nenhuma rolagem é feita.",12,TEXT,false));}
        new AlertDialog.Builder(this).setTitle("Talento de Origem").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("REGISTRAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject cfg=new JSONObject().put("feat",featLabel);JSONObject choices=new JSONObject();if(t1!=null){if(value(t1).length()==0||value(t2).length()==0||(t3!=null&&value(t3).length()==0)){toast("Preencha todas as escolhas do talento.");return;}cfg.put("choice1",value(t1)).put("choice2",value(t2));if(t3!=null)cfg.put("choice3",value(t3));if(mechanicNorm(baseFeat).equals("artifista"))choices.put("tools",new JSONArray().put(value(t1)).put(value(t2)).put(value(t3)));else if(mechanicNorm(baseFeat).equals("habilidoso"))choices.put("proficiencies",new JSONArray().put(value(t1)).put(value(t2)).put(value(t3)));else if(mechanicNorm(baseFeat).equals("musico"))choices.put("instruments",new JSONArray().put(value(t1)).put(value(t2)).put(value(t3)));}if(list!=null){if(value(t1).length()==0||value(t2).length()==0||value(spell).length()==0){toast("Informe dois truques e a magia de 1º círculo.");return;}if(mechanicNorm(value(t1)).equals(mechanicNorm(value(t2)))){toast("Os dois truques precisam ser diferentes.");return;}cfg.put("list",String.valueOf(list.getSelectedItem())).put("ability",String.valueOf(ability.getSelectedItem())).put("spell",value(spell));choices.put("list",String.valueOf(list.getSelectedItem())).put("ability",String.valueOf(ability.getSelectedItem())).put("cantrips",new JSONArray().put(value(t1)).put(value(t2))).put("first_level_spell",value(spell));}cfg.put("choices",choices);r.put(key,cfg);root.put("run136",r);f.featChoicesJson.setText(root.toString());rebuildSupplementFeatSummary(f,root);toast("Talento de Origem registrado.");}catch(Exception e){toast("Não foi possível registrar o talento: "+e.getMessage());}}}).show();
    }

