    private int inventoryOptionIndex(String line,String[] options){
        String name=mechanicNorm(line.split("\\|",2)[0]);
        for(int i=0;i<options.length;i++)if(name.equals(mechanicNorm(options[i].split("\\|",2)[0])))return i;
        return -1;
    }
    private boolean inventoryContainsOption(String current,String option,String[] options){
        int expected=inventoryOptionIndex(option,options);
        for(String line:current.split("\n"))if(inventoryOptionIndex(line,options)==expected)return true;
        return false;
    }

    private void showInventorySelector(final CharacterFormRefs f){final String[] options={"Mochila | 1 | 2,5 kg | Geral","Saco de dormir | 1 | 3,5 kg | Viagem","Rações de viagem | 10 | 1 kg | Consumível","Cantil | 1 | 2 kg | Viagem","Corda de cânhamo (15 m) | 1 | 5 kg | Utilidade","Tochas | 10 | 0,5 kg | Consumível","Pederneira e isqueiro | 1 | 0,5 kg | Utilidade","Pé de cabra | 1 | 2,5 kg | Ferramenta","Kit de escalada | 1 | 6 kg | Ferramenta","Kit de curandeiro | 1 | 1,5 kg | Consumível","Kit de disfarce | 1 | 1,5 kg | Ferramenta","Kit de falsificação | 1 | 2,5 kg | Ferramenta","Ferramentas de ladrão | 1 | 0,5 kg | Ferramenta","Alaúde | 1 | 1 kg | Instrumento","Flauta | 1 | 0,5 kg | Instrumento","Símbolo sagrado | 1 | 0,5 kg | Foco","Foco arcano | 1 | 0,5 kg | Foco","Bolsa de componentes | 1 | 1 kg | Foco","Poção de cura | 1 | 0,25 kg | Consumível","Armadura de couro | 1 | 5 kg | Armadura • EQUIPADO","Cota de malha | 1 | 27,5 kg | Armadura • EQUIPADO","Escudo | 1 | 3 kg | Armadura • EQUIPADO","Adaga | 1 | 0,5 kg | Arma • EQUIPADO","Espada longa | 1 | 1,5 kg | Arma • EQUIPADO","Arco curto | 1 | 1 kg | Arma • EQUIPADO","Aljava com 20 flechas | 1 | 0,5 kg | Munição"};final boolean[] selected=new boolean[options.length];final String current=value(f.inventory);for(int i=0;i<options.length;i++)selected[i]=selectionContains(current,options[i].split(" \\|")[0]);showApplyDialog(new AlertDialog.Builder(this).setTitle("Selecionar inventário e equipamento").setMultiChoiceItems(options,selected,new DialogInterface.OnMultiChoiceClickListener(){public void onClick(DialogInterface d,int which,boolean checked){selected[which]=checked;}}).setNegativeButton("Cancelar",null).setPositiveButton("APLICAR",null),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){StringBuilder out=new StringBuilder();for(String line:current.split("\n")){int index=inventoryOptionIndex(line,options);if(index<0||selected[index]){if(out.length()>0)out.append("\n");out.append(line);}}for(int i=0;i<options.length;i++)if(selected[i]&&!inventoryContainsOption(current,options[i],options)){if(out.length()>0)out.append("\n");String[] p=options[i].split(" \\| ");out.append(p[0]).append(" | QTD ").append(p.length>1?p[1]:"1").append(" | PESO ").append(p.length>2?p[2]:"0 kg").append(" | ").append(p.length>3?p[3]:"Geral");}f.inventory.setText(out.toString());}});}

    /**
     * Normaliza os campos mecânicos sem modificar Views.
     *
     * A versão anterior chamava setText() em f.skills enquanto collectCharacterSheet()
     * era executado. O TextWatcher da matriz de perícias chamava collectCharacterSheet()
     * novamente, criando uma recursão no thread principal e fazendo o app parecer travado
     * ao tocar em GERAR/TROCAR, SELECIONAR ou nos losangos.
     */
    private void normalizeSelectableMechanics(CharacterFormRefs f,JSONObject o){
        int level=Math.max(1,Math.min(20,o.optInt("level",1)));
        String hit=level+"d"+rulesEngine.classHitDie(baseClass(o.optString("class_name")));
        boolean[] saves=new boolean[6];
        String[] abilities={"Força","Destreza","Constituição","Inteligência","Sabedoria","Carisma"};
        for(int i=0;i<abilities.length;i++)saves[i]=mechanicRank(value(f.savingThrows),abilities[i])>0;
        if(!value(f.savingThrows).contains("★")&&"Mago".equals(baseClass(o.optString("class_name")))){saves[3]=true;saves[4]=true;}
        int[] ranks=new int[skillNames().length];
        for(int i=0;i<ranks.length;i++)ranks[i]=mechanicRank(value(f.skills),skillNames()[i]);
        if(!value(f.skills).contains("★")&&!value(f.skills).contains("◈")){
            String prof=" "+mechanicNorm(o.optString("proficiencies"))+" ";String[] all=skillNames();
            for(int i=0;i<ranks.length;i++)if(prof.contains(" "+mechanicNorm(all[i])+" "))ranks[i]=1;
        }
        Character2024SheetReconciler.applySelections(o,saves,ranks,skillNames());
        String saving=renderSavingThrows(o,saves),skills=renderSkills(o,ranks),passive=renderPassiveSenses(o,skills);
        try{
            o.put("hit_dice",hit);
            o.put("saving_throws",saving);
            o.put("skills",skills);
            o.put("passive_senses",passive);
            o.put("languages",value(f.languages));
        }catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
    }
    private String renderSavingThrows(JSONObject o,boolean[] selected){String[] names={"Força","Destreza","Constituição","Inteligência","Sabedoria","Carisma"};int[] scores={o.optInt("str",10),o.optInt("dex",10),o.optInt("con",10),o.optInt("int_score",10),o.optInt("wis",10),o.optInt("cha",10)};int pb=rulesEngine.proficiencyBonus(o.optInt("level",1));StringBuilder out=new StringBuilder();for(int i=0;i<names.length;i++){if(out.length()>0)out.append(" • ");int bonus=rulesEngine.modifier(scores[i])+(selected[i]?pb:0);out.append(names[i]).append(' ').append(signedModifier(bonus));if(selected[i])out.append(" ★");}return out.toString();}
    private String renderSkills(JSONObject o,int[] ranks){String[] skills=skillNames();int pb=rulesEngine.proficiencyBonus(o.optInt("level",1));StringBuilder out=new StringBuilder();for(int i=0;i<skills.length;i++){if(out.length()>0)out.append(" • ");int rank=i<ranks.length?Math.max(0,Math.min(2,ranks[i])):0;int bonus=rulesEngine.modifier(skillAbilityScore(o,skills[i]))+rank*pb;out.append(skills[i]).append(' ').append(signedModifier(bonus));if(rank==2)out.append(" ◈");else if(rank==1)out.append(" ★");}return out.toString();}
    private String renderPassiveSenses(JSONObject o,String skills){int pb=rulesEngine.proficiencyBonus(o.optInt("level",1));int per=10+rulesEngine.modifier(o.optInt("wis",10))+mechanicRank(skills,"Percepção")*pb;int inv=10+rulesEngine.modifier(o.optInt("int_score",10))+mechanicRank(skills,"Investigação")*pb;int ins=10+rulesEngine.modifier(o.optInt("wis",10))+mechanicRank(skills,"Intuição")*pb;return "Percepção "+per+" • Investigação "+inv+" • Intuição "+ins;}
    private int skillAbilityScore(JSONObject o,String skill){String n=mechanicNorm(skill);if(n.contains("atletismo"))return o.optInt("str",10);if(n.contains("acrobacia")||n.contains("furtividade")||n.contains("prestidigitacao"))return o.optInt("dex",10);if(n.contains("arcanismo")||n.contains("historia")||n.contains("investigacao")||n.contains("natureza")||n.contains("religiao"))return o.optInt("int_score",10);if(n.contains("adestrar")||n.contains("intuicao")||n.contains("medicina")||n.contains("percepcao")||n.contains("sobrevivencia"))return o.optInt("wis",10);return o.optInt("cha",10);}
    private int mechanicRank(String list,String name){String needle=mechanicNorm(name);for(String part:(list==null?"":list).split("[•\\n]")){String n=mechanicNorm(part);if(!n.startsWith(needle+" ")&&!n.equals(needle))continue;if(part.contains("◈")||n.contains("especialidade")||n.contains("especializacao"))return 2;if(part.contains("★")||n.contains("proficiente"))return 1;return 0;}return 0;}
    private boolean mechanicContains(String list,String name){String needle=mechanicNorm(name);for(String part:(list==null?"":list).split("[,;•\\n]"))if(mechanicNorm(part).equals(needle))return true;return false;}
    private String mechanicNorm(String value){String n=java.text.Normalizer.normalize(value==null?"":value.toLowerCase(new Locale("pt","BR")),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","");return n.replaceAll("[^a-z0-9]+"," ").trim();}
    private String[] skillNames(){return new String[]{"Acrobacia","Adestrar Animais","Arcanismo","Atletismo","Atuação","Enganação","Furtividade","História","Intimidação","Intuição","Investigação","Medicina","Natureza","Percepção","Persuasão","Prestidigitação","Religião","Sobrevivência"};}

    private void requestCharacterAi(final CharacterFormRefs f,final String profile){final JSONObject base=characterGenerator.ensureComplete(collectCharacterSheet(f,profile));applyCharacterSeed(f,base);final String key=geminiKey().trim();if(key.length()<20){toast("A ficha foi completada localmente. Configure a chave Gemini para a IA enriquecer a personalidade e a história.");return;}if(aiQuotaGovernor!=null&&!aiQuotaGovernor.canCall()){toast("A ficha já foi completada localmente. O orçamento de IA de hoje foi preservado.");return;}setStatus("A IA está completando a ficha em uma chamada...");String system="BRAS_SINGLE_CALL. Você auxilia a criação de personagens de D&D. Todo conteúdo visível deve ser escrito obrigatoriamente em português do Brasil, mesmo que nomes de livros, tabelas ou termos recebidos estejam em inglês. Traduza termos comuns e mecânicos; preserve em inglês apenas nomes próprios indispensáveis, acompanhados de explicação em PT-BR. Preserve EXATAMENTE a espécie, classe, antecedente e perfil de regras recebidos. Não transforme um anão em humano ou elfo, não misture raízes de outra espécie e não invente bônus mecânicos. Responda somente JSON válido, sem markdown.";String prompt="Melhore apenas os campos narrativos desta ficha, mantendo total coerência e escrevendo tudo em PT-BR. Retorne um objeto JSON com: name, nickname, title, alignment, concept, role, appearance, personality, ideal, bond, fear, flaw, contact, rival, debt, motivation, class_entry, history, mannerisms, quotes, level_up. Não altere espécie, classe, antecedente, nível, atributos, PV, CA, ataques, magias ou inventário. Ficha base: "+base.toString();gemini.generateText(key,prefs.getString("text_model","gemini-3.5-flash-lite"),system,prompt,new GeminiService.TextCallback(){public void onSuccess(final String raw){ui.post(new Runnable(){public void run(){if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(system.length()+prompt.length(),raw==null?0:raw.length());JSONObject ai=parseLooseJson(raw);JSONObject merged=characterGenerator.mergeNarrativeAi(base,ai);applyCharacterSeed(f,merged);setStatus("Ficha completada pela IA em PT-BR.");toast("A IA completou os campos narrativos em PT-BR sem alterar a mecânica.");}});}public void onError(final String error){ui.post(new Runnable(){public void run(){if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(system.length()+prompt.length(),0);applyCharacterSeed(f,base);setStatus("Ficha completada localmente.");toast("A IA não respondeu; os campos foram preenchidos pelo gerador local.");}});}});}
    private JSONObject parseLooseJson(String raw){try{String clean=raw==null?"":raw.trim();clean=clean.replaceFirst("(?s)^```(?:json)?\\s*","").replaceFirst("(?s)\\s*```$","");int a=clean.indexOf('{'),b=clean.lastIndexOf('}');if(a>=0&&b>a)clean=clean.substring(a,b+1);return new JSONObject(clean);}catch(Exception e){return new JSONObject();}}
    private JSONArray parseLooseArray(String raw){try{return new JSONArray(raw==null?"[]":raw);}catch(Exception e){return new JSONArray();}}
    private void selectSpinner(Spinner spinner,String value){if(spinner==null||spinner.getAdapter()==null)return;for(int i=0;i<spinner.getAdapter().getCount();i++)if(String.valueOf(spinner.getAdapter().getItem(i)).equalsIgnoreCase(value==null?"":value)){spinner.setSelection(i);return;}}
    private String value(EditText e){return e==null?"":e.getText().toString().trim();}

