    private void pickDiceFaceImage(String actorName,long actorId,int sides,int face){
        pendingDiceFaceActorName=actorName==null?"":actorName;pendingDiceFaceActorId=Math.max(0,actorId);pendingDiceFaceSides=sides;pendingDiceFaceValue=face;openFile("image/*",REQ_DICE_FACE_IMAGE,false);
    }

    private String diceHistoryDetails(JSONObject h){
        StringBuilder out=new StringBuilder();String actor=h.optString("actor_name","").trim();if(actor.length()>0)out.append("Personagem: ").append(actor).append('\n');
        out.append("Resultados individuais: ").append(h.optString("rolls_json","[]"));String faces=h.optString("physical_faces_json","[]");if(!"[]".equals(faces))out.append("\nFaces físicas: ").append(faces);
        String render=h.optString("render_mode","math");out.append("\nOrigem: ").append("physical3d".equals(render)?"física 3D":"manual_user".equals(render)?"faces informadas pelo jogador":"matemática autorizada");if("physical3d".equals(render)){out.append(" • ").append(h.optInt("physics_ms",0)).append(" ms");long seed=h.optLong("physics_seed",0);if(seed!=0)out.append(" • seed ").append(seed);String theme=h.optString("dice_theme_identity","");if(theme.length()>0)out.append("\nConjunto: ").append(theme);String sig=h.optString("roll_integrity_signature","");if(sig.length()>0)out.append("\nAssinatura física: ").append(sig.substring(0,Math.min(16,sig.length()))).append("…");}return out.toString();
    }

    private long recordDiceHistory(String formula,String requestedMode,String actor,long actorId,DiceResult r,JSONObject extra){
        try{JSONObject c=extra==null?new JSONObject():new JSONObject(extra.toString());c.put("actor_character_id",Math.max(0,actorId)).put("actor_name",actor==null?"":actor).put("roll_mode",r.mode).put("natural_roll",r.natural).put("rolls_json",r.rollsJson).put("physical_faces_json",r.physicalFacesJson).put("render_mode",r.renderMode).put("physics_ms",r.physicsMs).put("physics_seed",r.physicsSeed).put("dice_theme_identity",r.themeIdentity).put("roll_integrity_signature",r.integritySignature);return db.addDiceHistoryBound(formula,r.detail,r.total,(requestedMode==null?"Normal":requestedMode)+(actor!=null&&actor.length()>0?" • "+actor:""),c);}catch(Exception e){AppLog.e("Dice","Falha ao registrar histórico estruturado.",e);toast("A rolagem ocorreu, mas o histórico não pôde ser salvo: "+e.getMessage());return 0;}
    }

    private DiceResult rollDice(String formula,String mode)throws Exception{
        DiceRollSpec spec=DiceRollSpec.parse(formula,mode);java.security.SecureRandom random=new java.security.SecureRandom();List<Integer> rolls=spec.randomRolls(random);DiceRollSpec.Result resolved=spec.resolve(rolls);String critical=resolved.critical;return new DiceResult(resolved.total,resolved.detail,critical,resolved.natural,new JSONArray(rolls).toString(),"[]","math",0,0,"",spec.mode,"");
    }

    private static String intListJson(java.util.List<Integer> values){JSONArray out=new JSONArray();try{if(values!=null)for(Integer value:values)out.put(value==null?0:value.intValue());}catch(Exception ignored){AppLog.ignored("Dice3D","Falha ao serializar faces da rolagem 3D.",ignored);}return out.toString();}
    private interface DiceUiCallback{void done(DiceResult result);}
    private void rollDiceInteractive(final String formula,final String mode,final String actor,final DiceUiCallback callback){rollDiceInteractive(formula,mode,actor,0,callback);}
    private void rollDiceInteractive(final String formula,final String mode,final String actor,final long actorId,final DiceUiCallback callback){
        final DiceRollSpec spec;try{spec=DiceRollSpec.parse(formula,mode);}catch(Exception error){toast(error.getMessage());return;}
        if(!Dice3DOverlay.enabled(prefs)||!spec.supportsPhysical3d()){try{DiceResult r=rollDice(formula,spec.mode);if(Dice3DOverlay.enabled(prefs)&&!spec.supportsPhysical3d())toast("Este lançamento excede os corpos 3D suportados; rolagem matemática usada sem animação falsa.");callback.done(r);}catch(Exception error){toast(error.getMessage());}return;}
        Dice3DOverlay.roll(this,prefs,formula,spec.mode,actor,actorId,new Dice3DOverlay.Callback(){public void onResult(Dice3DOverlay.RollResult rr){try{callback.done(new DiceResult(rr.total,rr.detail,rr.critical,rr.natural,intListJson(rr.rolls),intListJson(rr.physicalFaces),"physical3d",rr.physicsMs,rr.physicsSeed,rr.themeIdentity,rr.mode,rr.integritySignature));}catch(Exception __diceResultFailure106){AppLog.e("Dice3D","Falha ao converter resultado físico 3D.",__diceResultFailure106);toast("A rolagem 3D terminou, mas o resultado não pôde ser convertido: "+__diceResultFailure106.getMessage());}}public void onCancel(){}public void onError(final String message){new AlertDialog.Builder(MainActivity.this).setTitle("Mesa física 3D indisponível").setMessage(message+"\n\nNenhuma animação falsa será usada. Você pode cancelar ou autorizar explicitamente uma rolagem matemática sem 3D.").setNegativeButton("Cancelar",null).setPositiveButton("ROLAR SEM 3D",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{callback.done(rollDice(formula,spec.mode));}catch(Exception e){toast(e.getMessage());}}}).show();}});
    }

