    private void promptManualCombatRoll(final String formula,final String mode,final DiceUiCallback callback){
        final DiceRollSpec spec;try{spec=DiceRollSpec.parse(formula,mode);}catch(Exception invalid){toast(safeMessage(invalid));return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(12));
        form.addView(text(spec.formula+" • "+spec.mode+". Informe as faces naturais na ordem da fórmula, separadas por vírgula. O motor aplica os modificadores. Esta rolagem não aplica dano nem gasta ação.",13,TEXT,false));
        final EditText faces=labeledField(form,"Faces naturais","",false);
        final boolean[] accepted={false};
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Dados manuais do combate").setView(form)
            .setNegativeButton("Cancelar",null).setPositiveButton("REGISTRAR",null).create();
        showBoundDialog(dialog,new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View view){
                if(accepted[0])return;
                try{
                    ArrayList<Integer> supplied=new ArrayList<Integer>();
                    String raw=value(faces);if(raw.isEmpty())throw new IllegalArgumentException("Informe as faces naturais.");
                    for(String part:raw.split("[,;/\\s]+"))supplied.add(Integer.parseInt(part));
                    DiceRollSpec.Result resolved=spec.resolve(supplied);
                    DiceResult rolled=new DiceResult(resolved.total,resolved.detail,resolved.critical,resolved.natural,new JSONArray(supplied).toString(),"[]","manual_user",0,0,"user_supplied",spec.mode,"manual:"+java.util.UUID.randomUUID());
                    accepted[0]=true;view.setEnabled(false);callback.done(rolled);dialog.dismiss();
                }catch(Exception invalid){faces.setError("Confira as faces: "+safeMessage(invalid));}
            }});
        }});
    }

    /** RUN207: configure the existing EQUIPPED ledger item; no inferred attack bonus. */
    private void configureEquippedWeaponDialog(final JSONObject hero){
        final long characterId=hero.optLong("source_id",0);
        final JSONArray items=db.listEquippedWeaponCandidates(characterId);
        if(items.length()==0){toast("Equipe primeiro uma arma no inventário estruturado da ficha.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),0);
        String[] names=new String[items.length()];
        for(int i=0;i<items.length();i++)names[i]=items.optJSONObject(i).optString("name","Item");
        final Spinner choice=spinner(names,names[0]);form.addView(cardWithLabel("ITEM EQUIPADO",choice));
        final EditText bonus=labeledField(form,"Bônus TOTAL de ataque confirmado na ficha","0",false);
        bonus.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
        final EditText formula=labeledField(form,"Dano da arma (exemplo: 1d8+3)","1d8+3",false);
        final Spinner type=spinner(new String[]{"cortante","perfurante","contundente"},"cortante");
        form.addView(cardWithLabel("TIPO DE DANO",type));
        final Spinner kind=spinner(new String[]{"Corpo a corpo","À distância"},"Corpo a corpo");
        form.addView(cardWithLabel("MODALIDADE DA ARMA",kind));
        final EditText reach=labeledField(form,"Alcance corpo a corpo em pés (5 ou 10, etc.)","5",false);
        final EditText normalRange=labeledField(form,"Distância normal (pés; 0 se corpo a corpo)","0",false);
        final EditText longRange=labeledField(form,"Distância máxima (pés; 0 se corpo a corpo)","0",false);
        form.addView(text("DUAS ARMAS (opcional)",14,GOLD,true));
        final CheckBox lightHand=check("Esta arma é Leve e empunhada em uma mão",false);form.addView(lightHand);
        final Spinner weaponHand=spinner(new String[]{"Mão esquerda","Mão direita"},"Mão esquerda");
        form.addView(cardWithLabel("MÃO QUE EMPUNHA ESTA ARMA",weaponHand));
        final EditText baseDice=labeledField(form,"Dados base sem modificador (ex.: 1d6)","1d6",false);
        final EditText abilityDamage=labeledField(form,"Modificador de atributo já presente na fórmula","0",false);
        final EditText itemDamage=labeledField(form,"Modificador do item já presente na fórmula","0",false);
        abilityDamage.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
        itemDamage.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
        form.addView(text("Para duas armas, confirme a propriedade Leve e separe o modificador da fórmula. " +
            "Sem estilo de combate confirmado, o ataque bônus não soma modificador positivo de atributo ao dano.",11,MUTED,false));
        form.addView(text("Confirme no livro ou na ficha os alcances da arma. Distância longa impõe desvantagem; " +
            "sem linha de visão ou fora de alcance a ação não será aplicada.",12,MUTED,false));
        form.addView(text("Os números serão guardados no item equipado. Confira a ficha: este formulário não deduz proficiência, atributo, propriedades mágicas ou talentos.",12,MUTED,false));
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Configurar arma equipada")
            .setView(form).setNegativeButton("CANCELAR",null).setPositiveButton("SALVAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(final DialogInterface d){
            ((AlertDialog)d).getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                int atk;try{atk=Integer.parseInt(value(bonus).trim());}catch(Exception e){bonus.setError("Informe o bônus numérico.");return;}
                JSONObject selected=items.optJSONObject(choice.getSelectedItemPosition());
                if(selected==null){toast("Item inválido.");return;}
                String raw=value(formula).trim().toLowerCase(java.util.Locale.ROOT).replace(" ","");
                String damageType=String.valueOf(type.getSelectedItem());
                if(!EquippedWeaponAttackRules.validProfile(selected.optString("id"),atk,raw,damageType)){
                    formula.setError("Use 1 a 10 dados d4/d6/d8/d10/d12 e modificador de -100 a +100.");return;
                }
                String modeKind=kind.getSelectedItemPosition()==0?"melee":"ranged";
                int reachFt,normalFt,farFt;
                try{reachFt=Integer.parseInt(value(reach).trim());normalFt=Integer.parseInt(value(normalRange).trim());
                    farFt=Integer.parseInt(value(longRange).trim());}
                catch(Exception e){reach.setError("Informe números inteiros para todos os alcances.");return;}
                if(!TacticalAttackGeometryRules.validProfile(modeKind,reachFt,normalFt,farFt)){
                    reach.setError("Corpo a corpo: alcance positivo e distâncias zero. Distância: alcance zero, intervalos de 5 pés.");return;
                }
                int twoAbility=0,twoItem=0;
                if(lightHand.isChecked()){
                    try{twoAbility=Integer.parseInt(value(abilityDamage));twoItem=Integer.parseInt(value(itemDamage));}
                    catch(Exception invalid){toast("Modificadores de duas armas inválidos.");return;}
                    EquippedWeaponAttackRules.Dice full=EquippedWeaponAttackRules.parse(raw),
                        base=EquippedWeaponAttackRules.parse(value(baseDice).trim());
                    if(!"melee".equals(modeKind)||full==null||base==null||base.modifier!=0||
                        full.count!=base.count||full.faces!=base.faces||
                        full.modifier!=twoAbility+twoItem){
                        toast("Arma Leve precisa ser corpo a corpo; dados e modificadores devem reproduzir a fórmula.");return;
                    }
                }
                if(!db.configureEquippedWeaponAttack(characterId,selected.optString("id"),atk,raw,damageType,
                    modeKind,reachFt,normalFt,farFt)){
                    toast("Equipamento foi alterado ou não pôde ser salvo. Confira a ficha.");return;
                }
                if(lightHand.isChecked()){
                    if(!db.configureEquippedTwoWeaponProfile(characterId,selected.optString("id"),
                        weaponHand.getSelectedItemPosition()==0?"left":"right",value(baseDice).trim(),
                        twoAbility,twoItem)){
                        toast("Perfil de duas armas inválido: dados e modificadores devem reproduzir o dano da arma.");return;
                    }
                }
                toast("Perfil da arma salvo no inventário.");((AlertDialog)d).dismiss();showCombat();
            }});
        }});dialog.show();
    }
    /** RUN210: choose a separate target and equipped weapon for EACH legal swing,
     * then commit all rolls/damage/one Attack action atomically after confirmation. */
    private void partyExtraAttackDialog(final JSONObject hero){
        if(hero.optInt("is_player",0)!=1||!"character".equals(hero.optString("source_kind"))){
            toast("Ataque Extra exige herói com ficha vinculada.");return;
        }
        final long characterId=hero.optLong("source_id",0);
        int capacity=db.extraAttackCapacity(characterId);
        if(capacity<2){toast("Ataque Extra não confirmado nos níveis de classe da ficha.");return;}
        final List<JSONObject> actions=new ArrayList<JSONObject>();
        for(JSONObject row:db.listPartyActions("narrated",100)){
            String intent=row.optString("intent_type","");
            if(row.optLong("character_id")==characterId&&("combate".equals(intent)||"livre".equals(intent)))actions.add(row);
        }
        if(actions.isEmpty()){toast("Narre primeiro a intenção de atacar deste herói.");return;}
        LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(dp(12),0,dp(12),0);
        final Spinner declaration=partyCombatActionSelector(layout,actions);declaration.setSelection(1);
        String[] counts=new String[capacity-1];for(int i=2;i<=capacity;i++)counts[i-2]=i+" ataques";
        final Spinner choice=spinner(counts,counts[0]);layout.addView(cardWithLabel("QUANTIDADE DE ATAQUES DA AÇÃO",choice));
        layout.addView(text("Cada ataque permite alvo e arma equipada diferentes. A AÇÃO é debitada UMA vez. " +
            "Todos os resultados serão confirmados juntos, com rollback completo se algum deles falhar. " +
            "Talentos, manobras, ataques bônus e subclasses especiais ainda exigem motores próprios.",12,MUTED,false));
        AlertDialog dlg=new AlertDialog.Builder(this).setTitle("Ataque Extra • mesma Ação Atacar")
            .setView(layout).setNegativeButton("CANCELAR",null).setPositiveButton("INICIAR ROLAGENS",null).create();
        dlg.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){
            dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                int idx=declaration.getSelectedItemPosition()-1;
                if(idx<0||idx>=actions.size()){toast("Escolha a declaração narrada.");return;}
                long actionId=actions.get(idx).optLong("id",0);
                int count=choice.getSelectedItemPosition()+2;
                if(!ExtraAttackActionRules.validCount(db.extraAttackCapacity(characterId),count)){
                    toast("Quantidade não concedida pela ficha.");return;
                }
                dlg.dismiss();rollExtraAttackStep(hero,actionId,new JSONArray(),0,count);
            }});
        }});dlg.show();
    }
    private void rollExtraAttackStep(final JSONObject hero,final long actionId,
                                     final JSONArray prepared,final int index,final int count){
        if(index==count){
            StringBuilder report=new StringBuilder("Confirmar AÇÃO ATACAR com "+count+" ataques?\n\n");
            for(int i=0;i<prepared.length();i++){
                JSONObject s=prepared.optJSONObject(i);if(s==null)continue;
                report.append(i+1).append(". ").append(s.optString("target_name","Alvo"))
                    .append(" • d20=").append(s.optInt("natural"))
                    .append(" • dano ").append(s.optInt("damage")).append("\n");
            }
            final String token="ui-extra-"+java.util.UUID.randomUUID();
            new AlertDialog.Builder(this).setTitle("Revisar todos os ataques").setMessage(report.toString())
                .setNegativeButton("NÃO APLICAR",null).setPositiveButton("APLICAR AÇÃO E DANOS",new DialogInterface.OnClickListener(){
                public void onClick(DialogInterface d,int which){
                    JSONObject result=db.applyExtraWeaponAttacksForPartyAction(actionId,hero.optLong("id"),prepared,token);
                    if(!result.optBoolean("party_action_resolved",false)){
                        toast("Nenhum efeito aplicado: "+result.optString("extra_attack_blocked",result.optString("operation_error","Revalidar ação")));
                        return;
                    }
                    toast(count+" ataques registrados na mesma ação.");showCombat();
                }}).show();return;
        }
        final long actorId=hero.optLong("id",0),characterId=hero.optLong("source_id",0);
        final JSONArray weapons=db.listEquippedWeaponAttackProfiles(characterId);
        final List<JSONObject> targets=new ArrayList<JSONObject>();
        for(JSONObject t:db.listCombatants())if(t.optLong("id")!=actorId)targets.add(t);
        if(weapons.length()==0||targets.isEmpty()){toast("Faltam arma equipada ou alvos válidos.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),0);
        String[] targetNames=new String[targets.size()],weaponNames=new String[weapons.length()];
        for(int i=0;i<targets.size();i++)targetNames[i]=targets.get(i).optString("name","Alvo");
        for(int i=0;i<weapons.length();i++)weaponNames[i]=weapons.optJSONObject(i).optString("name","Arma");
        final Spinner target=spinner(targetNames,targetNames[0]),weapon=spinner(weaponNames,weaponNames[0]);
        final Spinner mode=spinner(new String[]{"Normal","Vantagem","Desvantagem"},"Normal");
        form.addView(cardWithLabel("ALVO DO ATAQUE "+(index+1),target));
        form.addView(cardWithLabel("ARMA EQUIPADA",weapon));form.addView(cardWithLabel("D20",mode));
        AlertDialog dlg=new AlertDialog.Builder(this).setTitle("Ataque "+(index+1)+" de "+count)
            .setView(form).setNegativeButton("CANCELAR SEQUÊNCIA",null)
            .setPositiveButton("ROLAR ATAQUE",null).create();
        dlg.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){
            dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                JSONObject chosen=weapons.optJSONObject(weapon.getSelectedItemPosition());
                if(chosen==null){toast("Arma indisponível.");return;}
                final String item=chosen.optString("id"),formula=chosen.optString("weapon_damage_formula"),
                    type=chosen.optString("weapon_damage_type");
                final int bonus=chosen.optInt("weapon_attack_bonus",Integer.MIN_VALUE);
                final EquippedWeaponAttackRules.Dice dice=EquippedWeaponAttackRules.parse(formula);
                if(dice==null||!EquippedWeaponAttackRules.validProfile(item,bonus,formula,type)){
                    toast("Configure o perfil da arma na ficha.");return;
                }
                final long targetId=targets.get(target.getSelectedItemPosition()).optLong("id");
                final String targetName=targets.get(target.getSelectedItemPosition()).optString("name","Alvo");
                final JSONObject geom=db.previewTacticalWeaponAttack(actorId,targetId,item);
                if(!geom.optBoolean("attack_geometry_valid",false)){
                    toast("Alcance ou visão inválidos: "+geom.optString("attack_geometry_blocked"));return;
                }
                final String effective=geom.optBoolean("long_range_disadvantage",false)?"Desvantagem":
                    String.valueOf(mode.getSelectedItem());
                final int ac=geom.optInt("effective_ac",-999);
                final String fingerprint=geom.optString("attack_geometry_fingerprint");
                dlg.dismiss();
                rollDiceInteractive("d20"+(bonus>=0?"+":"")+bonus,effective,hero.optString("name"),characterId,
                    new DiceUiCallback(){public void done(final DiceResult attack){
                        if(attack.natural<1||attack.natural>20){toast("Rolagem d20 inválida. Sequência não aplicada.");return;}
                        final boolean hit=PartyAttackCausalReceiptGuard.hit(attack.natural,bonus,ac);
                        final int natural=attack.natural;
                        if(!hit){appendExtraAttackStep(hero,actionId,prepared,index,count,targetId,targetName,
                            item,formula,type,bonus,natural,0,ac,fingerprint,effective);return;}
                        rollDiceInteractive(dice.rolledFormula(natural==20),"Normal",hero.optString("name"),characterId,
                            new DiceUiCallback(){public void done(DiceResult damage){
                                appendExtraAttackStep(hero,actionId,prepared,index,count,targetId,targetName,
                                    item,formula,type,bonus,natural,Math.max(0,damage.total),ac,fingerprint,effective);
                            }});
                    }});
            }});
        }});dlg.show();
    }
    private void appendExtraAttackStep(JSONObject hero,long actionId,JSONArray rolls,int index,int count,
        long targetId,String targetName,String item,String formula,String type,int bonus,int natural,
        int damage,int ac,String fingerprint,String mode){
        try{
            JSONObject step=new JSONObject().put("target_id",targetId).put("target_name",targetName)
                .put("weapon_id",item).put("formula",formula).put("damage_type",type)
                .put("bonus",bonus).put("natural",natural).put("damage",damage)
                .put("expected_ac",ac).put("fingerprint",fingerprint).put("roll_mode",mode);
            rolls.put(step);
            rollExtraAttackStep(hero,actionId,rolls,index+1,count);
        }catch(Exception failure){toast("Falha ao armazenar rolagem: nada foi aplicado.");}
    }

    /** RUN206 — execute one ordinary weapon attack, never infer Extra Attack. */
    private void partySingleWeaponAttackDialog(final JSONObject hero){
        if(hero.optInt("is_player",0)!=1||!"character".equals(hero.optString("source_kind"))){
            toast("Este executor exige herói vinculado à ficha.");return;
        }
        final long actorId=hero.optLong("id"),characterId=hero.optLong("source_id");
        final List<JSONObject> declarations=new ArrayList<JSONObject>();
        for(JSONObject a:db.listPartyActions("narrated",100)){
            String intent=a.optString("intent_type","");
            if(a.optLong("character_id",0)==characterId&&
                ("combate".equals(intent)||"livre".equals(intent)))declarations.add(a);
        }
        if(declarations.isEmpty()){toast("Narre primeiro uma declaração de combate deste herói.");return;}
        final List<JSONObject> targets=new ArrayList<JSONObject>();
        for(JSONObject c:db.listCombatants())if(c.optLong("id")!=actorId)targets.add(c);
        if(targets.isEmpty()){toast("Não há outro combatente como alvo.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),0);
        String[] names=new String[targets.size()];for(int i=0;i<targets.size();i++)names[i]=targets.get(i).optString("name");
        final Spinner target=spinner(names,names[0]);form.addView(cardWithLabel("ALVO",target));
        final JSONArray weapons=db.listEquippedWeaponAttackProfiles(characterId);
        if(weapons.length()==0){toast("Nenhuma arma equipada com perfil válido. Use CONFIGURAR ARMA.");return;}
        String[] weaponNames=new String[weapons.length()];
        for(int i=0;i<weapons.length();i++)weaponNames[i]=weapons.optJSONObject(i).optString("name","Arma");
        final Spinner weapon=spinner(weaponNames,weaponNames[0]);form.addView(cardWithLabel("ARMA EQUIPADA NA FICHA",weapon));
        final Spinner mode=spinner(new String[]{"Normal","Vantagem","Desvantagem"},"Normal");
        form.addView(cardWithLabel("ROLAGEM DE ATAQUE",mode));
        final Spinner action=partyCombatActionSelector(form,declarations);
        action.setSelection(1); // Explicit confirmation required; no generic, inferred character action.
        form.addView(text("O MAPA valida alcance, cobertura e linha de visão antes e depois da rolagem. " +
            "Armas configuradas antes desta atualização devem receber perfil de alcance. " +
            "Execução básica: UMA jogada de ataque consumirá a AÇÃO do turno, inclusive em erro. " +
            "Não substitui Ataque Extra, duas armas, magias, manobras ou reações. " +
            "Acerto crítico dobra somente os dados de dano da fórmula simples; bônus permanece igual.",12,MUTED,false));
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Ataque de arma • execução causal")
            .setView(form).setNegativeButton("Cancelar",null).setPositiveButton("ROLAR E EXECUTAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                final int idx=action.getSelectedItemPosition()-1;
                if(idx<0||idx>=declarations.size()){toast("Selecione uma declaração narrada para concluir.");return;}
                final JSONObject selected=weapons.optJSONObject(weapon.getSelectedItemPosition());
                if(selected==null){toast("Arma não encontrada.");return;}
                final int atk=selected.optInt("weapon_attack_bonus",Integer.MIN_VALUE);
                final String formula=selected.optString("weapon_damage_formula","");
                final String damageType=selected.optString("weapon_damage_type","");
                final String itemId=selected.optString("id","");
                final EquippedWeaponAttackRules.Dice dice=EquippedWeaponAttackRules.parse(formula);
                if(dice==null||!EquippedWeaponAttackRules.validProfile(itemId,atk,formula,damageType)){
                    toast("Perfil inválido: configure a arma na ficha.");return;
                }

                final long targetId=targets.get(target.getSelectedItemPosition()).optLong("id");
                final long actionId=declarations.get(idx).optLong("id");
                final JSONObject geom=db.previewTacticalWeaponAttack(actorId,targetId,itemId);
                if(!geom.optBoolean("attack_geometry_valid",false)){
                    toast("Ataque bloqueado pelo mapa: "+geom.optString("attack_geometry_blocked"));return;
                }
                final String fingerprint=geom.optString("attack_geometry_fingerprint");
                final int effectiveAc=geom.optInt("effective_ac",10);
                final String effectiveMode=geom.optBoolean("long_range_disadvantage",false)?"Desvantagem":
                    String.valueOf(mode.getSelectedItem());
                if(geom.optBoolean("long_range_disadvantage",false))
                    toast("Alvo em distância longa: rolando com desvantagem.");
                final String token="ui-weapon2-"+java.util.UUID.randomUUID();
                rollDiceInteractive("d20"+(atk>=0?"+":"")+atk,effectiveMode,
                    hero.optString("name"),characterId,new DiceUiCallback(){public void done(final DiceResult roll){
                    if(roll.natural<1||roll.natural>20){toast("D20 não validado; ação preservada.");return;}
                    final int natural=roll.natural;
                    final int ac=effectiveAc;
                    if(db.combatantHasTotalCover(targetId)){toast("Cobertura total: ataque bloqueado.");return;}
                    final boolean hit=PartyAttackCausalReceiptGuard.hit(natural,atk,ac);
                    String raw=dice.rolledFormula(hit&&natural==20);
                    final String actual=raw;
                    if(!hit){partyAttackConfirmApply(hero,actionId,targetId,natural,atk,0,damageType,token,itemId,formula,ac,fingerprint,effectiveMode,
                        "ERRO ("+natural+" no d20): a AÇÃO será consumida; alvo sem dano.",dialog);return;}
                    rollDiceInteractive(actual,"Normal",hero.optString("name"),characterId,
                        new DiceUiCallback(){public void done(DiceResult rolled){
                        int damage=Math.max(0,rolled.total);
                        partyAttackConfirmApply(hero,actionId,targetId,natural,atk,damage,damageType,token,itemId,formula,ac,fingerprint,effectiveMode,
                            "ACERTO"+(natural==20?" CRÍTICO":"")+" • "+natural+"+"+atk+" vs CA "+ac+
                            " • "+actual+" = "+damage+" "+damageType+".\nConfirmar gasto da ação e dano?",dialog);
                    }});
                }});
            }});
        }});dialog.show();
    }
    private void partyAttackConfirmApply(final JSONObject hero,final long actionId,final long targetId,
        final int natural,final int bonus,final int damage,final String type,final String token,
        final String weaponId,final String damageFormula,final int expectedAc,
        final String geometryFingerprint,final String rollMode,String summary,final AlertDialog entry){
        new AlertDialog.Builder(this).setTitle("Revisar ataque antes de aplicar").setMessage(summary)
            .setNegativeButton("VOLTAR SEM ALTERAR",null).setPositiveButton("CONFIRMAR",new DialogInterface.OnClickListener(){
            public void onClick(DialogInterface d,int w){
                JSONObject applied=db.applySingleWeaponAttackForPartyAction(actionId,hero.optLong("id"),targetId,
                    natural,bonus,damage,type,token,weaponId,damageFormula,expectedAc,geometryFingerprint,rollMode);
                String reason=applied.optString("party_attack_blocked",applied.optString("operation_error",""));
                if(!applied.optBoolean("party_action_resolved",false)){
                    toast("Ataque não executado; transação bloqueada: "+reason);return;
                }
                toast(applied.optBoolean("attack_hit",false)?"Ataque e dano aplicados na mesma transação.":
                    "Ataque falhou; ação consumida sem dano.");entry.dismiss();showCombat();
            }}).show();
    }
    /** Bonus-action Light attack after a durable single Attack-action receipt. */
    private void partyTwoWeaponAttackDialog(final JSONObject hero){
        final long actorId=hero.optLong("id"),characterId=hero.optLong("source_id");
        final List<JSONObject> actions=new ArrayList<JSONObject>(),targets=new ArrayList<JSONObject>();
        for(JSONObject row:db.listPartyActions("resolved",100))
            if(row.optLong("character_id")==characterId&&
                row.optString("resolution_receipt").startsWith(PartyAttackCausalReceiptGuard.PREFIX))actions.add(row);
        for(JSONObject row:db.listCombatants())if(row.optLong("id")!=actorId)targets.add(row);
        final JSONArray equipped=db.listEquippedWeaponAttackProfiles(characterId);
        final List<JSONObject> offWeapons=new ArrayList<JSONObject>();
        for(int i=0;i<equipped.length();i++){
            JSONObject item=equipped.optJSONObject(i);
            if(item!=null&&item.optBoolean("two_weapon_light",false)&&
                "melee".equals(item.optString("weapon_attack_kind")))offWeapons.add(item);
        }
        if(actions.isEmpty()||targets.isEmpty()||offWeapons.size()<2){
            toast("É preciso um ataque único já resolvido e duas armas Leves configuradas em mãos opostas.");return;
        }
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);
        form.setPadding(dp(12),0,dp(12),0);
        String[] actionLabels=new String[actions.size()],targetLabels=new String[targets.size()],
            weaponLabels=new String[offWeapons.size()];
        for(int i=0;i<actions.size();i++)actionLabels[i]="#"+actions.get(i).optLong("id")+" • "+
            actions.get(i).optString("action_text","Ação Atacar");
        for(int i=0;i<targets.size();i++)targetLabels[i]=targets.get(i).optString("name","Alvo");
        for(int i=0;i<offWeapons.size();i++)weaponLabels[i]=offWeapons.get(i).optString("name","Arma");
        final Spinner mainAction=spinner(actionLabels,actionLabels[0]),target=spinner(targetLabels,targetLabels[0]),
            off=spinner(weaponLabels,weaponLabels[0]),mode=spinner(new String[]{"Normal","Vantagem","Desvantagem"},"Normal");
        form.addView(cardWithLabel("AÇÃO ATACAR JÁ RESOLVIDA",mainAction));
        form.addView(cardWithLabel("ALVO",target));
        form.addView(cardWithLabel("ARMA NA OUTRA MÃO",off));
        form.addView(cardWithLabel("MODO DA ROLAGEM",mode));
        form.addView(text("A ação principal deve ter ocorrido neste turno. O aplicativo validará armas equipadas, " +
            "alcance e CA novamente, gastará a AÇÃO BÔNUS e aplicará dano na mesma transação.",12,MUTED,false));
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Ataque com duas armas")
            .setView(form).setNegativeButton("CANCELAR",null).setPositiveButton("ROLAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                final long actionId=actions.get(mainAction.getSelectedItemPosition()).optLong("id"),
                    targetId=targets.get(target.getSelectedItemPosition()).optLong("id");
                final JSONObject selected=offWeapons.get(off.getSelectedItemPosition());
                final String offId=selected.optString("id");
                final JSONObject preview=db.previewTwoWeaponAttack(actionId,actorId,targetId,offId);
                if(!preview.optBoolean("two_weapon_valid",false)){
                    toast("Ataque bônus indisponível: "+preview.optString("two_weapon_blocked"));return;
                }
                final int bonus=preview.optInt("off_bonus"),ac=preview.optInt("effective_ac");
                final String fingerprint=preview.optString("geometry_fingerprint"),
                    rollMode=String.valueOf(mode.getSelectedItem());
                final EquippedWeaponAttackRules.Dice dice=EquippedWeaponAttackRules.parse(preview.optString("base_dice"));
                if(dice==null){toast("Dados base inválidos.");return;}
                final String token="ui-two-"+java.util.UUID.randomUUID();
                rollDiceInteractive("d20"+(bonus>=0?"+":"")+bonus,rollMode,
                    hero.optString("name"),characterId,new DiceUiCallback(){public void done(final DiceResult attack){
                    if(attack.natural<1||attack.natural>20){toast("D20 inválido; nada aplicado.");return;}
                    final int natural=attack.natural;
                    if(!PartyAttackCausalReceiptGuard.hit(natural,bonus,ac)){
                        confirmTwoWeaponAttack(dialog,actionId,actorId,targetId,offId,natural,bonus,0,
                            ac,fingerprint,rollMode,token);return;
                    }
                    rollDiceInteractive(dice.rolledFormula(natural==20),"Normal",hero.optString("name"),
                        characterId,new DiceUiCallback(){public void done(DiceResult damage){
                        confirmTwoWeaponAttack(dialog,actionId,actorId,targetId,offId,natural,bonus,
                            Math.max(0,damage.total),ac,fingerprint,rollMode,token);
                    }});
                }});
            }});
        }});dialog.show();
    }
    private void confirmTwoWeaponAttack(final AlertDialog entry,final long actionId,
        final long actorId,final long targetId,final String offId,final int natural,
        final int bonus,final int diceTotal,final int ac,final String fingerprint,
        final String rollMode,final String token){
        new AlertDialog.Builder(this).setTitle("Confirmar ataque bônus")
            .setMessage("D20 "+natural+" + "+bonus+" contra CA "+ac+"; dados de dano "+diceTotal+
                ". Confirmar gasto da ação bônus e resultado?")
            .setNegativeButton("NÃO APLICAR",null)
            .setPositiveButton("CONFIRMAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
                JSONObject result=db.applyTwoWeaponAttack(actionId,actorId,targetId,offId,natural,
                    bonus,diceTotal,ac,fingerprint,rollMode,token);
                if(!result.optBoolean("two_weapon_committed",false)){
                    toast("Ataque bônus não aplicado: "+result.optString("two_weapon_blocked",
                        result.optString("operation_error","revise o combate")));return;
                }
                toast(result.optBoolean("attack_hit",false)?
                    "Ataque bônus acertou: "+result.optInt("raw_damage")+" de dano.":
                    "Ataque bônus errou; ação bônus consumida.");entry.dismiss();showCombat();
            }}).show();
    }

    /** RUN230: explicit hostility is directed, editable and persisted in SQLite.
     * It never guesses allegiance from the combatant name or is_player flag. */
    private void compiledMonsterHostilityDialog(final JSONObject monster){
        final long actorId=monster.optLong("id",0);
        final JSONObject ledger=db.getCompiledMonsterHostilityLedger(actorId);
        if(!ledger.optBoolean("hostility_ledger_valid",false)){
            toast("Relações não disponíveis: "+ledger.optString("hostility_ledger_blocked"));return;
        }
        final ArrayList<JSONObject> others=new ArrayList<JSONObject>();
        for(JSONObject row:db.listCombatants())if(row.optLong("id")!=actorId)others.add(row);
        if(others.size()>MonsterHostilityLedgerRules.MAX_HOSTILES){
            toast("Muitos combatentes para configurar hostilidade de uma vez.");return;
        }
        final String[] labels=new String[others.size()];
        final boolean[] selected=new boolean[others.size()];
        final JSONArray saved=ledger.optJSONArray("hostile_ids");
        for(int i=0;i<others.size();i++){
            JSONObject other=others.get(i);long id=other.optLong("id",0);
            labels[i]=other.optString("name","Combatente")+" (#"+id+")";
            for(int j=0;saved!=null&&j<saved.length();j++)if(saved.optLong(j)==id)selected[i]=true;
        }
        toast("Marque apenas inimigos comprovados; a relação é unilateral e persistente.");
        new AlertDialog.Builder(this).setTitle("Inimigos declarados • selecione")
            .setMultiChoiceItems(labels,selected,new DialogInterface.OnMultiChoiceClickListener(){
                public void onClick(DialogInterface d,int index,boolean checked){selected[index]=checked;}
            })
            .setNegativeButton("CANCELAR",null)
            .setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){
                public void onClick(DialogInterface d,int which){
                    JSONArray ids=new JSONArray();for(int i=0;i<selected.length;i++)if(selected[i])
                        ids.put(others.get(i).optLong("id"));
                    JSONObject result=db.replaceCompiledMonsterHostilityLedger(actorId,ids,
                        "ui-hostility-"+java.util.UUID.randomUUID());
                    if(!result.optBoolean("hostility_ledger_committed",false)){
                        toast("Hostilidade não gravada: "+result.optString("hostility_ledger_blocked",
                            result.optString("operation_error","falha de transação")));return;
                    }
                    toast("Relações persistidas (revisão "+result.optInt("revision")+").");showCombat();
                }
            }).show();
    }

    /** Guided UI for a compiled monster/statblock action; no payload JSON is
     * required. The player supplies only the physical dice results. */
    private void compiledMonsterAttackDialog(final JSONObject monster){
        final long actorId=monster.optLong("id");
        final JSONObject resources=parseObjectSafe(monster.optString("resources_json","{}"));
        final String statblock=resources.optString("block_id","");
        if(statblock.trim().isEmpty()){toast("Este monstro não possui bloco compilado autorizado.");return;}
        final ArrayList<JSONObject> targets=new ArrayList<JSONObject>();
        for(JSONObject row:db.listCombatants())if(row.optLong("id")!=actorId&&row.optInt("hp",0)>0)targets.add(row);
        if(targets.isEmpty()){toast("Não há alvo vivo para o ataque.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),0);
        final String[] targetNames=new String[targets.size()];for(int i=0;i<targets.size();i++)targetNames[i]=targets.get(i).optString("name","Alvo");
        final Spinner target=spinner(targetNames,targetNames[0]);form.addView(cardWithLabel("ALVO",target));
        // Manual explicit hostility; is_player=0 is NOT proof of allegiance.
        final String[] threatNames=new String[targets.size()+1];threatNames[0]="Nenhum outro inimigo";
        for(int i=0;i<targets.size();i++)threatNames[i+1]=targets.get(i).optString("name","Combatente")+" (#"+targets.get(i).optLong("id")+")";
        final Spinner additionalHostile=spinner(threatNames,threatNames[0]);
        form.addView(cardWithLabel("OUTRO INIMIGO (LEGADO; AUTOMÁTICO SE CONFIGURADO)",additionalHostile));
        form.addView(text("Use CONFIGURAR INIMIGOS para registrar relações persistentes. " +
            "Se configuradas, o motor detecta automaticamente inimigos adjacentes " +
            "declarados e revalida visão, vida e condições no commit. Selecione manualmente " +
            "somente para legados sem declaração.",11,MUTED,false));
        final JSONObject profile=CompiledStatblockEngine.runtimeProfile(statblock);
        final JSONArray declaredActions=profile.optJSONArray("actions");
        final ArrayList<String> attackNames=new ArrayList<String>();
        final ArrayList<String> attackSourceNames=new ArrayList<String>();
        if(declaredActions!=null)for(int i=0;i<declaredActions.length();i++){JSONObject candidate=declaredActions.optJSONObject(i);if(candidate!=null&&candidate.has("to_hit")&&
            !MonsterActionEconomyGuard.standaloneCost(candidate.optString("category","action")).isEmpty()&&
            MonsterActionEconomyGuard.attackRiderBlock(candidate,statblock).isEmpty()&&
            CompiledMonsterActionGuard.actionRechargeBlock(candidate.optString("recharge","")).isEmpty())
            {String sourceName=candidate.optString("name","Ação");attackSourceNames.add(sourceName);
             attackNames.add(DndPtBrLocalizer.localizeText(sourceName));}}
        if(attackNames.isEmpty()){toast("O bloco compilado não declara ataques diretos executáveis.");return;}
        final String[] actionNames=attackNames.toArray(new String[0]);
        final Spinner action=spinner(actionNames,actionNames[0]);form.addView(cardWithLabel("AÇÃO DO BLOCO",action));
        final TextView chargeStatus=text("",11,GOLD,false);chargeStatus.setVisibility(View.GONE);form.addView(chargeStatus);
        final EditText d20=labeledField(form,"Primeiro d20 natural (1–20)","",false);
        final EditText longD20=labeledField(form,"Segundo d20 (vantagem ou desvantagem; 0 para normal)","0",false);
        final LinearLayout singleDamageBox=new LinearLayout(this);singleDamageBox.setOrientation(LinearLayout.VERTICAL);
        singleDamageBox.addView(text("TOTAL DE DANO ROLADO (0 SE ERROU)",12,GOLD,true));
        final EditText damage=input("Total de dano","0",false);damage.setInputType(InputType.TYPE_CLASS_NUMBER);
        singleDamageBox.addView(damage);form.addView(singleDamageBox);
        final LinearLayout typedDamageBox=new LinearLayout(this);typedDamageBox.setOrientation(LinearLayout.VERTICAL);
        typedDamageBox.setVisibility(View.GONE);form.addView(typedDamageBox);
        final ArrayList<JSONObject> typedDamageSpecs=new ArrayList<JSONObject>();
        final ArrayList<EditText> typedDamageValues=new ArrayList<EditText>();
        boolean initialCharge=refreshMonsterChargeStatus(actorId,targets.get(target.getSelectedItemPosition()).optLong("id"),
            statblock,attackSourceNames.get(0),chargeStatus);
        configureMonsterAttackDamageFields(profile,attackSourceNames.get(0),singleDamageBox,typedDamageBox,
            damage,typedDamageSpecs,typedDamageValues,initialCharge);
        action.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){
            public void onItemSelected(AdapterView<?> parent,View view,int position,long rowId){
                boolean qualified=refreshMonsterChargeStatus(actorId,
                    targets.get(target.getSelectedItemPosition()).optLong("id"),statblock,
                    attackSourceNames.get(position),chargeStatus);
                configureMonsterAttackDamageFields(profile,attackSourceNames.get(position),
                    singleDamageBox,typedDamageBox,damage,typedDamageSpecs,typedDamageValues,qualified);
            }
            public void onNothingSelected(AdapterView<?> parent){}
        });
        target.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){
            public void onItemSelected(AdapterView<?> parent,View view,int position,long rowId){
                int selectedAction=action.getSelectedItemPosition();
                boolean qualified=refreshMonsterChargeStatus(actorId,targets.get(position).optLong("id"),
                    statblock,attackSourceNames.get(selectedAction),chargeStatus);
                configureMonsterAttackDamageFields(profile,attackSourceNames.get(selectedAction),
                    singleDamageBox,typedDamageBox,damage,typedDamageSpecs,typedDamageValues,qualified);
            }
            public void onNothingSelected(AdapterView<?> parent){}
        });
        final EditText save=labeledField(form,"Total da salvaguarda do efeito (obrigatório se acertar e houver CD)","0",false);
        // Only used for a statblock-authorized push/pull after a failed
        // on-hit saving throw. Empty (-1) never teleports a combatant.
        form.addView(text("Se o bloco declarar empurrão, puxão ou outro deslocamento obrigatório ao acertar ou após falha na salvaguarda, informe a célula de destino do alvo. O app valida direção permitida, distância, obstáculos e ocupação. Deixe -1 quando não se aplicar.",11,MUTED,false));
        final EditText forcedX=labeledField(form,"Célula de destino X (-1 se não aplicável)","-1",false);
        final EditText forcedY=labeledField(form,"Célula de destino Y (-1 se não aplicável)","-1",false);
        final Button previewRoll=button("CONFERIR MODO DE ROLAGEM E CA",GREEN);
        form.addView(previewRoll);
        previewRoll.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            JSONObject info=db.previewCompiledMonsterAttackRollMode(actorId,
                targets.get(target.getSelectedItemPosition()).optLong("id"),statblock,
                attackSourceNames.get(action.getSelectedItemPosition()),additionalHostile.getSelectedItemPosition()==0?0L:
                    targets.get(additionalHostile.getSelectedItemPosition()-1).optLong("id"));
            if(!info.optBoolean("monster_roll_preview_valid",false)){
                toast("Prévia bloqueada: "+info.optString("monster_roll_preview_blocked","revisar alvo"));return;
            }
            toast("D20: "+info.optString("roll_mode")+" • CA "+info.optInt("effective_ac")+
                " • Distância "+info.optInt("distance_ft")+" pés"+
                (info.optBoolean("second_d20_required",false)?" • informe dois d20":" • somente um d20"));
        }});
        form.addView(text("Bloco compilado: "+statblock+". O aplicativo valida a ação, CA, crítico, dano e condição dentro da transação.",12,MUTED,false));
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Ataque de monstro compilado")
            .setView(scrollableDialogView(form)).setNegativeButton("CANCELAR",null).setPositiveButton("APLICAR",null).create();
        final String attackToken="ui-monster-"+java.util.UUID.randomUUID();final boolean[] applied={false};
        showBoundDialog(dialog,new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            if(applied[0])return;
            int roll,longRoll,rawDamage,saveRoll,destX,destY;JSONArray damageComponents=new JSONArray();
            try{roll=Integer.parseInt(value(d20));longRoll=Integer.parseInt(value(longD20));rawDamage=Integer.parseInt(value(damage));saveRoll=Integer.parseInt(value(save));
                destX=Integer.parseInt(value(forcedX));destY=Integer.parseInt(value(forcedY));}
            catch(Exception bad){toast("Informe números válidos para os dados.");return;}
            if(roll<1||roll>20||longRoll<0||longRoll>20||rawDamage<0||saveRoll<0||destX< -1||destY< -1){toast("Dados inválidos; nada aplicado.");return;}
            if(typedDamageSpecs.size()>1){
                int typedSum=0;
                try{for(int i=0;i<typedDamageSpecs.size();i++){
                    int componentTotal=Integer.parseInt(value(typedDamageValues.get(i)).trim());
                    if(componentTotal<0||componentTotal>100000)throw new IllegalArgumentException("component_out_of_range");
                    typedSum+=componentTotal;
                    JSONObject spec=typedDamageSpecs.get(i);
                    damageComponents.put(new JSONObject().put("expression",spec.optString("expression"))
                        .put("damage_type",spec.optString("type")).put("damage_total",componentTotal));
                }}catch(Exception invalid){toast("Informe um total válido para cada tipo de dano.");return;}
                // On a miss the typed array must be empty; AppDb independently
                // rejects nonzero damage on misses and validates every hit roll.
                if(typedSum>0)rawDamage=typedSum;else damageComponents=new JSONArray();
            }
            JSONObject preview=db.previewCompiledMonsterAttackRollMode(actorId,
                targets.get(target.getSelectedItemPosition()).optLong("id"),statblock,attackSourceNames.get(action.getSelectedItemPosition()),
                additionalHostile.getSelectedItemPosition()==0?0L:
                    targets.get(additionalHostile.getSelectedItemPosition()-1).optLong("id"));
            if(!preview.optBoolean("monster_roll_preview_valid",false)){
                toast("Ataque indisponível: "+preview.optString("monster_roll_preview_blocked"));return;
            }
            if(preview.optBoolean("second_d20_required",false)?longRoll<1||longRoll>20:longRoll!=0){
                toast("Modo "+preview.optString("roll_mode")+": revise a quantidade de d20.");return;
            }
            final int confirmedRoll=roll,confirmedSecond=longRoll,confirmedDamage=rawDamage,
                confirmedSave=saveRoll,confirmedX=destX,confirmedY=destY;
            final JSONArray confirmedComponents=damageComponents;
            final String confirmedAction=attackSourceNames.get(action.getSelectedItemPosition());
            final long targetId=targets.get(target.getSelectedItemPosition()).optLong("id"),
                hostileId=additionalHostile.getSelectedItemPosition()==0?0L:
                targets.get(additionalHostile.getSelectedItemPosition()-1).optLong("id");
            confirmCoreAction("Confirmar "+DndPtBrLocalizer.localizeText(confirmedAction)+"?\n"+
                "Alvo: "+targets.get(target.getSelectedItemPosition()).optString("name")+
                "\nd20: "+confirmedRoll+" / "+confirmedSecond+" • dano: "+confirmedDamage+
                "\n"+preview.toString(),new Runnable(){public void run(){
                if(applied[0])return;
                JSONObject result;
                if(confirmedComponents.length()>0)result=db.applyCompiledStatblockAttack(actorId,targetId,statblock,
                    confirmedAction,confirmedRoll,confirmedSecond,confirmedComponents,confirmedSave,
                    hostileId,confirmedX,confirmedY,attackToken);
                else result=db.applyCompiledStatblockAttack(actorId,targetId,statblock,
                    confirmedAction,confirmedRoll,confirmedSecond,confirmedDamage,confirmedSave,
                    hostileId,confirmedX,confirmedY,attackToken);
                if(!result.optBoolean("statblock_attack_committed",false)){showXmmResult("Ataque bloqueado",result);return;}
                applied[0]=true;dialog.dismiss();showCombat();showXmmResult("Recibo do ataque",result);
            }});

        }});}});
    }

    /** Show individual physical roll inputs whenever the compiled source
     * declares distinct damage types. The database independently revalidates
     * this exact expression/type order before applying any effect. */
    private void configureMonsterAttackDamageFields(JSONObject profile,String action,
        LinearLayout singleBox,LinearLayout typedBox,EditText aggregate,
        ArrayList<JSONObject> specs,ArrayList<EditText> values){
        configureMonsterAttackDamageFields(profile,action,singleBox,typedBox,aggregate,specs,values,false);
    }
    private void configureMonsterAttackDamageFields(JSONObject profile,String action,
        LinearLayout singleBox,LinearLayout typedBox,EditText aggregate,
        ArrayList<JSONObject> specs,ArrayList<EditText> values,boolean chargeQualified){
        specs.clear();values.clear();typedBox.removeAllViews();
        JSONArray actions=profile==null?null:profile.optJSONArray("actions");JSONObject selected=null;
        for(int i=0;actions!=null&&i<actions.length();i++){
            JSONObject candidate=actions.optJSONObject(i);
            if(candidate!=null&&action.equalsIgnoreCase(candidate.optString("name",""))){selected=candidate;break;}
        }
        String expression=selected==null?"":selected.optString("damage","");
        String extra=selected==null?"":selected.optString("extra_damage","");
        if(selected!=null&&chargeQualified&&!selected.optString("damage_alternative_expression","").isEmpty()){
            expression=selected.optString("damage_alternative_expression");extra="";
        }else if(selected!=null&&!chargeQualified){extra="";}
        JSONArray declared=selected==null?new JSONArray():StatblockCombatFlowEngine.damageSpecs(
            expression,selected.optString("damage_type",""),extra,
            selected.optString("extra_damage_type",selected.optString("damage_type","")));
        if(declared.length()>1){
            for(int i=0;i<declared.length();i++){
                JSONObject spec=declared.optJSONObject(i);if(spec==null)continue;
                try{specs.add(new JSONObject(spec.toString()));}catch(Exception ignored){specs.add(new JSONObject());}
                String componentExpression=spec.optString("expression","dano"),type=spec.optString("type","");
                String label="Total rolado • "+componentExpression+(type.isEmpty()?" • tipo não resolvido":" • "+type);
                typedBox.addView(text(label,12,GOLD,true));
                EditText field=input(label,"0",false);field.setInputType(InputType.TYPE_CLASS_NUMBER);
                typedBox.addView(field);values.add(field);
            }
            typedBox.setVisibility(View.VISIBLE);singleBox.setVisibility(View.GONE);
        }else{
            singleBox.setVisibility(View.VISIBLE);typedBox.setVisibility(View.GONE);
            aggregate.setText("0");
        }
    }

    private boolean refreshMonsterChargeStatus(long actorId,long targetId,String statblock,String action,
        TextView label){
        JSONObject preview=db.previewXmmChargeAttack(actorId,targetId,statblock,action);
        if(!preview.optBoolean("charge_preview_valid",false)){
            label.setVisibility(View.GONE);return false;
        }
        JSONObject charge=preview.optJSONObject("charge");if(charge==null){label.setVisibility(View.GONE);return false;}
        boolean qualified=charge.optBoolean("charge_qualified",false);
        JSONObject sourceAction=null;JSONArray actions=CompiledStatblockEngine.runtimeProfile(statblock).optJSONArray("actions");
        for(int i=0;actions!=null&&i<actions.length();i++){
            JSONObject item=actions.optJSONObject(i);if(item!=null&&action.equalsIgnoreCase(item.optString("name",""))){sourceAction=item;break;}
        }
        String required=String.valueOf(charge.optInt("required_feet",0));
        if(qualified){
            String result="Investida validada: "+required+" pés em linha reta; efeito condicional habilitado.";
            if(sourceAction!=null&&XmmChargeMovementRules.hasConditionalProne(sourceAction))
                result+=charge.optBoolean("charge_prone_eligible",false)?" O alvo também pode ficar Caído.":" O alvo excede o limite de tamanho para Caído.";
            label.setText(result);
        }else label.setText("Investida não validada: o ataque normal continua disponível; dano condicional desativado.");
        label.setVisibility(View.VISIBLE);return qualified;
    }

    /** RUN223: multiattack is offered only for an explicit machine-readable plan.
     * Each roll and target is chosen by the user; one durable transaction commits. */
    private void compiledMonsterMultiattackDialog(final JSONObject monster){
        final String id=parseObjectSafe(monster.optString("resources_json","{}")).optString("block_id","");
        try{
            final JSONObject source=Xmm2025MultiattackPlanIndex.plan(id);
            if(!source.optBoolean("resolved")){compiledMonsterMultiattackDialog(monster,null,null);return;}
            final JSONArray variants=source.optJSONArray("v");
            if(variants==null||variants.length()==0){showXmmResult("Multiataque bloqueado",new JSONObject().put("statblock_multiattack_blocked","complex_multiattack_requires_manual_source_resolution"));return;}
            String[] labels=new String[variants.length()];
            for(int i=0;i<labels.length;i++){
                StringBuilder label=new StringBuilder("Composição "+(i+1)+": ");JSONArray groups=variants.getJSONArray(i);
                for(int g=0;g<groups.length();g++){
                    if(g>0)label.append(" + ");JSONObject group=groups.getJSONObject(g);
                    label.append(group.getInt("c")).append(" × ");JSONArray options=group.getJSONArray("o");
                    for(int o=0;o<options.length();o++){if(o>0)label.append(" / ");label.append(DndPtBrLocalizer.localizeText(options.getString(o)));}
                }labels[i]=label.toString();
            }
            new AlertDialog.Builder(this).setTitle("Composição do multiataque")
                .setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,final int variant){
                    try{
                        final JSONObject selection=new JSONObject().put("variant_index",variant);
                        final Runnable choose=new Runnable(){public void run(){chooseXmmMultiattackSlot(monster,variants.optJSONArray(variant),0,new JSONArray(),selection);}};
                        final JSONObject context=source.optJSONObject("context");
                        if(context==null){choose.run();return;}
                        new AlertDialog.Builder(MainActivity.this).setTitle("Contexto obrigatório")
                            .setMessage(context.optString("field")+" neste turno?")
                            .setPositiveButton("Sim",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){setXmmContext(selection,context,true,choose);}})
                            .setNegativeButton("Não",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){setXmmContext(selection,context,false,choose);}}).show();
                    }catch(Exception e){toast("invalid_source_plan");}
                }}).setNegativeButton("Cancelar",null).show();
        }catch(Exception e){toast("source_plan_unavailable");}
    }
    private void setXmmContext(JSONObject selection,JSONObject context,boolean value,Runnable next){
        try{selection.put(context.getString("field"),value);next.run();}catch(Exception e){toast("invalid_source_context");}
    }
    private void chooseXmmMultiattackSlot(final JSONObject monster,final JSONArray groups,final int slot,
            final JSONArray choices,final JSONObject selection){
        try{
            JSONArray options=null;int offset=0;
            for(int i=0;i<groups.length();i++){JSONObject group=groups.getJSONObject(i);int n=group.getInt("c");
                if(slot<offset+n){options=group.getJSONArray("o");break;}offset+=n;}
            if(options==null){
                selection.put("selected_actions",choices);
                String id=parseObjectSafe(monster.optString("resources_json","{}")).optString("block_id","");
                JSONObject declared=XmmMultiattackHostPlan.declaration(id,selection);
                if(declared.has("statblock_multiattack_blocked")){showXmmResult("Multiataque bloqueado",declared);return;}
                compiledMonsterMultiattackDialog(monster,declared,selection);return;
            }
            final String[] labels=new String[options.length()];for(int i=0;i<labels.length;i++)labels[i]=options.getString(i);
            if(labels.length==1){choices.put(labels[0]);chooseXmmMultiattackSlot(monster,groups,slot+1,choices,selection);return;}
            new AlertDialog.Builder(this).setTitle("Componente "+(slot+1)).setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){choices.put(labels[which]);chooseXmmMultiattackSlot(monster,groups,slot+1,choices,selection);}}).setNegativeButton("Cancelar",null).show();
        }catch(Exception e){toast("invalid_source_components");}
    }
    /** Explicit, local previews. No preview result is submitted as a sheet mutation. */
    private void compiledMonsterEffectPreviewDialog(final JSONObject monster){
        final String id=parseObjectSafe(monster.optString("resources_json","{}")).optString("block_id","");
        try{
            final ArrayList<JSONObject> profiles=new ArrayList<JSONObject>();final ArrayList<Integer> kinds=new ArrayList<Integer>();
            JSONArray[] catalogs={Xmm2025RecurringDamagePreviewEngine.catalog(),Xmm2025SaveConditionPreviewEngine.catalog(),Xmm2025ZeroHpConditionPreviewEngine.catalog()};
            ArrayList<String> labels=new ArrayList<String>();
            for(int k=0;k<catalogs.length;k++)for(int i=0;i<catalogs[k].length();i++){
                JSONObject row=catalogs[k].getJSONObject(i);if(!id.equals(row.optString("id")))continue;
                profiles.add(row);kinds.add(k);labels.add(DndPtBrLocalizer.localizeText(row.optString("action"))+" • "+new String[]{"periódico","condição / duração","ao chegar a 0 PV"}[k]);
            }
            if(profiles.isEmpty()){showXmmResult("Efeitos",new JSONObject().put("effect_blocked","source_effect_preview_not_registered"));return;}
            new AlertDialog.Builder(this).setTitle("Efeito do bloco compilado").setItems(labels.toArray(new String[labels.size()]),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){compiledMonsterEffectInputs(monster,profiles.get(which),kinds.get(which));}}).setNegativeButton("Cancelar",null).show();
        }catch(Exception e){toast("source_effect_catalog_unavailable");}
    }
    private void compiledMonsterEffectInputs(final JSONObject monster,final JSONObject spec,final int kind){
        final ArrayList<JSONObject> targets=new ArrayList<JSONObject>();
        for(JSONObject row:db.listCombatants())if(row.optLong("id")!=monster.optLong("id"))targets.add(row);
        if(targets.isEmpty()){toast("persisted_target_required");return;}
        String[] names=new String[targets.size()];for(int i=0;i<names.length;i++)names[i]=targets.get(i).optString("name");
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),dp(8),dp(12),dp(8));
        form.addView(text("Efeito oficial do D&D Monster Manual 2025 com aplicação atômica e persistente em combate.",12,MUTED,false));
        final Spinner target=spinner(names,names[0]);form.addView(cardWithLabel("ALVO PERSISTIDO",target));
        final String[] fields=kind==0?new String[]{"lifecycle_active"}:kind==1?new String[]{"save_succeeded","target_eligibility_confirmed","prerequisite_confirmed"}:new String[]{"attack_hit","target_reduced_to_zero_hp"};
        String[] captions=kind==0?new String[]{"Vínculo / condição continua ativo?"}:kind==1?new String[]{"Salvaguarda teve sucesso?","Alvo elegível segundo a fonte?","Pré-requisito confirmado?"}:new String[]{"Ataque acertou?","Este ataque reduziu o alvo a 0 PV?"};
        final Spinner[] answers=new Spinner[fields.length];for(int i=0;i<fields.length;i++){answers[i]=spinner(new String[]{"Escolha","Sim","Não"},"Escolha");form.addView(cardWithLabel(captions[i],answers[i]));}
        final EditText damage=kind==0?labeledField(form,"Dano periódico rolado ("+spec.optString("damage")+")","",false):null;
        final Spinner boundary=kind==0?spinner(new String[]{"Escolha","target_turn_start","source_turn_start"},"Escolha"):null;
        if(boundary!=null)form.addView(cardWithLabel("LIMITE DO TURNO",boundary));
        form.addView(text("Fonte: "+spec.optString("source_pointer",spec.optString("ptr"))+"\n"+spec.toString(),11,MUTED,false));
        final AlertDialog effectDialog=new AlertDialog.Builder(this).setTitle("Escolhas do efeito")
            .setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setPositiveButton("APLICAR EFEITO",null).create();
        effectDialog.show();effectDialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(
            new View.OnClickListener(){public void onClick(View view){try{
                JSONObject input=new JSONObject().put("monster",spec.getString("id")).put("action",spec.getString("action"))
                    .put("source_pointer",spec.optString("source_pointer",spec.optString("ptr")))
                    .put("source_blob_sha1",Xmm2025RecurringDamagePreviewEngine.SOURCE_BLOB);
                for(int i=0;i<fields.length;i++){if(answers[i].getSelectedItemPosition()==0){toast("explicit_effect_context_required");return;}input.put(fields[i],answers[i].getSelectedItemPosition()==1);}
                if(kind==0){if(boundary.getSelectedItemPosition()==0){toast("explicit_turn_boundary_required");return;}
                    input.put("turn_boundary",String.valueOf(boundary.getSelectedItem())).put("damage_total",Integer.parseInt(value(damage)));}
                JSONObject preview=kind==0?Xmm2025RecurringDamagePreviewEngine.resolve(input):kind==1?Xmm2025SaveConditionPreviewEngine.resolve(input):Xmm2025ZeroHpConditionPreviewEngine.resolve(input);
                long targetId=targets.get(target.getSelectedItemPosition()).optLong("id");
                if(preview.optBoolean("resolved",false)){
                    JSONObject applied=db.applyCompiledMonsterLifecycleEffect(monster.optLong("id"),targetId,spec.getString("id"),spec.getString("action"),kind,preview,"ui-monster-eff-"+java.util.UUID.randomUUID());
                    showXmmResult("Efeito de Monstro Aplicado",applied);
                    showCombat();
                }else{
                    showXmmResult("Efeito bloqueado",preview);
                }
            }catch(Exception e){toast("invalid_manual_effect_inputs");}}});
    }
    private void showXmmResult(final String title,final JSONObject result){
        AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(title)
            .setMessage(result==null?"{}":result.toString()).setPositiveButton("Fechar",null);
        if(result!=null&&result.optBoolean("manual_arbitration_applied",false)){
            final long actorId=result.optJSONObject("actor")!=null?result.optJSONObject("actor").optLong("id",0):activeCombatant().optLong("id",0);
            final String receiptKey=result.optString("receipt_key","");
            b.setNeutralButton("REVERTER ARBITRAGEM",new DialogInterface.OnClickListener(){
                public void onClick(DialogInterface d,int w){
                    JSONObject rev=db.revertXmmManualArbitration(actorId,receiptKey,
                        "ui-monster-arb-rev-"+java.util.UUID.randomUUID());
                    if(!rev.optBoolean("manual_arbitration_reverted",false)){
                        toast("Reversão bloqueada: "+rev.optString("manual_arbitration_revert_blocked","erro"));return;
                    }
                    showCombat();showXmmResult("Arbitragem revertida",rev);
                }});
        }else if(result!=null&&(result.has("xmm_action_blocked")||result.has("effect_commit_blocked")||
                result.has("statblock_multiattack_blocked")||result.optBoolean("preview_only",false))){
            final JSONObject active=activeCombatant();
            if(active.length()>0&&active.optInt("is_player",0)==0){
                final String ref=result.optString("source_pointer",result.optString("action","Multiattack"));
                final String reason=result.optString("blocker_reason",
                    result.optString("effect_commit_blocked",result.optString("statblock_multiattack_blocked","")));
                b.setNeutralButton("ARBITRAR MANUALMENTE",new DialogInterface.OnClickListener(){
                    public void onClick(DialogInterface d,int w){
                        compiledMonsterManualArbitrationDialog(active,ref,reason);
                    }});
            }
        }
        b.show();
    }
    private void compiledMonsterManualArbitrationDialog(final JSONObject monster,final String initialRef,final String initialBlocker){
        final long actorId=monster.optLong("id",0);
        final JSONObject resources=parseObjectSafe(monster.optString("resources_json","{}"));
        final String statblockId=resources.optString("block_id","").trim();
        if(statblockId.isEmpty()){toast("Este monstro não possui bloco compilado autorizado.");return;}
        final ArrayList<JSONObject> targets=new ArrayList<JSONObject>();
        for(JSONObject row:db.listCombatants())if(row.optLong("id")!=actorId)targets.add(row);
        if(targets.isEmpty()){toast("Não há alvos persistidos no encontro.");return;}
        final String[] targetNames=new String[targets.size()];
        for(int i=0;i<targets.size();i++)targetNames[i]=targets.get(i).optString("name","Alvo")+" (#"+targets.get(i).optLong("id")+")";
        final ArrayList<String> refOptions=new ArrayList<String>();
        if(initialRef!=null&&!initialRef.trim().isEmpty())refOptions.add(initialRef.trim());
        for(XmmCombatSourceRegistry.Entry e:XmmCombatSourceRegistry.entries().values()){
            if(statblockId.equals(e.monster)&&!refOptions.contains(e.pointer))refOptions.add(e.pointer);
        }
        JSONObject profile=CompiledStatblockEngine.runtimeProfile(statblockId);
        if(profile.optJSONObject("multiattack")!=null&&!refOptions.contains("Multiattack"))refOptions.add("Multiattack");
        JSONArray actions=profile.optJSONArray("actions");
        if(actions!=null)for(int i=0;i<actions.length();i++){
            JSONObject a=actions.optJSONObject(i);
            if(a!=null&&!a.optString("name","").isEmpty()&&!refOptions.contains(a.optString("name")))
                refOptions.add(a.optString("name"));
        }
        if(refOptions.isEmpty())refOptions.add("Multiattack");
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),dp(8),dp(12),dp(8));
        form.addView(text("Arbitragem manual determinística XMM 2025 • Bloco: "+statblockId+
            (initialBlocker!=null&&!initialBlocker.isEmpty()?"\nMotivo: "+initialBlocker:""),12,MUTED,false));
        final Spinner targetSpinner=spinner(targetNames,targetNames[0]);
        form.addView(cardWithLabel("ALVO PERSISTIDO",targetSpinner));
        final Spinner refSpinner=spinner(refOptions.toArray(new String[0]),refOptions.get(0));
        form.addView(cardWithLabel("AÇÃO / PONTEIRO DA FONTE XMM",refSpinner));
        final Spinner costSpinner=spinner(new String[]{"action","bonus_action","reaction","none"},"action");
        form.addView(cardWithLabel("CUSTO DE ECONOMIA DE TURNO",costSpinner));
        final EditText damageField=labeledField(form,"Dano total arbitrado (0 se nenhum)","0",true);
        final EditText damageTypeField=labeledField(form,"Tipo de dano (ex.: necrotic, psychic, slashing)","",false);
        final EditText addCondField=labeledField(form,"Adicionar condições CSV (ex.: poisoned, grappled)","",false);
        final EditText remCondField=labeledField(form,"Remover condições CSV","",false);
        final EditText noteField=labeledField(form,"Nota de arbitragem para o recibo causal","Arbitragem manual XMM confirmada",false);
        AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle("Arbitragem Manual • XMM")
            .setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null)
            .setPositiveButton("PRÉVIA E CONFIRMAR",null);
        final String lastReceiptKey=resources.optString("last_xmm_manual_arbitration_receipt","");
        if(!lastReceiptKey.isEmpty()){
            builder.setNeutralButton("REVERTER ÚLTIMA",new DialogInterface.OnClickListener(){
                public void onClick(DialogInterface d,int w){
                    JSONObject rev=db.revertXmmManualArbitration(actorId,lastReceiptKey,
                        "ui-monster-arb-rev-"+java.util.UUID.randomUUID());
                    if(!rev.optBoolean("manual_arbitration_reverted",false)){
                        toast("Reversão bloqueada: "+rev.optString("manual_arbitration_revert_blocked","erro"));return;
                    }
                    showCombat();showXmmResult("Arbitragem revertida",rev);
                }});
        }
        final AlertDialog dlg=builder.create();
        dlg.show();
        dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){
            public void onClick(View v){
                try{
                    final long targetId=targets.get(targetSpinner.getSelectedItemPosition()).optLong("id");
                    final String selectedRef=String.valueOf(refSpinner.getSelectedItem());
                    final String selectedCost=String.valueOf(costSpinner.getSelectedItem());
                    String rawDmg=value(damageField);
                    final int dmg=rawDmg.isEmpty()?0:Integer.parseInt(rawDmg);
                    final String dmgType=value(damageTypeField);
                    final String addCond=value(addCondField);
                    final String remCond=value(remCondField);
                    final String note=value(noteField);
                    JSONObject preview=db.previewXmmManualArbitration(actorId,targetId,statblockId,
                        selectedRef,selectedCost,dmg,dmgType,addCond,remCond);
                    if(preview.has("manual_arbitration_blocked")||preview.has("manual_arbitration_error")){
                        toast("Arbitragem bloqueada: "+preview.optString("manual_arbitration_blocked",
                            preview.optString("manual_arbitration_error","erro")));
                        return;
                    }
                    new AlertDialog.Builder(MainActivity.this).setTitle("Confirmar arbitragem manual XMM")
                        .setMessage("Confirmar aplicação determinística no SQLite?\n\n"+preview.toString())
                        .setNegativeButton("Voltar",null)
                        .setPositiveButton("CONFIRMAR E APLICAR",new DialogInterface.OnClickListener(){
                            public void onClick(DialogInterface d2,int w2){
                                JSONObject applied=db.applyXmmManualArbitration(actorId,targetId,statblockId,
                                    selectedRef,selectedCost,dmg,dmgType,addCond,remCond,true,note,
                                    "ui-monster-arb-"+java.util.UUID.randomUUID());
                                if(!applied.optBoolean("manual_arbitration_applied",false)){
                                    toast("Não aplicado: "+applied.optString("manual_arbitration_blocked","erro"));
                                    return;
                                }
                                dlg.dismiss();showCombat();showXmmResult("Recibo de Arbitragem Manual XMM",applied);
                            }}).show();
                }catch(Exception ex){toast("Entradas inválidas para arbitragem manual.");}
            }});
    }
    private void compiledMonsterMultiattackDialog(final JSONObject monster,JSONObject sourcePlan,final JSONObject sourceSelection){
        final long actorId=monster.optLong("id",0);
        final String id=parseObjectSafe(monster.optString("resources_json","{}")).optString("block_id","");
        final JSONObject profile=CompiledStatblockEngine.runtimeProfile(id),plan=sourcePlan==null?profile.optJSONObject("multiattack"):sourcePlan;
        if(plan==null){toast("Este bloco não possui multiataque compilado.");return;}
        JSONArray rawSequence=plan.optJSONArray("sequence");String[] sequence=null;
        if(rawSequence!=null){sequence=new String[rawSequence.length()];for(int i=0;i<sequence.length;i++)sequence[i]=rawSequence.optString(i);}
        final int count=plan.optInt("count",sequence==null?0:sequence.length);
        final String fixed=plan.optString("action",""),options=plan.optString("options","");
        String blocked=MultiattackActionRules.declarationBlock(sequence,count,fixed,options);
        if(!blocked.isEmpty()){toast("Multiataque não automatizado: "+blocked);return;}
        final ArrayList<JSONObject> targets=new ArrayList<JSONObject>();
        for(JSONObject row:db.listCombatants())if(row.optLong("id")!=actorId&&row.optInt("hp",0)>0)targets.add(row);
        if(targets.isEmpty()){toast("Não há alvos vivos.");return;}
        final String[] targetNames=new String[targets.size()];
        for(int i=0;i<targets.size();i++)targetNames[i]=targets.get(i).optString("name","Alvo");
        final String[] threatNames=new String[targets.size()+1];threatNames[0]="Nenhum outro inimigo";
        for(int i=0;i<targets.size();i++)threatNames[i+1]=targets.get(i).optString("name","Combatente")+" (#"+targets.get(i).optLong("id")+")";
        final Spinner[] targetSpinners=new Spinner[count],actionSpinners=new Spinner[count],threatSpinners=new Spinner[count];
        final EditText[] attackFields=new EditText[count],longRangeFields=new EditText[count],damageFields=new EditText[count],saveFields=new EditText[count];
        final EditText[] forcedXFields=new EditText[count],forcedYFields=new EditText[count];
        final LinearLayout[] singleDamageBoxes=new LinearLayout[count],typedDamageBoxes=new LinearLayout[count];
        final ArrayList<ArrayList<JSONObject>> typedDamageSpecs=new ArrayList<ArrayList<JSONObject>>();
        final ArrayList<ArrayList<EditText>> typedDamageValues=new ArrayList<ArrayList<EditText>>();
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);
        form.setPadding(dp(12),dp(8),dp(12),dp(12));
        form.addView(text("Cada componente exige um d20 natural, dano total rolado (0 se errar) e salvaguarda do efeito (0 quando não houver). " +
            "O aplicativo valida o plano, os alvos, o alcance e a CA antes de consumir UMA única ação. " +
            "Hostilidade registrada é detectada automaticamente. Uma alteração de condição, ameaça " +
            "ou geometria durante a sequência reverte a transação inteira.",12,MUTED,false));
        for(int i=0;i<count;i++){
            final int stepIndex=i;
            form.addView(text("ATAQUE "+(i+1)+" DE "+count,14,GOLD,true));
            String[] choices=sequence!=null?new String[]{sequence[i]}:
                !fixed.trim().isEmpty()?new String[]{fixed}:options.split("\\|");
            actionSpinners[i]=spinner(choices,choices[0]);form.addView(cardWithLabel("AÇÃO AUTORIZADA",actionSpinners[i]));
            final ArrayList<JSONObject> stepDamageSpecs=new ArrayList<JSONObject>();
            final ArrayList<EditText> stepDamageValues=new ArrayList<EditText>();
            typedDamageSpecs.add(stepDamageSpecs);typedDamageValues.add(stepDamageValues);
            singleDamageBoxes[i]=new LinearLayout(this);singleDamageBoxes[i].setOrientation(LinearLayout.VERTICAL);
            singleDamageBoxes[i].addView(text("DANO TOTAL (0 SE ERROU)",12,GOLD,true));
            damageFields[i]=input("Dano total","0",false);damageFields[i].setInputType(InputType.TYPE_CLASS_NUMBER);
            singleDamageBoxes[i].addView(damageFields[i]);form.addView(singleDamageBoxes[i]);
            typedDamageBoxes[i]=new LinearLayout(this);typedDamageBoxes[i].setOrientation(LinearLayout.VERTICAL);
            typedDamageBoxes[i].setVisibility(View.GONE);form.addView(typedDamageBoxes[i]);
            configureMonsterAttackDamageFields(profile,choices[0],singleDamageBoxes[i],typedDamageBoxes[i],
                damageFields[i],stepDamageSpecs,stepDamageValues);
            final TextView damageHint=text("",11,MUTED,false);form.addView(damageHint);
            actionSpinners[i].setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){
                public void onItemSelected(AdapterView<?> parent,View view,int position,long rowId){
                    String selected=String.valueOf(parent.getItemAtPosition(position));
                    configureMonsterAttackDamageFields(profile,selected,singleDamageBoxes[stepIndex],typedDamageBoxes[stepIndex],
                        damageFields[stepIndex],stepDamageSpecs,stepDamageValues);
                    JSONArray actions=profile.optJSONArray("actions");
                    String hint="Esta ação precisa de um ataque compilado com d20.";
                    for(int j=0;actions!=null&&j<actions.length();j++){
                        JSONObject candidate=actions.optJSONObject(j);
                        if(candidate!=null&&selected.equalsIgnoreCase(candidate.optString("name",""))){
                            String base=candidate.optString("damage",""),extra=candidate.optString("extra_damage","");
                            hint="Dano: "+(base.isEmpty()?"0":base)+(extra.isEmpty()?"":" + "+extra)+
                                " • "+candidate.optString("damage_type","sem tipo")+
                                (candidate.optInt("save_dc",0)>0?" • CD "+candidate.optInt("save_dc"):"");
                            break;
                        }
                    }
                    damageHint.setText(hint);
                }
                public void onNothingSelected(AdapterView<?> parent){}
            });
            targetSpinners[i]=spinner(targetNames,targetNames[0]);form.addView(cardWithLabel("ALVO",targetSpinners[i]));
            threatSpinners[i]=spinner(threatNames,threatNames[0]);
            form.addView(cardWithLabel("OUTRO INIMIGO ADJACENTE (CONFIGURADO OU MANUAL LEGADO)",threatSpinners[i]));
            attackFields[i]=labeledField(form,"Primeiro d20 natural (1–20)","",false);
            longRangeFields[i]=labeledField(form,"Segundo d20 (vantagem/desvantagem; 0 se normal)","0",false);
            saveFields[i]=labeledField(form,"Salvaguarda do efeito (0 se não aplicável)","0",false);
            if(i==count-1){
                form.addView(text("Só o último ataque pode deslocar um alvo. Informe X/Y manualmente se o bloco autorizado exigir push/pull; -1 quando não aplicável.",11,MUTED,false));
                forcedXFields[i]=labeledField(form,"Destino X do último ataque (-1 = sem deslocamento)","-1",false);
                forcedYFields[i]=labeledField(form,"Destino Y do último ataque (-1 = sem deslocamento)","-1",false);
                forcedXFields[i].setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
                forcedYFields[i].setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
            }
            attackFields[i].setInputType(InputType.TYPE_CLASS_NUMBER);
            longRangeFields[i].setInputType(InputType.TYPE_CLASS_NUMBER);
            saveFields[i].setInputType(InputType.TYPE_CLASS_NUMBER);
        }
        ScrollView scroll=new ScrollView(this);scroll.addView(form);
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Multiataque • uma ação")
            .setView(scroll).setNegativeButton("CANCELAR",null).setPositiveButton("REVISAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                final JSONArray rolls=new JSONArray();StringBuilder summary=new StringBuilder("Confirmar "+count+" ataques numa única ação?\n\n");
                for(int i=0;i<count;i++){
                    int natural,longRoll,damage,save,destX=-1,destY=-1;JSONArray damageComponents=new JSONArray();
                    try{natural=Integer.parseInt(value(attackFields[i]).trim());longRoll=Integer.parseInt(value(longRangeFields[i]).trim());
                        damage=Integer.parseInt(value(damageFields[i]).trim());
                        save=Integer.parseInt(value(saveFields[i]).trim());
                        if(forcedXFields[i]!=null)destX=Integer.parseInt(value(forcedXFields[i]).trim());
                        if(forcedYFields[i]!=null)destY=Integer.parseInt(value(forcedYFields[i]).trim());}
                    catch(Exception invalid){toast("Ataque "+(i+1)+": informe todos os valores numéricos.");return;}
                    if(natural<1||natural>20||longRoll<0||longRoll>20||damage<0||damage>100000||save<0||save>100||destX< -1||destY< -1){
                        toast("Ataque "+(i+1)+": valores fora do intervalo.");return;
                    }
                    if(typedDamageSpecs.get(i).size()>1){
                        int sum=0;
                        try{for(int component=0;component<typedDamageSpecs.get(i).size();component++){
                            int rolled=Integer.parseInt(value(typedDamageValues.get(i).get(component)).trim());
                            if(rolled<0||rolled>100000)throw new IllegalArgumentException("damage_component_out_of_range");
                            sum+=rolled;JSONObject spec=typedDamageSpecs.get(i).get(component);
                            damageComponents.put(new JSONObject().put("expression",spec.optString("expression"))
                                .put("damage_type",spec.optString("type")).put("damage_total",rolled));
                        }}catch(Exception invalid){toast("Ataque "+(i+1)+": informe o total de cada componente.");return;}
                        if(sum>0)damage=sum;else damageComponents=new JSONArray();
                    }
                    String action=String.valueOf(actionSpinners[i].getSelectedItem());
                    JSONObject target=targets.get(targetSpinners[i].getSelectedItemPosition());
                    long additionalThreatId=threatSpinners[i].getSelectedItemPosition()==0?0L:
                        targets.get(threatSpinners[i].getSelectedItemPosition()-1).optLong("id");
                    JSONObject preview=db.previewCompiledMonsterAttackRollMode(actorId,target.optLong("id"),id,action,additionalThreatId);
                    if(!preview.optBoolean("monster_roll_preview_valid",false)){
                        toast("Ataque "+(i+1)+" bloqueado: "+preview.optString("monster_roll_preview_blocked"));return;
                    }
                    boolean earlierSameTarget=false;
                    for(int prior=0;prior<i;prior++)if(targets.get(targetSpinners[prior].getSelectedItemPosition())
                        .optLong("id")==target.optLong("id")){earlierSameTarget=true;break;}
                    // If an earlier rider applies a condition, the next roll
                    // mode is derived inside AppDb from the staged condition.
                    // The preview of that later step is advisory, not final.
                    if(!earlierSameTarget&&
                        (preview.optBoolean("second_d20_required",false)?longRoll<1||longRoll>20:longRoll!=0)){
                        toast("Ataque "+(i+1)+" • "+preview.optString("roll_mode")+
                            ": informe "+(preview.optBoolean("second_d20_required",false)?"dois d20":"um d20")+".");return;
                    }
                    try{JSONObject step=new JSONObject().put("target_id",target.optLong("id"))
                        .put("action",action).put("natural",natural)
                        .put("long_range_second_d20",longRoll).put("damage_total",damage)
                        .put("rider_save_roll",save).put("additional_hostile_id",additionalThreatId)
                        .put("forced_destination_x",destX).put("forced_destination_y",destY);
                        if(damageComponents.length()>0)step.put("damage_components",damageComponents);
                        rolls.put(step);}
                    catch(Exception invalid){toast("Não foi possível preparar o ataque "+(i+1));return;}
                    summary.append(i+1).append(". ").append(action).append(" → ").append(target.optString("name"))
                        .append(" • d20 ").append(natural)
                        .append(longRoll>0?" / "+longRoll:"")
                        .append(" • ").append(earlierSameTarget?"modo revalidado após ataques anteriores":
                            preview.optString("roll_mode"))
                        .append(" vs CA ").append(preview.optInt("effective_ac"))
                        .append(" • dano ").append(damage)
                        .append(destX>=0&&destY>=0?" • destino ("+destX+","+destY+")":"")
                        .append(additionalThreatId>0?" • inimigo adjacente #"+additionalThreatId:"").append("\n");
                }
                new AlertDialog.Builder(MainActivity.this).setTitle("Confirmar multiataque")
                    .setMessage(summary.toString()).setNegativeButton("VOLTAR",null)
                    .setPositiveButton("APLICAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
                        JSONObject result=db.applyCompiledStatblockMultiattack(actorId,id,rolls,
                            "ui-monster-multi-"+java.util.UUID.randomUUID(),sourceSelection);
                        if(!result.optBoolean("statblock_multiattack_committed",false)){
                            toast("Multiataque não aplicado: "+result.optString("statblock_multiattack_blocked",
                                result.optString("operation_error","revalidar rolagens e mapa")));return;
                        }
                        dialog.dismiss();showCombat();showXmmResult("Recibo do multiataque",result);
                    }}).show();
            }});
        }});dialog.show();
    }

    private void compiledSlowingBreathBatchDialog(final JSONObject monster) {
        final long actor=monster.optLong("id");
        final String block=parseObjectSafe(monster.optString("resources_json","{}")).optString("block_id");
        if(XmmSaveEffectLedger.dc(block)==0){toast("Este bloco não possui Sopro Lento automatizado.");return;}
        final ArrayList<JSONObject> targets=new ArrayList<JSONObject>();
        final ArrayList<CheckBox> included=new ArrayList<CheckBox>();
        final ArrayList<EditText> saves=new ArrayList<EditText>();
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);
        form.setPadding(dp(12),dp(8),dp(12),dp(12));
        form.addView(text("Marque todas as criaturas no cone de "+XmmSaveEffectLedger.cone(block)+
            " pés, incluindo aliados. Informe o total de cada salvaguarda de Constituição (CD "+
            XmmSaveEffectLedger.dc(block)+"). Uma ação aplica o sopro inteiro. O Mestre confirma o cone; alcance e caminho são conferidos no mapa.",12,MUTED,false));
        for(JSONObject row:db.listCombatants())if(row.optLong("id")!=actor&&row.optInt("hp",0)>0){
            targets.add(row);CheckBox selected=check(row.optString("name"),false);
            included.add(selected);form.addView(selected);
            saves.add(labeledField(form,"Total da salvaguarda de "+row.optString("name"),"",false));
        }
        ScrollView scroll=new ScrollView(this);scroll.addView(form);
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Sopro Lento • cone")
            .setView(scroll).setNegativeButton("CANCELAR",null).setPositiveButton("APLICAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                JSONArray rows=new JSONArray();
                try {
                    for(int i=0;i<targets.size();i++)if(included.get(i).isChecked())
                        rows.put(new JSONObject().put("target_id",targets.get(i).optLong("id"))
                            .put("save_total",Integer.parseInt(value(saves.get(i)).trim())));
                }catch(Exception bad){toast("Informe um total inteiro para cada alvo marcado.");return;}
                if(rows.length()==0){toast("Marque ao menos um alvo do cone.");return;}
                JSONObject result=db.applyCompiledSaveEffectBatch(actor,block,"Slowing Breath",rows,
                    "ui-monster-save-"+java.util.UUID.randomUUID());
                if(!result.optBoolean("save_effect_batch_committed",false)){
                    toast("Sopro preservado sem aplicação: "+result.optString("save_effect_batch_blocked",
                        result.optString("operation_error","confira alvos, salvaguardas e mapa")));return;
                }
                toast("Sopro Lento aplicado a todos os alvos com uma ação.");dialog.dismiss();showCombat();
            }});
        }});dialog.show();
    }

    /** Guided compiled monster action with a target saving throw; damage is supplied after the save. */
    private void compiledMonsterSaveActionDialog(final JSONObject monster){
        final long actorId=monster.optLong("id");final JSONObject resources=parseObjectSafe(monster.optString("resources_json","{}"));final String statblock=resources.optString("block_id","");
        if(statblock.trim().isEmpty()){toast("Este monstro não possui bloco compilado autorizado.");return;}
        final JSONArray declared=CompiledStatblockEngine.runtimeProfile(statblock).optJSONArray("actions");
        final ArrayList<String> names=new ArrayList<String>();final ArrayList<String> sourceNames=new ArrayList<String>();
        final ArrayList<JSONObject> targets=new ArrayList<JSONObject>();for(JSONObject row:db.listCombatants())if(row.optLong("id")!=actorId&&row.optInt("hp",0)>0)targets.add(row);
        if(declared!=null)for(int i=0;i<declared.length();i++){JSONObject a=declared.optJSONObject(i);if(a!=null&&a.optInt("save_dc",0)>0&&!a.has("to_hit")&&
            MonsterActionEconomyGuard.saveAbilityBlock(a.optInt("save_dc",0),
                a.optString("save_ability","")).isEmpty()&&
            (a.optString("category","action").equals("action")||
             a.optString("category","action").equals("bonus_action")||
             a.optString("category","action").equals("bonus"))&&
            CompiledMonsterActionGuard.actionRechargeBlock(a.optString("recharge","")).isEmpty())
            {String sourceName=a.optString("name","Ação");sourceNames.add(sourceName);
             names.add(DndPtBrLocalizer.localizeText(sourceName));}}
        if(names.isEmpty()||targets.isEmpty()){toast(names.isEmpty()?"Este bloco não declara ações de salvaguarda.":"Não há alvo vivo para a ação.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),0);String[] targetNames=new String[targets.size()];for(int i=0;i<targets.size();i++)targetNames[i]=targets.get(i).optString("name","Alvo");
        final Spinner target=spinner(targetNames,targetNames[0]);form.addView(cardWithLabel("ALVO",target));final Spinner action=spinner(names.toArray(new String[0]),names.get(0));form.addView(cardWithLabel("AÇÃO DE SALVAGUARDA",action));
        if(XmmSaveEffectLedger.dc(statblock)>0) {
            form.addView(text("Sopro Lento: o Mestre confirma quais criaturas estão no cone. Não causa dano nem exige recarga. Em uma falha, o alvo fica sem reações, com deslocamento pela metade e pode usar ação OU ação bônus até o fim do próximo turno.",12,MUTED,false));
            Button coneBatch=button("SOPRO LENTO • TODOS OS ALVOS DO CONE",GREEN);
            coneBatch.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                compiledSlowingBreathBatchDialog(monster);
            }});form.addView(coneBatch);
        }
        final EditText save=labeledField(form,"Total da salvaguarda (d20 + bônus)","",false);final EditText damage=labeledField(form,"Dano final após a salvaguarda","0",false);
        final EditText forcedX=labeledField(form,"Empurrar/puxar: célula X de destino (se aplicável)","",false);
        final EditText forcedY=labeledField(form,"Empurrar/puxar: célula Y de destino (se aplicável)","",false);
        form.addView(text("O dano informado já deve refletir sucesso/fracasso; o aplicativo não inventa metade do dano. Para empurrar ou puxar, escolha manualmente uma célula livre no mapa tático (X/Y iniciam em zero). O motor confere distância, direção e obstáculos.",12,MUTED,false));
        Button positionButton=new Button(this);positionButton.setText("VER POSIÇÕES NO MAPA TÁTICO");form.addView(positionButton);
        positionButton.setOnClickListener(new View.OnClickListener(){public void onClick(View ignored){
            JSONObject source=db.tacticalGridPosition(actorId);
            JSONObject dest=db.tacticalGridPosition(targets.get(target.getSelectedItemPosition()).optLong("id"));
            if(source.has("grid_blocked")||dest.has("grid_blocked")){
                toast("Posições táticas indisponíveis; abra o mapa de combate.");return;
            }
            new AlertDialog.Builder(MainActivity.this).setTitle("Mapa tático • células")
                .setMessage("Origem do monstro: ("+source.optInt("cell_x")+", "+source.optInt("cell_y")+")"+
                    "\nAlvo: ("+dest.optInt("cell_x")+", "+dest.optInt("cell_y")+")"+
                    "\nDimensões: "+dest.optInt("width_cells")+" × "+dest.optInt("height_cells")+
                    "\nInforme um destino livre. Empurrar aumenta e puxar reduz a distância até o monstro.")
                .setPositiveButton("OK",null).show();
        }});
        ScrollView saveScroll=new ScrollView(this);saveScroll.addView(form);
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Ação especial de monstro").setView(saveScroll).setNegativeButton("CANCELAR",null).setPositiveButton("APLICAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            int saveRoll,rawDamage;try{saveRoll=Integer.parseInt(value(save));rawDamage=Math.max(0,Integer.parseInt(value(damage)));}catch(Exception bad){toast("Informe números válidos.");return;}
            int destX=-1,destY=-1;
            if(!value(forcedX).trim().isEmpty()||!value(forcedY).trim().isEmpty()){
                try{destX=Integer.parseInt(value(forcedX).trim());destY=Integer.parseInt(value(forcedY).trim());}
                catch(Exception invalid){toast("Informe ambas as coordenadas X/Y do destino.");return;}
            }
            final int confirmedSave=saveRoll,confirmedDamage=rawDamage,confirmedX=destX,confirmedY=destY;
            final String confirmedAction=sourceNames.get(action.getSelectedItemPosition());
            final long targetId=targets.get(target.getSelectedItemPosition()).optLong("id");
            final JSONObject preview=db.previewCompiledStatblockSaveAction(actorId,targetId,statblock,confirmedAction,confirmedSave);
            if(!preview.optBoolean("statblock_save_preview_valid",false)){showXmmResult("Salvaguarda bloqueada",preview);return;}
            final String token="ui-monster-save-"+java.util.UUID.randomUUID();
            confirmCoreAction("Confirmar "+DndPtBrLocalizer.localizeText(confirmedAction)+"?\nAlvo: "+
                targets.get(target.getSelectedItemPosition()).optString("name")+
                "\nSalvaguarda: "+confirmedSave+" • dano rolado: "+confirmedDamage+
                "\n"+preview.toString()+"\nO mapa e a fonte serão revalidados na transação.",new Runnable(){public void run(){
                JSONObject result=db.applyCompiledStatblockSaveAction(actorId,targetId,statblock,
                    confirmedAction,confirmedSave,confirmedDamage,confirmedX,confirmedY,token);
                if(!result.optBoolean("statblock_save_committed",false)){showXmmResult("Salvaguarda bloqueada",result);return;}
                dialog.dismiss();showCombat();showXmmResult("Recibo da salvaguarda",result);
            }});

        }});}});dialog.show();
    }

    private void compiledMonsterNextAttackBonusDialog(final JSONObject monster){
        final long actorId=monster.optLong("id");
        final String block=parseObjectSafe(monster.optString("resources_json","{}"))
            .optString("block_id","");
        JSONArray actions=CompiledStatblockEngine.runtimeProfile(block).optJSONArray("special_actions");
        final ArrayList<String> names=new ArrayList<String>(),sourceNames=new ArrayList<String>();
        if(actions!=null)for(int i=0;i<actions.length();i++){
            JSONObject a=actions.optJSONObject(i);
            if(a!=null&&a.optBoolean("grants_advantage_next_attack_this_turn",false)){
                String name=a.optString("name","");sourceNames.add(name);
                names.add(DndPtBrLocalizer.localizeText(name));
            }
        }
        if(names.isEmpty()){toast("Este bloco não declara essa ação bônus executável.");return;}
        final Spinner action=spinner(names.toArray(new String[0]),names.get(0));
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);
        form.setPadding(dp(12),0,dp(12),0);form.addView(cardWithLabel("AÇÃO BÔNUS",action));
        form.addView(text("A vantagem fica vinculada ao próximo ataque deste turno e é consumida mesmo se errar.",12,MUTED,false));
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Ação bônus de monstro")
            .setView(form).setNegativeButton("CANCELAR",null).setPositiveButton("APLICAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){
                public void onClick(View v){
                    JSONObject result=db.applyCompiledStatblockNextAttackAdvantage(actorId,block,
                        sourceNames.get(action.getSelectedItemPosition()),"ui-monster-bonus-"+
                            java.util.UUID.randomUUID());
                    if(!result.optBoolean("statblock_bonus_committed",false)){
                        toast("Ação bônus não aplicada: "+result.optString("statblock_bonus_blocked","revise o bloco"));
                        return;
                    }
                    toast("A próxima rolagem de ataque terá vantagem.");dialog.dismiss();showCombat();
                }
            });
        }});dialog.show();
    }

    /** Guided d6 recharge for a compiled monster action; the roll is explicit and durable. */
    private void compiledMonsterRechargeDialog(final JSONObject monster){
        final long actorId=monster.optLong("id");
        final JSONObject resources=parseObjectSafe(monster.optString("resources_json","{}"));
        final String statblock=resources.optString("block_id","");
        if(statblock.trim().isEmpty()){toast("Este monstro não possui bloco compilado autorizado.");return;}
        final JSONArray declared=CompiledStatblockEngine.runtimeProfile(statblock).optJSONArray("actions");
        final ArrayList<String> names=new ArrayList<String>();final ArrayList<String> sourceNames=new ArrayList<String>();
        if(declared!=null)for(int i=0;i<declared.length();i++){JSONObject a=declared.optJSONObject(i);if(a!=null&&CompiledMonsterActionGuard.diceRecharge(a.optString("recharge",""))){String sourceName=a.optString("name","Ação");sourceNames.add(sourceName);names.add(DndPtBrLocalizer.localizeText(sourceName));}}
        if(names.isEmpty()){toast("Este bloco não declara ações com recarga.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),0);
        final Spinner action=spinner(names.toArray(new String[0]),names.get(0));form.addView(cardWithLabel("AÇÃO COM RECARGA",action));
        final EditText d6=labeledField(form,"Resultado do d6 (1–6)","",false);
        form.addView(text("A recarga só fica disponível quando o d6 atende a faixa do bloco compilado.",12,MUTED,false));
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Recarregar ação de monstro")
            .setView(form).setNegativeButton("CANCELAR",null).setPositiveButton("APLICAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            int roll;try{roll=Integer.parseInt(value(d6));}catch(Exception bad){toast("Informe um d6 válido.");return;}
            JSONObject result=db.rechargeCompiledStatblockAction(actorId,statblock,sourceNames.get(action.getSelectedItemPosition()),roll,"ui-monster-recharge-"+java.util.UUID.randomUUID());
            if(!result.optBoolean("statblock_recharge_committed",false)){toast("Recarga não aplicada: "+result.optString("statblock_recharge_blocked","revise o bloco"));return;}
            JSONObject resolved=result.optJSONObject("resolved");toast(resolved!=null&&resolved.optBoolean("recharged",false)?"Ação recarregada.":"Ação continua indisponível.");dialog.dismiss();showCombat();
        }});}});dialog.show();
    }

    // RUN192_ATTACK_PREVIEW: deterministic d20 + cover, never mutates HP or spends resources.
    private void addCombatAttackPanel(LinearLayout parent){
        final List<JSONObject> roster=db.listCombatants();
        if(roster.size()<2)return;
        LinearLayout panel=card();
        panel.addView(text("ATAQUE GUIADO • D20",15,GOLD,true));
        panel.addView(text("Escolha quem ataca e o alvo. O aplicativo resolve acerto, 1/20 naturais e cobertura. Dano, ação e reação exigem confirmação separada.",12,MUTED,false));
        final String[] names=new String[roster.size()];
        for(int i=0;i<roster.size();i++)names[i]=roster.get(i).optString("name","Combatente");
        final Spinner attacker=spinner(names,names[0]);
        final Spinner target=spinner(names,names[roster.size()-1]);
        panel.addView(cardWithLabel("QUEM ATACA",attacker));
        panel.addView(cardWithLabel("ALVO",target));
        final EditText bonus=labeledField(panel,"Bônus de ataque da ficha (pode ser negativo)","0",false);
        bonus.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
        final Spinner mode=spinner(new String[]{"Normal","Vantagem","Desvantagem"},"Normal");
        panel.addView(cardWithLabel("TIPO DE ROLAGEM",mode));
        Button resolve=button("🎲 ROLAR E VERIFICAR ACERTO",GOLD);
        resolve.setTextColor(Color.BLACK);
        resolve.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            int a=attacker.getSelectedItemPosition(),t=target.getSelectedItemPosition();
            if(a<0||t<0||a>=roster.size()||t>=roster.size()||a==t){toast("Escolha combatentes diferentes.");return;}
            final int attackBonus;
            try{attackBonus=Integer.parseInt(value(bonus).trim());}catch(Exception invalid){bonus.setError("Informe o bônus numérico da ficha.");return;}
            if(attackBonus< -30||attackBonus>60){bonus.setError("Bônus fora do intervalo de segurança.");return;}
            final JSONObject actor=roster.get(a);
            final long targetId=roster.get(t).optLong("id",0);
            JSONObject defender=db.getCombatant(targetId);
            if(defender.length()==0){toast("Alvo não existe mais.");return;}
            JSONObject defenses=parseJsonObject(defender.optString("resources_json","{}"));
            if(rulesEngine.hasTotalCover(defenses.optString("cover",""))){toast("Cobertura total: alvo não pode ser escolhido para este ataque direto.");return;}
            final String rollMode=String.valueOf(mode.getSelectedItem());
            final String formula="d20"+(attackBonus>=0?"+":"")+attackBonus;
            rollDiceInteractive(formula,rollMode,actor.optString("name"),actor.optInt("is_player")==1?actor.optLong("source_id",0):0,new DiceUiCallback(){
                public void done(DiceResult dice){
                    if(dice.natural<1||dice.natural>20){toast("Rolagem sem face natural válida. Nada foi aplicado.");return;}
                    JSONObject live=db.getCombatant(targetId);
                    if(live.length()==0){toast("O alvo foi removido. Nada foi aplicado.");return;}
                    JSONObject state=parseJsonObject(live.optString("resources_json","{}"));
                    String cover=state.optString("cover","");
                    if(rulesEngine.hasTotalCover(cover)){toast("O alvo passou a ter cobertura total. Nenhum ataque foi aplicado.");return;}
                    int armor=live.optInt("ac",10)+rulesEngine.coverAcBonus(cover);
                    JSONObject result=rulesEngine.resolveAttack(dice.natural,attackBonus,armor,false,false);
                    boolean hit=result.optBoolean("hit",false);
                    String summary="d20 "+dice.natural+" "+(attackBonus>=0?"+ ":"− ")+Math.abs(attackBonus)+" = "+result.optInt("total")
                        +" contra CA "+armor+(cover.length()>0?" ("+cover+")":"")
                        +"\n"+(result.optBoolean("critical",false)?"ACERTO CRÍTICO (20 natural)":result.optBoolean("automatic_miss",false)?"ERRO AUTOMÁTICO (1 natural)":hit?"ACERTO":"ERRO");
                    long history=recordDiceHistory(formula,rollMode,actor.optString("name"),actor.optInt("is_player")==1?actor.optLong("source_id",0):0,dice,new JSONObject());
                    if(history>0)db.addAuditEvent("combate","Ataque D20 calculado (sem dano)",actor.optString("name")+" → "+live.optString("name")+"; "+summary,"{}",result.toString(),false);
                    AlertDialog.Builder notice=new AlertDialog.Builder(MainActivity.this)
                        .setTitle("Resultado do ataque").setMessage(summary+"\n\nO ataque não gastou recursos nem alterou PV. Registre o dano apenas após confirmar o acerto e o valor rolado.")
                        .setNegativeButton("FECHAR",null);
                    if(hit)notice.setPositiveButton("ABRIR DANO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
                        JSONObject stillThere=db.getCombatant(targetId);
                        if(stillThere.length()>0)combatDamageDialog(stillThere);
                    }});
                    notice.show();
                }
            });
        }});
        panel.addView(resolve);
        JSONObject active=activeCombatant();
        if(active.length()>0&&active.optInt("is_player",0)==1&&"character".equals(active.optString("source_kind"))){
            final JSONObject hero=active;
            Button real=button("EXECUTAR ATAQUE ÚNICO • AÇÃO + DANO + RECIBO",GREEN);
            real.setOnClickListener(new View.OnClickListener(){public void onClick(View v){partySingleWeaponAttackDialog(hero);}});
            panel.addView(real);
            if(db.extraAttackCapacity(hero.optLong("source_id",0))>=2){
                Button extra=button("ATAQUE EXTRA • UMA AÇÃO, VÁRIOS ATAQUES",GREEN);
                extra.setOnClickListener(new View.OnClickListener(){public void onClick(View v){partyExtraAttackDialog(hero);}});
                panel.addView(extra);
            }
            Button twoWeapons=button("DUAS ARMAS • ATAQUE COM AÇÃO BÔNUS",GREEN);
            twoWeapons.setOnClickListener(new View.OnClickListener(){public void onClick(View v){partyTwoWeaponAttackDialog(hero);}});
            panel.addView(twoWeapons);
            Button setup=button("CONFIGURAR ARMA EQUIPADA • FICHA",PANEL2);
            setup.setOnClickListener(new View.OnClickListener(){public void onClick(View v){configureEquippedWeaponDialog(hero);}});
            panel.addView(setup);
        }
        if(active.length()>0&&active.optInt("is_player",0)!=1){
            Button hostility=button("CONFIGURAR INIMIGOS DO MONSTRO • HOSTILIDADE",PANEL2);
            hostility.setOnClickListener(new View.OnClickListener(){public void onClick(View v){compiledMonsterHostilityDialog(active);}});
            panel.addView(hostility);
            Button monsterAttack=button("ATAQUE DE MONSTRO • BLOCO COMPILADO",GREEN);
            monsterAttack.setOnClickListener(new View.OnClickListener(){public void onClick(View v){compiledMonsterAttackDialog(active);}});
            panel.addView(monsterAttack);
            JSONObject monsterProfile=CompiledStatblockEngine.runtimeProfile(
                parseObjectSafe(active.optString("resources_json","{}")).optString("block_id",""));
            Button monsterMulti=button("MULTIATAQUE DO MONSTRO • UMA AÇÃO",GREEN);
            monsterMulti.setOnClickListener(new View.OnClickListener(){public void onClick(View v){compiledMonsterMultiattackDialog(active);}});
            panel.addView(monsterMulti);
            Button longEffects=button("EFEITOS LONGOS E PERIÓDICOS • PRÉVIA",PANEL2);
            longEffects.setOnClickListener(new View.OnClickListener(){public void onClick(View v){compiledMonsterEffectPreviewDialog(active);}});
            panel.addView(longEffects);
            Button monsterSave=button("AÇÃO ESPECIAL • SALVAGUARDA",GREEN);
            monsterSave.setOnClickListener(new View.OnClickListener(){public void onClick(View v){compiledMonsterSaveActionDialog(active);}});
            panel.addView(monsterSave);
            JSONArray bonusActions=monsterProfile.optJSONArray("special_actions");boolean hasNextAttackBonus=false;
            for(int i=0;bonusActions!=null&&i<bonusActions.length();i++){
                JSONObject action=bonusActions.optJSONObject(i);
                if(action!=null&&action.optBoolean("grants_advantage_next_attack_this_turn",false))
                    hasNextAttackBonus=true;
            }
            if(hasNextAttackBonus){Button monsterBonus=button("AÇÃO BÔNUS • EFEITO COMPILADO",GREEN);
                monsterBonus.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                    compiledMonsterNextAttackBonusDialog(active);
                }});
                panel.addView(monsterBonus);
            }
            Button monsterRecharge=button("RECARREGAR AÇÃO • D6 DO BLOCO",PANEL2);
            monsterRecharge.setOnClickListener(new View.OnClickListener(){public void onClick(View v){compiledMonsterRechargeDialog(active);}});
            panel.addView(monsterRecharge);
            Button monsterManualArb=button("ARBITRAGEM MANUAL DA FONTE • XMM",PANEL2);
            monsterManualArb.setOnClickListener(new View.OnClickListener(){public void onClick(View v){compiledMonsterManualArbitrationDialog(active,"","");}});
            panel.addView(monsterManualArb);
        }
        parent.addView(panel);
    }

    private void addCombatNarrativePanel(LinearLayout parent,final JSONObject state){
        LinearLayout narrative=card();narrative.addView(text("NARRATIVA DA BATALHA",14,GOLD,true));String latest=prefs.getString("last_combat_narration","");if(latest.trim().length()==0&&state.optInt("running",0)==1)latest=lastNarration;
        TextView body=text(latest.trim().length()==0?"O bloco acompanhará cada batida narrada entre o início e o fim do combate.":stripMarkdown(latest),14,TEXT,false);body.setLineSpacing(0,1.12f);narrative.addView(body);
        final List<JSONObject> combatants=db.listCombatants();String[] names=new String[Math.max(1,combatants.size())];if(combatants.isEmpty())names[0]="Grupo";else for(int i=0;i<combatants.size();i++)names[i]=combatants.get(i).optString("name","Combatente");final Spinner actor=spinner(names,activeCombatantName().length()>0?activeCombatantName():names[0]);narrative.addView(actor);
        final EditText action=input("Descreva movimento, ataque, magia, fala ou outra ação desta rodada.","",true);action.setMinLines(2);narrative.addView(action);
        LinearLayout buttons=new LinearLayout(this);buttons.setOrientation(LinearLayout.HORIZONTAL);Button resolve=smallButton(aiBusy?"AGUARDE...":"RESOLVER COM O MESTRE",GOLD);resolve.setTextColor(Color.BLACK);resolve.setEnabled(!aiBusy&&state.optInt("running",0)==1);Button master=smallButton("ABRIR MESTRE IA",PANEL2);
        resolve.setOnClickListener(new View.OnClickListener(){public void onClick(View v){String declared=action.getText().toString().trim();if(declared.length()==0){toast("Descreva a ação do combatente.");return;}String who=String.valueOf(actor.getSelectedItem());String prompt="COMBATE EM ANDAMENTO — rodada "+state.optInt("round_no",1)+". "+who+" declara: "+declared+". Resolva somente esta batida usando iniciativa, posição tática, ficha, regras recuperadas e estado real do combate. Preserve a narrativa no bloco de combate e proponha as consequências estruturadas necessárias.";prefs.edit().putString("pending_combat_actor",who).apply();sendAi("Narrador",prompt);setStatus("O Mestre está resolvendo a ação de "+who+"…");}});
        master.setOnClickListener(new View.OnClickListener(){public void onClick(View v){navigate("Mestre IA");}});buttons.addView(resolve,new LinearLayout.LayoutParams(0,dp(50),2));buttons.addView(master,new LinearLayout.LayoutParams(0,dp(50),1));narrative.addView(buttons);parent.addView(narrative);
    }

    private JSONObject activeCombatant(){for(JSONObject combatant:db.listCombatants())if(combatant.optInt("active_turn",0)==1)return combatant;return new JSONObject();}
    private String activeCombatantName(){return activeCombatant().optString("name","");}

    private void combatantInfoDialog(final JSONObject combatant){
        final boolean player=combatant.optInt("is_player",0)==1;
        final String name=combatant.optString("name","Combatente");
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);
        LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(12),dp(8),dp(12),dp(24));body.setBackgroundColor(BG);
        LinearLayout header=card();header.addView(text(name.toUpperCase(new Locale("pt","BR")),22,player?GOLD:TEXT,true));header.addView(text(player?"HERÓI":"NPC / INIMIGO",12,MUTED,true));
        Button portraitBtn=button("✦ GERAR RETRATO NO GEMINI",GOLD);portraitBtn.setTextColor(Color.BLACK);portraitBtn.setOnClickListener(new View.OnClickListener(){public void onClick(View v){beginPortraitForCombatant(combatant);}});
        header.addView(portraitBtn);body.addView(header);
        StringBuilder vital=new StringBuilder();
        vital.append("Iniciativa ").append(combatant.optInt("initiative",0));
        if(combatant.optInt("active_turn",0)==1)vital.append(" • TURNO ATUAL");
        vital.append("\nPV ").append(combatant.optInt("hp",0)).append('/').append(combatant.optInt("max_hp",0));
        if(combatant.optInt("temp_hp",0)>0)vital.append(" + ").append(combatant.optInt("temp_hp")).append(" temporários");
        vital.append(" • CA ").append(combatant.optInt("ac",0));
        addSheetSection(body,"STATUS DE COMBATE",vital.toString());
        StringBuilder state=new StringBuilder();
        if(combatant.optString("conditions").trim().length()>0)state.append("Condições: ").append(combatant.optString("conditions")).append('\n');
        if(combatant.optString("concentration").trim().length()>0)state.append("Concentração: ").append(combatant.optString("concentration")).append('\n');
        state.append("Reação: ").append(combatant.optInt("reaction_used",0)==1?"já utilizada":"disponível");
        try { if(!"mystara".equals(db.getActiveMapProfile())&&XmmSaveEffectLedger.slowed(
                parseObjectSafe(combatant.optString("resources_json","{}")),combatant.optLong("id")))
            state.append("\nSopro Lento: sem reações; deslocamento pela metade; ação OU ação bônus. Termina no fim do próximo turno.");
        } catch(Exception invalid) { state.append("\nEfeito de sopro inválido: confira os dados de combate."); }
        if(combatant.optInt("death_success",0)+combatant.optInt("death_fail",0)>0)state.append("\nMorte: ").append(combatant.optInt("death_success",0)).append(" sucessos • ").append(combatant.optInt("death_fail",0)).append(" falhas");
        addSheetSection(body,"CONDIÇÕES E TURNO",state.toString());
        StringBuilder defenses=new StringBuilder();
        if(combatant.optString("resistances").trim().length()>0)defenses.append("Resistências: ").append(combatant.optString("resistances")).append('\n');
        if(combatant.optString("vulnerabilities").trim().length()>0)defenses.append("Vulnerabilidades: ").append(combatant.optString("vulnerabilities")).append('\n');
        if(combatant.optString("immunities").trim().length()>0)defenses.append("Imunidades: ").append(combatant.optString("immunities"));
        addSheetSection(body,"DEFESAS ESPECIAIS",defenses.toString());
        addSheetSection(body,"DURAÇÕES",prettyCombatJson(combatant.optString("condition_timers_json","[]")));
        addSheetSection(body,"RECURSOS",prettyCombatJson(combatant.optString("resources_json","{}")));

        final JSONObject character=player?db.findCharacterByName(name):new JSONObject();
        if(character.length()>0){
            String cls=character.optString("class_name",character.optString("class",""));
            String species=character.optString("species",character.optString("race",""));
            addSheetSection(body,"RESUMO DA FICHA",species+(species.length()>0&&cls.length()>0?" • ":"")+cls+(cls.length()>0?" • nível "+character.optInt("level",1):""));
            String attrs="FOR "+character.optInt("str",10)+" • DES "+character.optInt("dex",10)+" • CON "+character.optInt("con",10)+" • INT "+character.optInt("int_score",10)+" • SAB "+character.optInt("wis",10)+" • CAR "+character.optInt("cha",10);
            addSheetSection(body,"ATRIBUTOS",attrs);
            addSheetSection(body,"ATAQUES",character.optString("attacks"));
            addSheetSection(body,"RECURSOS E TRAÇOS",character.optString("features"));
            addSheetSection(body,"MAGIAS",character.optString("spells"));
            addSheetSection(body,"INVENTÁRIO",character.optString("inventory",character.optString("equipment")));
            Button full=button("ABRIR FICHA COMPLETA",GOLD);full.setTextColor(Color.BLACK);full.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showCharacterSheetDialog(character);}});body.addView(full);
        }else{
            JSONObject memory=db.findNpcMemoryByName(name);
            if(memory.length()>0){
                addSheetSection(body,"RESUMO DO NPC",memory.optString("summary"));
                addSheetSection(body,"ATITUDE E RELAÇÃO",memory.optString("attitude")+(memory.optString("relationship").length()>0?"\n"+memory.optString("relationship"):""));
                addSheetSection(body,"OBJETIVOS",memory.optString("goals"));
                addSheetSection(body,"CONHECIMENTO",memory.optString("knowledge"));
                addSheetSection(body,"ÚLTIMA APARIÇÃO",memory.optString("last_seen"));
                addSheetSection(body,"ESTATÍSTICAS DO NPC",prettyCombatJson(memory.optString("stats_json","{}")));
            }
            JSONObject cognition=db.getNpcCognitiveState(name);
            if(cognition.length()>0){
                String mind="Emoção: "+cognition.optString("emotion","neutro")+"\nConfiança "+cognition.optInt("trust",0)+" • Medo "+cognition.optInt("fear",0)+" • Suspeita "+cognition.optInt("suspicion",0)+" • Urgência "+cognition.optInt("urgency",0);
                if(cognition.optString("next_action").length()>0)mind+="\nPróxima ação: "+cognition.optString("next_action");
                if(cognition.optString("faction").length()>0)mind+="\nFacção: "+cognition.optString("faction");
                if(cognition.optString("current_location").length()>0)mind+="\nLocal: "+cognition.optString("current_location");
                addSheetSection(body,"ESTADO DO NPC",mind);
            }
        }
        List<JSONObject> guildMemberships=player&&character.length()>0?db.listGuildMembershipsForHero(character.optLong("id")):db.listGuildMembershipsForNpc(name);
        if(!guildMemberships.isEmpty()){StringBuilder guildSummary=new StringBuilder();for(JSONObject membership:guildMemberships){if(guildSummary.length()>0)guildSummary.append("\n");guildSummary.append(membership.optString("guild_name")).append(" • ").append(membership.optString("rank_name","sem patente")).append(" • reputação ").append(membership.optInt("reputation",0));if(membership.optInt("dues_due_day",0)>0)guildSummary.append(" • taxa pendente desde o dia ").append(membership.optInt("dues_due_day"));}addSheetSection(body,"GUILDAS",guildSummary.toString());}
        scroll.addView(body);
        new AlertDialog.Builder(this).setTitle("Status — "+name).setView(scroll).setNegativeButton("Fechar",null).show();
    }

    private String prettyCombatJson(String raw){
        if(raw==null||raw.trim().length()==0||"{}".equals(raw.trim())||"[]".equals(raw.trim()))return "";
        try{return raw.trim().startsWith("[")?new JSONArray(raw).toString(2):new JSONObject(raw).toString(2);}catch(Exception ignored){return raw;}
    }

    // RUN197_AREA_UI_CONFIRM: guided multi-target effect, no JSON and no automatic character choice.
    private void addCombatAreaEffectPanel(LinearLayout parent){
        final List<JSONObject> roster=db.listCombatants();
        if(roster.isEmpty()||db.getCombatState().optInt("running",0)!=1)return;
        LinearLayout panel=card();panel.addView(text("EFEITO EM ÁREA • DANO / CURA",15,GOLD,true));
        panel.addView(text("Selecione os alvos, o valor já rolado e quem gastará uma ação. Nada é aplicado antes da confirmação. Regras de área, alcance, salvaguardas e metade do dano devem ser resolvidas antes de preencher os valores; esta tela não os presume.",12,MUTED,false));
        Button open=button("PREPARAR EFEITO EM VÁRIOS ALVOS",PANEL2);
        open.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showCombatAreaEffectDialog();}});
        panel.addView(open);parent.addView(panel);
    }
    private void showCombatAreaEffectDialog(){
        final List<JSONObject> roster=db.listCombatants();
        if(roster.isEmpty()){toast("Adicione participantes ao combate.");return;}
        final LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(12),0,dp(12),dp(16));
        final String[] actors=new String[roster.size()];
        for(int i=0;i<roster.size();i++)actors[i]=roster.get(i).optString("name","Combatente");
        final Spinner actor=spinner(actors,actors[0]);body.addView(cardWithLabel("QUEM EXECUTA (SE HOUVER GASTO)",actor));
        final String[] costs={"Sem gastar recurso de turno","Ação","Ação bônus","Reação"};
        final Spinner resource=spinner(costs,costs[1]);body.addView(cardWithLabel("CUSTO DO EFEITO — ESCOLHA MANUAL",resource));
        final String[] kinds={"Dano","Cura"};
        final Spinner kind=spinner(kinds,kinds[0]);body.addView(cardWithLabel("EFEITO APLICADO",kind));
        final EditText amount=labeledField(body,"Valor já rolado por alvo (0 ou maior)","0",false);
        amount.setInputType(InputType.TYPE_CLASS_NUMBER);
        final EditText type=labeledField(body,"Tipo de dano (fogo, frio etc.)", "",false);
        body.addView(text("ALVOS — MARQUE APENAS OS ATINGIDOS",13,GOLD,true));
        final ArrayList<CheckBox> targets=new ArrayList<CheckBox>();
        for(JSONObject c:roster){
            CheckBox choice=check(c.optString("name","Combatente")+" — PV "+c.optInt("hp")+"/"+c.optInt("max_hp"),false);
            targets.add(choice);body.addView(choice);
        }
        final List<JSONObject> narratedActions=narratedCombatDeclarations();
        final Spinner linkedAction=partyCombatActionSelector(body,narratedActions);
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Preparar efeito de área")
            .setView(scrollableDialogView(body)).setNegativeButton("CANCELAR",null)
            .setPositiveButton("REVISAR ANTES DE APLICAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                int points;try{points=Integer.parseInt(value(amount).trim());}catch(Exception invalid){amount.setError("Informe um valor inteiro.");return;}
                if(points<0||points>1000000){amount.setError("Valor fora do limite aceito.");return;}
                String resourceKey=new String[]{"none","action","bonus_action","reaction"}[resource.getSelectedItemPosition()];
                final long actorId=roster.get(actor.getSelectedItemPosition()).optLong("id",0);
                final JSONArray effects=new JSONArray();StringBuilder names=new StringBuilder();
                String actionKind=kind.getSelectedItemPosition()==0?"damage":"healing";
                try{
                    for(int i=0;i<targets.size();i++)if(targets.get(i).isChecked()){
                        JSONObject current=db.getCombatant(roster.get(i).optLong("id",0));
                        if(current.length()==0){toast("Um alvo saiu do combate. Revise a seleção.");return;}
                        JSONObject effect=new JSONObject().put("target_id",current.optLong("id"))
                            .put("kind",actionKind).put("amount",points)
                            .put("expected_hp",current.optInt("hp")).put("expected_temp_hp",current.optInt("temp_hp"));
                        if("damage".equals(actionKind))effect.put("damage_type",value(type).trim());
                        effects.put(effect);if(names.length()>0)names.append(", ");names.append(current.optString("name"));
                    }
                }catch(Exception failed){toast("Não foi possível preparar os alvos.");return;}
                if(effects.length()<1){toast("Escolha ao menos um alvo.");return;}
                if(effects.length()>64){toast("Limite seguro: 64 alvos.");return;}
                int linkedIndex=linkedAction.getSelectedItemPosition();
                if(!validatePartyCombatSelection(linkedIndex,narratedActions,actorId,resourceKey))return;
                String linkLabel=linkedIndex>0?"\nDeclaração vinculada: #"+
                    narratedActions.get(linkedIndex-1).optLong("id")+" • "+
                    narratedActions.get(linkedIndex-1).optString("character_name"):"\nDeclaração vinculada: nenhuma";
                String costSummary=costs[resource.getSelectedItemPosition()];
                String summary="Executor: "+roster.get(actor.getSelectedItemPosition()).optString("name")+
                    "\nCusto: "+costSummary+"\nEfeito: "+kinds[kind.getSelectedItemPosition()]+
                    "\nValor declarado por alvo: "+points+
                    ("damage".equals(actionKind)?"\nTipo: "+value(type).trim():"")+
                    "\nAlvos ("+effects.length()+"): "+names.toString()+linkLabel+
                    "\n\nTodas as alterações e o gasto escolhido serão confirmados juntos ou revertidos juntos. Nenhuma salvaguarda é rolada aqui.";
                new AlertDialog.Builder(MainActivity.this).setTitle("CONFIRMAR EFEITO DE ÁREA")
                    .setMessage(summary).setNegativeButton("VOLTAR E CORRIGIR",null)
                    .setPositiveButton("CONFIRMAR E APLICAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
                        String operationToken="ui-area-"+java.util.UUID.randomUUID();
                        int linkedIndex=linkedAction.getSelectedItemPosition();
                        long linkedId=linkedIndex>0&&linkedIndex<=narratedActions.size()?
                            narratedActions.get(linkedIndex-1).optLong("id"):0;
                        JSONObject out=linkedId>0?
                            db.applyCombatEffectsForPartyAction(linkedId,actorId,resourceKey,effects,operationToken):
                            db.applyCombatEffectsWithAction(actorId,resourceKey,effects,operationToken);
                        if(!out.optBoolean("area_action_committed",false)){
                            toast("Nenhum efeito confirmado: "+out.optString("party_action_blocked",out.optString("area_action_blocked",out.optString("operation_error",out.optString("effects_batch_blocked","revise estado e recursos")))));
                            showCombat();return;
                        }
                        db.addAuditEvent("combate","Efeito em área confirmado",operationToken+" — "+effects.length()+" alvo(s)","{}",out.toString(),true);
                        dialog.dismiss();showCombat();
                    }}).show();
            }});
        }});dialog.show();
    }

    // RUN198_SAVE_AREA_UI: roll each selected target with the real dice UI; no automatic targets.
    private void addCombatSavingAreaPanel(LinearLayout parent){
        if(db.getCombatState().optInt("running",0)!=1||db.listCombatants().isEmpty())return;
        LinearLayout panel=card();panel.addView(text("EFEITO EM ÁREA • SALVAGUARDAS",15,GOLD,true));
        panel.addView(text("Calcula CD, salvaguarda, metade/nenhum dano e Evasão quando aplicável. Rolagens por alvo; resistências e concentração são resolvidas pelo motor de combate. Alcance, cobertura, alvos e espaço de magia ainda exigem validação da habilidade usada.",12,MUTED,false));
        Button open=button("ROLAR SALVAGUARDAS EM ÁREA",PANEL2);
        open.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showCombatSavingAreaDialog();}});
        panel.addView(open);parent.addView(panel);
    }
    private void showCombatSavingAreaDialog(){
        final List<JSONObject> roster=db.listCombatants();if(roster.isEmpty())return;
        final LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);
        final String[] names=new String[roster.size()];for(int i=0;i<names.length;i++)names[i]=roster.get(i).optString("name","Combatente");
        final Spinner actor=spinner(names,names[0]);body.addView(cardWithLabel("QUEM EXECUTA",actor));
        final String[] costs={"Sem gasto","Ação","Ação bônus","Reação"};
        final Spinner cost=spinner(costs,costs[1]);body.addView(cardWithLabel("CUSTO DE TURNO — ESCOLHA MANUAL",cost));
        final String[] abilities={"Destreza","Constituição","Sabedoria","Força","Inteligência","Carisma"};
        final String[] keys={"dex","con","wis","str","int","cha"};
        final Spinner ability=spinner(abilities,abilities[0]);body.addView(cardWithLabel("SALVAGUARDA",ability));
        final EditText dc=labeledField(body,"Classe de Dificuldade (CD)","15",false);dc.setInputType(InputType.TYPE_CLASS_NUMBER);
        final EditText raw=labeledField(body,"Dano total já rolado, antes da salvaguarda","20",false);raw.setInputType(InputType.TYPE_CLASS_NUMBER);
        final EditText damageType=labeledField(body,"Tipo de dano","fogo",false);
        final String[] policies={"Metade no sucesso","Nenhum no sucesso","Dano integral no sucesso"};
        final String[] policyKeys={"half","none","full"};
        final Spinner policy=spinner(policies,policies[0]);body.addView(cardWithLabel("RESULTADO DE SUCESSO",policy));
        body.addView(text("Selecione alvos, confira o bônus e role cada salvaguarda. Vantagem e desvantagem devem ser escolhidas conforme a situação.",12,MUTED,false));
        final ArrayList<CheckBox> selected=new ArrayList<CheckBox>();
        final ArrayList<EditText> bonuses=new ArrayList<EditText>();
        final ArrayList<Spinner> modes=new ArrayList<Spinner>();
        final int[] natural=new int[roster.size()],rollBonus=new int[roster.size()],rollDc=new int[roster.size()];
        final String[] rollAbility=new String[roster.size()],rollMode=new String[roster.size()];
        final boolean[] rolled=new boolean[roster.size()];
        for(int i=0;i<roster.size();i++){
            final int index=i;final JSONObject c=roster.get(i);
            LinearLayout row=card();final CheckBox check=check(c.optString("name","Combatente")+" • PV "+c.optInt("hp")+"/"+c.optInt("max_hp"),false);
            selected.add(check);row.addView(check);
            final EditText bonus=labeledField(row,"Bônus de salvaguarda (NPC: confirme manualmente se não há ficha)","",false);
            bonus.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);bonuses.add(bonus);
            final Spinner mode=spinner(new String[]{"Normal","Vantagem","Desvantagem"},"Normal");modes.add(mode);
            row.addView(cardWithLabel("CONDIÇÃO DA ROLAGEM",mode));
            final TextView result=text("Salvaguarda ainda não rolada",12,MUTED,false);
            Button roll=button("ROLAR 1d20 — "+c.optString("name","Alvo"),PANEL2);
            roll.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                if(!check.isChecked()){toast("Marque este alvo primeiro.");return;}
                int saveDc;try{saveDc=Integer.parseInt(value(dc).trim());}catch(Exception e){dc.setError("CD inválida");return;}
                if(saveDc<1||saveDc>40){dc.setError("CD entre 1 e 40");return;}
                final String saveKey=keys[ability.getSelectedItemPosition()];
                JSONObject info=db.combatantAreaSaveInfo(c.optLong("id"),saveKey);
                if(info.optBoolean("bonus_known",false))bonus.setText(String.valueOf(info.optInt("bonus")));
                final int b;try{b=Integer.parseInt(value(bonus).trim());}catch(Exception e){bonus.setError("Confirme o bônus de salvaguarda.");return;}
                if(b< -50||b>100){bonus.setError("Bônus fora do limite.");return;}
                final String modeName=String.valueOf(mode.getSelectedItem());
                rollDiceInteractive("d20"+(b>=0?"+":"")+b,modeName,c.optString("name"),
                    c.optInt("is_player")==1?c.optLong("source_id",0):0,new DiceUiCallback(){public void done(DiceResult r){
                        natural[index]=r.natural;rollBonus[index]=b;rollDc[index]=saveDc;
                        rollAbility[index]=saveKey;rollMode[index]=modeName;rolled[index]=true;
                        result.setText("d20="+r.natural+" + "+b+" = "+r.total+" vs CD "+saveDc+
                            (r.total>=saveDc?" • SUCESSO":" • FALHA"));
                    }});
            }});
            row.addView(roll);row.addView(result);body.addView(row);
        }
        final List<JSONObject> narratedActions=narratedCombatDeclarations();
        final Spinner linkedAction=partyCombatActionSelector(body,narratedActions);
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Salvaguardas de área")
            .setView(scrollableDialogView(body)).setNegativeButton("CANCELAR",null)
            .setPositiveButton("REVISAR RESULTADOS",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                final int rawAmount,saveDc;try{rawAmount=Integer.parseInt(value(raw).trim());saveDc=Integer.parseInt(value(dc).trim());}
                catch(Exception e){toast("Informe dano inteiro e CD.");return;}
                if(rawAmount<0||rawAmount>1000000||saveDc<1||saveDc>40){toast("Dano ou CD fora do intervalo.");return;}
                final String saveKey=keys[ability.getSelectedItemPosition()],policyKey=policyKeys[policy.getSelectedItemPosition()];
                final JSONArray saves=new JSONArray();StringBuilder summary=new StringBuilder();
                for(int i=0;i<roster.size();i++)if(selected.get(i).isChecked()){
                    if(!rolled[i]||rollDc[i]!=saveDc||!saveKey.equals(rollAbility[i])||
                        !String.valueOf(modes.get(i).getSelectedItem()).equals(rollMode[i])||
                        !String.valueOf(rollBonus[i]).equals(value(bonuses.get(i)).trim())){
                        toast("Role novamente a salvaguarda de "+names[i]+" após conferir os parâmetros.");return;
                    }
                    JSONObject c=db.getCombatant(roster.get(i).optLong("id"));
                    JSONObject info=db.combatantAreaSaveInfo(c.optLong("id"),saveKey);
                    if(c.length()==0||info.has("save_info_error")){toast("Um alvo não está mais disponível.");return;}
                    if(info.optBoolean("bonus_known",false)&&info.optInt("bonus")!=rollBonus[i]){
                        toast("O bônus de "+names[i]+" mudou; role novamente.");return;
                    }
                    try{
                        AreaSaveDamageRules.Outcome o=AreaSaveDamageRules.resolve(rawAmount,saveKey,saveDc,
                            natural[i],rollBonus[i],policyKey,info.optBoolean("evasion"),info.optBoolean("incapacitated"));
                        saves.put(new JSONObject().put("target_id",c.optLong("id")).put("save_ability",saveKey)
                            .put("dc",saveDc).put("d20",natural[i]).put("save_bonus",rollBonus[i])
                            .put("manual_bonus_confirmed",!info.optBoolean("bonus_known",false))
                            .put("raw_damage",rawAmount).put("on_success",policyKey)
                            .put("damage_type",value(damageType).trim())
                            .put("expected_hp",c.optInt("hp")).put("expected_temp_hp",c.optInt("temp_hp")));
                        summary.append("\n").append(names[i]).append(": ").append(o.total).append("/CD ").append(saveDc)
                            .append(o.saved?" sucesso":" falha").append(o.evasionUsed?" • Evasão":"")
                            .append(" → ").append(o.damage).append(" dano antes de resistências");
                    }catch(Exception e){toast("Salvaguarda inválida: "+e.getMessage());return;}
                }
                if(saves.length()<1||saves.length()>64){toast("Selecione entre 1 e 64 alvos.");return;}
                final long actorId=roster.get(actor.getSelectedItemPosition()).optLong("id");
                final String costKey=new String[]{"none","action","bonus_action","reaction"}[cost.getSelectedItemPosition()];
                int linkedIndex=linkedAction.getSelectedItemPosition();
                if(!validatePartyCombatSelection(linkedIndex,narratedActions,actorId,costKey))return;
                String linkLabel=linkedIndex>0?"\nDeclaração vinculada: #"+
                    narratedActions.get(linkedIndex-1).optLong("id")+" • "+
                    narratedActions.get(linkedIndex-1).optString("character_name"):"\nDeclaração vinculada: nenhuma";
                String msg="Executor: "+names[actor.getSelectedItemPosition()]+"\nCusto: "+costs[cost.getSelectedItemPosition()]+
                    "\nDano bruto: "+rawAmount+" "+value(damageType).trim()+"\nRegra: "+policies[policy.getSelectedItemPosition()]+
                    "\n"+summary.toString()+linkLabel+"\n\nConfirmar gasto e efeitos em uma transação?";
                new AlertDialog.Builder(MainActivity.this).setTitle("CONFIRMAR SALVAGUARDAS E DANO")
                    .setMessage(msg).setNegativeButton("VOLTAR",null)
                    .setPositiveButton("CONFIRMAR E APLICAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
                        String token="ui-area-save-"+java.util.UUID.randomUUID();
                        int linkedIndex=linkedAction.getSelectedItemPosition();
                        long linkedId=linkedIndex>0&&linkedIndex<=narratedActions.size()?
                            narratedActions.get(linkedIndex-1).optLong("id"):0;
                        JSONObject out=linkedId>0?
                            db.applyCombatSaveDamageForPartyAction(linkedId,actorId,costKey,saves,token):
                            db.applyCombatSaveDamageWithAction(actorId,costKey,saves,token);
                        if(!out.optBoolean("area_save_committed",false)){
                            toast("Nenhum efeito aplicado: "+out.optString("party_action_blocked",out.optString("area_save_blocked",
                                out.optString("area_action_blocked",out.optString("operation_error","estado alterado")))));
                            showCombat();return;
                        }
                        db.addAuditEvent("combate","Salvaguardas de área confirmadas",token+" • "+saves.length()+" alvos",
                            "{}",out.toString(),true);dialog.dismiss();showCombat();
                    }}).show();
            }});
        }});dialog.show();
    }

    // RUN199_CORE2024_SPELL_UI: guided, no JSON or canonical IDs exposed to players.
    private void addCore2024SpellCastingPanel(LinearLayout parent){
        boolean revised=new DndRulesEngine().is2024(db.getCampaign().optString("rules_profile",""));
        if(!revised)for(JSONObject ch:db.listActiveCharacters())
            if(new DndRulesEngine().is2024(ch.optString("rules_source",""))){revised=true;break;}
        if(!revised)return;
        LinearLayout card=card();card.addView(text("MAGIAS OFICIAIS 2024 • EXECUTOR INTEGRADO",15,GOLD,true));
        card.addView(text("Bola de Fogo, Mãos Flamejantes e Curar Ferimentos. A preparação é validada pelo registro persistente de cada classe (Livro do Jogador 2024). Ação, espaço e efeitos são atômicos. Linha de visão e componentes V/S ainda exigem confirmação.",12,MUTED,false));
        Button manage=button("GERENCIAR MAGIAS PREPARADAS",PANEL2);
        manage.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showCore2024PreparationPicker();}});
        card.addView(manage);
        Button open=button("CONJURAR MAGIA 2024",PANEL2);
        open.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showCore2024SpellDialog();}});
        card.addView(open);
        Button bless=button("CONJURAR BÊNÇÃO — CONCENTRAÇÃO",PANEL2);
        bless.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showCore2024BlessDialog();}});
        card.addView(bless);parent.addView(card);
    }
    // RUN201: player-facing preparation editor. No JSON, internal keys or spell IDs.
    private void showCore2024PreparationPicker(){
        final ArrayList<JSONObject> heroes=new ArrayList<JSONObject>();
        final ArrayList<String> names=new ArrayList<String>();
        for(JSONObject ch:db.listActiveCharacters()){
            String profile=ch.optString("rules_source",db.getCampaign().optString("rules_profile",""));
            if(!new DndRulesEngine().is2024(profile))continue;
            heroes.add(ch);names.add(ch.optString("name","Personagem"));
        }
        if(heroes.isEmpty()){toast("Não há personagens ativos usando as regras de 2024.");return;}
        new AlertDialog.Builder(this).setTitle("MAGIAS PREPARADAS • 2024")
            .setItems(names.toArray(new String[0]),new DialogInterface.OnClickListener(){
                public void onClick(DialogInterface dialog,int which){
                    showCore2024PreparationClassPicker(heroes.get(which).optLong("id"));
                }}).setNegativeButton("Cancelar",null).show();
    }
    private void showCore2024PreparationClassPicker(final long characterId){
        JSONObject preview=db.previewCore2024PreparedSpells(characterId);
        if(!preview.optBoolean("preparation_valid",false)){
            toast("Não foi possível conferir as classes: "+preview.optString("preparation_error","ficha incompleta"));return;
        }
        JSONObject classes=preview.optJSONObject("classes");
        if(classes==null){toast("Não há classes conjuradoras certificadas nesta ficha.");return;}
        final ArrayList<String> ids=new ArrayList<String>(),names=new ArrayList<String>();
        java.util.Iterator<String> keys=classes.keys();
        while(keys.hasNext()){
            String cls=keys.next();JSONObject view=classes.optJSONObject(cls);
            if(view==null)continue;
            ids.add(cls);names.add(core2024ClassLabel(cls)+" • "+
                (view.optJSONArray("prepared")==null?0:view.optJSONArray("prepared").length())+
                "/"+view.optInt("capacity")+" preparadas"+
                (view.optBoolean("can_edit",false)?" • edição disponível":" • bloqueada até descanso/nível"));
        }
        if(ids.isEmpty()){toast("Esta classe ainda não tem gerenciador PHB 2024 certificado.");return;}
        new AlertDialog.Builder(this).setTitle("ESCOLHER CLASSE CONJURADORA")
            .setItems(names.toArray(new String[0]),new DialogInterface.OnClickListener(){
                public void onClick(DialogInterface d,int which){
                    showCore2024PreparationEditor(characterId,ids.get(which));
                }}).setNegativeButton("Cancelar",null).show();
    }
    private static String core2024ClassLabel(String cls){
        if("wizard".equals(cls))return "Mago";
        if("sorcerer".equals(cls))return "Feiticeiro";
        if("cleric".equals(cls))return "Clérigo";
        if("druid".equals(cls))return "Druida";
        if("bard".equals(cls))return "Bardo";
        if("ranger".equals(cls))return "Guardião";
        if("paladin".equals(cls))return "Paladino";
        return cls;
    }
    private static boolean core2024ArrayContains(JSONArray array,String key){
        if(array==null)return false;
        for(int i=0;i<array.length();i++)if(key.equals(array.optString(i)))return true;
        return false;
    }
    private void showCore2024PreparationEditor(final long characterId,final String cls){
        JSONObject preview=db.previewCore2024PreparedSpells(characterId);
        JSONObject views=preview.optJSONObject("classes");
        final JSONObject state=views==null?null:views.optJSONObject(cls);
        if(state==null){toast("Classe não encontrada na ficha.");return;}
        final int revision=state.optInt("revision",0),level=state.optInt("class_level",0);
        final String windowId=state.optString("window_id","");
        final boolean editable=state.optBoolean("can_edit",false);
        final boolean wizard="wizard".equals(cls);
        LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);
        body.setPadding(dp(12),dp(8),dp(12),dp(12));
        body.addView(text(core2024ClassLabel(cls)+" • nível de classe "+level+
            " • limite "+state.optInt("capacity")+" • círculo máximo "+state.optInt("max_circle"),14,GOLD,true));
        body.addView(text("Só magias com regras executáveis verificadas são oferecidas aqui. " +
            "As escolhas são gravadas na ficha e validadas novamente ao conjurar. " +
            (editable?"Janela: "+state.optString("window_event","setup"):
                "Alterações bloqueadas: espere descanso longo ou subida de nível, conforme a classe."),12,MUTED,false));
        final ArrayList<Core2024SpellRules.Spell> options=new ArrayList<Core2024SpellRules.Spell>();
        final ArrayList<CheckBox> checks=new ArrayList<CheckBox>();
        final ArrayList<CheckBox> bookChecks=new ArrayList<CheckBox>();
        JSONArray oldPrepared=state.optJSONArray("prepared"),oldBook=state.optJSONArray("spellbook");
        for(Core2024SpellRules.Spell sp:Core2024SpellRules.supported()){
            if(sp.level>state.optInt("max_circle",0)||
                !Core2024CastingEligibility.listed(sp.key,cls))continue;
            options.add(sp);
            CheckBox chosen=check("Preparar "+sp.name+" • "+sp.level+"º círculo",
                core2024ArrayContains(oldPrepared,sp.key));
            chosen.setEnabled(editable);checks.add(chosen);body.addView(chosen);
            if(wizard){
                CheckBox inBook=check("Registrada no meu grimório: "+sp.name,
                    core2024ArrayContains(oldBook,sp.key));
                inBook.setEnabled(editable&&(!state.optBoolean("configured",false)||
                    ("level_up".equals(state.optString("window_event"))&&
                     state.optInt("free_spell_grants",0)>0)));
                bookChecks.add(inBook);body.addView(inBook);
            }
        }
        if(options.isEmpty())body.addView(text("Nenhuma das magias atualmente compiladas pertence à classe neste nível.",12,MUTED,false));
        final CheckBox confirmBook=check("Confirmo magias iniciais já registradas ou escolhas gratuitas da subida de nível do Mago. Fora disso, use a transcrição com tempo e ouro.",false);
        if(wizard&&editable)body.addView(confirmBook);
        if(wizard){
            final Button copy=button("COPIAR MAGIA ENCONTRADA • 50 PO E 2 H/CÍRCULO",PANEL2);
            copy.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                showCore2024WizardCopyDialog(characterId);
            }});
            body.addView(copy);
            final Button finish=button("VERIFICAR / CONCLUIR TRANSCRIÇÃO",PANEL2);
            finish.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                showCore2024WizardCopyFinishDialog(characterId);
            }});
            body.addView(finish);
        }
        new AlertDialog.Builder(this).setTitle("PREPARAÇÃO • "+core2024ClassLabel(cls))
            .setView(scrollableDialogView(body)).setNegativeButton("FECHAR",null)
            .setPositiveButton("SALVAR E FINALIZAR",new DialogInterface.OnClickListener(){
                public void onClick(DialogInterface d,int which){
                    JSONArray selected=new JSONArray(),book=new JSONArray();
                    for(int i=0;i<options.size();i++){
                        if(checks.get(i).isChecked())selected.put(options.get(i).key);
                        if(wizard&&bookChecks.get(i).isChecked())book.put(options.get(i).key);
                    }
                    JSONObject saved=db.saveCore2024PreparedSpells(characterId,cls,selected,book,
                        confirmBook.isChecked(),revision,windowId);
                    if(!saved.optBoolean("preparation_saved",false))
                        toast("Preparação não alterada: "+saved.optString("preparation_error",
                            saved.optString("operation_error","regras/estado inválidos")));
                    else toast("Magias preparadas salvas. "+saved.optInt("prepared_count")+
                        "/"+saved.optInt("capacity")+" vagas utilizadas.");
                }}).show().getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(editable);
    }

    // PHB 2024, Mago p.149. UI cannot give spells freely after initialization.
    private void showCore2024WizardCopyDialog(final long characterId){
        JSONObject preview=db.previewCore2024PreparedSpells(characterId);
        JSONObject classes=preview.optJSONObject("classes");
        JSONObject wizard=classes==null?null:classes.optJSONObject("wizard");
        if(wizard==null||!wizard.optBoolean("configured",false)){
            toast("Configure o grimório inicial antes de copiar novas magias.");return;
        }
        if(db.previewCore2024WizardCopy(characterId).optBoolean("wizard_copy_pending",false)){
            toast("Já existe uma transcrição em andamento. Conclua-a antes de iniciar outra.");return;
        }
        final ArrayList<Core2024SpellRules.Spell> choices=new ArrayList<Core2024SpellRules.Spell>();
        final ArrayList<String> labels=new ArrayList<String>();
        JSONArray old=wizard.optJSONArray("spellbook");
        for(Core2024SpellRules.Spell sp:Core2024SpellRules.supported()){
            if(!Core2024CastingEligibility.listed(sp.key,"wizard")||
                sp.level>wizard.optInt("max_circle",0)||core2024ArrayContains(old,sp.key))continue;
            choices.add(sp);labels.add(sp.name+" • "+(sp.level*50)+" po • "+(sp.level*2)+" horas no mundo");
        }
        if(choices.isEmpty()){toast("Nenhuma nova magia executável está disponível para seu nível.");return;}
        final int revision=wizard.optInt("revision",0);
        new AlertDialog.Builder(this).setTitle("TRANSCRIÇÃO • MAGO 2024")
            .setItems(labels.toArray(new String[0]),new DialogInterface.OnClickListener(){
                public void onClick(DialogInterface d,int which){
                    final Core2024SpellRules.Spell sp=choices.get(which);
                    final CheckBox found=check("Confirmo ter encontrado um pergaminho ou livro com esta magia de Mago.",false);
                    new AlertDialog.Builder(MainActivity.this).setTitle("INICIAR CÓPIA: "+sp.name)
                        .setMessage("Regra Livro do Jogador 2024, p.149. É necessário dedicar "+
                            (2*sp.level)+" horas no relógio do mundo e pagar "+(50*sp.level)+
                            " po. O livro será atualizado somente após as horas transcorrerem.")
                        .setView(found).setNegativeButton("CANCELAR",null)
                        .setPositiveButton("INICIAR TRANSCRIÇÃO",new DialogInterface.OnClickListener(){
                            public void onClick(DialogInterface dd,int w){
                                JSONObject result=db.startCore2024WizardCopy(characterId,sp.key,
                                    "ui-wizard-copy-"+java.util.UUID.randomUUID(),found.isChecked(),revision);
                                if(result.optBoolean("wizard_copy_started",false)){
                                    toast("Transcrição iniciada. Registre horas dedicadas após o relógio avançar.");
                                }else toast("Transcrição bloqueada: "+result.optString("wizard_copy_error",
                                    result.optString("operation_error","regras ou recurso indisponíveis")));
                            }}).show();
                }}).setNegativeButton("CANCELAR",null).show();
    }
    private void showCore2024WizardCopyFinishDialog(final long characterId){
        JSONObject p=db.previewCore2024WizardCopy(characterId);
        if(!p.optBoolean("wizard_copy_pending",false)){
            toast("Nenhuma transcrição pendente neste personagem.");return;
        }
        final String token=p.optString("token","");
        final double remaining=p.optDouble("hours_remaining",Double.POSITIVE_INFINITY);
        String status=remaining>0?"Faltam "+String.format(java.util.Locale.ROOT,"%.1f",remaining)+
            " horas de ESTUDO DEDICADO registrado.":"Tempo de estudo certificado: pronto para pagamento e inscrição.";
        if(remaining>0){
            final EditText hours=new EditText(this);
            hours.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);
            hours.setHint("Horas reais dedicadas desde o último registro (ex.: 2)");
            new AlertDialog.Builder(this).setTitle("REGISTRAR ESTUDO DEDICADO")
                .setMessage("Relógio avançando sozinho NÃO conta. Confirme apenas horas em que o Mago esteve copiando a magia. " +
                    "Restam "+String.format(java.util.Locale.ROOT,"%.1f",remaining)+" horas.")
                .setView(hours).setNegativeButton("CANCELAR",null)
                .setPositiveButton("REGISTRAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
                    double n=0d;try{n=Double.parseDouble(hours.getText().toString().trim().replace(',','.'));}
                    catch(Exception ignored){}
                    JSONObject result=db.recordCore2024WizardCopyStudy(characterId,token,
                        "ui-study-"+java.util.UUID.randomUUID(),n,true);
                    if(result.optBoolean("wizard_copy_study_recorded",false))
                        toast("Estudo registrado. Falta(m): "+result.optDouble("hours_remaining")+" hora(s).");
                    else toast("Estudo não registrado: "+result.optString("wizard_copy_error",
                        result.optString("operation_error","registro inválido")));
                }}).setNeutralButton("ABANDONAR CÓPIA",new DialogInterface.OnClickListener(){
                    public void onClick(DialogInterface d,int w){
                        JSONObject result=db.cancelCore2024WizardCopy(characterId,token);
                        toast(result.optBoolean("wizard_copy_cancelled",false)?
                            "Transcrição cancelada sem débito de ouro.":"Não foi possível cancelar a transcrição.");
                }}).show();return;
        }
        new AlertDialog.Builder(this).setTitle("CONCLUIR GRIMÓRIO • 2024")
            .setMessage("Magia: "+p.optString("spell")+"\nCusto: "+p.optInt("cost_gp")+
                " po\n"+status)
            .setNegativeButton("VOLTAR",null)
            .setPositiveButton("CONCLUIR E PAGAR",new DialogInterface.OnClickListener(){
                public void onClick(DialogInterface d,int w){
                    JSONObject result=db.finishCore2024WizardCopy(characterId,token);
                    if(result.optBoolean("wizard_copy_committed",false))
                        toast("Magia copiada no grimório. "+result.optInt("gold_spent")+" po consumidos.");
                    else toast("Cópia não concluída: "+result.optString("wizard_copy_error",
                        result.optString("operation_error","ainda não é possível")));
                }}).show();
    }

    // RUN225: Bless uses its own target selection and typed atomic executor. Unlike
    // damage spells, no rolled amount or fabricated saving throw is requested.
    private void showCore2024BlessDialog(){
        final java.util.List<JSONObject> combatants=db.listCombatants();
        final java.util.ArrayList<JSONObject> casters=new java.util.ArrayList<JSONObject>();
        final java.util.ArrayList<String> casterNames=new java.util.ArrayList<String>();
        for(JSONObject c:combatants)if(c.optInt("is_player",0)==1&&
            "character".equals(c.optString("source_kind"))&&c.optLong("source_id",0)>0){
            JSONObject hero=db.getCharacter(c.optLong("source_id"));
            if(hero.length()>0){casters.add(c);casterNames.add(hero.optString("name","Conjurador"));}
        }
        if(casters.isEmpty()){toast("Adicione um personagem conjurador ao combate.");return;}
        final LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);
        body.setPadding(dp(12),dp(8),dp(12),dp(8));
        final Spinner caster=spinner(casterNames.toArray(new String[0]),casterNames.get(0));
        final Spinner slot=spinner(new String[]{"1","2","3","4","5","6","7","8","9"},"1");
        final Spinner ability=spinner(new String[]{"Sabedoria","Carisma"},"Sabedoria");
        body.addView(cardWithLabel("PERSONAGEM",caster));
        body.addView(cardWithLabel("CÍRCULO DO ESPAÇO (1–9)",slot));
        body.addView(cardWithLabel("ATRIBUTO DA CLASSE QUE PREPAROU BÊNÇÃO",ability));
        body.addView(text("Bênção (PHB 2024): escolha até 2 + círculo alvos em até 9 m. " +
            "O sistema verifica a ficha, a preparação, o símbolo sagrado de pelo menos 5 PO " +
            "no inventário estruturado e as posições atuais. Concentração: 1 minuto. " +
            "O bônus de 1d4 deve ser rolado quando um ataque ou salvaguarda elegível ocorrer.",12,MUTED,false));
        final java.util.ArrayList<CheckBox> chosen=new java.util.ArrayList<CheckBox>();
        for(JSONObject row:combatants){
            CheckBox box=check(row.optString("name","Criatura")+" • PV "+row.optInt("hp"),false);
            chosen.add(box);body.addView(box);
        }
        final CheckBox voice=check("Confirmo componente verbal e capacidade de falar",false);
        final CheckBox hand=check("Confirmo componente somático e mão disponível",false);
        final CheckBox line=check("Confirmei linha de efeito e obstáculos para todos os alvos",false);
        body.addView(voice);body.addView(hand);body.addView(line);
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("BÊNÇÃO • CONJURAÇÃO 2024")
            .setView(scrollableDialogView(body)).setNegativeButton("CANCELAR",null)
            .setPositiveButton("REVISAR E CONJURAR",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                final JSONObject actor=casters.get(caster.getSelectedItemPosition());
                final long heroId=actor.optLong("source_id",0),casterId=actor.optLong("id",0);
                final int level=slot.getSelectedItemPosition()+1;
                final String castingAbility=ability.getSelectedItemPosition()==0?"wis":"cha";
                JSONObject eligible=db.previewCore2024CastingEligibility(heroId,"Bênção",castingAbility);
                if(!eligible.optBoolean("eligibility_valid",false)){
                    toast("Bênção bloqueada: "+eligible.optString("eligibility_error","classe ou material"));return;
                }
                if(!voice.isChecked()||!hand.isChecked()||!line.isChecked()){
                    toast("Confirme todos os componentes e a linha de efeito.");return;
                }
                final JSONArray targetIds=new JSONArray();final StringBuilder targetNames=new StringBuilder();
                for(int i=0;i<combatants.size();i++)if(chosen.get(i).isChecked()){
                    long targetId=combatants.get(i).optLong("id",0);
                    if(targetId<=0){toast("Alvo inválido; reabra o painel.");return;}
                    targetIds.put(targetId);targetNames.append("\n• ").append(combatants.get(i).optString("name"));
                }
                if(targetIds.length()<1||targetIds.length()>level+2){
                    toast("Selecione entre 1 e "+(level+2)+" alvos.");return;
                }
                new AlertDialog.Builder(MainActivity.this).setTitle("CONFIRMAR BÊNÇÃO")
                    .setMessage("Gastar uma ação e um espaço de círculo "+level+"?"+
                        "\nAlvos:"+targetNames+"\n\nConcentração por até 10 rodadas. " +
                        "A operação será desfeita integralmente se falhar.")
                    .setNegativeButton("VOLTAR",null)
                    .setPositiveButton("CONFIRMAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
                        try{
                            JSONObject spellRequest=new JSONObject().put("casting_ability",castingAbility)
                                .put("casting_ability_confirmed",true).put("target_ids",targetIds)
                                .put("voice_available",true).put("hand_available",true)
                                .put("line_of_effect_confirmed",true);
                            JSONObject dispatch=new JSONObject().put("channel","PLAYER_REACTION")
                                .put("mechanic_family","core2024_spell")
                                .put("action_id","ui-bless-"+java.util.UUID.randomUUID().toString())
                                .put("character_id",heroId).put("caster_combatant_id",casterId)
                                .put("spell_name","Bênção").put("slot_level",level)
                                .put("spell_request",spellRequest);
                            JSONObject result=db.dispatchCompiledPlayerAction(dispatch);
                            if(!result.optBoolean("accepted",false)||!result.optBoolean("state_committed",false)){
                                toast("Bênção não aplicada: "+result.optString("authority","ação indisponível"));
                            }else{toast("Bênção aplicada: ação, espaço e concentração persistidos.");dialog.dismiss();}
                        }catch(Exception e){toast("Bênção cancelada: "+e.getMessage());}
                        showCombat();
                    }}).show();
            }});
        }});
        dialog.show();
    }

    private void showCore2024SpellDialog(){
        final List<JSONObject> roster=db.listCombatants();
        final ArrayList<JSONObject> casters=new ArrayList<JSONObject>();
        final ArrayList<String> casterNames=new ArrayList<String>();
        for(JSONObject c:roster)if(c.optInt("is_player",0)==1){
            JSONObject ch=c.optLong("source_id",0)>0?db.getCharacter(c.optLong("source_id")):
                db.findCharacterByName(c.optString("name",""));
            if(ch.length()>0){casters.add(c);casterNames.add(ch.optString("name","Conjurador"));}
        }
        if(casters.isEmpty()||roster.isEmpty()){toast("Adicione ao combate um personagem conjurador antes de abrir as magias.");return;}
        final Core2024SpellRules.Spell[] spells=Core2024SpellRules.supported();
        final String[] spellNames=new String[spells.length];
        for(int i=0;i<spells.length;i++)spellNames[i]=spells[i].name;
        final LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);
        body.setPadding(dp(12),dp(6),dp(12),dp(6));
        final Spinner caster=spinner(casterNames.toArray(new String[0]),casterNames.get(0));
        final Spinner spell=spinner(spellNames,spellNames[0]);
        final Spinner slot=spinner(new String[]{"1","2","3","4","5","6","7","8","9"},"3");
        final String[] abilityKeys={"int","wis","cha","str","dex","con"};
        final Spinner ability=spinner(new String[]{"Inteligência","Sabedoria","Carisma","Força","Destreza","Constituição"},"Inteligência");
        body.addView(cardWithLabel("PERSONAGEM CONJURADOR",caster));
        body.addView(cardWithLabel("MAGIA VERIFICADA NO PHB 2024",spell));
        body.addView(cardWithLabel("CÍRCULO DO ESPAÇO",slot));
        body.addView(cardWithLabel("ATRIBUTO DE CONJURAÇÃO",ability));
        final TextView detail=text("",13,TEXT,false);body.addView(detail);
        final CheckBox components=check("Confirmo os componentes V/S/M necessários e as mãos livres",false);
        final TextView preparedStatus=text("Preparação verificada automaticamente no registro da ficha. Use GERENCIAR MAGIAS PREPARADAS para escolher magias nos momentos permitidos.",12,MUTED,false);
        final CheckBox geometry=check("Confirmei linha de visão, cobertura e obstáculos não certificados automaticamente",false);
        final CheckBox abilityCheck=check("Confirmei o atributo de conjuração correto para esta magia",false);
        body.addView(components);body.addView(preparedStatus);body.addView(geometry);body.addView(abilityCheck);
        final TextView damageResult=text("Role os dados de dano/cura antes de confirmar.",13,GOLD,true);
        final int[] amount={Integer.MIN_VALUE};final String[] amountStamp={""};
        final Button rollAmount=button("ROLAR DANO / CURA",GOLD);rollAmount.setTextColor(Color.BLACK);
        body.addView(rollAmount);body.addView(damageResult);
        // RUN200: geometry is derived from persistent token positions, never chosen by AI.
        JSONObject tacticalScene=new ProceduralTacticalSceneGenerator(db).ensureForCurrentScene();
        final int gridW=Math.max(1,Math.min(100,tacticalScene.optInt("width_cells",12)));
        final int gridH=Math.max(1,Math.min(100,tacticalScene.optInt("height_cells",8)));
        final ArrayList<String> cells=new ArrayList<String>();
        for(int y=0;y<gridH;y++)for(int x=0;x<gridW;x++)
            cells.add("Coluna "+(x+1)+" • Linha "+(y+1));
        final Spinner center=spinner(cells.toArray(new String[0]),cells.get(0));
        final Spinner coneDirection=spinner(new String[]{"Leste","Sudeste","Sul","Sudoeste","Oeste","Noroeste","Norte","Nordeste"},"Leste");
        body.addView(cardWithLabel("CENTRO DA BOLA DE FOGO • CÉLULA DE 5 PÉS",center));
        body.addView(cardWithLabel("DIREÇÃO DO CONE DE MÃOS FLAMEJANTES",coneDirection));
        body.addView(text("Posicione os tokens no tabuleiro antes de abrir este painel. A prévia seleciona automaticamente todos os atingidos, inclusive aliados. Para Curar Ferimentos, marque exatamente um alvo antes da prévia.",12,MUTED,false));
        final TextView geometryResult=text("Área ainda não calculada.",13,GOLD,true);
        final Button previewGeometry=button("CALCULAR ALCANCE E TODOS OS ALVOS",PANEL2);
        body.addView(previewGeometry);body.addView(geometryResult);
        final String[] previewStamp={""},previewSignature={""},previewScene={""};
        final long[] previewTouchId={0};
        final ArrayList<CheckBox> selected=new ArrayList<CheckBox>();
        final ArrayList<EditText> bonuses=new ArrayList<EditText>();
        final ArrayList<Spinner> modes=new ArrayList<Spinner>();
        final int[] d20=new int[roster.size()],rollBonus=new int[roster.size()];
        final String[] rollStamp=new String[roster.size()];
        final TextView[] rollResults=new TextView[roster.size()];
        for(int i=0;i<roster.size();i++){
            final int index=i;final JSONObject combatant=roster.get(i);
            LinearLayout row=card();
            CheckBox mark=check(combatant.optString("name","Alvo")+" • PV "+combatant.optInt("hp")+"/"+combatant.optInt("max_hp"),false);
            selected.add(mark);row.addView(mark);
            EditText bonus=labeledField(row,"Bônus de salvaguarda (NPC: informe e confirme)","",false);
            bonus.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
            bonuses.add(bonus);
            Spinner mode=spinner(new String[]{"Normal","Vantagem","Desvantagem"},"Normal");
            modes.add(mode);row.addView(cardWithLabel("TIPO DE ROLAGEM",mode));
            TextView result=text("Sem salvaguarda rolada",12,MUTED,false);
            rollResults[i]=result;
            Button roll=button("ROLAR SALVAGUARDA",PANEL2);
            roll.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                if(!selected.get(index).isChecked()){toast("Marque o alvo antes de rolar.");return;}
                Core2024SpellRules.Spell sp=spells[spell.getSelectedItemPosition()];
                if(sp.healing){toast("Curar Ferimentos não exige salvaguarda.");return;}
                JSONObject info=db.combatantAreaSaveInfo(combatant.optLong("id"),sp.saveAbility);
                if(info.optBoolean("bonus_known",false))bonuses.get(index).setText(String.valueOf(info.optInt("bonus")));
                final int bonusValue;
                try{bonusValue=Integer.parseInt(value(bonuses.get(index)).trim());}
                catch(Exception e){bonuses.get(index).setError("Informe o bônus.");return;}
                if(bonusValue< -50||bonusValue>100){toast("Bônus de salvaguarda inválido.");return;}
                final String stamp=core2024SpellStamp(casters.get(caster.getSelectedItemPosition()),sp,
                    slot.getSelectedItemPosition()+1,abilityKeys[ability.getSelectedItemPosition()]);
                final String modeName=String.valueOf(modes.get(index).getSelectedItem());
                rollDiceInteractive("d20"+(bonusValue>=0?"+":"")+bonusValue,modeName,
                    combatant.optString("name","Alvo"),combatant.optInt("is_player",0)==1?combatant.optLong("source_id",0):0,
                    new DiceUiCallback(){public void done(DiceResult r){
                        d20[index]=r.natural;rollBonus[index]=bonusValue;
                        rollStamp[index]=stamp+":"+modeName;
                        rollResults[index].setText("d20="+r.natural+" + "+bonusValue+" = "+r.total);
                    }});
            }});
            row.addView(roll);row.addView(result);body.addView(row);
        }
        previewGeometry.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            Core2024SpellRules.Spell sp=spells[spell.getSelectedItemPosition()];
            JSONObject casterRow=casters.get(caster.getSelectedItemPosition());
            long touchId=0;
            if(sp.healing){
                for(int i=0;i<selected.size();i++)if(selected.get(i).isChecked()){
                    if(touchId!=0){toast("Curar Ferimentos requer exatamente um alvo.");return;}
                    touchId=roster.get(i).optLong("id");
                }
                if(touchId<=0){toast("Marque um alvo para o toque antes de calcular.");return;}
            }
            int x=center.getSelectedItemPosition()%gridW,y=center.getSelectedItemPosition()/gridW;
            int direction=coneDirection.getSelectedItemPosition();
            JSONObject plan=db.previewCore2024SpellGeometry(casterRow.optLong("id"),sp.name,x,y,direction,touchId);
            if(!plan.optBoolean("geometry_valid",false)){
                previewStamp[0]="";previewSignature[0]="";
                geometryResult.setText("Área bloqueada: "+plan.optString("geometry_error","mapa indisponível"));return;
            }
            JSONArray affected=plan.optJSONArray("target_ids");
            java.util.HashSet<Long> ids=new java.util.HashSet<Long>();
            for(int i=0;affected!=null&&i<affected.length();i++)ids.add(affected.optLong(i));
            StringBuilder names=new StringBuilder();
            for(int i=0;i<roster.size();i++){
                long id=roster.get(i).optLong("id");boolean hit=ids.contains(id);
                selected.get(i).setChecked(hit);
                if(hit)names.append("\n• ").append(roster.get(i).optString("name"));
            }
            previewTouchId[0]=touchId;previewSignature[0]=plan.optString("geometry_signature");
            previewScene[0]=plan.optString("scene_key");
            previewStamp[0]=core2024GeometryStamp(casterRow,sp,x,y,direction,touchId);
            geometryResult.setText("Área calculada: "+ids.size()+" alvo(s) • "+
                (sp.healing?"toque":sp.area)+names.toString()+
                "\nLOS/cobertura exigem confirmação. Mudanças de posições exigem nova prévia.");
        }});
        final Runnable refresh=new Runnable(){public void run(){
            Core2024SpellRules.Spell sp=spells[spell.getSelectedItemPosition()];
            JSONObject casterRow=casters.get(caster.getSelectedItemPosition());
            JSONObject ch=casterRow.optLong("source_id",0)>0?db.getCharacter(casterRow.optLong("source_id")):
                db.findCharacterByName(casterRow.optString("name",""));
            String suggested=Core2024SpellRules.classAbility(ch.optString("class_name",""));
            String key=abilityKeys[ability.getSelectedItemPosition()];
            int score="int".equals(key)?ch.optInt("int_score",10):"wis".equals(key)?ch.optInt("wis",10):
                "cha".equals(key)?ch.optInt("cha",10):"str".equals(key)?ch.optInt("str",10):
                "dex".equals(key)?ch.optInt("dex",10):ch.optInt("con",10);
            int mod=new DndRulesEngine().modifier(score);
            int dc=new DndRulesEngine().spellSaveDc(score,Math.max(1,ch.optInt("level",1)),true);
            int level=slot.getSelectedItemPosition()+1;
            JSONObject eligibility=db.previewCore2024CastingEligibility(ch.optLong("id"),sp.name,key);
            String eligibilityText=eligibility.optBoolean("eligibility_valid",false)?
                "\nClasse/atributo e material: verificados no estado atual.":
                "\n⚠ Classe/atributo/material: "+eligibility.optString("eligibility_error","não verificado");
            detail.setText(sp.name+" • círculo "+sp.level+" • "+sp.components+" • " +
                ("touch".equals(sp.area)?"Toque":"cone".equals(sp.area)?"Cone 4,5 m":"Esfera raio 6 m a até 45 m")+
                " • " +(sp.healing?"Cura":"Salvaguarda "+sp.saveAbility.toUpperCase(java.util.Locale.ROOT)+" CD "+dc)+
                "\nDados: "+(level>=sp.level?sp.diceFormula(level,mod):"Espaço insuficiente")+
                " • atributo sugerido: "+(suggested.isEmpty()?"conferir ficha":suggested.toUpperCase(java.util.Locale.ROOT))+
                "\nAs salvaguardas e dados já rolados precisam ser repetidos se alterar os parâmetros."+eligibilityText);
        }};
        android.widget.AdapterView.OnItemSelectedListener changed=new android.widget.AdapterView.OnItemSelectedListener(){
            public void onNothingSelected(android.widget.AdapterView<?> p){}
            public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int position,long id){refresh.run();}
        };
        caster.setOnItemSelectedListener(changed);spell.setOnItemSelectedListener(changed);
        slot.setOnItemSelectedListener(changed);ability.setOnItemSelectedListener(changed);
        rollAmount.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            Core2024SpellRules.Spell sp=spells[spell.getSelectedItemPosition()];
            int level=slot.getSelectedItemPosition()+1;
            if(level<sp.level){toast("Escolha um espaço de círculo adequado.");return;}
            JSONObject casterRow=casters.get(caster.getSelectedItemPosition());
            JSONObject ch=casterRow.optLong("source_id",0)>0?db.getCharacter(casterRow.optLong("source_id")):
                db.findCharacterByName(casterRow.optString("name",""));
            String key=abilityKeys[ability.getSelectedItemPosition()];
            int score="int".equals(key)?ch.optInt("int_score",10):"wis".equals(key)?ch.optInt("wis",10):
                "cha".equals(key)?ch.optInt("cha",10):"str".equals(key)?ch.optInt("str",10):
                "dex".equals(key)?ch.optInt("dex",10):ch.optInt("con",10);
            int mod=new DndRulesEngine().modifier(score);
            final String stamp=core2024SpellStamp(casterRow,sp,level,key);
            rollDiceInteractive(sp.diceFormula(level,mod),"Normal",ch.optString("name","Conjurador"),ch.optLong("id",0),
                new DiceUiCallback(){public void done(DiceResult r){
                    amount[0]=r.total;amountStamp[0]=stamp;
                    damageResult.setText("Rolagem confirmada: "+r.detail+" = "+r.total);
                }});
        }});
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Conjuração oficial 2024")
            .setView(scrollableDialogView(body)).setNegativeButton("CANCELAR",null)
            .setPositiveButton("REVISAR EFEITOS",null).create();
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface unused){
            refresh.run();
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                final Core2024SpellRules.Spell sp=spells[spell.getSelectedItemPosition()];
                final JSONObject casterRow=casters.get(caster.getSelectedItemPosition());
                final JSONObject ch=casterRow.optLong("source_id",0)>0?db.getCharacter(casterRow.optLong("source_id")):
                    db.findCharacterByName(casterRow.optString("name",""));
                final String abilityKey=abilityKeys[ability.getSelectedItemPosition()];
                final int level=slot.getSelectedItemPosition()+1;
                final String stamp=core2024SpellStamp(casterRow,sp,level,abilityKey);
                JSONObject eligibility=db.previewCore2024CastingEligibility(ch.optLong("id"),sp.name,abilityKey);
                if(!eligibility.optBoolean("eligibility_valid",false)){
                    toast("Conjuração bloqueada: "+eligibility.optString("eligibility_error","classe/material"));return;
                }
                if(!stamp.equals(amountStamp[0])){toast("Role novamente dano/cura com os parâmetros atuais.");return;}
                int centerX=center.getSelectedItemPosition()%gridW,centerY=center.getSelectedItemPosition()/gridW;
                int direction=coneDirection.getSelectedItemPosition();
                long touchId=sp.healing?previewTouchId[0]:0;
                if(previewStamp[0].length()==0||!previewStamp[0].equals(
                    core2024GeometryStamp(casterRow,sp,centerX,centerY,direction,touchId))){
                    toast("Calcule novamente a área e os alvos no mapa.");return;
                }
                JSONObject currentGeometry=db.previewCore2024SpellGeometry(casterRow.optLong("id"),sp.name,
                    centerX,centerY,direction,touchId);
                if(!currentGeometry.optBoolean("geometry_valid",false)||
                    !previewSignature[0].equals(currentGeometry.optString("geometry_signature"))||
                    !previewScene[0].equals(currentGeometry.optString("scene_key"))){
                    toast("Tokens ou cena mudaram. Recalcule a área.");return;
                }
                if(!components.isChecked()||!geometry.isChecked()||!abilityCheck.isChecked()){
                    toast("Confirme componentes, preparação, geometria e atributo.");return;
                }
                final JSONArray targets=new JSONArray();StringBuilder summary=new StringBuilder();
                for(int i=0;i<roster.size();i++)if(selected.get(i).isChecked()){
                    JSONObject c=db.getCombatant(roster.get(i).optLong("id"));
                    if(c.length()==0){toast("Alvo removido; abra novamente.");return;}
                    try{
                        JSONObject target=new JSONObject().put("target_id",c.optLong("id"))
                            .put("expected_hp",c.optInt("hp")).put("expected_temp_hp",c.optInt("temp_hp"));
                        if(!sp.healing){
                            String expectedStamp=stamp+":"+String.valueOf(modes.get(i).getSelectedItem());
                            if(!expectedStamp.equals(rollStamp[i])||
                                !String.valueOf(rollBonus[i]).equals(value(bonuses.get(i)).trim())){
                                toast("Role a salvaguarda atual de "+c.optString("name"));return;
                            }
                            target.put("d20",d20[i]).put("save_bonus",rollBonus[i])
                                .put("manual_bonus_confirmed",true);
                        }
                        targets.put(target);summary.append("\n• ").append(c.optString("name"));
                    }catch(Exception e){toast("Alvo inválido.");return;}
                }
                int score="int".equals(abilityKey)?ch.optInt("int_score",10):"wis".equals(abilityKey)?ch.optInt("wis",10):
                    "cha".equals(abilityKey)?ch.optInt("cha",10):"str".equals(abilityKey)?ch.optInt("str",10):
                    "dex".equals(abilityKey)?ch.optInt("dex",10):ch.optInt("con",10);
                String check=Core2024SpellRules.validate("2024",sp.name,level,targets.length(),amount[0],
                    new DndRulesEngine().modifier(score),components.isChecked(),geometry.isChecked(),true);
                if(!check.isEmpty()){toast("Conjuração bloqueada: "+check);return;}
                final JSONObject request=new JSONObject();
                try{request.put("casting_ability",abilityKey).put("casting_ability_confirmed",true)
                    .put("components_confirmed",true).put("geometry_confirmed",true)
                    .put("prepared_confirmed",true).put("raw_amount",amount[0]).put("targets",targets)
                    .put("geometry_mode","tactical_v1")
                    .put("center_cell_x",centerX).put("center_cell_y",centerY)
                    .put("cone_direction",direction).put("touch_target_id",touchId)
                    .put("geometry_signature",previewSignature[0])
                    .put("geometry_scene_key",previewScene[0]);}
                catch(Exception e){toast("Falha ao preparar conjuração.");return;}
                final String token="ui-core-spell-"+java.util.UUID.randomUUID();
                new AlertDialog.Builder(MainActivity.this).setTitle("CONFIRMAR MAGIA E GASTOS")
                    .setMessage(ch.optString("name")+" conjura "+sp.name+" (espaço "+level+")"+
                        "\nAção: 1 • espaço de magia: 1"+
                        "\n"+(sp.healing?"Cura":"Dano")+": "+amount[0]+
                        "\nAlvos: "+summary.toString()+
                        "\n\nAção, espaço e todos os efeitos serão gravados juntos. Confirmar?")
                    .setNegativeButton("VOLTAR",null)
                    .setPositiveButton("CONFIRMAR E CONJURAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
                        JSONObject result;
                        try{
                            JSONObject dispatch=new JSONObject().put("channel","PLAYER_REACTION")
                                .put("mechanic_family","core2024_spell").put("action_id",token)
                                .put("character_id",ch.optLong("id"))
                                .put("caster_combatant_id",casterRow.optLong("id"))
                                .put("spell_name",sp.name).put("slot_level",level)
                                .put("spell_request",request);
                            result=db.dispatchCompiledPlayerAction(dispatch);
                        }catch(Exception error){toast("Conjuração cancelada: "+error.getMessage());showCombat();return;}
                        if(!result.optBoolean("accepted",false)||!result.optBoolean("effect_applied",false)
                            ||!result.optBoolean("state_committed",false)){
                            toast("Nenhuma mudança aplicada: "+result.optString("authority",
                                result.optString("operation_error","estado alterado ou custo indisponível")));
                            showCombat();return;
                        }
                        db.addAuditEvent("combate","Magia oficial 2024 confirmada",sp.name+" • "+targets.length()+" alvo(s)",
                            "{}",result.toString(),true);
                        dialog.dismiss();showCombat();
                    }}).show();
            }});
        }});
        dialog.show();
    }
    private static String core2024GeometryStamp(JSONObject caster,Core2024SpellRules.Spell spell,
                                                 int x,int y,int direction,long touchId){
        return caster.optLong("id")+":"+spell.key+":"+x+":"+y+":"+direction+":"+touchId;
    }
    private static String core2024SpellStamp(JSONObject caster,Core2024SpellRules.Spell spell,int slot,String ability){
        return caster.optLong("id")+":"+spell.key+":"+slot+":"+ability;
    }

    private void combatDamageDialog(final JSONObject combatant){
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(12));
        final EditText amount=labeledField(form,"Dano","0",false),type=labeledField(form,"Tipo de dano","",false);
        amount.setInputType(InputType.TYPE_CLASS_NUMBER);
        final CheckBox critical=check("Acerto crítico",false),nonlethal=check("Nocaute não letal — somente ataque corpo a corpo que reduziria a 0 PV",false);
        form.addView(critical);form.addView(nonlethal);
        final String token="ui-"+java.util.UUID.randomUUID();final boolean[] committed={false};
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Aplicar dano — "+combatant.optString("name"))
            .setView(form).setNegativeButton("Cancelar",null).setPositiveButton("APLICAR",null).create();
        showBoundDialog(dialog,new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View view){
                if(committed[0])return;
                final int damage;try{damage=Integer.parseInt(value(amount));if(damage<=0)throw new IllegalArgumentException();}
                catch(Exception invalid){amount.setError("Informe um dano inteiro maior que zero.");return;}
                JSONObject before=db.getCombatant(combatant.optLong("id"));
                if(before.length()==0){toast("Combatente removido; reabra o encontro.");return;}
                JSONObject after=db.applyCombatantDamage(combatant.optLong("id"),damage,value(type),critical.isChecked(),nonlethal.isChecked(),token);
                if(after.has("operation_error")||after.has("operation_blocked")){
                    toast("Dano não aplicado: "+after.optString("operation_blocked",after.optString("operation_error")));return;
                }
                committed[0]=true;view.setEnabled(false);
                if(!after.optBoolean("operation_replayed",false))db.addAuditEvent("combate",after.optBoolean("nonlethal_knockout",false)?"Nocaute não letal":"Dano estruturado",
                    before.optString("name")+" sofreu "+damage+(value(type).isEmpty()?"":" "+value(type)),before.toString(),after.toString(),true);
                dialog.dismiss();showCombat();
            }});
        }});
    }

    private int combatantConcentrationBonus(JSONObject combatant){if(combatant.optInt("is_player",0)==1){JSONObject ch=db.findCharacterByName(combatant.optString("name"));if(ch.length()>0)return new DndRulesEngine().savingThrowBonus(ch,"Constitution");}try{return new JSONObject(combatant.optString("resources_json","{}")).optInt("con_save_bonus",0);}catch(Exception ignored){return 0;}}

    private void refreshXanatharInitiativeFeatResources(){
        try{for(JSONObject ch:db.listActiveCharacters()){long id=ch.optLong("id",0);if(id<=0)continue;JSONObject sheet=new JSONObject(ch.optString("sheet_json","{}"));XanatharRacialFeatRuntimeEngine.onInitiative(sheet);CrossBookSubclassRuntimeEngine.onInitiative(sheet);db.updateCharacterSheetChecked(id,sheet.toString());}}catch(Exception error){AppLog.w("XanatharFeat","Não foi possível atualizar todos os recursos de iniciativa.",error);}
    }

    private void addActiveHeroesToCombat(){
        final List<JSONObject> chars=partyDirector.activeHeroRoster();if(chars.size()==0){toast("Nenhum herói está na companhia atual.");return;}final ArrayList<String> names=new ArrayList<String>();final java.util.HashSet<String> seen=new java.util.HashSet<String>();
        for(JSONObject character:chars)if(db.findCombatantByName(character.optString("name")).length()==0)addInitiativeName(names,seen,character.optString("name"));
        try{for(JSONObject candidate:combatNpcCandidates(new JSONObject()).values()){String name=candidate.optString("name",candidate.optString("label","")).trim();if(name.length()==0||db.findCharacterByName(name).length()>0||db.findCombatantByName(name).length()>0)continue;JSONObject memory=db.findNpcMemoryByName(name);if(isCombatParticipantNpc(candidate,memory))addInitiativeName(names,seen,name);}}catch(Exception error){toast("Os participantes presentes não puderam ser preparados: "+safeMessage(error));return;}
        if(names.isEmpty()){toast("A companhia já está no combate.");return;}
        promptInitiativeValues(names,"Iniciativa da companhia",new InitiativeValuesCallback(){public void accepted(final JSONObject values){
            try{for(String name:names)requireExternalInitiative(values,name);final boolean wasRunning=db.getCombatState().optInt("running",0)==1;final JSONObject sceneEnvelope=new JSONObject();
                db.runInTransactionChecked(new AppDb.CheckedTransaction(){public void run()throws Exception{
                    for(JSONObject character:chars){String name=character.optString("name").trim();if(name.length()==0||db.findCombatantByName(name).length()>0)continue;JSONObject sheet=parseJsonObject(character.optString("sheet_json","{}"));String conditions=sheet.optString("conditions","");long id=db.addCombatantWithVisualChecked(name,requireExternalInitiative(values,name),character.optInt("hp"),character.optInt("max_hp"),character.optInt("ac"),conditions,true,"character",character.optLong("id"),character.optString("token_uri"));JSONObject resources=sheet.optJSONObject("combat_resources");if(resources==null)resources=new JSONObject();db.updateCombatantAdvancedChecked(id,sheet.optInt("temp_hp",0),sheet.optString("concentration",""),false,0,0,conditions,sheet.optString("condition_timers_json","[]"),sheet.optString("resistances",""),sheet.optString("vulnerabilities",""),sheet.optString("immunities",""),resources.toString());}
                    db.setCombatRunningChecked(true);syncPresentNpcsIntoRunningCombat(sceneEnvelope,values);if(!wasRunning&&db.listCombatants().size()>0)db.nextTurn();
                }});
                refreshXanatharInitiativeFeatResources();if(!wasRunning){String opening="O encontro tático começou em "+db.getSceneState().optString("location","local atual")+". A iniciativa foi confirmada pelo jogador.";prefs.edit().putString("last_combat_narration",opening).apply();db.addJournalFact("Combate iniciado",opening,"Combate","combat-start-"+db.getCombatState().optString("encounter_id",""),"combat");}showCombat();
            }catch(Exception error){toast("Combate preservado; não foi possível aplicar as iniciativas: "+safeMessage(error));}
        }});
    }
    private void combatantDialog(){
        LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(12),0,dp(12),0);final EditText name=labeledField(f,"Nome","Goblin",false),init=labeledField(f,"Iniciativa final (d20 + bônus)","",false),hp=labeledField(f,"PV","7",false),ac=labeledField(f,"CA","15",false),conditions=labeledField(f,"Condições","",false);init.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);hp.setInputType(InputType.TYPE_CLASS_NUMBER);ac.setInputType(InputType.TYPE_CLASS_NUMBER);
        final EditText bonus=labeledField(f,"Bônus de iniciativa da criatura","0",false);
        bonus.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
        Button roll=button("🎲 ROLAR 1d20 + BÔNUS",PANEL2);
        roll.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            int modifier;
            try{modifier=Integer.parseInt(value(bonus));}catch(Exception invalid){bonus.setError("Informe o bônus da criatura.");return;}
            if(modifier< -20||modifier>30){bonus.setError("Confira o bônus da ficha da criatura.");return;}
            int die=1+new java.security.SecureRandom().nextInt(20);
            init.setText(String.valueOf(die+modifier));
            toast("D20: "+die+" + "+modifier+". Confira e confirme para adicionar.");
        }});
        f.addView(roll);
        final boolean[] added={false};
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Adicionar combatente").setView(scrollableDialogView(f)).setNegativeButton("Cancelar",null).setPositiveButton("Adicionar",null).create();showBoundDialog(dialog,new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(added[0])return;final String combatantName=name.getText().toString().trim();if(combatantName.length()==0){name.setError("Informe o nome.");return;}final int initiative;try{initiative=Integer.parseInt(init.getText().toString().trim());}catch(Exception invalid){init.setError("Role no aplicativo ou digite o total.");return;}if(initiative< -20||initiative>100){init.setError("Use um valor entre -20 e 100.");return;}final int hitPoints,armor;try{hitPoints=Integer.parseInt(value(hp));if(hitPoints<1||hitPoints>9999)throw new IllegalArgumentException();}catch(Exception invalid){hp.setError("Informe PV entre 1 e 9999.");return;}try{armor=Integer.parseInt(value(ac));if(armor<1||armor>99)throw new IllegalArgumentException();}catch(Exception invalid){ac.setError("Informe CA entre 1 e 99.");return;}
            final boolean wasRunning=db.getCombatState().optInt("running",0)==1;
            try{db.runInTransactionChecked(new AppDb.CheckedTransaction(){public void run()throws Exception{
                db.addCombatantWithVisualChecked(combatantName,initiative,hitPoints,hitPoints,armor,value(conditions),false,"",0,"");
                db.setCombatRunningChecked(true);if(!wasRunning){JSONObject turn=db.nextTurn();if(turn.length()==0||turn.has("operation_error")||turn.has("turn_advance_blocked"))throw new IllegalStateException("Turno inicial bloqueado");}
            }});}catch(Exception error){toast("Combatente não adicionado: "+safeMessage(error));return;}
            added[0]=true;v.setEnabled(false);if(!wasRunning){String opening="O encontro tático começou com "+combatantName+" em cena e iniciativa confirmada pelo jogador.";prefs.edit().putString("last_combat_narration",opening).apply();db.addJournalFact("Combate iniciado",opening,"Combate","combat-start-"+db.getCombatState().optString("encounter_id",""),"combat");}dialog.dismiss();showCombat();}});}});
    }
    private void compiledCombatantDialog(){
        JSONArray available=new JSONArray();
        JSONArray installed=CompiledStatblockEngine.ids();
        for(int i=0;i<installed.length();i++){
            String id=installed.optString(i);JSONObject raw=CompiledStatblockEngine.get(id);
            JSONObject source=raw.optJSONObject("source_fidelity");
            if("Monster Manual (2025)".equals(raw.optString("source_book"))&&source!=null&&"XMM".equals(source.optString("source_code")))available.put(id);
        }
        if(available.length()==0){toast("Nenhum bloco XMM 2025 compilado está instalado.");return;}
        String[] ids=new String[available.length()];for(int i=0;i<available.length();i++)ids[i]=available.optString(i);
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),0);
        final Spinner block=spinner(ids,ids[0]);form.addView(cardWithLabel("MONSTRO • XMM 2025",block));
        final EditText name=labeledField(form,"Nome em cena (opcional)","",false);
        final EditText initiative=labeledField(form,"Iniciativa final (d20 + bônus)","",false);
        initiative.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
        final TextView details=text("",12,MUTED,false);form.addView(details);
        block.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> parent,View view,int position,long id){
            JSONObject profile=CompiledStatblockEngine.runtimeProfile(String.valueOf(block.getSelectedItem()));
            details.setText("PV "+profile.optInt("hit_points")+" • CA "+profile.optInt("armor_class")+" • ações "+(profile.optJSONArray("actions")==null?0:profile.optJSONArray("actions").length()));
        }public void onNothingSelected(AdapterView<?> parent){}});
        final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Adicionar monstro compilado")
            .setView(scrollableDialogView(form)).setNegativeButton("CANCELAR",null).setPositiveButton("ADICIONAR",null).create();
        final String spawnToken="ui-monster-spawn-"+java.util.UUID.randomUUID();final boolean[] spawned={false};
        showBoundDialog(dialog,new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View v){
            if(spawned[0])return;
            int roll;try{roll=Integer.parseInt(value(initiative));if(roll< -20||roll>100)throw new IllegalArgumentException();}catch(Exception invalid){initiative.setError("Informe o total da iniciativa.");return;}
            JSONObject result=db.addCompiledStatblockCombatant(String.valueOf(block.getSelectedItem()),value(name),roll,spawnToken);
            if(!result.optBoolean("statblock_spawn_committed",false)){toast("Monstro não adicionado: "+result.optString("statblock_spawn_blocked",result.optString("operation_error","revise o bloco")));return;}
            spawned[0]=true;v.setEnabled(false);
            if(result.optBoolean("encounter_started",false)){
                String opening="Encontro iniciado com "+result.optString("statblock_id")+" • XMM 2025 • iniciativa confirmada.";
                prefs.edit().putString("last_combat_narration",opening).apply();
                db.addJournalFact("Combate iniciado",opening,"Combate","combat-start-"+db.getCombatState().optString("encounter_id",""),"combat");
            }
            toast("Monstro compilado adicionado ao combate.");dialog.dismiss();showCombat();
        }});}});
    }
