    private void addMasterSupportCard(final LinearLayout parent){
        try{
            JSONArray citations=lastRagCitations==null?new JSONArray():copyJsonArray(lastRagCitations);
            if(citations.length()==0)try{citations=new JSONArray(prefs.getString("last_rag_citations","[]"));}catch(Exception ignored){citations=new JSONArray();}
            if(lastMasterSupport==null||lastMasterSupport.length()==0){
                lastMasterSupport=MasterSupportPanelEngine.build(new JSONObject(),activeRuleRetrieval,citations,db.getSceneState(),safeActiveCharacters(),currentOptions,pendingTest,lastPrompt,isMystaraWorld(),activeInputChannel());
            }
            final LinearLayout help=card();int helpAccent=Color.rgb(96,200,230);help.setBackground(makeBg(Color.rgb(19,49,73),helpAccent,12));
            help.addView(text("AJUDA DO MESTRE — FORA DA NARRATIVA",15,helpAccent,true));
            help.addView(text("Nada escrito neste quadro vira fala, ação, passagem de tempo ou consequência da aventura.",11,Color.rgb(190,225,238),false));

            String sceneSummary=lastMasterSupport.optString("scene_summary","");if(sceneSummary.length()>0){help.addView(text("CENA AGORA",11,helpAccent,true));help.addView(text(sceneSummary,13,Color.WHITE,false));}
            String did=lastMasterSupport.optString("what_happened","");if(did.length()>0){help.addView(text("O QUE O SISTEMA FEZ",11,helpAccent,true));help.addView(text(did,13,Color.WHITE,false));}
            help.addView(text("REGRAS",11,helpAccent,true));
            String rules=lastMasterSupport.optString("rules_explanation",prefs.getString("last_manual_context","Nenhuma explicação mecânica registrada."));help.addView(text(rules,13,Color.WHITE,false));
            int evidence=lastMasterSupport.optInt("evidence_count",0);String ruleStatus=lastMasterSupport.optBoolean("rules_searched",false)?(evidence>0?"✓ Manuais consultados • "+evidence+" fonte(s) pertinente(s)":"✓ Consulta executada • nenhuma passagem pertinente; mecânicas bloqueadas"):"Nenhuma consulta mecânica necessária nesta batida";help.addView(text(ruleStatus,11,evidence>0?Color.rgb(151,235,184):Color.rgb(240,211,132),true));

            JSONArray skills=lastMasterSupport.optJSONArray("skill_suggestions");if(skills!=null&&skills.length()>0){help.addView(text("PERÍCIAS / ABORDAGENS POSSÍVEIS",11,helpAccent,true));for(int i=0;i<skills.length();i++){JSONObject sk=skills.optJSONObject(i);if(sk==null)continue;String best=sk.optString("best_character","");String line="• "+sk.optString("skill","Abordagem")+(best.length()>0?" — melhor ficha: "+best:"")+"\n  "+sk.optString("why","");help.addView(text(line,12,Color.WHITE,false));}help.addView(text("São possibilidades opcionais. O Mestre só pede rolagem quando houver incerteza, consequência e competência relevante.",11,Color.rgb(190,225,238),false));}

            JSONArray sources=lastMasterSupport.optJSONArray("sources");if(sources!=null&&sources.length()>0){help.addView(text("FONTES CONSULTADAS",11,helpAccent,true));for(int i=0;i<sources.length()&&i<4;i++){JSONObject src=sources.optJSONObject(i);if(src==null)continue;String line="• "+src.optString("book","Manual")+(src.optInt("page",0)>0?" • p. "+src.optInt("page"):"");help.addView(text(line,11,Color.rgb(190,225,238),false));}}

            addMasterConversationHistory(help,helpAccent,false);

            help.addView(text("PERGUNTAR AO MESTRE SEM AGIR",12,helpAccent,true));
            final EditText question=input("Ex.: Quem está na cena? Qual a distância até a porta? O que meu personagem sabe? Que perícias poderiam servir?","",true);question.setMinLines(2);question.setEnabled(!aiBusy);help.addView(question);
            LinearLayout quick=new LinearLayout(this);quick.setOrientation(LinearLayout.HORIZONTAL);Button who=smallButton("O QUE ESTOU VENDO?",PANEL2),where=smallButton("POSIÇÃO E DISTÂNCIAS",PANEL2);who.setTextSize(10);where.setTextSize(10);who.setEnabled(!aiBusy);where.setEnabled(!aiBusy);who.setOnClickListener(new View.OnClickListener(){public void onClick(View v){sendMasterSideQuestion("O que estou vendo nesta cena agora? Descreva somente elementos observáveis já sustentados pelo estado: pessoas, criaturas, objetos, saídas, terreno e condições visíveis. Não avance o tempo e não transforme observação em ação.");}});where.setOnClickListener(new View.OnClickListener(){public void onClick(View v){sendMasterSideQuestion("Descreva a posição relativa dos presentes, as saídas visíveis e as distâncias já estabelecidas. Onde não houver medida exata no estado, diga claramente que ela ainda não foi fixada.");}});quick.addView(who,new LinearLayout.LayoutParams(0,dp(44),1));quick.addView(where,new LinearLayout.LayoutParams(0,dp(44),1));help.addView(quick);
            Button ask=button(aiBusy&&masterSideQueryActive?"RESPONDENDO...":"PERGUNTAR SEM AVANÇAR A CENA",helpAccent);ask.setTextColor(Color.rgb(8,24,36));ask.setEnabled(!aiBusy);ask.setOnClickListener(new View.OnClickListener(){public void onClick(View v){String q=question.getText().toString().trim();if(q.length()==0){toast("Escreva uma pergunta ao Mestre.");return;}sendMasterSideQuestion(q);}});help.addView(ask);
            parent.addView(help);
        }catch(Throwable error){AppLog.e("MasterSupportPanel","Falha ao montar o quadro auxiliar.",error);LinearLayout fallback=card();fallback.setBackground(makeBg(Color.rgb(19,49,73),Color.rgb(96,200,230),12));fallback.addView(text("AJUDA DO MESTRE INDISPONÍVEL",13,Color.WHITE,true));fallback.addView(text("A narrativa continua isolada. O quadro auxiliar encontrou: "+safeUiError(error),11,Color.WHITE,false));parent.addView(fallback);}
    }

    private void addStrixhavenMasterConversationCard(final LinearLayout parent){
        try{JSONArray history=masterConversationHistory();if(history.length()==0)return;final int blue=Color.rgb(96,200,230);LinearLayout help=card();help.setBackground(makeBg(Color.rgb(19,49,73),blue,12));help.addView(text("CONVERSA COM O MESTRE — FORA DA HISTÓRIA",11,blue,true));addMasterConversationHistory(help,blue,true);help.addView(text("A cena, o relógio, NPCs e o mapa não avançaram.",10,Color.rgb(190,225,238),false));parent.addView(help);}catch(Throwable error){AppLog.w("StrixMasterChat","Falha ao renderizar conversa auxiliar; narrativa preservada.",error);}
    }

    private JSONArray masterConversationHistory(){
        JSONArray history=lastMasterSupport==null?null:lastMasterSupport.optJSONArray("conversation_history");if(history!=null&&history.length()>0)return history;JSONArray fallback=new JSONArray();try{String q=lastMasterSupport==null?"":lastMasterSupport.optString("last_question","");String a=lastMasterSupport==null?"":lastMasterSupport.optString("last_answer","");if(a.length()>0){String scene=currentMasterConversationSceneFingerprint();fallback.put(new JSONObject().put("turn_id",stableFingerprint(scene+"|legacy|"+q+"|"+a)).put("question",q).put("answer",a).put("question_kind",masterQuestionKind(q)).put("actionable",masterQuestionCanBecomeAction(q)).put("scene_fingerprint",scene).put("promotion_status","available"));}}catch(Exception ignored){AppLog.ignored("MasterConversation","Falha ao reconstruir histórico legado.",ignored);}return fallback;
    }

    private JSONObject appendMasterConversationHistory(JSONObject previous,JSONObject current,String question,String answer){
        JSONObject out=copyJsonObject(current);try{JSONArray old=previous==null?null:previous.optJSONArray("conversation_history");JSONArray next=new JSONArray();if(old!=null){int start=Math.max(0,old.length()-7);for(int i=start;i<old.length();i++){JSONObject turn=old.optJSONObject(i);if(turn!=null)next.put(copyJsonObject(turn));}}String q=question==null?"":question.trim(),a=answer==null?"":answer.trim();JSONObject last=next.length()>0?next.optJSONObject(next.length()-1):null;boolean duplicate=last!=null&&q.equals(last.optString("question"))&&a.equals(last.optString("answer"));if(!duplicate&&a.length()>0){long created=System.currentTimeMillis();String scene=currentMasterConversationSceneFingerprint();JSONObject turn=new JSONObject().put("turn_id",stableFingerprint(scene+"|"+created+"|"+q)).put("question",q).put("answer",a).put("question_kind",masterQuestionKind(q)).put("actionable",masterQuestionCanBecomeAction(q)).put("scene_fingerprint",scene).put("promotion_status","available").put("created_at",created).put("hint_authority","advisory_only");JSONArray hints=current==null?null:current.optJSONArray("skill_suggestions");if(hints!=null&&hints.length()>0)turn.put("consultation_hints",copyJsonArray(hints));turn.put("consultation_evidence_count",current==null?0:current.optInt("evidence_count",0));turn.put("consultation_rules_status",current==null?"":current.optString("rules_status",""));next.put(turn);}out.put("conversation_history",next);}catch(Exception error){AppLog.w("MasterConversation","Falha ao anexar turno; última resposta foi preservada.",error);}return out;
    }

    private String currentMasterConversationSceneFingerprint(){return stableFingerprint(db.getActiveMapProfile()+"|"+db.getSceneState().toString()+"|"+lastNarration);}

    private JSONObject preserveMasterConversationHistory(JSONObject previous,JSONObject current){JSONObject out=copyJsonObject(current);try{JSONArray history=previous==null?null:previous.optJSONArray("conversation_history");if(history!=null&&history.length()>0)out.put("conversation_history",copyJsonArray(history));}catch(Exception error){AppLog.w("MasterConversation","Falha ao preservar histórico auxiliar entre cenas.",error);}return out;}

    private void addMasterConversationHistory(final LinearLayout parent,final int accent,boolean compact){
        JSONArray history=masterConversationHistory();if(history.length()==0)return;parent.addView(text(compact?"CONVERSA RECENTE":"HISTÓRICO DA CONVERSA",11,accent,true));String currentScene=currentMasterConversationSceneFingerprint();int start=Math.max(0,history.length()-(compact?3:6));for(int i=start;i<history.length();i++){JSONObject turn=history.optJSONObject(i);if(turn==null)continue;String question=turn.optString("question","");String answer=turn.optString("answer","");if(question.length()>0)parent.addView(text("Você: "+question,11,Color.rgb(190,225,238),false));if(answer.length()>0){TextView a=text("Mestre: "+answer,compact?12:13,Color.WHITE,false);a.setTextIsSelectable(true);a.setLineSpacing(0,1.08f);parent.addView(a);}String questionKind=turn.optString("question_kind",masterQuestionKind(question));if("information".equals(questionKind))parent.addView(text("CONSULTA • NÃO É UMA AÇÃO",9,Color.rgb(151,235,184),true));final String actionableQuestion=question;final String actionableTurnId=turn.optString("turn_id",stableFingerprint(turn.optString("scene_fingerprint",currentScene)+"|legacy|"+question));String promotionStatus=turn.optString("promotion_status","available");boolean sameScene=currentScene.equals(turn.optString("scene_fingerprint",currentScene));boolean available="available".equals(promotionStatus)||"cancelled".equals(promotionStatus)||promotionStatus.length()==0;if(sameScene&&available&&turn.optBoolean("actionable",masterQuestionCanBecomeAction(question))&&question.length()>0){Button tryIt=smallButton("cancelled".equals(promotionStatus)?"TENTAR NOVAMENTE NA HISTÓRIA":"TENTAR ISSO NA HISTÓRIA",GOLD);tryIt.setTextColor(Color.BLACK);tryIt.setOnClickListener(new View.OnClickListener(){public void onClick(View v){promoteMasterQuestionToAction(actionableTurnId,actionableQuestion);}});parent.addView(tryIt,new LinearLayout.LayoutParams(-1,dp(40)));}else if("awaiting_master".equals(promotionStatus)){parent.addView(text("✓ TENTATIVA CONFIRMADA • O MESTRE ESTÁ ENQUADRANDO A AÇÃO",10,Color.rgb(240,211,132),true));}else if("awaiting_roll".equals(promotionStatus)){parent.addView(text("✓ TENTATIVA CONFIRMADA • AGUARDANDO SUA ROLAGEM",10,Color.rgb(240,211,132),true));}else if("resolving_roll".equals(promotionStatus)){parent.addView(text("✓ ROLAGEM ENVIADA • O MESTRE ESTÁ INTERPRETANDO",10,Color.rgb(240,211,132),true));}else if("cancelled".equals(promotionStatus)){parent.addView(text("↩ TENTATIVA CANCELADA • VOCÊ PODE TENTAR NOVAMENTE NESTA CENA",10,Color.rgb(190,225,238),true));}else if("resolved".equals(promotionStatus)){parent.addView(text("✓ RESOLVIDO NA HISTÓRIA",10,Color.rgb(151,235,184),true));}String traceTest=turn.optString("test_label","");if(traceTest.length()>0)parent.addView(text("TESTE PEDIDO: "+traceTest,10,Color.rgb(240,211,132),false));if(turn.optLong("roll_id",0)>0){String traceRoll="ROLAGEM: "+turn.optString("roll_actor","Personagem")+" • "+turn.optString("roll_formula","d20")+" • total "+turn.optInt("roll_total",0)+" • "+("success".equals(turn.optString("roll_outcome"))?"SUCESSO":"FALHA");parent.addView(text(traceRoll,10,Color.rgb(190,225,238),true));}String storyTrace=turn.optString("resolution_excerpt","");if(storyTrace.length()>0)parent.addView(text("NA HISTÓRIA: "+storyTrace,compact?10:11,Color.WHITE,false));}}

    private String masterConversationResolutionExcerpt(String raw){String clean=raw==null?"":stripMarkdown(raw).replaceAll("\\s+"," ").trim();if(clean.length()<=260)return clean;return clean.substring(0,257)+"…";}

    private String masterQuestionKind(String raw){String q=raw==null?"":Normalizer.normalize(raw,Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.US).trim();if(q.length()==0)return "information";String[] observational={"o que estou vendo","o que eu vejo","quem esta","quem está","onde estou","qual a distancia","qual a distância","o que meu personagem sabe","o que sabemos","descreva","posicao e distancias","posição e distâncias"};for(String t:observational)if(q.contains(t))return "information";String[] possibility={"consigo","posso","seria possivel","seria possível","da para","dá para","tento","quero","vou ","subir","escalar","saltar","pular","abrir","forcar","arrombar","convencer","investigar","examinar","seguir","esconder","atacar","nadar","pegar","usar ","entrar","atravessar","desarmar"};for(String t:possibility)if(q.contains(t))return "action_possibility";return "information";}

    private boolean masterQuestionCanBecomeAction(String raw){return "action_possibility".equals(masterQuestionKind(raw));}

    private JSONObject updateMasterConversationTurn(String turnId,String status,JSONObject details){
        JSONObject support=copyJsonObject(lastMasterSupport);try{JSONArray history=support.optJSONArray("conversation_history");if(history==null)return support;JSONArray next=new JSONArray();for(int i=0;i<history.length();i++){JSONObject turn=history.optJSONObject(i);if(turn==null)continue;JSONObject copy=copyJsonObject(turn);String id=copy.optString("turn_id","");if(id.length()==0){id=stableFingerprint(copy.optString("scene_fingerprint","")+"|legacy|"+copy.optString("question","")+"|"+copy.optString("answer",""));copy.put("turn_id",id);}if(id.equals(turnId)){copy.put("promotion_status",status).put("promotion_updated_at",System.currentTimeMillis());if(details!=null){java.util.Iterator<String> keys=details.keys();while(keys.hasNext()){String key=keys.next();Object value=details.opt(key);if(value==null||value==JSONObject.NULL)copy.remove(key);else copy.put(key,value);}}}next.put(copy);}support.put("conversation_history",next);lastMasterSupport=support;prefs.edit().putString("last_master_support_json",support.toString()).apply();}catch(Exception error){AppLog.w("MasterConversation","Falha ao atualizar estado da tentativa promovida.",error);}return support;
    }

    private String masterPromotionAdvisoryContext(JSONObject turn){
        if(turn==null)return "";JSONArray hints=turn.optJSONArray("consultation_hints");if(hints==null||hints.length()==0)return "";StringBuilder b=new StringBuilder();for(int i=0;i<hints.length()&&i<3;i++){JSONObject h=hints.optJSONObject(i);if(h==null)continue;if(b.length()>0)b.append("; ");b.append(h.optString("skill","abordagem"));String why=h.optString("why","").trim();if(why.length()>0)b.append(" — ").append(why);}return b.toString();
    }

    private void promoteMasterQuestionToAction(String turnId,String rawQuestion){String q=rawQuestion==null?"":rawQuestion.trim();if(q.length()==0||aiBusy)return;String currentScene=currentMasterConversationSceneFingerprint();JSONArray history=masterConversationHistory();boolean allowed=false;JSONObject selectedTurn=null;for(int i=0;i<history.length();i++){JSONObject turn=history.optJSONObject(i);if(turn==null)continue;String id=turn.optString("turn_id",stableFingerprint(turn.optString("scene_fingerprint",currentScene)+"|legacy|"+turn.optString("question","")));String status=turn.optString("promotion_status","available");if(id.equals(turnId)&&currentScene.equals(turn.optString("scene_fingerprint",currentScene))&&("available".equals(status)||"cancelled".equals(status)||status.length()==0)){allowed=true;selectedTurn=turn;break;}}if(!allowed){toast("Essa possibilidade já foi usada ou pertence a outra cena.");return;}String advisory=masterPromotionAdvisoryContext(selectedTurn);boolean retrying="cancelled".equals(selectedTurn.optString("promotion_status","available"));JSONObject promotionDetails=new JSONObject();try{promotionDetails.put("hint_authority","advisory_only");if(advisory.length()>0)promotionDetails.put("promotion_advisory",advisory);if(retrying){promotionDetails.put("retry_count",selectedTurn.optInt("retry_count",0)+1);String[] stale={"test_key","test_label","test_ability","test_skill","test_mode","test_dc","test_source_rule_id","roll_id","roll_actor","roll_formula","roll_mode","roll_natural","roll_total","roll_outcome","roll_source","resolved_after_roll","resolved_without_roll","resolution_excerpt","resolution_scene_fingerprint"};for(String key:stale)promotionDetails.put(key,JSONObject.NULL);}}catch(Exception ignored){AppLog.ignored("MasterConversation","Falha ao registrar contexto consultivo da promoção.",ignored);}activeMasterPromotionTurnId=turnId;activeMasterPromotionQuestion=q;activeMasterPromotionFromRoll=false;updateMasterConversationTurn(turnId,"awaiting_master",promotionDetails);prefs.edit().putString("ai_mode","Narrador").apply();String declared="O jogador confirma que quer TENTAR na ficção a possibilidade discutida na consulta anterior. master_turn_id="+turnId+". Pergunta anterior: "+q+". "+(advisory.length()>0?"CONTEXTO AUXILIAR NÃO AUTORITATIVO da conversa azul: "+advisory+". NÃO copie isso como regra, não fixe CD por causa desta sugestão e não force essa perícia; use apenas como pista de intenção. ":"")+"Trate isto agora como PLAYER_ACTION. Decida o enquadramento mecânico de forma independente pelas regras recuperadas e pelo estado atual. Se houver incerteza e consequência real, peça o teste apropriado pelas regras e pause para a rolagem; depois da rolagem, interprete o resultado e retorne à história. Não considere a consulta anterior como ação já realizada.";sendAi("Narrador",declared);}

    private void sendMasterSideQuestion(String rawQuestion){
        String question=rawQuestion==null?"":rawQuestion.trim();if(question.length()==0){toast("Escreva uma pergunta ao Mestre.");return;}if(aiBusy){toast("Aguarde a resposta atual.");return;}
        masterSideQueryActive=true;masterSideQueryText=question;masterSidePreviousAiMode=lastAiMode;masterSidePreviousPrompt=lastPrompt;masterSidePreviousUsedRag=lastAiUsedRag;masterSidePreviousCitations=copyJsonArray(lastRagCitations);masterSidePreviousRuleRetrieval=copyJsonObject(activeRuleRetrieval);masterSidePreviousManuals=copyJsonArray(lastAiManuals);masterSidePreviousManualContext=prefs.getString("last_manual_context","");masterSidePreviousSourceAudit=prefs.getString("last_source_audit","{}");
        String routed="CONSULTA AUXILIAR FORA DA FICÇÃO. Responda no quadro separado e não altere a aventura. Se houver várias perguntas, responda uma por uma. Não invente distância, presença, conhecimento ou regra que não esteja no estado/manuais. Se a pergunta for sobre uma possibilidade de ação (por exemplo: posso/consigo subir, abrir, convencer, atravessar), explique primeiro o que é observável e se a tentativa parece possível. Se houver incerteza com consequência e as regras recuperadas sustentarem isso, diga qual atributo/perícia provavelmente seria testado; NÃO fixe CD, não role e não crie teste pendente no canal GM_HELP. A rolagem só nasce depois de o jogador confirmar TENTAR NA HISTÓRIA, quando a mensagem será promovida a PLAYER_ACTION. PERGUNTA DO JOGADOR: "+question;
        sendAi("Narrador",routed);
    }

    private void restoreAfterMasterSideQuery(){
        lastAiMode=masterSidePreviousAiMode;lastPrompt=masterSidePreviousPrompt;lastAiUsedRag=masterSidePreviousUsedRag;lastRagCitations=copyJsonArray(masterSidePreviousCitations);activeRuleRetrieval=copyJsonObject(masterSidePreviousRuleRetrieval);lastAiManuals=copyJsonArray(masterSidePreviousManuals);
        SharedPreferences.Editor edit=prefs.edit().putString("last_manual_context",masterSidePreviousManualContext).putString("last_source_audit",masterSidePreviousSourceAudit).putString("last_ai_response_mode",lastAiMode);if(lastRagCitations.length()>0)edit.putString("last_rag_citations",lastRagCitations.toString());else edit.remove("last_rag_citations");edit.apply();
        masterSideQueryActive=false;masterSideQueryText="";activeMasterPlan=null;if(masterOrchestrator!=null)masterOrchestrator.setActivePlanForValidation(null);
    }

    private void showNarratorRecovery(final Throwable openingError){
        narratorScroll=page("Mestre IA","Modo seguro: a narração, o chat e os comandos continuam disponíveis enquanto o painel que falhou permanece isolado.");
        final LinearLayout b=body(narratorScroll);
        addRuleCuriosityButton(b);
        LinearLayout warning=card();
        warning.setBackground(makeBg(Color.rgb(70,38,34),RED,12));
        warning.addView(text(openingError==null?"MODO SEGURO DO MESTRE IA":"A TELA COMPLETA ENCONTROU UM ERRO",15,Color.WHITE,true));
        String detail=openingError==null?"Um erro anterior foi isolado para impedir que a tela inteira volte a fechar.":openingError.getClass().getSimpleName()+": "+safeUiError(openingError);
        warning.addView(text(detail,12,Color.WHITE,false));
        LinearLayout recoveryButtons=new LinearLayout(this);recoveryButtons.setOrientation(LinearLayout.HORIZONTAL);
        Button retryFull=smallButton("TENTAR TELA COMPLETA",GOLD);retryFull.setTextColor(Color.BLACK);
        retryFull.setOnClickListener(new View.OnClickListener(){public void onClick(View v){prefs.edit().putBoolean("master_screen_safe_mode",false).apply();screenCache.remove("Mestre IA");screenCacheTime.remove("Mestre IA");showNarrator();}});
        Button clearVisual=smallButton("LIMPAR CACHE VISUAL",PANEL2);
        clearVisual.setOnClickListener(new View.OnClickListener(){public void onClick(View v){sharedImageUri=null;sceneImage=null;prefs.edit().remove(PREF_SCENE_IMAGE_URI).remove(PREF_SCENE_IMAGE_FINGERPRINT).remove(PREF_PENDING_IMAGE_FINGERPRINT).putBoolean("master_screen_safe_mode",false).apply();screenCache.remove("Mestre IA");screenCacheTime.remove("Mestre IA");toast("Somente a referência visual da cena foi limpa; campanha, fichas e manuais foram preservados.");showNarrator();}});
        recoveryButtons.addView(retryFull,new LinearLayout.LayoutParams(0,dp(48),1));recoveryButtons.addView(clearVisual,new LinearLayout.LayoutParams(0,dp(48),1));warning.addView(recoveryButtons);
        Button copyDiagnostic=button("COPIAR DIAGNÓSTICO",PANEL2);copyDiagnostic.setOnClickListener(new View.OnClickListener(){public void onClick(View v){String diagnostic="Mestre IA • "+BuildConfig.VERSION_NAME+" • "+(openingError==null?"modo seguro persistido":openingError.getClass().getName()+": "+safeUiError(openingError));ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(cm!=null)cm.setPrimaryClip(ClipData.newPlainText("Diagnóstico Mestre IA",diagnostic));toast("Diagnóstico copiado.");}});warning.addView(copyDiagnostic);b.addView(warning);

        LinearLayout modeCard=card();modeCard.addView(text("MODO DE USO",12,GOLD,true));
        narratorMode=spinner(new String[]{"Narrador","Regras RAW/RAI","Sortear dos livros","Criar encontro","Criar NPC","Preparar sessão"},prefs.getString("ai_mode","Narrador"));modeCard.addView(narratorMode,new LinearLayout.LayoutParams(-1,dp(50)));b.addView(modeCard);

        LinearLayout response=card();response.addView(text("NARRAÇÃO",13,GOLD,true));String safeNarration=lastNarration==null||lastNarration.trim().length()==0?"A aventura ainda não começou.":lastNarration;addNarrationChapters(response,safeNarration);b.addView(response);
        addMasterSupportCard(b);

        LinearLayout command=card();command.addView(text("AÇÃO LIVRE DO PERSONAGEM / GRUPO",13,GOLD,true));narratorInput=input("Descreva somente a ação que o personagem ou grupo executa. Dúvidas ficam no quadro azul acima.","",true);if(pendingRestoredNarratorDraft!=null&&pendingRestoredNarratorDraft.length()>0){narratorInput.setText(pendingRestoredNarratorDraft);narratorInput.setSelection(narratorInput.length());pendingRestoredNarratorDraft="";}narratorInput.setMinLines(3);narratorInput.setEnabled(!aiBusy);command.addView(narratorInput);
        Button send=button(aiBusy?"AGUARDE...":"ENVIAR AO MESTRE",GOLD);send.setTextColor(Color.BLACK);send.setEnabled(!aiBusy);send.setOnClickListener(new View.OnClickListener(){public void onClick(View v){String query=narratorInput.getText().toString().trim();if(query.length()==0){toast("Descreva uma ação ou pergunta.");return;}String mode=narratorMode==null?"Narrador":String.valueOf(narratorMode.getSelectedItem());prefs.edit().putString("ai_mode",mode).apply();sendAi(mode,query);}});command.addView(send);b.addView(command);

        LinearLayout links=new LinearLayout(this);links.setOrientation(LinearLayout.HORIZONTAL);Button manuals=smallButton("MANUAIS",PANEL2),settings=smallButton("CONFIGURAÇÕES",PANEL2);manuals.setOnClickListener(new View.OnClickListener(){public void onClick(View v){navigate("Manuais");}});settings.setOnClickListener(new View.OnClickListener(){public void onClick(View v){navigate("Config");}});links.addView(manuals,new LinearLayout.LayoutParams(0,dp(48),1));links.addView(settings,new LinearLayout.LayoutParams(0,dp(48),1));b.addView(links);
    }

    private void addNarratorSectionSafely(LinearLayout parent,String title,Runnable section){
        try{section.run();}
        catch(Throwable error){AppLog.e("MestreIA","Painel isolado: "+title,error);LinearLayout warning=card();warning.addView(text(title.toUpperCase(new Locale("pt","BR"))+" INDISPONÍVEL",12,RED,true));warning.addView(text("Este painel foi ignorado sem fechar o Mestre IA. "+safeUiError(error),11,MUTED,false));parent.addView(warning);}
    }

    private int safePartyActionCount(){try{return db==null?0:db.countPartyActions("queued");}catch(Throwable error){AppLog.e("MestreIA","Falha ao contar ações da companhia.",error);return 0;}}
