    private String[] speciesForProfile(String profile){
        java.util.LinkedHashSet<String> all=new java.util.LinkedHashSet<String>();
        if(profile!=null&&profile.startsWith("5.5"))java.util.Collections.addAll(all,"Humano","Anão","Elfo","Halfling","Draconato","Gnomo","Golias","Orc","Tiefling","Aasimar");
        else if(profile!=null&&profile.startsWith("Híbrido"))java.util.Collections.addAll(all,"Humano","Anão","Elfo","Halfling","Draconato","Gnomo","Golias","Orc","Meio-elfo","Meio-orc","Tiefling","Aasimar");
        else java.util.Collections.addAll(all,"Humano","Anão","Elfo","Halfling","Draconato","Gnomo","Meio-elfo","Meio-orc","Tiefling");
        JSONArray legacyCross=CrossBookCharacterOptionEngine.allSpecies();for(int i=0;i<legacyCross.length();i++)all.add(legacyCross.optString(i));
        JSONArray extra=CharacterOptionCatalogEngine.allSpecies();for(int i=0;i<extra.length();i++)all.add(extra.optString(i));
        JSONArray eberron=EberronForgeCompleteEngine.species();for(int i=0;i<eberron.length();i++)all.add(eberron.optString(i));
        all.add("Dhampir");
        all.add("Boggart");
        all.add("Elfo de Lorwyn-Shadowmoor");
        all.add("Faerie");
        all.add("Flamekin");
        all.add("Kithkin");
        all.add("Changeling de Lorwyn");
        all.add("Rimekin");
        return all.toArray(new String[all.size()]);
    }
