    private int[] suggestedStats(String cls){String c=cls.toLowerCase(Locale.US);if(c.contains("mago")||c.contains("artíf")||c.contains("artific"))return new int[]{8,14,13,15,12,10};if(c.contains("feiticeiro")||c.contains("bardo")||c.contains("bruxo"))return new int[]{8,14,13,10,12,15};if(c.contains("clérigo")||c.contains("druida"))return new int[]{10,12,14,8,15,13};if(c.contains("ladino")||c.contains("monge")||c.contains("patrulheiro"))return new int[]{10,15,14,12,13,8};return new int[]{15,13,14,8,12,10};}
