    private int abilityModifier(JSONObject ch,String ability){String a=ability==null?"":ability.toLowerCase(Locale.US);int score;if(a.startsWith("for"))score=ch.optInt("str",10);else if(a.startsWith("des"))score=ch.optInt("dex",10);else if(a.startsWith("con"))score=ch.optInt("con",10);else if(a.startsWith("int"))score=ch.optInt("int_score",10);else if(a.startsWith("sab")||a.startsWith("wis"))score=ch.optInt("wis",10);else score=ch.optInt("cha",10);return modifier(score);}



    private void showGuilds(){
        if(guildEngine==null)guildEngine=new GuildEngine(db);ScrollView s=page("Guildas","Organizações completas com hierarquia, membros, reputação, contratos, projetos, sedes, relações, estoque e tesouraria ligadas ao Mundo Vivo.");LinearLayout b=body(s);
        JSONObject npcReport=db.backfillNpcPersonalities();LinearLayout status=card();status.addView(text("NPCs & PERSONALIDADES",16,GOLD,true));status.addView(text(npcReport.optInt("catalog_profiles",300)+" perfis no catálogo • "+npcReport.optInt("after",0)+" NPCs persistentes com personalidade aplicada",13,TEXT,false));status.addView(text("Todo NPC criado, importado, restaurado, apresentado em cena ou inscrito em guilda recebe um perfil persistente sem substituir edições do Mestre.",12,GREEN,false));b.addView(status);
        LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button add=smallButton("+ NOVA GUILDA",GREEN),seed=smallButton("GERAR GUILDAS DO CENÁRIO",GOLD);seed.setTextColor(Color.BLACK);add.setOnClickListener(new View.OnClickListener(){public void onClick(View v){guildDialog(null);}});seed.setOnClickListener(new View.OnClickListener(){public void onClick(View v){try{int created=guildEngine.seedSuggestedGuilds(db.getCampaign().optString("tone"));screenCache.remove("Guildas");showGuilds();toast(created>0?created+" guildas integradas ao mundo.":"Já existem guildas nesta campanha.");}catch(Exception e){toast("Não foi possível gerar guildas: "+e.getMessage());}}});actions.addView(add,new LinearLayout.LayoutParams(0,dp(48),1));actions.addView(seed,new LinearLayout.LayoutParams(0,dp(48),1));b.addView(actions);
        List<JSONObject> guilds=db.listGuilds(200);if(guilds.isEmpty())b.addView(empty("Nenhuma guilda criada. Gere um conjunto inicial ou crie uma organização própria."));
        for(JSONObject guild:guilds){final long id=guild.optLong("id");LinearLayout c=card();c.setBackground(makeBg(PANEL,CARD_STROKE,12));LinearLayout top=new LinearLayout(this);top.setOrientation(LinearLayout.HORIZONTAL);top.setGravity(Gravity.CENTER_VERTICAL);LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.addView(text(guild.optString("name"),18,GOLD,true));info.addView(text(guild.optString("type","Outra")+" • "+guild.optString("headquarters","sede não definida"),13,MUTED,false));top.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button open=smallButton("ABRIR",PANEL2);open.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showGuildDetail(id);}});top.addView(open);c.addView(top);String desc=guild.optString("description");if(desc.length()>0)c.addView(text(desc,13,TEXT,false));c.addView(text("Influência "+guild.optInt("influence")+" • Reputação do grupo "+guild.optInt("party_reputation")+" • Tesouro "+formatGuildMoney(guild.optDouble("treasury"))+" "+guild.optString("currency","po"),13,TEXT,true));c.addView(text(db.countGuildMembers(id)+" membros • "+(db.countGuildContracts(id,"open")+db.countGuildContracts(id,"accepted"))+" contratos ativos • "+db.countGuildProjects(id,"active")+" projetos",12,GREEN,false));b.addView(c);}
    }

    private void guildDialog(final JSONObject current){
        final JSONObject g=current==null?new JSONObject():current;LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(12),0,dp(12),dp(12));final EditText name=labeledField(f,"Nome",g.optString("name"),false);final Spinner type=spinner(GuildEngine.TYPES,g.optString("type","Outra"));f.addView(cardWithLabel("TIPO",type));final EditText description=labeledField(f,"Descrição",g.optString("description"),true),charter=labeledField(f,"Carta, valores e regras internas",g.optString("charter"),true),hq=labeledField(f,"Sede principal",g.optString("headquarters"),false),treasury=labeledField(f,"Tesouro atual",String.valueOf(g.optDouble("treasury",0)),false),currency=labeledField(f,"Moeda",g.optString("currency","po"),false),influence=labeledField(f,"Influência (0–100)",String.valueOf(g.optInt("influence",25)),false),rep=labeledField(f,"Reputação do grupo (-100–100)",String.valueOf(g.optInt("party_reputation",0)),false),admission=labeledField(f,"Requisitos de admissão, um por linha",looseArrayLines(g.optString("admission_json","[]")),true),benefits=labeledField(f,"Benefícios, um por linha",looseArrayLines(g.optString("benefits_json","[]")),true),services=labeledField(f,"Serviços, um por linha",looseArrayLines(g.optString("services_json","[]")),true),rules=labeledField(f,"Regras e proibições, uma por linha",looseArrayLines(g.optString("rules_json","[]")),true),plan=labeledField(f,"Plano atual",g.optString("current_plan"),true);treasury.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);influence.setInputType(InputType.TYPE_CLASS_NUMBER);rep.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
        new AlertDialog.Builder(this).setTitle(current==null?"Nova guilda":"Editar guilda").setView(scrollableDialogView(f)).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject x=new JSONObject();if(g.optLong("id")>0)x.put("id",g.optLong("id"));x.put("name",value(name)).put("type",String.valueOf(type.getSelectedItem())).put("description",value(description)).put("charter",value(charter)).put("headquarters",value(hq)).put("treasury",decimal(treasury,0)).put("currency",value(currency)).put("influence",num(influence,25)).put("party_reputation",num(rep,0)).put("admission_json",linesArray(admission).toString()).put("benefits_json",linesArray(benefits).toString()).put("services_json",linesArray(services).toString()).put("rules_json",linesArray(rules).toString()).put("current_plan",value(plan));long id=current==null?guildEngine.create(x):guildEngine.update(x);db.addAuditEvent("guilda",current==null?"Guilda criada":"Guilda atualizada",value(name),g.toString(),db.getGuild(id).toString(),true);screenCache.remove("Guildas");showGuildDetail(id);}catch(Exception e){toast("Guilda não salva: "+e.getMessage());}}}).show();
    }

    private void showGuildDetail(final long guildId){
        final JSONObject g=db.getGuild(guildId);if(g.length()==0){showGuilds();return;}content.removeAllViews();ScrollView s=new ScrollView(this);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(12),dp(12),dp(12),dp(32));s.addView(b);content.addView(s,new FrameLayout.LayoutParams(-1,-1));
        Button back=smallButton("← TODAS AS GUILDAS",PANEL2);back.setOnClickListener(new View.OnClickListener(){public void onClick(View v){screenCache.remove("Guildas");showGuilds();}});b.addView(back);LinearLayout head=card();head.addView(text(g.optString("name"),23,GOLD,true));head.addView(text(g.optString("type")+" • "+g.optString("headquarters","sede não definida"),14,MUTED,true));head.addView(text(g.optString("description"),14,TEXT,false));head.addView(text("CARTA E VALORES",12,GOLD,true));head.addView(text(g.optString("charter","Não definidos."),13,TEXT,false));head.addView(text("Tesouro "+formatGuildMoney(g.optDouble("treasury"))+" "+g.optString("currency","po")+" • influência "+g.optInt("influence")+" • reputação do grupo "+g.optInt("party_reputation"),13,GREEN,true));LinearLayout editRow=new LinearLayout(this);editRow.setOrientation(LinearLayout.HORIZONTAL);Button edit=smallButton("EDITAR",PANEL2),ledger=smallButton("LANÇAMENTO",PANEL2),del=smallButton("EXCLUIR",RED);edit.setOnClickListener(new View.OnClickListener(){public void onClick(View v){guildDialog(g);}});ledger.setOnClickListener(new View.OnClickListener(){public void onClick(View v){guildLedgerDialog(guildId);}});del.setOnClickListener(new View.OnClickListener(){public void onClick(View v){confirm("Excluir a guilda e todos os seus membros, contratos e projetos?",new Runnable(){public void run(){try{safety.beforeDestructiveChange("excluir guilda");db.deleteGuild(guildId);screenCache.remove("Guildas");showGuilds();}catch(Exception e){toast("Exclusão bloqueada: "+e.getMessage());}}});}});editRow.addView(edit,new LinearLayout.LayoutParams(0,dp(44),1));editRow.addView(ledger,new LinearLayout.LayoutParams(0,dp(44),1));editRow.addView(del,new LinearLayout.LayoutParams(0,dp(44),1));head.addView(editRow);b.addView(head);
        addGuildMembersSection(b,g);addGuildContractsSection(b,g);addGuildProjectsSection(b,g);addGuildSitesSection(b,g);addGuildRelationsSection(b,g);addGuildLedgerSection(b,g);
    }

    private void addGuildMembersSection(LinearLayout b,final JSONObject guild){final long gid=guild.optLong("id");LinearLayout c=card();c.addView(text("MEMBROS & HIERARQUIA",16,GOLD,true));LinearLayout addRow=new LinearLayout(this);addRow.setOrientation(LinearLayout.HORIZONTAL);Button hero=smallButton("+ HERÓI",GREEN),npc=smallButton("+ NPC",GREEN),rank=smallButton("+ PATENTE",PANEL2);hero.setOnClickListener(new View.OnClickListener(){public void onClick(View v){guildHeroMemberDialog(gid);}});npc.setOnClickListener(new View.OnClickListener(){public void onClick(View v){guildNpcMemberDialog(gid);}});rank.setOnClickListener(new View.OnClickListener(){public void onClick(View v){guildRankDialog(gid);}});addRow.addView(hero,new LinearLayout.LayoutParams(0,dp(44),1));addRow.addView(npc,new LinearLayout.LayoutParams(0,dp(44),1));addRow.addView(rank,new LinearLayout.LayoutParams(0,dp(44),1));c.addView(addRow);for(JSONObject m:db.listGuildMembers(gid,"",200)){String name="hero".equals(m.optString("member_kind"))?m.optString("hero_name","Herói"):m.optString("npc_name","NPC");LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.addView(text(name,14,TEXT,true));info.addView(text(m.optString("rank_name","Sem patente")+" • "+m.optString("status")+" • reputação "+m.optInt("reputation")+(m.optInt("dues_due_day",0)>0?" • taxa pendente desde o dia "+m.optInt("dues_due_day"):""),12,MUTED,false));row.addView(info,new LinearLayout.LayoutParams(0,-2,1));final long memberId=m.optLong("id");if(m.optInt("dues_due_day",0)>0&&m.optDouble("rank_dues_amount",0d)>0d){Button pay=smallButton("PAGAR",GOLD);pay.setTextColor(Color.BLACK);pay.setOnClickListener(new View.OnClickListener(){public void onClick(View v){try{JSONObject current=db.getGuildMember(memberId);db.recordGuildDuesPaymentChecked(memberId,current.optDouble("rank_dues_amount",0d),"registro manual");showGuildDetail(gid);toast("Mensalidade registrada.");}catch(Exception e){toast("Pagamento não registrado: "+e.getMessage());}}});row.addView(pay);}Button toggle=smallButton("active".equals(m.optString("status"))?"SUSPENDER":"ATIVAR",PANEL2);toggle.setOnClickListener(new View.OnClickListener(){public void onClick(View v){db.updateGuildMemberStatus(memberId,"active".equals(m.optString("status"))?"suspended":"active");showGuildDetail(gid);}});row.addView(toggle);c.addView(row);}b.addView(c);}

    private void guildHeroMemberDialog(final long gid){List<JSONObject> heroes=db.listCharacters();if(heroes.isEmpty()){toast("Crie um herói primeiro.");return;}String[] names=new String[heroes.size()];for(int i=0;i<heroes.size();i++)names[i]=heroes.get(i).optString("name");final Spinner hero=spinner(names,names[0]);final Spinner rank=spinner(guildRankNames(gid),guildRankNames(gid)[0]);LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.addView(cardWithLabel("HERÓI",hero));f.addView(cardWithLabel("PATENTE",rank));new AlertDialog.Builder(this).setTitle("Inscrever herói").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("INScrever",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject ch=findCharacterByName(String.valueOf(hero.getSelectedItem()));long rankId=findGuildRankId(gid,String.valueOf(rank.getSelectedItem()));db.addGuildMemberChecked(new JSONObject().put("guild_id",gid).put("member_kind","hero").put("character_id",ch.optLong("id")).put("rank_id",rankId).put("status","active"));showGuildDetail(gid);}catch(Exception e){toast("Membro não adicionado: "+e.getMessage());}}}).show();}
    private void guildNpcMemberDialog(final long gid){JSONArray npcs=db.listNpcMemories(1000);if(npcs.length()==0){toast("Nenhum NPC persistente foi criado ainda.");return;}String[] names=new String[npcs.length()];for(int i=0;i<npcs.length();i++)names[i]=npcs.optJSONObject(i).optString("name");final Spinner npc=spinner(names,names[0]);final String[] ranks=guildRankNames(gid);final Spinner rank=spinner(ranks,ranks[0]);LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.addView(cardWithLabel("NPC",npc));f.addView(cardWithLabel("PATENTE",rank));new AlertDialog.Builder(this).setTitle("Inscrever NPC").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("INSCREVER",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{String name=String.valueOf(npc.getSelectedItem());db.addGuildMemberChecked(new JSONObject().put("guild_id",gid).put("member_kind","npc").put("npc_name",name).put("rank_id",findGuildRankId(gid,String.valueOf(rank.getSelectedItem()))).put("status","active"));showGuildDetail(gid);}catch(Exception e){toast("NPC não adicionado: "+e.getMessage());}}}).show();}
    private void guildRankDialog(final long gid){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);final EditText name=labeledField(f,"Nome da patente","",false),order=labeledField(f,"Ordem hierárquica","0",false),requirements=labeledField(f,"Requisitos, um por linha","",true),benefits=labeledField(f,"Benefícios, um por linha","",true),permissions=labeledField(f,"Permissões, uma por linha","",true),dues=labeledField(f,"Mensalidade / taxa","0",false);new AlertDialog.Builder(this).setTitle("Nova patente").setView(scrollableDialogView(f)).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{db.addGuildRankChecked(new JSONObject().put("guild_id",gid).put("name",value(name)).put("rank_order",num(order,0)).put("requirements_json",linesArray(requirements)).put("benefits_json",linesArray(benefits)).put("permissions_json",linesArray(permissions)).put("dues_amount",decimal(dues,0)));showGuildDetail(gid);}catch(Exception e){toast("Patente não salva: "+e.getMessage());}}}).show();}

    private void addGuildContractsSection(LinearLayout b,final JSONObject g){final long gid=g.optLong("id");LinearLayout c=card();c.addView(text("CONTRATOS & TRABALHOS",16,GOLD,true));Button add=smallButton("+ NOVO CONTRATO",GREEN);add.setOnClickListener(new View.OnClickListener(){public void onClick(View v){guildContractDialog(gid);}});c.addView(add);for(final JSONObject x:db.listGuildContracts(gid,"",100)){c.addView(text(x.optString("title"),14,TEXT,true));c.addView(text(x.optString("status")+(x.optInt("deadline_day")>0?" • prazo dia "+x.optInt("deadline_day"):"")+"\n"+x.optString("description"),12,MUTED,false));LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);if("open".equals(x.optString("status"))){Button accept=smallButton("ACEITAR",GREEN);accept.setOnClickListener(new View.OnClickListener(){public void onClick(View v){try{long questId=db.acceptGuildContractChecked(x.optLong("id"),0);db.addJournal("Contrato de guilda aceito",x.optString("title")+" — missão "+questId+" criada para "+g.optString("name"),"Guilda");showGuildDetail(gid);}catch(Exception e){toast(e.getMessage());}}});row.addView(accept);}if("accepted".equals(x.optString("status"))){Button done=smallButton("CONCLUIR",GOLD);done.setTextColor(Color.BLACK);done.setOnClickListener(new View.OnClickListener(){public void onClick(View v){try{db.completeGuildContractChecked(x.optLong("id"));db.addJournal("Contrato de guilda concluído",x.optString("title")+" — "+g.optString("name")+". Recompensas mecânicas permanecem em revisão segura.","Guilda");showGuildDetail(gid);}catch(Exception e){toast(e.getMessage());}}});row.addView(done);}if(row.getChildCount()>0)c.addView(row);}b.addView(c);}
