    private void guildProjectDialog(final long gid){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);final EditText title=labeledField(f,"Título","",false),description=labeledField(f,"Descrição","",true),kind=labeledField(f,"Tipo","obra",false),goal=labeledField(f,"Meta de progresso","100",false),rate=labeledField(f,"Progresso por dia","5",false),cost=labeledField(f,"Custos, um por linha","",true),result=labeledField(f,"Resultado, um por linha","",true),location=labeledField(f,"Local","",false);new AlertDialog.Builder(this).setTitle("Novo projeto").setView(scrollableDialogView(f)).setNegativeButton("Cancelar",null).setPositiveButton("INICIAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{db.addGuildProjectChecked(new JSONObject().put("guild_id",gid).put("title",value(title)).put("description",value(description)).put("kind",value(kind)).put("goal",decimal(goal,100)).put("progress_per_day",decimal(rate,5)).put("cost_json",linesArray(cost).toString()).put("result_json",linesArray(result).toString()).put("location",value(location)));showGuildDetail(gid);}catch(Exception e){toast("Projeto não salvo: "+e.getMessage());}}}).show();}

