    private void guildRelationDialog(final long gid){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);final Spinner kind=spinner(new String[]{"guild","faction","settlement","other"},"guild");f.addView(cardWithLabel("TIPO DE ALVO",kind));final EditText target=labeledField(f,"Nome do alvo","",false),relation=labeledField(f,"Relação (-100–100)","0",false),stance=labeledField(f,"Postura","neutral",false),treaties=labeledField(f,"Tratados, um por linha","",true),notes=labeledField(f,"Notas","",true);new AlertDialog.Builder(this).setTitle("Relação da guilda").setView(scrollableDialogView(f)).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{db.upsertGuildRelationChecked(new JSONObject().put("guild_id",gid).put("target_kind",String.valueOf(kind.getSelectedItem())).put("target_name",value(target)).put("relation",num(relation,0)).put("stance",value(stance)).put("treaties_json",linesArray(treaties).toString()).put("notes",value(notes)));showGuildDetail(gid);}catch(Exception e){toast("Relação não salva: "+e.getMessage());}}}).show();}

