    private JSONArray linesArray(EditText field){JSONArray out=new JSONArray();for(String line:value(field).split("\\r?\\n"))if(line.trim().length()>0)out.put(line.trim());return out;}
    private double decimal(EditText field,double fallback){try{return Double.parseDouble(value(field).replace(',','.'));}catch(Exception e){return fallback;}}
    private String formatGuildMoney(double value){if(Math.abs(value-Math.rint(value))<.001)return String.valueOf((long)Math.rint(value));return String.format(Locale.US,"%.2f",value);}
    private String[] guildRankNames(long gid){List<JSONObject> rows=db.listGuildRanks(gid);if(rows.isEmpty())return new String[]{"Sem patente"};String[] out=new String[rows.size()];for(int i=0;i<rows.size();i++)out[i]=rows.get(i).optString("name");return out;}
    private long findGuildRankId(long gid,String name){for(JSONObject r:db.listGuildRanks(gid))if(name.equals(r.optString("name")))return r.optLong("id");return db.defaultGuildRank(gid).optLong("id");}
    private JSONObject findCharacterByName(String name){for(JSONObject h:db.listCharacters())if(name.equals(h.optString("name")))return h;return new JSONObject();}

    private void showLivingWorld(){
        if(livingWorldEngine==null)livingWorldEngine=new LivingWorldEngine(db);
        ScrollView s=page("Mundo Vivo","Sandbox de campanha: os heróis envelhecem, criam vínculos, mantêm ocupações e podem viajar como uma trupe, sempre sob as regras do mundo ativo.");LinearLayout b=body(s);
        final JSONObject state=livingWorldEngine.state();final int day=livingWorldEngine.currentDay();
        LinearLayout calendar=card();calendar.addView(text("CALENDÁRIO CANÔNICO",17,GOLD,true));calendar.addView(text(livingWorldEngine.calendarLabel(day)+"\nModo: "+livingWorldModeLabel(state.optString("simulation_mode"))+" • "+(state.optInt("enabled",1)==1?"simulação ativa":"simulação pausada")+" • tempo real "+(state.optInt("background_simulation_enabled",0)==1?"conectado":"desligado"),14,TEXT,false));
        calendar.addView(text("Envelhecer nunca altera atributos, PV, nível ou outras estatísticas automaticamente. Atividades só mudam ficha, inventário ou recursos quando uma regra do mundo ativo tem fonte, página e trecho registrados.",12,GREEN,false));
        LinearLayout calendarActions=new LinearLayout(this);calendarActions.setOrientation(LinearLayout.HORIZONTAL);Button advance=smallButton("AVANÇAR TEMPO",GOLD),settings=smallButton("CONFIGURAR",PANEL2);advance.setTextColor(Color.BLACK);advance.setOnClickListener(new View.OnClickListener(){public void onClick(View v){livingWorldAdvanceDialog();}});settings.setOnClickListener(new View.OnClickListener(){public void onClick(View v){livingWorldSettingsDialog(state);}});calendarActions.addView(advance,new LinearLayout.LayoutParams(0,dp(48),1));calendarActions.addView(settings,new LinearLayout.LayoutParams(0,dp(48),1));calendar.addView(calendarActions);b.addView(calendar);

        addLivingWorldAutomationPanel(b,state,day);
        addWorldSixPanel(b,day);

        JSONObject troupe=livingWorldEngine.troupe();LinearLayout troupeCard=card();troupeCard.addView(text("TRUPE / MODO DE VIDA DO GRUPO",17,GOLD,true));if(troupe.length()==0)troupeCard.addView(text("Nenhuma trupe configurada. O grupo pode manter uma base, vagar junto ou atuar como companhia itinerante.",13,MUTED,false));else{troupeCard.addView(text(troupe.optString("name","Companhia")+" • "+troupe.optString("troupe_mode","itinerante"),16,TEXT,true));troupeCard.addView(text("Agora: "+emptyAs(troupe.optString("current_location"),"local não definido")+" • Base: "+emptyAs(troupe.optString("home_base"),"sem base fixa"),13,MUTED,false));troupeCard.addView(text("Integrantes: "+looseArrayLines(troupe.optString("members_json","[]")).replace("\n",", "),13,TEXT,false));if(troupe.optString("notes").length()>0)troupeCard.addView(text(troupe.optString("notes"),12,MUTED,false));}Button editTroupe=button(troupe.length()==0?"CRIAR TRUPE":"EDITAR TRUPE",PANEL2);editTroupe.setOnClickListener(new View.OnClickListener(){public void onClick(View v){livingWorldTroupeDialog();}});troupeCard.addView(editTroupe);b.addView(troupeCard);

        List<JSONObject> heroes=db.listActiveCharacters();LinearLayout heroHeader=card();heroHeader.addView(text("VIDAS DOS HERÓIS",17,GOLD,true));heroHeader.addView(text(heroes.isEmpty()?"Marque ao menos um herói como Em jogo.":"Cada herói mantém idade, lar, ocupação, família, vínculos e objetivos próprios.",13,MUTED,false));b.addView(heroHeader);
        for(JSONObject hero:heroes){
            final long heroId=hero.optLong("id");final JSONObject life=livingWorldEngine.heroLife(heroId);final JSONObject heroCopy=hero;
            LinearLayout hc=card();hc.addView(text(hero.optString("name")+" • "+life.optInt("age_years",18)+" anos",17,GOLD,true));hc.addView(text(emptyAs(life.optString("occupation"),"Aventureiro")+" • "+emptyAs(life.optString("residence"),"sem residência fixa"),13,TEXT,false));
            String family=life.optString("family_name"),relationship=life.optString("relationship_status");if(family.length()>0||relationship.length()>0)hc.addView(text((family.length()>0?"Família: "+family:"")+(family.length()>0&&relationship.length()>0?" • ":"")+(relationship.length()>0?relationship:""),12,MUTED,false));
            List<JSONObject> links=livingWorldEngine.relationships(heroId);if(!links.isEmpty()){StringBuilder line=new StringBuilder();for(int i=0;i<links.size()&&i<4;i++){if(line.length()>0)line.append(" • ");JSONObject link=links.get(i);line.append(link.optString("relation_type")).append(": ").append(link.optString("related_name"));if(link.optInt("age_known",0)==1)line.append(" (").append(link.optInt("age_years")).append(" anos)");}hc.addView(text(line.toString(),12,MUTED,false));}
            LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button editLife=smallButton("VIDA",PANEL2),addLink=smallButton("VÍNCULO",PANEL2),activity=smallButton("ATIVIDADE",GREEN);editLife.setOnClickListener(new View.OnClickListener(){public void onClick(View v){livingWorldHeroDialog(heroCopy,life);}});addLink.setOnClickListener(new View.OnClickListener(){public void onClick(View v){livingWorldRelationshipDialog(heroCopy);}});activity.setOnClickListener(new View.OnClickListener(){public void onClick(View v){livingWorldActivityDialog(heroCopy);}});actions.addView(editLife,new LinearLayout.LayoutParams(0,dp(46),1));actions.addView(addLink,new LinearLayout.LayoutParams(0,dp(46),1));actions.addView(activity,new LinearLayout.LayoutParams(0,dp(46),1));hc.addView(actions);b.addView(hc);
        }

        List<JSONObject> activities=livingWorldEngine.activities(30);
        LinearLayout activityCard=card();activityCard.addView(text("AGENDA DE VIDA",17,GOLD,true));
        if(activities.isEmpty())activityCard.addView(text("Nenhuma atividade planejada.",13,MUTED,false));
        for(JSONObject activity:activities){
            final long activityId=activity.optLong("id");final String activityTitle=activity.optString("title"),heroName=activity.optString("character_name","Herói");final String rawStatus=activity.optString("status","planejada");String status=rawStatus.replace('_',' ');
            activityCard.addView(text(heroName+" — "+activityTitle+"\n"+activity.optInt("duration_days",1)+" dia(s) • "+status+(activity.optInt("rule_authorized",0)==1?" • regra documentada":" • somente narrativa"),13,"concluida".equals(rawStatus)?GREEN:TEXT,false));
            if("aguardando_aplicacao".equals(rawStatus)){
                Button apply=button("APLICAR RESULTADO DOCUMENTADO",GREEN);apply.setOnClickListener(new View.OnClickListener(){public void onClick(View v){livingWorldApplyActivity(activityId,activityTitle);}});activityCard.addView(apply);
            }else if(!"concluida".equals(rawStatus)){
                LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);
                Button master=smallButton("RESOLVER NO MESTRE",PANEL2),secondary=smallButton("aguardando_regra".equals(rawStatus)?"DOCUMENTAR REGRA":"CONCLUIR NARRATIVA",GREEN);
                master.setOnClickListener(new View.OnClickListener(){public void onClick(View v){navigate("Mestre IA");sendAi("Narrador","Resolva a atividade de Mundo Vivo #"+activityId+" de "+heroName+": "+activityTitle+". Preserve a barreira: sem fonte, página e regra confirmada, produza apenas resultado narrativo e passagem de tempo; não conceda XP, ouro, itens ou bônus.");}});
                secondary.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if("aguardando_regra".equals(rawStatus))livingWorldAuthorizeActivityDialog(activityId,activityTitle);else livingWorldCompleteActivityDialog(activityId,activityTitle);}});
                row.addView(master,new LinearLayout.LayoutParams(0,dp(44),1));row.addView(secondary,new LinearLayout.LayoutParams(0,dp(44),1));activityCard.addView(row);
            }
        }
        b.addView(activityCard);
    }

    private void addLivingWorldAutomationPanel(LinearLayout parent,final JSONObject state,final int day){
        final JSONObject dashboard=livingWorldEngine.automationDashboard(8,12);LinearLayout panel=card();panel.setBackground(makeBg(PANEL2,CARD_STROKE,isMystaraWorld()?2:12));
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);LinearLayout titleBox=new LinearLayout(this);titleBox.setOrientation(LinearLayout.VERTICAL);titleBox.addView(text("AUTOMAÇÃO DO MUNDO",17,GOLD,true));titleBox.addView(text(dashboard.optBoolean("enabled",true)?"O mundo processa tempo, NPCs, facções, guildas, eventos e atividades. Orçamento por ciclo: 8 facções, 12 NPCs, 8 atividades/eventos/guildas; excedentes ficam para o próximo ciclo.":"A simulação está pausada; o painel continua mostrando pendências e agenda.",12,dashboard.optBoolean("enabled",true)?GREEN:GOLD,false));header.addView(titleBox,new LinearLayout.LayoutParams(0,-2,1));Button refresh=smallButton("ATUALIZAR",PANEL);refresh.setTextSize(10);refresh.setOnClickListener(new View.OnClickListener(){public void onClick(View v){screenCache.remove("Mundo Vivo");showLivingWorld();}});header.addView(refresh,new LinearLayout.LayoutParams(dp(104),dp(42)));panel.addView(header);
        long sync=dashboard.optLong("last_background_sync_at",0);String syncLabel=sync>0?formatDate(sync):"nunca";panel.addView(text("Última simulação: dia "+dashboard.optInt("last_simulated_day",day)+" • última sincronização offline: "+syncLabel+" • modo "+livingWorldModeLabel(dashboard.optString("simulation_mode",state.optString("simulation_mode"))),12,MUTED,false));
        LinearLayout counts=new LinearLayout(this);counts.setOrientation(LinearLayout.HORIZONTAL);counts.addView(livingWorldMetric("RECENTES",dashboard.optInt("recent_count",0),GREEN),new LinearLayout.LayoutParams(0,-2,1));counts.addView(livingWorldMetric("PRÓXIMAS",dashboard.optInt("upcoming_count",0),GOLD),new LinearLayout.LayoutParams(0,-2,1));counts.addView(livingWorldMetric("PENDENTES",dashboard.optInt("pending_count",0),dashboard.optInt("pending_count",0)>0?RED:GREEN),new LinearLayout.LayoutParams(0,-2,1));panel.addView(counts);
        panel.addView(livingWorldSectionTitle("ÚLTIMAS AÇÕES AUTOMÁTICAS"));JSONArray recent=dashboard.optJSONArray("recent_activity");if(recent==null||recent.length()==0)panel.addView(text("Nenhuma ação automática foi registrada ainda. O histórico aparecerá depois que o tempo, uma cena ou uma viagem forem processados.",12,MUTED,false));else for(int i=0;i<recent.length()&&i<6;i++)addLivingWorldDashboardRow(panel,recent.optJSONObject(i),day,false);
        panel.addView(livingWorldSectionTitle("PRÓXIMAS AÇÕES PREVISTAS"));JSONArray upcoming=dashboard.optJSONArray("upcoming_actions");if(upcoming==null||upcoming.length()==0)panel.addView(text("Nenhum evento, atividade, relógio, plano de facção, ação de NPC ou projeto de guilda está agendado.",12,MUTED,false));else for(int i=0;i<upcoming.length()&&i<8;i++)addLivingWorldDashboardRow(panel,upcoming.optJSONObject(i),day,true);
        panel.addView(livingWorldSectionTitle("FILA ÚNICA DE PENDÊNCIAS"));final JSONArray pending=db.listPendingActions("pending",100);if(pending==null||pending.length()==0)panel.addView(text("Nenhuma consequência aguarda revisão. O estado persistente está sincronizado.",12,GREEN,true));else{for(int i=0;i<pending.length()&&i<4;i++)addLivingWorldDashboardRow(panel,pending.optJSONObject(i),day,false);Button review=button("REVISAR "+pending.length()+" PENDÊNCIA(S)",RED);review.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showLivingWorldPendingDialog(pending);}});panel.addView(review);}
        parent.addView(panel);
    }


    private void addWorldSixPanel(LinearLayout parent,final int day){
        if(emergentCampaignDirector==null)return;
        final JSONObject ctx=worldSixCoordinator==null?new JSONObject():worldSixCoordinator.context();
        final JSONArray arcs=ctx.optJSONObject("campaign_director")==null?new JSONArray():ctx.optJSONObject("campaign_director").optJSONArray("active_arcs");
        final JSONArray rumors=ctx.optJSONObject("rumors")==null?new JSONArray():ctx.optJSONObject("rumors").optJSONArray("circulating");
        final JSONArray history=ctx.optJSONObject("history")==null?new JSONArray():ctx.optJSONObject("history").optJSONArray("important");
        final JSONArray legacies=ctx.optJSONObject("legacy")==null?new JSONArray():ctx.optJSONObject("legacy").optJSONArray("active_legacies");
        LinearLayout panel=card();panel.addView(text("MUNDO QUE SE LEMBRA — 6.0",18,GOLD,true));panel.addView(text("Diretor emergente, cidades vivas, rumores, história mundial, legado, vozes de NPC, cenas táticas procedurais e mesa local compartilham o mesmo estado. Nada cria regra mecânica sem o motor de regras.",12,GREEN,false));
        LinearLayout metrics=new LinearLayout(this);metrics.setOrientation(LinearLayout.HORIZONTAL);metrics.addView(livingWorldMetric("ARCOS",arcs==null?0:arcs.length(),GOLD),new LinearLayout.LayoutParams(0,-2,1));metrics.addView(livingWorldMetric("RUMORES",rumors==null?0:rumors.length(),GREEN),new LinearLayout.LayoutParams(0,-2,1));metrics.addView(livingWorldMetric("HISTÓRIA",history==null?0:history.length(),TEXT),new LinearLayout.LayoutParams(0,-2,1));metrics.addView(livingWorldMetric("LEGADOS",legacies==null?0:legacies.length(),MUTED),new LinearLayout.LayoutParams(0,-2,1));panel.addView(metrics);
        if(arcs!=null&&arcs.length()>0){panel.addView(livingWorldSectionTitle("ARCOS EMERGENTES"));for(int i=0;i<Math.min(3,arcs.length());i++){JSONObject a=arcs.optJSONObject(i);if(a==null)continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(8),dp(7),dp(8),dp(7));row.setBackground(makeBg(PANEL,CARD_STROKE,8));row.addView(text(a.optString("title"),13,TEXT,true));row.addView(text(a.optString("dramatic_question"),11,MUTED,false));row.addView(text(a.optString("stage").replace('_',' ')+" • impulso "+a.optInt("momentum")+" • urgência "+a.optInt("urgency"),10,GOLD,false));panel.addView(row);}}
        LinearLayout buttons=new LinearLayout(this);buttons.setOrientation(LinearLayout.HORIZONTAL);Button refresh=smallButton("ATUALIZAR 6.0",GREEN),details=smallButton("VER MUNDO",PANEL2),table=smallButton("MESA LOCAL",PANEL2);refresh.setOnClickListener(new View.OnClickListener(){public void onClick(View v){setStatus("Atualizando história, rumores, cidades e arcos emergentes…");AppExecutors.io().execute(new Runnable(){public void run(){final JSONObject r=worldSixCoordinator.tick();ui.post(new Runnable(){public void run(){screenCache.remove("Mundo Vivo");setStatus(r.optString("error").length()>0?"Mundo 6.0: "+r.optString("error"):"Mundo emergente atualizado sem criar consequências mecânicas arbitrárias.");showLivingWorld();}});}});}});details.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showWorldSixDetailsDialog();}});table.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showLocalTableDialog();}});buttons.addView(refresh,new LinearLayout.LayoutParams(0,dp(48),1));buttons.addView(details,new LinearLayout.LayoutParams(0,dp(48),1));buttons.addView(table,new LinearLayout.LayoutParams(0,dp(48),1));panel.addView(buttons);
        LinearLayout second=new LinearLayout(this);second.setOrientation(LinearLayout.HORIZONTAL);Button tactical=smallButton("GERAR CENA TÁTICA",PANEL2),legacy=smallButton("LEGADO / NOVA ERA",PANEL2),voices=smallButton("VOZES DOS NPCS",PANEL2);tactical.setOnClickListener(new View.OnClickListener(){public void onClick(View v){JSONObject scene=tacticalSceneGenerator.regenerate();toast("Cena tática: "+scene.optString("environment","gerada")+" • "+scene.optInt("width_cells",12)+"×"+scene.optInt("height_cells",8));}});legacy.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showLegacyDialog();}});voices.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showNpcVoicesDialog();}});second.addView(tactical,new LinearLayout.LayoutParams(0,dp(48),1));second.addView(legacy,new LinearLayout.LayoutParams(0,dp(48),1));second.addView(voices,new LinearLayout.LayoutParams(0,dp(48),1));panel.addView(second);
        LinearLayout third=new LinearLayout(this);third.setOrientation(LinearLayout.HORIZONTAL);Button npcsWorld=smallButton("NPCS DO MUNDO",PANEL2),createNpc=smallButton("CRIAR NPC DOS LIVROS",GOLD),spreadNpcs=smallButton("ESPALHAR NO MUNDO",GREEN);npcsWorld.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showMemoryDialog();}});createNpc.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showCreateNpcFromBooksDialog();}});spreadNpcs.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(npcWorldSpreader==null)npcWorldSpreader=new NpcWorldSpreaderEngine(db);JSONObject rep=npcWorldSpreader.spreadActiveNpcs();toast(rep.optString("message","NPCs espalhados pelo mundo."));screenCache.remove("Mundo Vivo");showLivingWorld();}});third.addView(npcsWorld,new LinearLayout.LayoutParams(0,dp(48),1));third.addView(createNpc,new LinearLayout.LayoutParams(0,dp(48),1));third.addView(spreadNpcs,new LinearLayout.LayoutParams(0,dp(48),1));panel.addView(third);parent.addView(panel);
    }

    private void showWorldSixDetailsDialog(){
        JSONObject ctx=worldSixCoordinator==null?new JSONObject():worldSixCoordinator.context();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(10),dp(8),dp(10),dp(18));
        JSONObject director=ctx.optJSONObject("campaign_director"),sett=ctx.optJSONObject("settlements"),rum=ctx.optJSONObject("rumors"),hist=ctx.optJSONObject("history"),leg=ctx.optJSONObject("legacy");
        addJsonSummaryRows(box,"ARCOS EMERGENTES",director==null?null:director.optJSONArray("active_arcs"),"title","dramatic_question",8);
        addJsonSummaryRows(box,"CIDADES / REGIÕES SOB PRESSÃO",sett==null?null:sett.optJSONArray("pressured"),"name","region",10);
        addJsonSummaryRows(box,"RUMORES EM CIRCULAÇÃO",rum==null?null:rum.optJSONArray("circulating"),"statement","origin",10);
        addJsonSummaryRows(box,"HISTÓRIA IMPORTANTE",hist==null?null:hist.optJSONArray("important"),"title","summary",10);
        addJsonSummaryRows(box,"LEGADO DO WORLD SEED",leg==null?null:leg.optJSONArray("active_legacies"),"subject","statement",10);
        ScrollView scroll=new ScrollView(this);scroll.addView(box);new AlertDialog.Builder(this).setTitle("Mundo que se lembra").setView(scroll).setNegativeButton("Fechar",null).show();
    }
    private void addJsonSummaryRows(LinearLayout box,String title,JSONArray rows,String titleKey,String detailKey,int limit){box.addView(text(title,13,GOLD,true));if(rows==null||rows.length()==0){box.addView(text("Nenhum registro ainda.",11,MUTED,false));return;}for(int i=0;i<Math.min(limit,rows.length());i++){JSONObject x=rows.optJSONObject(i);if(x==null)continue;box.addView(text("• "+x.optString(titleKey,"Registro"),12,TEXT,true));String d=x.optString(detailKey).trim();if(d.length()>0)box.addView(text(d,11,MUTED,false));}}

    private void showNpcVoicesDialog(){
        JSONArray rows=npcVoiceDirector==null?new JSONArray():npcVoiceDirector.ensureScene();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(10),dp(8),dp(10),dp(18));if(rows.length()==0)box.addView(text("Nenhum NPC presente na cena. As vozes serão atribuídas de forma persistente quando aparecerem.",12,MUTED,false));for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);if(x==null)continue;box.addView(text(x.optString("npc_name")+" • "+x.optString("voice_name","Charon"),13,GOLD,true));box.addView(text(x.optString("register_name")+" • calor "+x.optInt("warmth")+" • formalidade "+x.optInt("formality"),11,MUTED,false));}ScrollView scroll=new ScrollView(this);scroll.addView(box);new AlertDialog.Builder(this).setTitle("Vozes persistentes dos NPCs").setView(scroll).setNegativeButton("Fechar",null).show();
    }

    private void showLocalTableDialog(){
        if(localTableServer==null)localTableServer=new LocalTableServer(db);final boolean running=localTableServer.isRunning();final JSONObject state=running?localTableServer.status():new JSONObject();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(10),dp(8),dp(10),dp(18));box.addView(text(running?"MESA LOCAL ATIVA":"MESA LOCAL DESLIGADA",16,running?GREEN:GOLD,true));box.addView(text("Os jogadores entram pelo navegador usando o Wi-Fi local. Cada convite vê somente a própria ficha, a cena compartilhada, seu estado de combate, rumores conhecidos e informações privadas destinadas àquele herói.",12,TEXT,false));if(running){box.addView(text("Código da sessão: "+state.optString("code")+"\nEndereço do Mestre: "+state.optString("url"),12,GOLD,true));final JSONArray players=state.optJSONArray("players");if(players!=null)for(int i=0;i<players.length();i++){final JSONObject p=players.optJSONObject(i);if(p==null)continue;Button invite=button("COPIAR CONVITE — "+p.optString("character_name"),PANEL2);invite.setOnClickListener(new View.OnClickListener(){public void onClick(View v){ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(cm!=null)cm.setPrimaryClip(ClipData.newPlainText("Convite Braseiro",p.optString("url")));toast("Convite de "+p.optString("character_name")+" copiado.");}});box.addView(invite);}if(players!=null&&players.length()>0){Button secret=button("ENVIAR SEGREDO A UM HERÓI",PANEL2);secret.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showLocalTableSecretDialog(players);}});box.addView(secret);}}ScrollView scroll=new ScrollView(this);scroll.addView(box);AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle("Modo Mesa Local").setView(scroll).setNegativeButton("Fechar",null);if(running)b.setPositiveButton("PARAR MESA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){localTableServer.stop();toast("Mesa local encerrada.");}});else b.setPositiveButton("INICIAR MESA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){JSONObject r=localTableServer.start();if(r.optBoolean("running"))showLocalTableDialog();else toast("Não foi possível abrir a mesa: "+r.optString("error"));}});b.show();
    }

    private void showLocalTableSecretDialog(final JSONArray players){
        if(players==null||players.length()==0)return;ArrayList<String> labels=new ArrayList<String>();for(int i=0;i<players.length();i++){JSONObject p=players.optJSONObject(i);if(p!=null)labels.add(p.optString("character_name","Herói"));}if(labels.isEmpty())return;LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),dp(4),dp(12),dp(10));final Spinner who=spinner(labels.toArray(new String[0]),labels.get(0));form.addView(cardWithLabel("DESTINATÁRIO",who));final EditText title=input("Título do segredo","Informação privada",false),body=input("Conteúdo que somente este herói verá","",true);body.setMinLines(5);form.addView(title);form.addView(body);new AlertDialog.Builder(this).setTitle("Segredo da Mesa Local").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("ENVIAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){int index=who.getSelectedItemPosition();JSONObject p=players.optJSONObject(index);if(p==null||value(body).isEmpty()){toast("Informe o segredo e o destinatário.");return;}boolean ok=localTableServer!=null&&localTableServer.addPrivateSecret(p.optLong("character_id"),value(title),value(body));toast(ok?"Segredo enviado apenas para "+p.optString("character_name")+".":"Não foi possível registrar o segredo.");}}).show();
    }

