    /** RUN204: select the exact narrated declaration BEFORE committing mechanical effects. */
    private List<JSONObject> narratedCombatDeclarations(){
        List<JSONObject> out=new ArrayList<JSONObject>();
        for(JSONObject a:db.listPartyActions("narrated",100)){
            String intent=a.optString("intent_type");
            if(a.optLong("character_id")>0&&("combate".equals(intent)||"livre".equals(intent)))out.add(a);
        }
        return out;
    }
    private boolean validatePartyCombatSelection(int index,List<JSONObject> declarations,
        long actorId,String resource){
        if(index<=0)return true;
        if(index>declarations.size()){toast("A declaração selecionada não existe mais.");return false;}
        JSONObject action=declarations.get(index-1),actor=db.getCombatant(actorId);
        if(actor.optInt("is_player",0)!=1||!"character".equals(actor.optString("source_kind"))||
            actor.optLong("source_id",0)!=action.optLong("character_id",-1)){
            toast("O executor deve ser o próprio herói da declaração, vinculado à ficha.");return false;
        }
        if("none".equals(resource)){
            toast("Para vincular esta execução, selecione AÇÃO, BÔNUS ou REAÇÃO.");return false;
        }
        return true;
    }
    private Spinner partyCombatActionSelector(LinearLayout form,List<JSONObject> declarations){
        String[] labels=new String[declarations.size()+1];labels[0]="Não vincular declaração";
        for(int i=0;i<declarations.size();i++){
            JSONObject a=declarations.get(i);String t=a.optString("action_text");
            labels[i+1]="#"+a.optLong("id")+" • "+a.optString("character_name")+" — "+
                (t.length()>70?t.substring(0,70)+"…":t);
        }
        Spinner select=spinner(labels,labels[0]);
        form.addView(cardWithLabel("DECLARAÇÃO NARRADA (opcional, vínculo causal)",select));
        form.addView(text("Se escolher uma declaração, o herói executor deve ser o mesmo da ficha. " +
            "O gasto e todos os efeitos serão confirmados juntos com a declaração ou nada será gravado.",11,MUTED,false));
        return select;
    }
    /** RUN205: optional narrated-action binding for real tactical movement and standing. */
    private void combatMovementActionDialog(final JSONObject combatant,final boolean standing){
        combatMovementActionDialog(combatant,standing,-1,-1);
    }
    private void combatMovementActionDialog(final JSONObject combatant,final boolean standing,
        final int requestedX,final int requestedY){
        final long actorId=combatant.optLong("id"),characterId=combatant.optLong("source_id",0);
        final List<JSONObject> actions=new ArrayList<JSONObject>();
        if(combatant.optInt("is_player",0)==1&&"character".equals(combatant.optString("source_kind"))){
            for(JSONObject a:db.listPartyActions("narrated",100)){
                String intent=a.optString("intent_type");
                if(a.optLong("character_id",0)==characterId&&
                    ("movimento".equals(intent)||"livre".equals(intent)))actions.add(a);
            }
        }
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);
        form.setPadding(dp(12),dp(8),dp(12),dp(8));
        // RUN208: destination is a real tactical cell; distance is derived from the
        // persisted scene and blocking tokens, never typed independently of position.
        final JSONObject origin=standing?new JSONObject():db.tacticalGridPosition(actorId);
        if(!standing&&origin.has("grid_blocked")){
            toast("Tabuleiro indisponível: "+origin.optString("grid_blocked"));return;
        }
        if(!standing)form.addView(text("Posição atual: coluna "+origin.optInt("cell_x")+
            ", linha "+origin.optInt("cell_y")+" • grade "+origin.optInt("width_cells")+
            " × "+origin.optInt("height_cells")+". Informe a célula de destino; o sistema calculará " +
            "o caminho livre e consumirá o deslocamento real.",12,MUTED,false));
        final EditText destX=standing?null:labeledField(form,"Destino: coluna (começando em 0)",
            String.valueOf(requestedX>=0?requestedX:
                Math.min(Math.max(0,origin.optInt("width_cells",12)-1),origin.optInt("cell_x",0)+1)),false);
        final EditText destY=standing?null:labeledField(form,"Destino: linha (começando em 0)",
            String.valueOf(requestedY>=0?requestedY:origin.optInt("cell_y",0)),false);
        if(destX!=null)destX.setInputType(InputType.TYPE_CLASS_NUMBER);
        if(destY!=null)destY.setInputType(InputType.TYPE_CLASS_NUMBER);
        final CheckBox difficult=standing?null:check("Terreno difícil (confirmação do Mestre)",false);
        final CheckBox crawling=standing?null:check("Rastejando (+1 pé por pé percorrido)",false);
        if(difficult!=null)form.addView(difficult);
        if(crawling!=null)form.addView(crawling);
        String[] options=new String[actions.size()+1];options[0]="Movimento independente (não concluir declaração)";
        for(int i=0;i<actions.size();i++){
            JSONObject a=actions.get(i);options[i+1]="#"+a.optLong("id")+" • "+a.optString("action_text");
        }
        final Spinner select=spinner(options,options[0]);
        form.addView(cardWithLabel("DECLARAÇÃO NARRADA A EXECUTAR",select));
        form.addView(text("O percurso livre, o token, o gasto do turno e a declaração serão gravados juntos. " +
            "Obstáculos bloqueiam a rota; células marcadas explicitamente como difíceis " +
            "custam mais movimento, e o motor escolhe o caminho de menor custo. " +
            "A caixa de terreno difícil vale para todo o trajeto; rastejar é confirmado manualmente. " +
            "Ataques de oportunidade de combatentes com perfil corpo a corpo serão resolvidos ao sair do alcance. " +
            "Se houver reação, avance uma célula por vez. Perigos de percurso exigem revisão do Mestre. " +
            "O movimento tático não avança o relógio de viagens.",12,MUTED,false));
        final AlertDialog dialog=new AlertDialog.Builder(this)
            .setTitle(standing?"Levantar-se • metade do deslocamento":"Movimento tático • orçamento real")
            .setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null)
            .setPositiveButton("EXECUTAR",null).create();
        showBoundDialog(dialog,new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(new View.OnClickListener(){public void onClick(View ignored){
                int traveled=0,feet=0,tx=0,ty=0;
                JSONObject preview=new JSONObject();
                if(!standing){
                    try{tx=Integer.parseInt(value(destX));ty=Integer.parseInt(value(destY));}
                    catch(Exception invalid){destX.setError("Informe coluna e linha inteiras.");return;}
                    preview=db.previewTacticalGridMovement(actorId,tx,ty,
                        difficult.isChecked(),crawling.isChecked());
                    if(!preview.optBoolean("grid_valid",false)){
                        toast("Rota impedida: "+preview.optString("grid_blocked","verificar destino"));return;
                    }
                    if(preview.optBoolean("opportunity_segment_required",false)){
                        toast("Há ataque de oportunidade no trajeto. Avance uma célula por vez para resolver a reação no ponto certo.");return;
                    }
                    traveled=preview.optInt("distance_ft",0);
                    feet=preview.optInt("movement_cost_ft",0);
                    if(preview.optInt("difficult_steps",0)>0)
                        toast("Rota: "+preview.optInt("steps")+" células; "+
                            preview.optInt("difficult_steps")+" difíceis; custo "+feet+" pés.");
                    final JSONObject before=db.getCombatant(actorId);
                    final JSONObject resources;
                    try{resources=new JSONObject(before.optString("resources_json","{}"));}
                    catch(Exception e){toast("Orçamento de movimento ilegível.");return;}
                    if(feet>resources.optInt("movement_remaining_ft",0)){
                        toast("Deslocamento insuficiente: requer "+feet+" pés; resta "+
                            resources.optInt("movement_remaining_ft",0)+".");return;
                    }
                }
                int selection=select.getSelectedItemPosition();
                final String token=standing?"ui-movement-"+java.util.UUID.randomUUID():
                    "ui-grid-"+java.util.UUID.randomUUID();
                if(!standing&&preview.optJSONArray("opportunity_attacks")!=null&&
                    preview.optJSONArray("opportunity_attacks").length()>0){
                    collectGridOpportunityChoices(dialog,preview,actorId,tx,ty,difficult.isChecked(),
                        crawling.isChecked(),selection>0&&selection<=actions.size()?
                            actions.get(selection-1).optLong("id"):0,token,new JSONArray(),0);
                    return;
                }
                JSONObject result;
                if(standing){
                    result=selection>0&&selection<=actions.size()?
                        db.applyMovementForPartyAction(actions.get(selection-1).optLong("id"),actorId,0,true,token):
                        db.standCombatantFromProne(actorId,token);
                }else if(selection>0&&selection<=actions.size()){
                    result=db.applyTacticalGridMovementForPartyAction(
                        actions.get(selection-1).optLong("id"),actorId,tx,ty,difficult.isChecked(),
                        crawling.isChecked(),preview.optString("grid_fingerprint"),token);
                }else{
                    result=db.moveCombatantToGridCell(actorId,tx,ty,difficult.isChecked(),
                        crawling.isChecked(),preview.optString("grid_fingerprint"),token);
                }
                String blocked=result.optString("grid_blocked",result.optString("party_movement_blocked",
                    result.optString("movement_blocked",result.optString("stand_blocked",
                    result.optString("operation_blocked",result.optString("operation_error",""))))));
                if(!blocked.isEmpty()||result.optBoolean("operation_replayed",false)){
                    toast("Movimento não executado: "+(blocked.isEmpty()?"repetição":blocked));return;
                }
                if(selection>0&&!result.optBoolean("party_action_resolved",false)){
                    toast("Declaração não comprovada; operação não confirmada.");return;
                }
                if(!standing&&!result.optBoolean("grid_movement_committed",false)){
                    toast("Destino não foi persistido; verifique a operação.");return;
                }
                toast(standing?"Personagem levantado; deslocamento debitado.":
                    "Token na célula ("+tx+","+ty+"). Percurso "+traveled+
                    " pés; custo "+feet+" pés ("+
                    TacticalMovementCostRules.label(difficult.isChecked(),crawling.isChecked())+").");
                dialog.dismiss();showCombat();
            }});
        }});
    }
    /** Ask for each reaction before a one-cell move. Nothing mutates until the
     * final confirmation; AppDb rechecks the scene, profile, AC and rolls. */
    private void collectGridOpportunityChoices(final AlertDialog movementDialog,final JSONObject preview,
        final long moverId,final int tx,final int ty,final boolean difficult,final boolean crawling,
        final long actionId,final String token,final JSONArray choices,final int index){
        final JSONArray candidates=preview.optJSONArray("opportunity_attacks");
        if(candidates==null)return;
        if(index>=candidates.length()){
            new AlertDialog.Builder(this).setTitle("Confirmar deslocamento e reações")
                .setMessage("Mover uma célula; "+choices.length()+" oportunidade(s) revisada(s). " +
                    "Reação, dano, movimento e recibos serão gravados na mesma transação.")
                .setNegativeButton("CANCELAR",null)
                .setPositiveButton("CONFIRMAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
                    JSONObject result=actionId>0?
                        db.applyTacticalGridMovementForPartyAction(actionId,moverId,tx,ty,difficult,crawling,
                            preview.optString("grid_fingerprint"),token,choices):
                        db.moveCombatantToGridCell(moverId,tx,ty,difficult,crawling,
                            preview.optString("grid_fingerprint"),token,choices);
                    if(result.optBoolean("opportunity_stopped",false)){
                        toast("Ataque de oportunidade derrubou o combatente antes do deslocamento. A reação e o dano foram registrados.");
                        movementDialog.dismiss();showCombat();return;
                    }
                    if(!result.optBoolean("grid_movement_committed",false)||
                        actionId>0&&!result.optBoolean("party_action_resolved",false)){
                        toast("Movimento não confirmado: "+result.optString("grid_blocked",
                            result.optString("party_movement_blocked",result.optString("operation_error","revise o estado"))));return;
                    }
                    toast("Movimento e reações aplicados juntos.");movementDialog.dismiss();showCombat();
                }}).show();
            return;
        }
        final JSONObject c=candidates.optJSONObject(index);
        if(c==null){toast("Prévia de reação inválida.");return;}
        new AlertDialog.Builder(this).setTitle("Oportunidade • "+c.optString("reactor_name"))
            .setMessage("O alvo sai do alcance de "+c.optString("weapon_name")+". " +
                "Reação disponível; ataque contra CA "+c.optInt("effective_ac")+".")
            .setNegativeButton("CANCELAR MOVIMENTO",null)
            .setNeutralButton("RENUNCIAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
                try{choices.put(gridOpportunityChoice(c,"decline",0,0));
                    collectGridOpportunityChoices(movementDialog,preview,moverId,tx,ty,difficult,crawling,
                        actionId,token,choices,index+1);
                }catch(Exception e){toast("Não foi possível registrar a escolha.");}
            }})
            .setPositiveButton("ROLAR ATAQUE",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
                final int bonus=c.optInt("bonus"),ac=c.optInt("effective_ac");
                final EquippedWeaponAttackRules.Dice dice=EquippedWeaponAttackRules.parse(c.optString("formula"));
                if(dice==null){toast("Perfil de arma inválido.");return;}
                final JSONObject reactor=db.getCombatant(c.optLong("reactor_id"));
                rollDiceInteractive("d20"+(bonus>=0?"+":"")+bonus,c.optString("roll_mode","Normal"),
                    c.optString("reactor_name"),reactor.optInt("is_player",0)==1?
                        reactor.optLong("source_id",0):0,new DiceUiCallback(){public void done(final DiceResult roll){
                    if(roll.natural<1||roll.natural>20){toast("D20 inválido; movimento cancelado.");return;}
                    if(!PartyAttackCausalReceiptGuard.hit(roll.natural,bonus,ac)){
                        appendGridOpportunityChoice(movementDialog,preview,moverId,tx,ty,difficult,crawling,
                            actionId,token,choices,index,c,roll.natural,0);return;
                    }
                    rollDiceInteractive(dice.rolledFormula(roll.natural==20),"Normal",
                        c.optString("reactor_name"),reactor.optInt("is_player",0)==1?
                            reactor.optLong("source_id",0):0,new DiceUiCallback(){public void done(DiceResult damage){
                        appendGridOpportunityChoice(movementDialog,preview,moverId,tx,ty,difficult,crawling,
                            actionId,token,choices,index,c,roll.natural,Math.max(0,damage.total));
                    }});
                }});
            }}).show();
    }
    private JSONObject gridOpportunityChoice(JSONObject c,String decision,int natural,int damage)throws Exception{
        return new JSONObject().put("reactor_id",c.optLong("reactor_id"))
            .put("step_index",c.optInt("step_index")).put("weapon_id",c.optString("weapon_id"))
            .put("geometry_fingerprint",c.optString("geometry_fingerprint"))
            .put("effective_ac",c.optInt("effective_ac")).put("roll_mode",c.optString("roll_mode"))
            .put("decision",decision).put("natural",natural).put("damage",damage);
    }
    private void appendGridOpportunityChoice(AlertDialog movementDialog,JSONObject preview,long moverId,
        int tx,int ty,boolean difficult,boolean crawling,long actionId,String token,JSONArray choices,
        int index,JSONObject candidate,int natural,int damage){
        try{choices.put(gridOpportunityChoice(candidate,"attack",natural,damage));
            collectGridOpportunityChoices(movementDialog,preview,moverId,tx,ty,difficult,crawling,
                actionId,token,choices,index+1);
        }catch(Exception e){toast("Rolagem não registrada; movimento cancelado.");}
    }
    private void partyActionReceiptDialog(final JSONObject action){
        String intent=action.optString("intent_type");
        boolean movement="movimento".equals(intent);
        boolean supported="combate".equals(intent)||"livre".equals(intent)||movement;
        AlertDialog.Builder dialog=new AlertDialog.Builder(this)
            .setTitle(supported?"Execução mecânica vinculada":"Execução ainda não vinculada")
            .setMessage(supported?
                (movement?"Para validar este deslocamento, abra COMBATE, selecione MOVER ou LEVANTAR " +
                "no turno do herói e vincule a declaração #":"Para validar esta declaração, abra COMBATE, selecione EFEITO EM ÁREA " +
                "ou SALVAGUARDAS, escolha o herói executor e a declaração #")+action.optLong("id")+
                (movement?". O aplicativo debitará o deslocamento da rodada e concluirá a declaração " +
                    "na mesma transação. ":". O aplicativo gastará o recurso, aplicará os efeitos e concluirá a ação " +
                    "atomicamente. ")+
                "Recibos genéricos, de outros personagens ou de eventos do mundo " +
                "não comprovam esta ação.":
                "Ainda não existe um executor causal para este tipo de declaração. " +
                "A ação continuará pendente: a narração e recibos genéricos não autorizam " +
                "alterar ficha, tempo ou recursos. Você pode devolver à fila ou cancelar " +
                "explicitamente sem efeito; não será marcada como mecanicamente concluída.")
            .setNegativeButton("Voltar",null);
        if(supported)dialog.setPositiveButton("ABRIR COMBATE",new DialogInterface.OnClickListener(){
            public void onClick(DialogInterface d,int w){showCombat();}});
        else dialog.setPositiveButton("Entendi",null);
        dialog.show();
    }
    private void partyActionDismissDialog(final JSONObject action){
        final EditText note=input("Justificativa obrigatória (mínimo 8 caracteres)","Ação não produziu efeito mecânico.",true);
        final String intent=action.optString("intent_type");
        boolean narrativeAllowed=!"combate".equals(intent)&&!"movimento".equals(intent)&&!"descanso".equals(intent)&&!"curated_approved".equals(intent);
        new AlertDialog.Builder(this).setTitle("Encerrar sem aplicar efeitos?")
            .setMessage("CANCELAR registra que a ação não ocorreu. Em ações sociais, de exploração ou livres, você também pode registrar que houve apenas interpretação, sem custo, rolagem ou consequência mecânica.")
            .setView(note).setNegativeButton("Voltar",null)
            .setNeutralButton(narrativeAllowed?"SÓ NARRATIVA":"CANCELAR AÇÃO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
                String decision=("combate".equals(intent)||"movimento".equals(intent)||"descanso".equals(intent)||"curated_approved".equals(intent))?"cancelled":"narrative_only";
                boolean ok=db.finalizePartyAction(action.optLong("id"),decision,"",value(note));toast(ok?"Encerrada sem aplicar recursos ou consequências.":"Justificativa inválida ou ação já decidida.");showPartyDirector();
            }})
            .setPositiveButton("CANCELAR AÇÃO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
                boolean ok=db.finalizePartyAction(action.optLong("id"),"cancelled","",value(note));toast(ok?"Ação cancelada sem efeitos.":"Informe uma justificativa ou confira o estado.");showPartyDirector();
            }}).show();
    }

