    private void showMasterCognitiveAudit(){try{JSONObject d=masterOrchestrator==null?new JSONObject():masterOrchestrator.diagnostic();JSONObject runtime=db.getMasterRuntimeState();StringBuilder m=new StringBuilder();m.append("Núcleo cognitivo: ").append(d.optBoolean("complete",false)?"ATIVO":"INCOMPLETO").append("\n");m.append("Modo de cena: ").append(runtime.optString("scene_mode","ainda não definido")).append(" • tensão ").append(runtime.optInt("tension",0)).append("/100\n");m.append("Batidas registradas: ").append(runtime.optInt("beat_no",0)).append("\n");m.append("Memórias episódicas: ").append(d.optJSONObject("memory")==null?0:d.optJSONObject("memory").optInt("episodes",0)).append(" • sessões: ").append(d.optJSONObject("memory")==null?0:d.optJSONObject("memory").optInt("session_memories",0)).append("\n");m.append("Fatos visíveis/ocultos: ").append(d.optJSONObject("knowledge_firewall")==null?"0/0":d.optJSONObject("knowledge_firewall").optInt("visible_facts",0)+"/"+d.optJSONObject("knowledge_firewall").optInt("hidden_facts",0)).append("\n");m.append("NPCs com cognição persistente: ").append(d.optJSONObject("npc_agency")==null?0:d.optJSONObject("npc_agency").optInt("npc_cognitive_states",0)).append("\n");m.append(masterOrchestrator==null?"":masterOrchestrator.quotaStatus()).append("\n\n");m.append("O áudio permanece no motor atual e será substituído somente na próxima versão.");new AlertDialog.Builder(this).setTitle("Auditoria do Mestre Virtual").setMessage(m.toString()).setNegativeButton("Fechar",null).setPositiveButton("VER DIAGNÓSTICO COMPLETO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface dialog,int which){try{new AlertDialog.Builder(MainActivity.this).setTitle("Diagnóstico técnico").setMessage((masterOrchestrator==null?new JSONObject():masterOrchestrator.diagnostic()).toString(2)).setPositiveButton("Fechar",null).show();}catch(Exception e){toast(e.getMessage());}}}).show();}catch(Exception e){toast("Auditoria: "+e.getMessage());}}

    private void undoLastMasterResolution(final JSONObject transaction,final String snapshotName){new AlertDialog.Builder(this).setTitle("Desfazer última resolução?").setMessage("A campanha voltará exatamente ao snapshot criado antes da última aplicação confirmada. A narração e qualquer mudança feita depois desse ponto também voltarão ao estado anterior.").setNegativeButton("Cancelar",null).setPositiveButton("DESFAZER",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{safety.restoreSnapshot(snapshotName);if(stateTransactionManager!=null)stateTransactionManager.rolledBack(transaction.optLong("id"));activeMasterPlan=null;if(masterOrchestrator!=null)masterOrchestrator.setActivePlanForValidation(null);loadStoryState();prefs.edit().putString("last_state_update_summary","Última resolução desfeita pelo snapshot "+snapshotName+".").apply();setStatus("A última resolução do Mestre foi desfeita com segurança.");showPartyDirector();}catch(Exception e){toast("Não foi possível desfazer: "+e.getMessage());}}}).show();}

