    private void worldClockDialog(final JSONObject existing){
        LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(12),0,dp(12),0);
        final EditText name=labeledField(f,"Relógio de ameaça",existing.optString("name"),false),max=labeledField(f,"Segmentos",String.valueOf(existing.optInt("max_value",4)),false),current=labeledField(f,"Valor atual",String.valueOf(existing.optInt("current_value",0)),false),interval=labeledField(f,"Cadência em horas",String.valueOf(existing.optDouble("interval_hours",6d)),false),rate=labeledField(f,"Multiplicador de cadência",String.valueOf(existing.optDouble("rate_multiplier",1d)),false),tick=labeledField(f,"Delta por cadência (negativo = regressão)",String.valueOf(existing.optInt("tick_delta",1)),false),owner=labeledField(f,"Entidade responsável",existing.optString("owner_entity"),false),condition=labeledField(f,"Condição de avanço (vazio = sempre)",existing.optString("trigger_condition"),true),segments=labeledField(f,"Consequências por segmento — JSON [{value,title,narrative,consequence_json}]",existing.optString("segments_json","[]"),true),consequence=labeledField(f,"Consequência ao completar",existing.optString("consequence"),true);
        max.setInputType(InputType.TYPE_CLASS_NUMBER);current.setInputType(InputType.TYPE_CLASS_NUMBER);interval.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);rate.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);tick.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);segments.setMinLines(4);
        final CheckBox automatic=check("Avançar automaticamente com a passagem do tempo",existing.optInt("automatic",0)==1),paused=check("Pausar este relógio",existing.optInt("paused",0)==1),regression=check("Permitir regressão",existing.optInt("regression_allowed",0)==1);f.addView(automatic);f.addView(paused);f.addView(regression);
        new AlertDialog.Builder(this).setTitle(existing.length()>0?"Editar relógio":"Novo relógio").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{String segmentJson=value(segments).length()==0?"[]":value(segments);new JSONArray(segmentJson);long id=existing.optLong("id",0);if(id<=0)id=db.addWorldClock(name.getText().toString(),num(max,4),consequence.getText().toString(),automatic.isChecked());JSONObject update=new JSONObject().put("id",id).put("name",name.getText().toString()).put("current_value",Math.max(0,num(current,0))).put("max_value",Math.max(2,num(max,4))).put("consequence",consequence.getText().toString()).put("automatic",automatic.isChecked()).put("active",true).put("interval_hours",Math.max(1d,decimal(interval,6d))).put("rate_multiplier",Math.max(.01d,decimal(rate,1d))).put("tick_delta",num(tick,1)).put("paused",paused.isChecked()).put("regression_allowed",regression.isChecked()).put("owner_entity",value(owner)).put("segments_json",segmentJson).put("trigger_condition",condition.getText().toString().trim());db.applyWorldClockUpdate(update);showPartyDirector();}catch(Exception e){toast("Relógio: "+e.getMessage());}}}).show();
    }
    private void factionDialog(){factionDialog(new JSONObject());}
    private void factionDialog(final JSONObject existing){
        LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(12),0,dp(12),0);
        String politicalType=RealmLifecycleEngine.isRealm(existing)?"Reino / Estado":RealmLifecycleEngine.claimsStatehood(existing)?"Pretendente a reino":"Facção";final Spinner entityType=spinner(new String[]{"Facção","Pretendente a reino","Reino / Estado"},politicalType);f.addView(cardWithLabel("TIPO POLÍTICO",entityType));
        final EditText name=labeledField(f,"Nome",existing.optString("name"),false),agenda=labeledField(f,"Agenda",existing.optString("agenda"),true),resources=labeledField(f,"Recursos e capacidade",existing.optString("resources"),true),plan=labeledField(f,"Plano atual",existing.optString("current_plan"),true),location=labeledField(f,"Localização",existing.optString("location"),false),relation=labeledField(f,"Relação (-100 a 100)",String.valueOf(existing.optInt("relationship",0)),false),interval=labeledField(f,"Horas por etapa do plano",String.valueOf(Math.round(existing.optDouble("plan_interval_hours",24d))),false),steps=labeledField(f,"Etapas JSON [{title,summary,location,resources,risks,relationship_delta,next_plan,consequence_json}]",existing.optString("plan_steps_json","[]"),true),structure=labeledField(f,"Estrutura completa — JSON",factionStructureJson(existing),true);
        relation.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);interval.setInputType(InputType.TYPE_CLASS_NUMBER);steps.setMinLines(5);structure.setMinLines(12);final CheckBox cycle=check("Repetir as etapas do plano em ciclo",existing.optInt("plan_cycle",1)==1);f.addView(cycle);
        new AlertDialog.Builder(this).setTitle(existing.length()>0?"Editar organização persistente":"Organização persistente").setView(scrollableDialogView(f)).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{String rawSteps=value(steps);if(rawSteps.length()==0)rawSteps="[]";new JSONArray(rawSteps);JSONObject update=new JSONObject().put("id",existing.optLong("id",0)).put("name",value(name)).put("agenda",value(agenda)).put("resources",value(resources)).put("relationship",Math.max(-100,Math.min(100,num(relation,0)))).put("current_plan",value(plan)).put("location",value(location)).put("plan_interval_hours",Math.max(1,num(interval,24))).put("plan_steps_json",rawSteps).put("plan_cycle",cycle.isChecked()).put("active",true);applyFactionStructure(update,value(structure));applyFactionPoliticalType(update,existing,String.valueOf(entityType.getSelectedItem()));db.applyFactionUpdate(update);showPartyDirector();}catch(Exception e){toast("Estrutura da organização: use JSON válido. "+e.getMessage());}}}).show();
    }
    private String factionStructureJson(JSONObject existing){try{JSONObject out=new JSONObject();for(String key:new String[]{"objectives_json","resources_json","territories_json","relations_json","allies_json","enemies_json","information_json","costs_json","risks_json","success_conditions_json","failure_conditions_json","memory_json"}){String raw=existing==null?"":existing.optString(key);if(raw.trim().length()==0)raw=("objectives_json".equals(key)||"resources_json".equals(key)||"costs_json".equals(key))?"{}":"[]";out.put(key,raw.trim().startsWith("{")?new JSONObject(raw):new JSONArray(raw));}return out.toString(2);}catch(Exception error){return "{}";}}
    private void applyFactionStructure(JSONObject update,String raw)throws Exception{JSONObject structure=new JSONObject(raw==null||raw.trim().length()==0?"{}":raw);for(String key:new String[]{"objectives_json","resources_json","costs_json"}){Object value=structure.opt(key);if(value!=null){if(!(value instanceof JSONObject))throw new Exception(key+" deve ser objeto JSON");update.put(key,value.toString());}}for(String key:new String[]{"territories_json","relations_json","allies_json","enemies_json","information_json","risks_json","success_conditions_json","failure_conditions_json","memory_json"}){Object value=structure.opt(key);if(value!=null){if(!(value instanceof JSONArray))throw new Exception(key+" deve ser array JSON");update.put(key,value.toString());}}}
    private void applyFactionPoliticalType(JSONObject update,JSONObject existing,String label)throws Exception{JSONObject structured=parseLooseJson(update.optString("resources_json","{}"));structured.remove("claims_statehood");structured.remove("statehood_claim");structured.remove("realm");structured.remove("is_realm");int day=livingWorldEngine==null?1:livingWorldEngine.currentDay();if("Reino / Estado".equals(label)){update.put("entity_type",RealmLifecycleEngine.ENTITY_REALM);update.put("resources_json",structured.toString());String prior=existing==null?"":existing.optString("realm_state_json");if(prior.trim().length()>0)update.put("realm_state_json",prior);JSONObject seed=new JSONObject(update.toString());if(!seed.has("realm_state_json"))seed.put("realm_state_json","{}");update.put("realm_state_json",RealmLifecycleEngine.state(seed,day).toString());if(existing==null||existing.optInt("founded_day",0)<=0)update.put("founded_day",Math.max(1,day));}else if("Pretendente a reino".equals(label)){update.put("entity_type","faction");structured.put("claims_statehood",true);update.put("resources_json",structured.toString());String prior=existing==null?"":existing.optString("realm_state_json");update.put("realm_state_json",prior.trim().length()>0?prior:RealmLifecycleEngine.state(new JSONObject(update.toString()),day).toString());}else{update.put("entity_type","faction");update.put("resources_json",structured.toString());}}
    private static String realmStatusLabel(String value){if("ascendant".equals(value))return "ascendente";if("strained".equals(value))return "sob tensão";if("crisis".equals(value))return "em crise";if("civil_war".equals(value))return "guerra civil";if("fallen".equals(value))return "caído";if("claimant".equals(value))return "pretendente";if("forming".equals(value))return "em formação";return "estável";}

    private void worldEventDialog(){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(12),0,dp(12),0);final EditText title=labeledField(f,"Evento","",false),description=labeledField(f,"O que acontece","",true),day=labeledField(f,"Dia da campanha em que vence","0",false),trigger=labeledField(f,"Gatilho JSON (opcional)","{}",true),procedure=labeledField(f,"Procedimento JSON ou revisão exigida","{\"executable\":false,\"review_required\":true}",true),consequence=labeledField(f,"Consequência JSON","{}",true);day.setInputType(InputType.TYPE_CLASS_NUMBER);trigger.setMinLines(3);procedure.setMinLines(3);consequence.setMinLines(4);new AlertDialog.Builder(this).setTitle("Agendar evento do mundo").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("AGENDAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject triggerJson=new JSONObject(value(trigger).length()==0?"{}":value(trigger)),procedureJson=new JSONObject(value(procedure).length()==0?"{}":value(procedure)),consequenceJson=new JSONObject(value(consequence).length()==0?"{}":value(consequence));long id=db.addWorldEventStructured(new JSONObject().put("title",value(title)).put("description",value(description)).put("due_day",num(day,0)).put("trigger_json",triggerJson).put("procedure_json",procedureJson).put("consequence_json",consequenceJson));if(id<=0)throw new Exception("evento sem título");showPartyDirector();}catch(Exception error){toast("Evento: "+error.getMessage());}}}).show();}
    private void subgroupDialog(){final List<JSONObject> heroes=partyDirector.activeHeroRoster();if(heroes.isEmpty()){toast("Nenhum herói em jogo.");return;}LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(12),0,dp(12),0);final EditText name=labeledField(f,"Nome do subgrupo","",false);final ArrayList<CheckBox> checks=new ArrayList<CheckBox>();for(JSONObject h:heroes){CheckBox cb=new CheckBox(this);cb.setText(h.optString("name"));cb.setTextColor(TEXT);cb.setTag(h.optString("name"));checks.add(cb);f.addView(cb);}new AlertDialog.Builder(this).setTitle("Dividir a companhia").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{String groupName=name.getText().toString().trim();if(groupName.length()==0){toast("Dê um nome ao subgrupo.");return;}JSONArray members=new JSONArray();for(CheckBox cb:checks)if(cb.isChecked())members.put(String.valueOf(cb.getTag()));JSONObject state=db.getPartyState();JSONArray groups=parseLooseArray(state.optString("subgroups_json","[]"));JSONArray updated=new JSONArray();boolean replaced=false;for(int i=0;i<groups.length();i++){JSONObject g=groups.optJSONObject(i);if(g!=null&&groupName.equalsIgnoreCase(g.optString("name"))){updated.put(new JSONObject().put("name",groupName).put("members",members));replaced=true;}else if(g!=null)updated.put(g);}if(!replaced)updated.put(new JSONObject().put("name",groupName).put("members",members));state.put("subgroups_json",updated.toString());db.savePartyState(state);showPartyDirector();}catch(Exception e){toast(e.getMessage());}}}).show();}
    private void relationshipDialog(){final List<JSONObject> heroes=partyDirector.activeHeroRoster();if(heroes.size()<2){toast("São necessários ao menos dois heróis.");return;}String[] names=new String[heroes.size()];for(int i=0;i<heroes.size();i++)names[i]=heroes.get(i).optString("name");LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(12),0,dp(12),0);final Spinner a=spinner(names,names[0]),b=spinner(names,names[1]);final Spinner type=spinner(new String[]{"Confiança","Amizade","Rivalidade","Dívida","Promessa","Admiração","Medo","Romance permitido","Conflito"},"Confiança");final EditText score=labeledField(f,"Intensidade (-100 a 100)","0",false);score.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);f.addView(cardWithLabel("PRIMEIRO HERÓI",a));f.addView(cardWithLabel("SEGUNDO HERÓI",b));f.addView(cardWithLabel("RELAÇÃO",type));new AlertDialog.Builder(this).setTitle("Relação entre heróis").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{String an=String.valueOf(a.getSelectedItem()),bn=String.valueOf(b.getSelectedItem());if(an.equals(bn)){toast("Escolha dois heróis diferentes.");return;}JSONObject state=db.getPartyState();JSONArray relations=parseLooseArray(state.optString("relations_json","[]"));JSONArray updated=new JSONArray();for(int i=0;i<relations.length();i++){JSONObject r=relations.optJSONObject(i);if(r==null)continue;boolean same=(an.equals(r.optString("a"))&&bn.equals(r.optString("b")))||(an.equals(r.optString("b"))&&bn.equals(r.optString("a")));if(!same)updated.put(r);}updated.put(new JSONObject().put("a",an).put("b",bn).put("type",String.valueOf(type.getSelectedItem())).put("score",Math.max(-100,Math.min(100,num(score,0)))));state.put("relations_json",updated.toString());db.savePartyState(state);showPartyDirector();}catch(Exception e){toast(e.getMessage());}}}).show();}
    private static boolean arrayContains(JSONArray a,String value){if(a==null)return false;for(int i=0;i<a.length();i++)if(value.equals(a.optString(i)))return true;return false;}
    private static String controlLabel(String mode){String n=CompanionAgencyEngine.mode(mode);if("companion".equals(n))return "MESTRE CONTROLA";if("curated".equals(n))return "MESTRE COM CURADORIA";return "EU CONTROLO";}
    private static String controlMode(String label){if("MESTRE CONTROLA".equals(label))return "companion";if("MESTRE COM CURADORIA".equals(label))return "curated";return "manual";}
    private static String arcStatusLabel(String value){if("paused".equals(value))return "Em pausa";if("completed".equals(value))return "Concluído";if("failed".equals(value))return "Fracassado";if("transformed".equals(value))return "Transformado";return "Ativo";}
    private static String arcStatusValue(String label){if("Em pausa".equals(label))return "paused";if("Concluído".equals(label))return "completed";if("Fracassado".equals(label))return "failed";if("Transformado".equals(label))return "transformed";return "active";}
    private static String truthStatus(String label){String n=label.toLowerCase(Locale.ROOT);if(n.startsWith("rumor"))return "rumor";if(n.startsWith("mentira"))return "mentira";if(n.startsWith("interpre"))return "equivoco";return "verdade";}

    private void showJournal(){
        ScrollView s=page("Diário","Cenas, anotações e resumos persistentes.");LinearLayout b=body(s);Button add=button("+ NOVA ANOTAÇÃO",GREEN);add.setOnClickListener(new View.OnClickListener(){public void onClick(View v){journalDialog();}});b.addView(add);List<JSONObject> list=db.listJournal();if(list.size()==0)b.addView(empty("O diário ainda está vazio."));for(int i=0;i<list.size();i++){final JSONObject j=list.get(i);LinearLayout c=card();c.addView(text(j.optString("title"),19,GOLD,true));c.addView(text(j.optString("kind")+" • "+formatDate(j.optLong("created_at")),12,MUTED,false));TextView body=text(j.optString("body"),15,TEXT,false);body.setMaxLines(12);c.addView(body);Button del=smallButton("EXCLUIR",RED);del.setOnClickListener(new View.OnClickListener(){public void onClick(View v){db.deleteJournal(j.optLong("id"));showJournal();}});c.addView(del);b.addView(c);}
        Button export=button("EXPORTAR DIÁRIO COMO TEXTO",PANEL2);export.setOnClickListener(new View.OnClickListener(){public void onClick(View v){StringBuilder text=new StringBuilder();List<JSONObject> list=db.listJournal();for(int i=list.size()-1;i>=0;i--){JSONObject j=list.get(i);text.append("# ").append(j.optString("title")).append("\n").append(j.optString("body")).append("\n\n");}Intent x=new Intent(Intent.ACTION_SEND);x.setType("text/plain");x.putExtra(Intent.EXTRA_TEXT,text.toString());startActivity(Intent.createChooser(x,"Exportar diário"));}});b.addView(export);
        Button bard=button("EXPORTAR COMO CRÔNICA DE BARDO (PDF)",GREEN);bard.setOnClickListener(new View.OnClickListener(){public void onClick(View v){bardChronicleDialog();}});b.addView(bard);
        Button pdf=button("EXPORTAR AVENTURA COMO LIVRO PDF",GOLD);pdf.setTextColor(Color.BLACK);pdf.setOnClickListener(new View.OnClickListener(){public void onClick(View v){prepareLiteralAdventurePdf();}});b.addView(pdf);
    }
    private void bardChronicleDialog(){
        final List<JSONObject> journal=db.listJournal();if(journal.isEmpty()){toast("O Diário ainda não possui história para transformar em balada.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(10));
        form.addView(text("O PDF reorganiza os registros em ordem cronológica e os apresenta como uma história oral contada numa taverna. Fatos, nomes e consequências vêm somente da campanha; a moldura do bardo é estilística.",13,TEXT,false));
        final EditText bardName=labeledField(form,"Nome do bardo","Bardo do Braseiro",false);
        final Spinner tone=spinner(new String[]{"Épico e caloroso","Aventureiro e bem-humorado","Sombrio e dramático","Sóbrio e lendário"},"Épico e caloroso");form.addView(cardWithLabel("TOM DA NARRAÇÃO",tone));
        final CheckBox useAi=check("Lapidar a prosa com Gemini quando disponível (1 chamada)",geminiKey().trim().length()>=20);form.addView(useAi);
        form.addView(text("Ao marcar Gemini, o conteúdo necessário do Diário é enviado à API configurada para reescrita literária. Desmarque para manter todo o processo no aparelho.",12,GOLD,false));
        form.addView(text("Sem Gemini, a crônica continua sendo gerada inteiramente no aparelho, com prólogo, capítulos, transições e encerramento de bardo. Campanhas muito extensas usam automaticamente o modo local para não cortar acontecimentos.",12,MUTED,false));
        new AlertDialog.Builder(this).setTitle("Crônica de bardo").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("GERAR PDF",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){prepareBardChroniclePdf(value(bardName),String.valueOf(tone.getSelectedItem()),useAi.isChecked());}}).show();
    }

    private void prepareLiteralAdventurePdf(){
        setStatus("Montando o livro da aventura em segundo plano…");
        AppExecutors.io().execute(new Runnable(){public void run(){try{final File file=new AdventurePdfExporter(MainActivity.this).export(db.getCampaign(),db.listJournal());ui.post(new Runnable(){public void run(){pendingAdventurePdfKind="livro";pendingAdventurePdf=file;openAdventurePdfDestination("Cronicas_"+safeExportName(db.getCampaign().optString("name","Braseiro"))+".pdf");setStatus("Livro da aventura pronto para salvar.");}});}catch(final Exception e){ui.post(new Runnable(){public void run(){toast("PDF: "+e.getMessage());setStatus("Não foi possível montar o PDF.");}});}}});
    }

