    private boolean hasManualFolderAccess(){return libraryConnections!=null?libraryConnections.hasPersistedReadPermission(LibraryConnectionManager.MANUALS):prefs!=null&&prefs.getString("manual_tree_uri","").trim().length()>0;}
    private boolean hasLibraryAccess(String source){return libraryConnections!=null&&libraryConnections.hasPersistedReadPermission(source);}
    private void selectBackupFolder(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(intent,REQ_BACKUP_FOLDER);}

    private void selectManualFolder(){
        Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);
        try{startActivityForResult(intent,REQ_MANUAL_FOLDER);}catch(Exception e){toast("Não foi possível abrir o seletor de pastas: "+e.getMessage());}
    }

    private void syncManualFolder(){
        final String stored=prefs.getString("manual_tree_uri","").trim();
        if(stored.length()==0){selectManualFolder();return;}
        if(libraryConnections!=null&&!libraryConnections.hasPersistedReadPermission(LibraryConnectionManager.MANUALS)){libraryConnections.recordSyncFailure(LibraryConnectionManager.MANUALS,"Permissão persistente revogada.");selectManualFolder();return;}
        final Uri treeUri=Uri.parse(stored);
        if(libraryConnections!=null)libraryConnections.recordSyncStart(LibraryConnectionManager.MANUALS);
        setStatus("Verificando somente os PDFs de manuais; a pasta tokens será ignorada...");
        AppExecutors.io().execute(new Runnable(){public void run(){
            try{
                if(manualFolderScanner==null)manualFolderScanner=new SafFolderScanner(MainActivity.this);
                final int removedTokenPdfs=db.purgeManualsFromReservedTokenFolders();
                final List<JSONObject> files=manualFolderScanner.listManualPdfs(treeUri,null,null);
                final long seen=System.currentTimeMillis();final String sourceRoot="saf-manuals:"+stableFingerprint(stored);
                int accepted=0,added=0,changed=0;
                for(JSONObject file:files){
                    String title=file.optString("name","").trim();
                    if(title.length()==0)continue;
                    String mime=file.optString("mimeType","application/pdf");
                    if(!"application/pdf".equalsIgnoreCase(mime)&&!title.toLowerCase(Locale.US).endsWith(".pdf"))continue;
                    String documentId=file.optString("documentId",file.optString("sourceUri"));
                    String stableId="saf:"+Integer.toHexString((stored+"|"+documentId).hashCode())+":"+documentId;
                    String[] classification=classifyManual(title);
                    String path=file.optString("path",title);
                    int sync=db.upsertManualSynced(stableId,title,classification[0],classification[1],"application/pdf",file.optLong("size"),String.valueOf(file.optLong("modifiedTime")),file.optString("sourceUri"),"Pasta Android / Google Drive"+(path.length()>0?" • "+path:""),sourceRoot,seen);
                    if(sync==1)added++;else if(sync==2)changed++;
                    accepted++;
                }
                final int count=accepted,addedCount=added,changedCount=changed,missingCount=db.disableMissingManuals(sourceRoot,seen,"Pasta Android / Google Drive");
                prefs.edit().putInt("last_manual_tree_count",count).putLong("last_manual_tree_sync",System.currentTimeMillis()).apply();
                if(libraryConnections!=null)libraryConnections.recordSyncSuccess(LibraryConnectionManager.MANUALS,count,addedCount,changedCount,missingCount);
                ui.post(new Runnable(){public void run(){
                    if(count==0){
                        setStatus("A pasta foi vinculada, mas nenhum PDF foi encontrado.");
                        new AlertDialog.Builder(MainActivity.this).setTitle("Nenhum PDF encontrado").setMessage("Escolha a pasta que contém os manuais. Se ela estiver em ‘Compartilhados comigo’, adicione um atalho em ‘Meu Drive’ e selecione esse atalho pelo seletor do Android.").setNegativeButton("Fechar",null).setPositiveButton("ESCOLHER OUTRA PASTA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){selectManualFolder();}}).show();
                    }else{
                        toast(count+" manuais encontrados • "+addedCount+" novo(s) • "+changedCount+" alterado(s) • "+missingCount+" ausente(s). A pasta tokens foi ignorada"+(removedTokenPdfs>0?" e "+removedTokenPdfs+" entrada(s) antiga(s) removida(s).":"."));
                        setStatus(count+" manuais sincronizados. Alterações invalidaram seus índices automaticamente; ausentes foram desativados. Toque em RETOMAR / INDEXAR TUDO para concluir.");
                        showManuals("");
                    }
                }});
            }catch(final Exception e){
                if(libraryConnections!=null)libraryConnections.recordSyncFailure(LibraryConnectionManager.MANUALS,e.getMessage()==null?e.toString():e.getMessage());
                ui.post(new Runnable(){public void run(){
                    String message=e.getMessage()==null?e.toString():e.getMessage();
                    setStatus("Não foi possível ler a pasta vinculada.");
                    new AlertDialog.Builder(MainActivity.this).setTitle("Acesso à pasta do Drive").setMessage(message+"\n\nSelecione novamente a pasta para renovar a permissão do Android.").setNegativeButton("Fechar",null).setPositiveButton("SELECIONAR PASTA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){selectManualFolder();}}).show();
                }});
            }
        }});
    }

    private boolean isUnregisteredDriveClient(String message){
        String n=message==null?"":message.toLowerCase(Locale.US);
        return n.contains("unregisteredonapiconsole")||n.contains("unregistered on api console")||n.contains("developer_error")||n.contains("api console");
    }

    private void showDriveOAuthFallback(final String after,String rawMessage){
        pendingDriveSync=after==null?"":after;
        String detail=rawMessage==null?"":rawMessage.trim();
        String oauthHelp="\n\nParâmetros para registro no Google Cloud Console:\nPacote: "+getPackageName()+"\nSHA-1: 6F:47:92:78:1F:11:ED:FF:C8:92:AF:EB:95:69:4E:3C:03:F3:5C:DF\nEscopo: https://www.googleapis.com/auth/drive.readonly";
        new AlertDialog.Builder(this).setTitle("Conexão do Google Drive").setMessage("Esta compilação requer registro OAuth no Google Cloud para o certificado da aplicação"+(detail.length()>0?" ("+detail+")":"")+".\n\nO Braseiro pode acessar os mesmos arquivos sem OAuth usando o seletor oficial do Android (SAF)."+oauthHelp).setNegativeButton("Cancelar",null).setPositiveButton("ESCOLHER PASTA NO DRIVE",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){if("tokenPdfs".equals(pendingDriveSync))selectTokenPdfFolder();else if("tokens".equals(pendingDriveSync))selectTokenImageFolder();else selectManualFolder();}}).show();
        setStatus("Use o seletor de pasta do Android ou cadastre o cliente OAuth com o SHA-1 indicado.");
    }

    private void authorizeDrive(final String after){
        pendingDriveSync=after==null?"":after;
        setStatus("Abrindo seleção da conta Google...");
        try{
            if(accountManager==null)accountManager=AccountManager.get(this);
            Intent chooser=AccountManager.newChooseAccountIntent(null,null,new String[]{"com.google"},null,null,null,null);
            startActivityForResult(chooser,REQ_DRIVE_AUTH);
        }catch(Exception e){
            toast("Não foi possível abrir a seleção de conta: "+e.getMessage());
            setStatus("Falha ao abrir a conta Google.");
        }
    }

    private void requestDriveToken(final Account account){
        if(account==null){toast("Nenhuma conta Google foi selecionada.");setStatus("Google Drive não conectado.");return;}
        pendingDriveAccountName=account.name==null?"":account.name;
        pendingDriveAccountType=account.type==null?"com.google":account.type;
        setStatus("Solicitando autorização somente de leitura do Google Drive...");
        if(accountManager==null)accountManager=AccountManager.get(this);
        accountManager.getAuthToken(account,DRIVE_AUTH_TOKEN_TYPE,null,this,new AccountManagerCallback<Bundle>(){
            public void run(AccountManagerFuture<Bundle> future){
                try{
                    Bundle bundle=future.getResult();
                    Intent consent=bundle==null?null:(Intent)bundle.getParcelable(AccountManager.KEY_INTENT);
                    if(consent!=null){
                        startActivityForResult(consent,REQ_DRIVE_CONSENT);
                        return;
                    }
                    String token=bundle==null?null:bundle.getString(AccountManager.KEY_AUTHTOKEN);
                    acceptDriveAccessToken(token);
                }catch(final Exception e){
                    ui.post(new Runnable(){public void run(){
                        String message=e.getMessage()==null?e.toString():e.getMessage();
                        if(isUnregisteredDriveClient(message))showDriveOAuthFallback(pendingDriveSync,message);
                        else{toast("Falha ao autorizar o Drive: "+message);setStatus("Google Drive não conectado.");}
                    }});
                }
            }
        },ui);
    }

    private void acceptDriveAccessToken(String token){
        if(token==null||token.length()<20){
            toast("O Google não retornou acesso ao Drive. Confirme a conta e a autorização solicitada.");
            setStatus("Google Drive não conectado.");
            return;
        }
        drive.saveAccessToken(token);
        prefs.edit().putString("drive_account_name",pendingDriveAccountName).putString("drive_account_type",pendingDriveAccountType).apply();
        toast("Google Drive conectado à conta selecionada.");
        setStatus("Google Drive conectado.");
        String next=pendingDriveSync;pendingDriveSync="";
        if("tokens".equals(next))syncTokens();
        else if("tokenPdfs".equals(next))syncTokenPdfCatalog();
        else if("manuals".equals(next))syncDrive();
        else if("Config".equalsIgnoreCase(currentScreen))showSettings();
    }

    private void syncDrive(){
        if(hasManualFolderAccess()){syncManualFolder();return;}
        if(!drive.isConnected()){selectManualFolder();return;}
        setStatus("Lendo a pasta de manuais pela API legada do Drive...");
        final String folder=prefs.getString("drive_folder",DEFAULT_FOLDER);final String sourceRoot="drive-manuals:"+DriveService.extractFolderId(folder);
        drive.listFolderRecursive(folder,new DriveService.FilesCallback(){
            public void onSuccess(final List<JSONObject> files){
                long seen=System.currentTimeMillis();int accepted=0,added=0,changed=0;
                for(int i=0;i<files.size();i++){
                    JSONObject f=files.get(i);String mime=f.optString("mimeType");if(!"application/pdf".equals(mime))continue;
                    accepted++;String title=f.optString("name");String[] cls=classifyManual(title);
                    int sync=db.upsertManualSynced(f.optString("id"),title,cls[0],cls[1],mime,f.optLong("size"),f.optString("modifiedTime"),"","Google Drive API"+(f.optString("path").length()>0?" • "+f.optString("path"):""),sourceRoot,seen);
                    if(sync==1)added++;else if(sync==2)changed++;
                }
                final int count=accepted,addedCount=added,changedCount=changed,missingCount=db.disableMissingManuals(sourceRoot,seen,"Google Drive API");
                ui.post(new Runnable(){public void run(){setStatus(count+" manuais pela API • "+addedCount+" novo(s) • "+changedCount+" alterado(s) • "+missingCount+" ausente(s). Alterações já invalidaram os índices antigos; toque em RETOMAR / INDEXAR TUDO.");showManuals("");}});
            }
            public void onError(final String message){ui.post(new Runnable(){public void run(){
                if(isUnregisteredDriveClient(message)){drive.disconnect();showDriveOAuthFallback("manuals",message);}
                else if(message.toLowerCase(Locale.US).contains("expir")){drive.disconnect();selectManualFolder();}
                else{toast(message);setStatus("Falha ao sincronizar; selecione a pasta pelo Android.");}
            }});}
        });
    }

    private void indexManual(final JSONObject manual){
        final String worldAtStart=activeWorldProfile();if(!manualBelongsToWorld(manual,worldAtStart)){toast("Esse manual pertence a outro mundo e foi bloqueado.");return;}if(ragIndexingRunning){toast("O índice local já está trabalhando.");return;}if(manual.optString("local_uri").length()==0&&!drive.isConnected()){toast("Vincule novamente a pasta de manuais para acessar este PDF.");selectManualFolder();return;}
        ragIndexingRunning=true;ragIndexingWorld=worldAtStart;setStatus("Indexando localmente "+manualDisplayTitle(manual)+"...");
        AppExecutors.io().execute(new Runnable(){public void run(){try{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);}catch(Throwable ignored){Thread.currentThread().setPriority(Thread.MIN_PRIORITY);}final ArrayList<JSONObject> candidates=new ArrayList<JSONObject>();candidates.add(manual);String key=LocalManualIndexer.duplicateKey(manual.optString("title"));if(key.length()>=8){for(JSONObject other:filterManualsForWorld(db.listManuals(""),worldAtStart)){if(other.optLong("id")==manual.optLong("id")||other.optInt("enabled",1)!=1)continue;if(key.equals(LocalManualIndexer.duplicateKey(other.optString("title"))))candidates.add(other);}}Exception lastError=null;JSONObject winner=null;for(JSONObject candidate:candidates){if(!worldAtStart.equals(activeWorldProfile()))break;try{localManualIndexer.index(candidate,true,new LocalManualIndexer.Progress(){public void update(String message,int done,int total){postRagProgress(message);}});winner=candidate;lastError=null;break;}catch(Exception e){lastError=e;AppLog.w("ManualIndexer","Falha em uma cópia de "+manualDisplayTitle(candidate)+"; tentando duplicada quando existir.",e);}}if(winner!=null){if(key.length()>=8){for(JSONObject candidate:candidates){if(candidate.optLong("id")==winner.optLong("id"))continue;db.setManualRagProgress(candidate.optLong("id"),"duplicate_skipped","Duplicado coberto por "+manualDisplayTitle(winner)+" já indexado.","",LocalManualIndexer.STORE,candidate.optString("modified_time"),"",0,0,0,"local");}}ui.post(new Runnable(){public void run(){ragIndexingRunning=false;ragIndexingWorld="";toast("Manual pronto no índice local.");if(worldAtStart.equals(activeWorldProfile()))showManuals("");}});}else{final String failure=lastError==null?"Não foi possível concluir a indexação.":lastError.getMessage();ui.post(new Runnable(){public void run(){ragIndexingRunning=false;ragIndexingWorld="";toast(manualIndexErrorPtBr(failure));if(worldAtStart.equals(activeWorldProfile()))showManuals("");}});}}});
    }

