        final StrixhavenAssetCatalog embeddedCatalog=strixhavenAssetCatalog();LinearLayout embedded=card();embedded.addView(text("STRIXHAVEN • ASSETS EMBUTIDOS",16,GOLD,true));embedded.addView(text(embeddedCatalog.isComplete()?"Pacote completo no APK: "+embeddedCatalog.assetCount()+" recortes, "+embeddedCatalog.mapCount()+" mapas e "+embeddedCatalog.sourceSheetCount()+" folhas-fonte.":"Pacote Strixhaven incompleto — verifique a validação da release.",12,embeddedCatalog.isComplete()?GREEN:RED,true));embedded.addView(text("Os recortes podem ser vinculados diretamente a heróis/NPCs e passam a aparecer na party, combate e mapa pelo mesmo token_uri já usado pelo projeto. Pesquise pelo ID Sxx-xxx ou nome da folha-fonte.",12,MUTED,false));int embeddedTotal=embeddedCatalog.matchingCount(filter);List<JSONObject> embeddedAssets=embeddedCatalog.list(filter,Math.min(strixhavenAssetVisibleLimit,embeddedTotal==0?1:embeddedTotal));for(int i=0;i<embeddedAssets.size();i++){final JSONObject asset=embeddedAssets.get(i);LinearLayout row=card();row.addView(text(asset.optString("asset_id","ASSET"),15,TEXT,true));row.addView(text(asset.optInt("width")+"×"+asset.optInt("height")+" • "+asset.optString("source_sheet"),10,MUTED,false));LinearLayout actions=new LinearLayout(this);Button preview=smallButton("VER",PANEL2),use=smallButton("VINCULAR",GREEN);preview.setOnClickListener(new View.OnClickListener(){public void onClick(View v){previewStrixhavenAsset(asset);}});use.setOnClickListener(new View.OnClickListener(){public void onClick(View v){chooseHeroForStrixhavenAsset(asset);}});actions.addView(preview);actions.addView(use);row.addView(actions);embedded.addView(row);}if(embeddedTotal>embeddedAssets.size()){Button more=button("CARREGAR MAIS "+Math.min(30,embeddedTotal-embeddedAssets.size())+" ASSETS STRIXHAVEN",PANEL2);more.setOnClickListener(new View.OnClickListener(){public void onClick(View v){strixhavenAssetVisibleLimit+=30;showTokens(filter,selectedGroup);}});embedded.addView(more);}b.addView(embedded);

        LinearLayout legacy=card();legacy.addView(text("BIBLIOTECA PNG/JPG EM PASTA",16,GOLD,true));final boolean tokenImageFolderLinked=prefs.getString("token_image_tree_uri","").trim().length()>0;legacy.addView(text((tokenImageFolderLinked?"Pasta vinculada sem OAuth • ":"")+db.countTokens()+" imagens catalogadas. A pasta serve para carregar muitos tokens de uma vez e permanece separada da escolha individual acima.",12,tokenImageFolderLinked?GREEN:MUTED,false));Button chooseImages=button(tokenImageFolderLinked?"TROCAR PASTA DE TOKENS":"IMPORTAR PASTA DE TOKENS",PANEL2),legacySync=button("SINCRONIZAR PASTA",PANEL2);chooseImages.setOnClickListener(new View.OnClickListener(){public void onClick(View v){selectTokenImageFolder();}});legacySync.setOnClickListener(new View.OnClickListener(){public void onClick(View v){syncTokens();}});legacy.addView(chooseImages);legacy.addView(legacySync);b.addView(legacy);
        List<JSONObject> list=db.listTokens(filter,"Todas");int max=Math.min(tokenImageVisibleLimit,list.size());for(int i=0;i<max;i++){final JSONObject token=list.get(i);LinearLayout row=card();row.addView(text(token.optString("label",token.optString("name")),15,TEXT,true));row.addView(text(token.optString("species")+" • "+token.optString("creature_type")+" • "+token.optString("role"),11,GOLD,false));LinearLayout actions=new LinearLayout(this);Button preview=smallButton("VER",PANEL2),use=smallButton("VINCULAR",GREEN);preview.setOnClickListener(new View.OnClickListener(){public void onClick(View v){previewToken(token);}});use.setOnClickListener(new View.OnClickListener(){public void onClick(View v){chooseHeroForToken(token);}});actions.addView(preview);actions.addView(use);row.addView(actions);b.addView(row);}if(list.size()>max){Button moreImages=button("CARREGAR MAIS "+Math.min(30,list.size()-max)+" IMAGENS",PANEL2);moreImages.setOnClickListener(new View.OnClickListener(){public void onClick(View v){tokenImageVisibleLimit+=30;showTokens(filter,selectedGroup);}});b.addView(moreImages);}
