    private void syncTokens(){
        if(tokenSyncRunning)return;
        final String stored=prefs.getString("token_image_tree_uri","").trim();
        if(stored.length()>0){
            if(libraryConnections!=null&&!libraryConnections.hasPersistedReadPermission(LibraryConnectionManager.TOKEN_IMAGES)){libraryConnections.recordSyncFailure(LibraryConnectionManager.TOKEN_IMAGES,"Permissão persistente revogada.");selectTokenImageFolder();return;}
            if(libraryConnections!=null)libraryConnections.recordSyncStart(LibraryConnectionManager.TOKEN_IMAGES);
            tokenSyncRunning=true;setStatus("Lendo imagens individuais pela pasta vinculada...");
            AppExecutors.io().execute(new Runnable(){public void run(){try{
                if(manualFolderScanner==null)manualFolderScanner=new SafFolderScanner(MainActivity.this);
                List<JSONObject> files=manualFolderScanner.listImages(Uri.parse(stored));final long seen=System.currentTimeMillis();int accepted=0;
                for(JSONObject f:files){String mime=f.optString("mimeType","");if(!mime.startsWith("image/"))continue;accepted++;String name=f.optString("name");JSONObject classification=TokenClassifier.classify(name);String documentId=f.optString("documentId",f.optString("sourceUri"));String stableId="safimg:"+Integer.toHexString(stored.hashCode())+":"+Integer.toHexString(documentId.hashCode());db.upsertToken(stableId,name,classification,mime,f.optLong("size"),String.valueOf(f.optLong("modifiedTime")),f.optString("sourceUri"),"Pasta Android / Google Drive • "+f.optString("path",name),seen);JSONObject saved=db.getTokenByDriveId(stableId);if(saved.length()>0)db.setTokenLocalUri(saved.optLong("id"),f.optString("sourceUri"));}
                final int count=accepted;prefs.edit().putLong("last_token_sync",seen).apply();if(libraryConnections!=null)libraryConnections.recordSyncSuccess(LibraryConnectionManager.TOKEN_IMAGES,count,0,0,0);ui.post(new Runnable(){public void run(){tokenSyncRunning=false;setStatus(count+" imagens individuais sincronizadas pela pasta.");toast(count+" imagens encontradas.");showTokens("","Todos");}});
            }catch(final Exception e){if(libraryConnections!=null)libraryConnections.recordSyncFailure(LibraryConnectionManager.TOKEN_IMAGES,e.getMessage()==null?e.toString():e.getMessage());ui.post(new Runnable(){public void run(){tokenSyncRunning=false;toast("Imagens: "+e.getMessage());setStatus("Falha ao ler a pasta de imagens.");}});}}});
            return;
        }
        if(!drive.isConnected()){selectTokenImageFolder();return;}
        tokenSyncRunning=true;setStatus("Lendo imagens individuais pela API Google legada...");final String folder=prefs.getString("token_folder",DEFAULT_TOKEN_IMAGE_FOLDER);drive.listFolder(folder,new DriveService.FilesCallback(){public void onSuccess(final List<JSONObject> files){final long seen=System.currentTimeMillis();int accepted=0;for(int i=0;i<files.size();i++){JSONObject f=files.get(i);String mime=f.optString("mimeType","");if(!mime.startsWith("image/"))continue;accepted++;String name=f.optString("name");JSONObject classification=TokenClassifier.classify(name);db.upsertToken(f.optString("id"),name,classification,mime,f.optLong("size"),f.optString("modifiedTime"),f.optString("thumbnailLink"),"Google Drive API",seen);}final int count=accepted;prefs.edit().putLong("last_token_sync",seen).apply();ui.post(new Runnable(){public void run(){tokenSyncRunning=false;setStatus(count+" imagens individuais sincronizadas.");toast(count+" imagens encontradas.");showTokens("","Todos");}});}public void onError(final String message){ui.post(new Runnable(){public void run(){tokenSyncRunning=false;if(isUnregisteredDriveClient(message)){drive.disconnect();selectTokenImageFolder();}else if(message.toLowerCase(Locale.US).contains("expir")){drive.disconnect();selectTokenImageFolder();}else{toast(message);setStatus("Falha ao sincronizar imagens.");}}});}});
    }

    private InputStream openTokenInput(JSONObject token)throws Exception{
        String local=token.optString("local_uri","").trim();
        if(local.length()>0){Uri uri=Uri.parse(local);if("file".equalsIgnoreCase(uri.getScheme()))return new FileInputStream(new File(uri.getPath()));InputStream in=getContentResolver().openInputStream(uri);if(in==null)throw new Exception("Imagem local indisponível.");return in;}
        return drive.downloadFile(token.optString("drive_id"));
    }

    private String tokenImageMime(JSONObject token){String mime=token==null?"":token.optString("mime_type","").toLowerCase(Locale.US);if(mime.contains("jpeg")||mime.contains("jpg"))return "image/jpeg";if(mime.contains("webp"))return "image/webp";return "image/png";}

    private void previewToken(final JSONObject token){setStatus("Baixando prévia do token...");AppExecutors.io().execute(new Runnable(){public void run(){try{Uri source=null;String local=token.optString("local_uri");if(local.length()>0&&ImageStorageManager.isReadable(MainActivity.this,Uri.parse(local)))source=Uri.parse(local);if(source==null){InputStream in=openTokenInput(token);source=ImageStorageManager.importImage(MainActivity.this,in,tokenImageMime(token),"token_previews","preview_"+token.optString("drive_id","token"),12);}final Bitmap bitmap=ImageStorageManager.decodeSampled(MainActivity.this,source,1080,1080);ui.post(new Runnable(){public void run(){if(bitmap==null){toast("Não foi possível ler a imagem.");return;}ImageView view=new ImageView(MainActivity.this);view.setAdjustViewBounds(true);view.setScaleType(ImageView.ScaleType.CENTER_INSIDE);view.setImageBitmap(bitmap);new AlertDialog.Builder(MainActivity.this).setTitle(token.optString("label")).setView(view).setPositiveButton("Fechar",null).show();setStatus("Prévia carregada com resolução segura.");}});}catch(final Exception e){AppLog.e("TokenPreview","Falha ao preparar prévia.",e);ui.post(new Runnable(){public void run(){toast(e.getMessage());setStatus("Falha ao baixar token.");}});}}});}

