    private void downloadAndAssignToken(final JSONObject token,final long characterId){setStatus("Baixando token para o personagem...");AppExecutors.io().execute(new Runnable(){public void run(){try{InputStream in=openTokenInput(token);Uri stored=ImageStorageManager.importImage(MainActivity.this,in,tokenImageMime(token),"tokens","hero_"+characterId+"_"+token.optString("drive_id","token"),2000);String uri=stored.toString();db.setTokenLocalUri(token.optLong("id"),uri);db.setCharacterToken(characterId,uri);pendingTokenCharacterId="";ui.post(new Runnable(){public void run(){toast("Token validado e vinculado ao personagem.");setStatus("Token salvo no aparelho.");returnToTokenLibrary();}});}catch(final Exception e){AppLog.e("TokenImport","Falha ao vincular token ao personagem.",e);ui.post(new Runnable(){public void run(){toast(e.getMessage());setStatus("Falha ao vincular token.");}});}}});}

