    private void deleteDirectory(File file){if(file==null||!file.exists())return;if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)deleteDirectory(child);}file.delete();}

    private String[] classifyManual(String title){
        String t=title==null?"":title.toLowerCase(Locale.US);String category="Ambientação e ferramentas",profile="Conteúdo de apoio";
        if(ManualIdentityPolicy.isMystaraTitle(title)){
            category=MystaraManualAuthority.categoryFor(title);profile=MystaraManualAuthority.profileFor(title);
            if(containsAny(t,"adventure","aventura","module","módulo","modulo","quest","campaign","campanha")&&!t.contains("threshold"))category="Aventuras e campanhas de Mystara";
            else if(containsAny(t,"gazetteer","gazette","atlas","karameikos","glantri","thyatis","alphatia","darokin","ylaruam","rockhome","ethengar","minrothad","ierendi","atruaghin","hollow world","mundo oco","five shires","northern reaches","dawn of the emperors","red steel"))category="Cenário oficial, nações e povos de Mystara";
            return new String[]{category,profile};
        }
        boolean revised2024=containsAny(t,"2024","2025","revised","revisado","revisada");
        if(t.contains("livro do jogador")||t.contains("player's handbook")||t.contains("players handbook")||t.contains("guia do mestre")||t.contains("dungeon master")){category="Núcleo oficial de regras";profile=revised2024?DndRulesEngine.PROFILE_2024:DndRulesEngine.PROFILE_2014;}
        else if(t.contains("manual dos monstros")||t.contains("monster manual")||t.contains("bestiário")||t.contains("bestiario")||t.contains("bestiary")){category="Bestiário e encontros";profile=revised2024?DndRulesEngine.PROFILE_2024:DndRulesEngine.PROFILE_2014;}
        else if(t.contains("xanathar")||t.contains("tasha")||t.contains("mordenkainen")||t.contains("volo")||t.contains("fizban")){category="Suplemento oficial misto";profile="5e 2014";}
        else if(t.contains("phandelver")||t.contains("strahd")||t.contains("avernus")||t.contains("frostmaiden")||t.contains("tiamat")||t.contains("rainha drag")||t.contains("portal bocejante")||t.contains("netherdeep")||t.contains("fora do abismo")){category="Aventura e conteúdo de campanha";profile="5e 2014";}
        else if(t.contains("eberron")||t.contains("ravnica")||t.contains("costa da espada")||t.contains("sword coast")||t.contains("ravenloft")||t.contains("faerun")||t.contains("faerûn")){category="Cenário, cidades e facções";profile="5e 2014";}
        else if(t.contains("homebrew")||t.startsWith("hb ")||t.contains("classe")||t.contains("talento")){category="Homebrew / opções mecânicas";profile="Opcional";}
        else if(t.contains("tomo de batalha")||t.contains("nove espadas")){category="Outra edição";profile="Incompatível sem conversão";}
        else if(containsAny(t,"taverna","estalagem","inn","bordel","brothel","pesca","fishing","animal","cidade","city","selva","jungle","savana","savanna","navio","ship","merchant","comerciante","traveler","viajante","caravana","porto","mar")){category="Ambientação e ferramentas";profile="Conteúdo de apoio";}
        return new String[]{category,profile};
    }
