    private void focusMapOnCurrentPosition(){
        final MapBoardView target=mapView;if(target==null)return;
        final int[] attempts={0};final Runnable focus=new Runnable(){public void run(){if(target!=mapView||target.getWindowToken()==null)return;attempts[0]++;float zoom=Math.max(1.55f,(float)db.getMapState().optDouble("min_label_zoom",1.6));if(!target.focusCurrentPosition(zoom)&&attempts[0]<5)target.postDelayed(this,120L);}};
        target.post(focus);
    }

    private void searchMapLocation(final EditText field){
        String query=field==null?"":field.getText().toString().trim();JSONObject state=db.getMapState();String packageId=state.optString("map_package_id");
        if(packageId.length()==0){toast("O pacote completo do mapa ainda está sendo preparado.");return;}if(query.length()<2){toast("Digite pelo menos duas letras.");return;}
        final List<JSONObject> results=db.findMapLocationsByQuery(packageId,query,30);if(results.isEmpty()){toast("Nenhum local encontrado no catálogo de Faerûn.");return;}
        String[] labels=new String[results.size()];for(int i=0;i<results.size();i++){JSONObject loc=results.get(i);String region=loc.optString("region","");String bound=loc.optString("hex_id","").length()>0?" • "+loc.optString("hex_id"):" • posição não confirmada";labels[i]=loc.optString("name","Local")+(region.length()>0?" — "+region:"")+bound;}
        new AlertDialog.Builder(this).setTitle("Resultados no mapa").setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){focusMapLocation(results.get(which));}}).setNegativeButton("Fechar",null).show();
    }
    private void focusMapLocation(JSONObject loc){
        JSONObject state=db.getMapState();
        String packageId=state.optString("map_package_id","");
        String hex=loc.optString("hex_id","").trim();
        String description="",original="";
        Double u=null,v=null;
        if(loc.has("position_u")&&!loc.isNull("position_u")&&loc.has("position_v")&&!loc.isNull("position_v")){
            u=loc.optDouble("position_u");v=loc.optDouble("position_v");
        }
        try{
            JSONObject r=new JSONObject(loc.optString("raw_json","{}"));
            description=cleanJsonText(r.optString("description"),"");
            if(description.length()==0)description=cleanJsonText(r.optString("descricao_linha_1"),"");
            if(description.length()==0){JSONArray descriptions=r.optJSONArray("descricao");if(descriptions!=null&&descriptions.length()>0)description=cleanJsonText(descriptions.optString(0),"");}
            original=cleanJsonText(r.optString("nameOriginal"),"");
            if(original.length()==0)original=cleanJsonText(r.optString("nomeOriginal"),"");
            if(original.length()==0)original=cleanJsonText(r.optString("nome_original"),"");
        }catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada ao ler descrição de local.",ignored);}
        boolean contract=isAtlasContractRuntime(packageId);
        String activeFrame=db.getCoordinateFrameIdForPackage(packageId),locFrame=loc.optString("coordinate_frame_id","");
        boolean frameCompatible=u!=null&&v!=null&&activeFrame.length()>0&&activeFrame.equals(locFrame);
        boolean focused=false;
        if(mapView!=null){
            // Resultado de busca sempre substitui a seleção anterior. Câmara não move o grupo.
            mapView.setSelectedHexId(hex);
            if(contract){
                if(frameCompatible)focused=mapView.focusNormalizedPoint(u,v,1.15f);
                if(!focused&&hex.length()>0)focused=mapView.focusHexId(hex,1.15f);
            }else{
                double x=Double.NaN,y=Double.NaN;
                try{JSONObject r=new JSONObject(loc.optString("raw_json","{}"));JSONObject g=r.optJSONObject("geometry");JSONArray c=g==null?null:g.optJSONArray("coordinates");if(c!=null&&c.length()>=2){x=c.optDouble(0,Double.NaN);y=c.optDouble(1,Double.NaN);}}catch(Exception ignored){AppLog.ignored("MainActivity","Coordenada legada ausente.",ignored);}
                if(!Double.isNaN(x)&&!Double.isNaN(y))focused=mapView.focusMapPoint((float)x,(float)y,1.15f);else if(hex.length()>0)focused=mapView.focusHexId(hex,1.15f);
            }
            mapView.highlightLocation(loc.optString("name","Local"),hex,u,v);
            mapView.setDestination(hex);
        }
        StringBuilder body=new StringBuilder();
        if(original.length()>0&&!original.equalsIgnoreCase(loc.optString("name")))body.append("Nome original: ").append(original).append("\n");
        if(loc.optString("region").length()>0)body.append("Região: ").append(loc.optString("region")).append("\n");
        if(hex.length()>0){body.append("Hex canônico: ").append(hex);if(frameCompatible)body.append("\nPosição normalizada do contrato aplicada no frame atual.");else body.append("\nCentro do hex canônico aplicado; nenhuma coordenada legada foi usada.");}
        else body.append("Este registro está no catálogo, mas não possui posição cartográfica confirmada. O mapa não inventará coordenadas.");
        if(description.length()>0)body.append("\n\n").append(description);
        new AlertDialog.Builder(this).setTitle(loc.optString("name","Local")).setMessage(body.toString()).setPositiveButton("Fechar",null).show();
        if(focused)setStatus("Mapa centralizado em "+loc.optString("name","local")+(hex.length()>0?" • "+hex:"")+".");
    }
    private float mapDistanceBetweenHexes(String from,String to,JSONObject state){MapManifestGeometry g=mapGeometryFromState(state);float d=g==null?0f:g.distanceKm(from,to);return d>0?d:mapHexScaleKm(state);}
    private float mapDistanceToLocation(String from,JSONObject target,MapManifestGeometry geometry){if(geometry==null||target==null)return 0f;if(target.has("position_u")&&!target.isNull("position_u")&&target.has("position_v")&&!target.isNull("position_v")){float x=(float)(target.optDouble("position_u")*geometry.getImageWidth()),y=(float)(target.optDouble("position_v")*geometry.getImageHeight());return geometry.distanceKmFromHexToPoint(from,x,y);}return geometry.distanceKm(from,target.optString("hex_id"));}

    private String normalizeGridName(String value){if("Hexagonal".equals(value))return "Hexagonal flat-top";if(value!=null&&value.toLowerCase(Locale.US).contains("point"))return "Hexagonal pointy-top";if(value!=null&&value.toLowerCase(Locale.US).contains("hex"))return "Hexagonal flat-top";return value==null?"Quadrada":value;}

