    private void initializeAudioEngineAsync(){
        if(audioEngineReady||audioEngineInitializing)return;
        audioEngineInitializing=true;audioEngineError="";
        AppExecutors.io().execute(new Runnable(){public void run(){
            SmartAudioLibrary loadedLibrary=null;NarrativeAudioEngine loadedEngine=null;ReleaseReadinessManager loadedReadiness=null;String failure="";
            try{
                loadedLibrary=createSmartAudioSafely();
                loadedLibrary.setAutomaticSfxEnabled(false);
                loadedLibrary.purgeInvalidContinuousAudio();
                loadedEngine=new NarrativeAudioEngine(loadedLibrary,audio);
                loadedEngine.setStatus(new NarrativeAudioEngine.Status(){public void onStatus(final String text){if(ui!=null)ui.post(new Runnable(){public void run(){setBackgroundStatus(text);}});}});
                loadedReadiness=new ReleaseReadinessManager(MainActivity.this,db,safety,loadedLibrary,loadedEngine,npcTokenAutoBinder,secrets,taskQueue);
            }catch(Throwable error){failure=error.getClass().getSimpleName()+": "+String.valueOf(error.getMessage());AppLog.e("AudioInit","Falha ao iniciar o motor de áudio em segundo plano.",error);}
            final SmartAudioLibrary libraryResult=loadedLibrary;final NarrativeAudioEngine engineResult=loadedEngine;final ReleaseReadinessManager readinessResult=loadedReadiness;final String errorResult=failure;
            if(ui!=null)ui.post(new Runnable(){public void run(){
                audioEngineInitializing=false;
                if(isFinishing()||(Build.VERSION.SDK_INT>=17&&isDestroyed())){if(engineResult!=null)engineResult.shutdown();return;}
                if(engineResult==null||libraryResult==null){audioEngineReady=false;audioEngineError=errorResult;setStatus("O app abriu, mas o catálogo de áudio não iniciou. Abra Áudio e toque em TENTAR INICIAR NOVAMENTE.");return;}
                smartAudio=libraryResult;narrativeAudio=engineResult;releaseReadiness=readinessResult;audioEngineReady=true;audioEngineError="";
                try{if(db!=null&&db.getStoryState().optInt("started",0)==0)narrativeAudio.stopAll();}catch(Throwable ignored){AppLog.ignored("AudioInit","Falha tolerada ao verificar estado de início na inicialização de áudio.",ignored);}
                String pending=pendingAudioNarration;boolean useCharon=pendingAudioCharon;pendingAudioNarration="";pendingAudioCharon=false;
                int sounds=smartAudio.indexedSoundCount();
                setBackgroundStatus(sounds>0?"Áudio pronto: "+sounds+" sons indexados.":"Áudio pronto, mas a biblioteca de sons está vazia. Escolha novamente a pasta de áudio.");
                if(pending.trim().length()>0)ui.postDelayed(new Runnable(){public void run(){if(useCharon)speakGemini(pending);else speakNativeNarrationWithSfx(pending);}},120L);
            }});
        }});
    }

    private boolean ensureAudioEngineReadyOrQueue(String narration,boolean charon){
        if(audioEngineReady&&smartAudio!=null&&narrativeAudio!=null)return true;
        pendingAudioNarration=narration==null?"":narration;pendingAudioCharon=charon;
        initializeAudioEngineAsync();
        setStatus(audioEngineInitializing?"Preparando o catálogo de áudio sem travar a tela. A narração começará automaticamente.":"Áudio indisponível. Abra a aba Áudio para tentar novamente.");
        return false;
    }

    private JSONObject audioDiagnosticSnapshot(){
        if(narrativeAudio!=null)return narrativeAudio.diagnosticReport();
        JSONObject diagnostic=new JSONObject();
        try{diagnostic.put("ready",audioEngineReady).put("initializing",audioEngineInitializing).put("error",audioEngineError).put("catalog_sounds",smartAudio==null?0:smartAudio.indexedSoundCount());}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
        return diagnostic;
    }

    private SmartAudioLibrary createSmartAudioSafely(){
        try{return new SmartAudioLibrary(this,audio);}
        catch(Throwable first){
            AppLog.e("MainActivity","O catálogo de áudio falhou na inicialização; tentando reconstrução isolada.",first);
            try{AudioCatalogDb.recoverAfterInterruptedDiagnostic(this);return new SmartAudioLibrary(this,audio);}
            catch(Throwable second){AppLog.e("MainActivity","A reconstrução do catálogo de áudio também falhou.",second);if(second instanceof RuntimeException)throw (RuntimeException)second;if(second instanceof Error)throw (Error)second;throw new IllegalStateException("Catálogo de áudio indisponível.",second);}
        }
    }

    private void selectAudioFolder(){Intent x=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);x.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(x,REQ_AUDIO_FOLDER);}
    private void syncAudioLibrary(){
        final String uriText=prefs.getString("audio_tree_uri","");
        if(uriText.length()==0){selectAudioFolder();return;}
        if(libraryConnections!=null&&!libraryConnections.hasPersistedReadPermission(LibraryConnectionManager.AUDIO)){
            libraryConnections.recordSyncFailure(LibraryConnectionManager.AUDIO,"Permissão persistente revogada.");selectAudioFolder();return;
        }
        if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){
            requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},REQ_AUDIO_IMPORT_NOTIFICATIONS);
        }
        if(libraryConnections!=null)libraryConnections.recordSyncStart(LibraryConnectionManager.AUDIO);
        Data input=new Data.Builder().putString(AudioLibraryImportWorker.KEY_TREE_URI,uriText).build();
        final OneTimeWorkRequest request=new OneTimeWorkRequest.Builder(AudioLibraryImportWorker.class).setInputData(input).addTag(AudioLibraryImportWorker.UNIQUE_WORK).build();
        final WorkManager manager=WorkManager.getInstance(getApplicationContext());
        manager.enqueueUniqueWork(AudioLibraryImportWorker.UNIQUE_WORK,ExistingWorkPolicy.REPLACE,request);
        setStatus("Copiando a biblioteca para o armazenamento interno. A importação continuará mesmo se esta tela for fechada…");
        monitorAudioWork(manager,request.getId());
    }

    private void resumeAudioImportMonitor(){
        AppExecutors.io().execute(new Runnable(){public void run(){
            try{
                WorkManager manager=WorkManager.getInstance(getApplicationContext());
                List<WorkInfo> infos=manager.getWorkInfosForUniqueWork(AudioLibraryImportWorker.UNIQUE_WORK).get();
                if(infos==null||infos.isEmpty())return;
                WorkInfo selected=null;
                for(WorkInfo info:infos){
                    if(info==null)continue;
                    WorkInfo.State state=info.getState();
                    if(state==WorkInfo.State.RUNNING||state==WorkInfo.State.ENQUEUED||state==WorkInfo.State.BLOCKED){selected=info;break;}
                    if(state==WorkInfo.State.SUCCEEDED&&!info.getId().toString().equals(prefs.getString("audio_import_applied_work_id","")))selected=info;
                }
                if(selected!=null)monitorAudioWork(manager,selected.getId());
            }catch(Throwable error){AppLog.w("AudioImport","Não foi possível retomar o monitor da importação.",error);}
        }});
    }

    private void monitorAudioWork(final WorkManager manager,final UUID workId){
        if(manager==null||workId==null)return;
        final String monitorId=workId.toString();monitoredAudioWorkId=monitorId;
        AppExecutors.io().execute(new Runnable(){public void run(){
            try{
                while(monitorId.equals(monitoredAudioWorkId)){
                    WorkInfo info=manager.getWorkInfoById(workId).get();
                    if(info==null){Thread.sleep(400L);continue;}
                    Data progress=info.getProgress();
                    final int imported=progress.getInt(AudioLibraryImportWorker.KEY_IMPORTED,0),skipped=progress.getInt(AudioLibraryImportWorker.KEY_SKIPPED,0),failed=progress.getInt(AudioLibraryImportWorker.KEY_FAILED,0);
                    final String current=progress.getString("current");
                    ui.post(new Runnable(){public void run(){if(monitorId.equals(monitoredAudioWorkId))setStatus("Áudio: "+imported+" copiados • "+skipped+" ignorados • "+failed+" falhas"+(current==null?"":" • "+current));}});
                    if(info.getState().isFinished()){
                        if(info.getState()==WorkInfo.State.SUCCEEDED){
                            if(!monitorId.equals(prefs.getString("audio_import_applied_work_id",""))){
                                int wait=0;while((smartAudio==null||!audioEngineReady)&&wait<80){Thread.sleep(250L);wait++;}
                                if(smartAudio==null)throw new IllegalStateException("O catálogo terminou de importar, mas o motor de áudio ainda não iniciou.");
                                final int count=smartAudio.reloadAfterInternalImport();
                                prefs.edit().putInt("last_audio_scan_count",count).putString("audio_import_applied_work_id",monitorId).commit();
                                if(libraryConnections!=null)libraryConnections.recordSyncSuccess(LibraryConnectionManager.AUDIO,count,0,0,0);
                                ui.post(new Runnable(){public void run(){if(!isFinishing()){toast(count+" sons importados para o armazenamento interno.");setStatus("Biblioteca de áudio V3 pronta. SoundPool e rotação foram reconstruídos.");if("Áudio".equals(currentScreen))showAudio();}}});
                            }
                        }else if(info.getState()!=WorkInfo.State.CANCELLED||monitorId.equals(monitoredAudioWorkId)){
                            String error=info.getOutputData().getString("error");if(error==null||error.trim().isEmpty())error="Importação interrompida.";
                            if(libraryConnections!=null)libraryConnections.recordSyncFailure(LibraryConnectionManager.AUDIO,error);
                            final String shown=error;ui.post(new Runnable(){public void run(){if(!isFinishing()){toast("Áudio: "+shown);setStatus("Falha ao importar a biblioteca; campanha e demais bibliotecas foram preservadas.");}}});
                        }
                        if(monitorId.equals(monitoredAudioWorkId))monitoredAudioWorkId="";
                        break;
                    }
                    Thread.sleep(500L);
                }
            }catch(final Throwable error){
                if(monitorId.equals(monitoredAudioWorkId))monitoredAudioWorkId="";
                if(libraryConnections!=null)libraryConnections.recordSyncFailure(LibraryConnectionManager.AUDIO,String.valueOf(error.getMessage()));
                ui.post(new Runnable(){public void run(){if(!isFinishing())setStatus("Falha ao acompanhar a importação de áudio: "+String.valueOf(error.getMessage()));}});
            }
        }});
    }

    private String libraryConnectionSummary(boolean deep){
        if(libraryConnections==null)return "Gerenciador de pastas ainda não iniciado.";
        JSONArray statuses=libraryConnections.allStatuses(deep);StringBuilder out=new StringBuilder();
        for(int i=0;i<statuses.length();i++){JSONObject status=statuses.optJSONObject(i);if(status==null)continue;if(out.length()>0)out.append('\n');out.append(status.optBoolean("healthy",false)?"✓ ":"⚠ ").append(status.optString("label")).append(": ").append(libraryConnections.humanStatus(status));int count=status.optInt("last_count",0);if(count>0)out.append(" • ").append(count).append(" itens");}
        return out.toString();
    }

