    private String npcCognitionJson(JSONObject state){try{JSONObject out=new JSONObject();if(state!=null)for(String key:new String[]{"emotion","trust","fear","suspicion","urgency","next_action","schedule_json","beliefs_json","goals_json","personality_json","knowledge_json","resources_json","recent_events_json","faction","current_location","last_interaction_summary"})if(state.has(key)){Object value=state.opt(key);if(key.endsWith("_json")&&value instanceof String){String raw=String.valueOf(value);value=raw.trim().startsWith("{")?new JSONObject(raw):new JSONArray(raw);}out.put(key,value);}return out.toString(2);}catch(Exception error){return "{}";}}
    private JSONObject parseNpcCognition(String name,String raw)throws Exception{JSONObject source=new JSONObject(raw==null||raw.trim().length()==0?"{}":raw),out=new JSONObject().put("name",name);for(String key:new String[]{"schedule_json","beliefs_json","goals_json","knowledge_json","recent_events_json"}){Object value=source.opt(key);if(value!=null){if(!(value instanceof JSONArray))throw new Exception(key+" deve ser array JSON");out.put(key,value.toString());}}for(String key:new String[]{"personality_json","resources_json"}){Object value=source.opt(key);if(value!=null){if(!(value instanceof JSONObject))throw new Exception(key+" deve ser objeto JSON");out.put(key,value.toString());}}for(String key:new String[]{"emotion","next_action","faction","current_location","last_interaction_summary"})if(source.has(key))out.put(key,source.optString(key));for(String key:new String[]{"trust","fear","suspicion","urgency"})if(source.has(key))out.put(key,source.optInt(key));return out;}

    private void assignMissingNpcTokensAsync(final boolean showReport){
        if(npcTokenAutoBinder==null)return;setStatus("Procurando tokens compatíveis na pasta npc…");AppExecutors.io().execute(new Runnable(){public void run(){final NpcTokenAutoBinder.Result result=npcTokenAutoBinder.assignMissingTokens();ui.post(new Runnable(){public void run(){setStatus(result.assigned.size()+" token(s) de NPC vinculados automaticamente; os manuais foram preservados.");if(showReport)new AlertDialog.Builder(MainActivity.this).setTitle("Tokens automáticos de NPC").setMessage(result.summary()).setPositiveButton("Fechar",null).show();if("Mestre IA".equals(currentScreen))showNarrator();else if("Combate".equals(currentScreen))showCombat();}});}});
    }

    private void setPendingPortraitTarget(String type,long id,String stable,String name){
        if(prefs==null)return;SharedPreferences.Editor e=prefs.edit()
            .putString("pending_image_target_type",type==null?"":type)
            .putLong("pending_image_target_id",id)
            .putString("pending_image_target_stable_id",stable==null?"":stable)
            .putString("pending_image_target_name",name==null?"":name);
        if("NPC".equals(type))e.putLong("pending_npc_portrait_id",id).putString("pending_npc_portrait_stable_id",stable==null?"":stable).putString("pending_npc_portrait_name",name==null?"":name);
        else e.remove("pending_npc_portrait_id").remove("pending_npc_portrait_stable_id").remove("pending_npc_portrait_name");
        e.apply();
    }
    private String circularTokenPortraitRules(){
        return "FORMATO OBRIGATÓRIO: retrato quadrado 1:1 para TOKEN CIRCULAR de VTT; enquadramento EXCLUSIVAMENTE dos ombros para cima; rosto centralizado; cabeça inteira visível; cabelo, orelhas, chifres, capuz ou elmo totalmente dentro do quadro; margem de segurança generosa em todos os lados; olhos próximos ao centro; todos os traços importantes dentro dos 70% centrais para sobreviver ao recorte redondo. Fundo simples, discreto e de baixo contraste. Sem texto, nome, moldura, ficha, corpo inteiro, pose aberta ou cenário dominante. Não cortar topo da cabeça, queixo ou ombros. Equipamentos/armas só podem aparecer parcialmente se couberem naturalmente no enquadramento sem empurrar o rosto para fora do centro.";
    }
    private void sharePortraitPromptWithGemini(String prompt,String name){
        Intent share=new Intent(Intent.ACTION_SEND);share.setType("text/plain");share.putExtra(Intent.EXTRA_TEXT,prompt);share.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
        try{Intent direct=new Intent(share);direct.setPackage("com.google.android.apps.bard");startActivity(direct);}catch(Exception noGemini){startActivity(Intent.createChooser(share,"Gerar retrato de "+name));}
    }
    private void beginHeroPortrait(JSONObject entry){
        try{
            String name=entry==null?"":entry.optString("name","").trim();if(name.length()==0)return;
            JSONObject hero=db.findCharacterByName(name);if(hero.length()==0){toast("Herói não encontrado na ficha persistente.");return;}
            long id=hero.optLong("id",0);if(id<=0){toast("Identidade persistente do herói inválida.");return;}
            JSONObject sheet;try{sheet=new JSONObject(hero.optString("sheet_json","{}"));}catch(Exception e){sheet=new JSONObject();}
            String species=hero.optString("species",sheet.optString("species",sheet.optString("race",""))).trim();
            String cls=hero.optString("class_name",sheet.optString("class_name",sheet.optString("class",""))).trim();
            String subclass=sheet.optString("subclass_name",sheet.optString("subclass","")).trim();
            String background=hero.optString("background",sheet.optString("background_name",sheet.optString("background",""))).trim();
            String visual=hero.optString("visual_description",sheet.optString("appearance",sheet.optString("visual_description",""))).trim();
            String gender=sheet.optString("gender",sheet.optString("sex","")).trim();
            String age=sheet.optString("age",sheet.optString("age_range","")).trim();
            String equipment=hero.optString("equipment",sheet.optString("inventory",sheet.optString("equipment",""))).trim();
            setPendingPortraitTarget("HERO",id,String.valueOf(id),name);
            StringBuilder p=new StringBuilder();p.append("Crie o retrato CANÔNICO deste herói de D&D para uso como token no Braseiro VTT. Preserve a mesma identidade em futuras imagens. ").append(circularTokenPortraitRules()).append("\n\n");
            p.append("HERÓI: ").append(name).append(".\n");if(species.length()>0)p.append("Espécie/raça: ").append(species).append(".\n");if(cls.length()>0)p.append("Classe: ").append(cls).append(".\n");if(subclass.length()>0)p.append("Subclasse: ").append(subclass).append(".\n");if(hero.optInt("level",0)>0)p.append("Nível: ").append(hero.optInt("level")).append(".\n");if(background.length()>0)p.append("Antecedente: ").append(background).append(".\n");if(gender.length()>0)p.append("Sexo/gênero definido na ficha: ").append(gender).append(".\n");if(age.length()>0)p.append("Idade/faixa: ").append(age).append(".\n");if(visual.length()>0)p.append("Aparência canônica: ").append(visual).append(".\n");if(equipment.length()>0)p.append("Equipamento visual relevante: ").append(equipment).append(".\n");
            p.append("Priorize rosto, espécie, classe, aparência, cabelo/barba, olhos, pele/pelagem/escamas, roupas/armadura, marcas e expressão já definidas. Não invente mudança de raça, classe ou aparência que contradiga a ficha.");
            sharePortraitPromptWithGemini(p.toString(),name);setStatus("Prompt de retrato do herói enviado ao Gemini para "+name+". Compartilhe a imagem de volta ao Braseiro.");
        }catch(Exception e){AppLog.e("HeroPortrait","Falha ao preparar retrato persistente do herói.",e);toast("Retrato do herói: "+e.getMessage());}
    }
    private void beginNpcPortrait(JSONObject entry){
        try{
            String name=entry==null?"":entry.optString("name","").trim();if(name.length()==0)return;
            JSONObject npc=db.findNpcMemoryByName(name);
            if(npc.length()==0){db.upsertNpcMemory(new JSONObject().put("name",name).put("stable_id",NpcIdentityNormalizer.stableId(activeWorldProfile(),name)).put("visual_description",entry.optString("hint","")).put("active",1));npc=db.findNpcMemoryByName(name);}
            if(npc.length()==0){toast("Não foi possível criar a identidade persistente deste NPC.");return;}
            JSONObject stats;try{stats=new JSONObject(npc.optString("stats_json","{}"));}catch(Exception e){stats=new JSONObject();}
            if(stats.optBoolean("dead",false)||"dead".equalsIgnoreCase(stats.optString("status"))||"morto".equalsIgnoreCase(stats.optString("status"))){toast(name+" está registrado como morto; o retrato não será recriado.");return;}
            long id=npc.optLong("id",0);String stable=npc.optString("stable_id",NpcIdentityNormalizer.stableId(activeWorldProfile(),name));
            setPendingPortraitTarget("NPC",id,stable,name);
            String species=stats.optString("species",stats.optString("race",stats.optString("creature_type",entry.optString("hint",""))));
            String visual=npc.optString("visual_description","").trim();String summary=npc.optString("summary","").trim();
            StringBuilder p=new StringBuilder();p.append("Crie o retrato CANÔNICO deste NPC de D&D para uso como token no Braseiro VTT. Identidade única e persistente; não crie uma pessoa diferente. ").append(circularTokenPortraitRules()).append("\n\n");
            p.append("NPC: ").append(name).append(".\n");if(species.length()>0)p.append("Espécie/raça/tipo: ").append(species).append(".\n");if(visual.length()>0)p.append("Aparência canônica: ").append(visual).append(".\n");if(summary.length()>0)p.append("Papel/contexto visual: ").append(summary).append(".\n");if(npc.optString("attitude").length()>0)p.append("Postura/atitude visível: ").append(npc.optString("attitude")).append(".\n");p.append("Mantenha idade aparente, traços, pele/pelagem/escamas, cabelo, barba, olhos, roupas, equipamento e marcas distintivas consistentes em qualquer futura imagem deste mesmo NPC.");
            sharePortraitPromptWithGemini(p.toString(),name);setStatus("Prompt de retrato enviado ao Gemini para "+name+". Compartilhe a imagem de volta ao Braseiro.");
        }catch(Exception e){AppLog.e("NpcPortrait","Falha ao preparar retrato persistente.",e);toast("Retrato do NPC: "+e.getMessage());}
    }

    private void beginMonsterPortrait(JSONObject combatant){
        try{
            final String name=combatant.optString("name","").trim();
            final long id=combatant.optLong("id",combatant.optLong("combatant_id",0));
            if(name.length()==0||id<=0){toast("Identidade do combatente inválida.");return;}
            setPendingPortraitTarget("COMBATANT",id,String.valueOf(id),name);

            String clean=name.replaceFirst("\\s+(?:#?\\d+|[IVX]+)$","").trim();
            clean=clean.replaceFirst("\\s*\\((?:\\d+|[A-Za-z])\\)$","").trim();
            JSONObject stats=null;
            if(CompiledStatblockEngine.has(clean)){stats=CompiledStatblockEngine.get(clean);}
            else if(CompiledStatblockEngine.has(name)){stats=CompiledStatblockEngine.get(name);}
            JSONObject res=null;
            try{res=new JSONObject(combatant.optString("resources_json","{}"));}catch(Exception ignored){}
            if(stats==null&&res!=null&&res.has("block_id")&&CompiledStatblockEngine.has(res.optString("block_id"))){
                stats=CompiledStatblockEngine.get(res.optString("block_id"));
            }

            StringBuilder p=new StringBuilder();
            p.append("Crie o retrato CANÔNICO desta criatura/monstro de D&D para uso como token circular no Braseiro VTT. ").append(circularTokenPortraitRules()).append("\n\n");
            p.append("CRIATURA/MONSTRO: ").append(name).append(".\n");
            if(stats!=null){
                String type=stats.optString("type",stats.optString("creature_type",""));
                String size=stats.optString("size","");
                String alignment=stats.optString("alignment","");
                if(size.length()>0)p.append("Tamanho: ").append(size).append(".\n");
                if(type.length()>0)p.append("Tipo de criatura: ").append(type).append(".\n");
                if(alignment.length()>0)p.append("Tendência: ").append(alignment).append(".\n");
                if(stats.optInt("ac",0)>0)p.append("Classe de Armadura: ").append(stats.optInt("ac")).append(" (").append(stats.optString("ac_type","natural/armadura")).append(").\n");
                String desc=stats.optString("description",stats.optString("visual_description",""));
                if(desc.length()>0)p.append("Aparência canônica: ").append(desc).append(".\n");
                String traits=stats.optString("traits","");
                if(traits.length()>0)p.append("Traços físicos visíveis: ").append(traits).append(".\n");
            }else{
                p.append("Aparência: Monstro/criatura de D&D 5e em combate. Considere traços fiéis à sua espécie e tipo no D&D.\n");
            }
            p.append("Enquadramento rigorosamente no formato de busto dos ombros para cima, focado na cabeça/rosto da criatura, adequado para exibição em círculo de token de mapa tático.");
            sharePortraitPromptWithGemini(p.toString(),name);
            setStatus("Prompt de retrato de "+name+" enviado ao Gemini. Ao receber a imagem, compartilhe-a de volta com o Braseiro.");
        }catch(Exception e){AppLog.e("MonsterPortrait","Falha ao preparar retrato do monstro.",e);toast("Retrato do monstro: "+e.getMessage());}
    }

    private void beginPortraitForCombatant(JSONObject combatant){
        try{
            if(combatant==null||combatant.length()==0){toast("Combatente inválido.");return;}
            final String name=combatant.optString("name","").trim();
            if(name.length()==0)return;
            final boolean player=combatant.optInt("is_player",0)==1;
            final long id=combatant.optLong("id",combatant.optLong("combatant_id",0));
            if(player){
                JSONObject heroEntry=new JSONObject().put("name",name).put("id",id);
                beginHeroPortrait(heroEntry);
                return;
            }
            JSONObject npc=db.findNpcMemoryByName(name);
            if(npc.length()>0){
                JSONObject npcEntry=new JSONObject().put("name",name).put("id",npc.optLong("id",id));
                beginNpcPortrait(npcEntry);
                return;
            }
            beginMonsterPortrait(combatant);
        }catch(Exception e){AppLog.e("Portrait","Falha ao gerar retrato para combatente",e);toast("Retrato: "+e.getMessage());}
    }

    private void showTokenQuickActionsDialog(final long combatantId,final String name){
        final JSONObject combatant=db.getCombatant(combatantId);
        final String displayName=(combatant!=null&&combatant.optString("name").length()>0)?combatant.optString("name"):name;
        AlertDialog.Builder b=new AlertDialog.Builder(this);
        b.setTitle("Token: "+displayName);
        String[] options=new String[]{
            "✦ Gerar Retrato Canônico no Gemini (Ombros para Cima)",
            "Consultar Ficha / Status",
            "Mover no Tabuleiro Tático"
        };
        b.setItems(options,new DialogInterface.OnClickListener(){
            public void onClick(DialogInterface dialog,int which){
                if(which==0){
                    JSONObject target=combatant;
                    if(target==null||target.length()==0){
                        target=new JSONObject();
                        try{target.put("id",combatantId).put("name",name);}catch(Exception ignored){}
                    }
                    beginPortraitForCombatant(target);
                }else if(which==1){
                    if(combatant!=null&&combatant.length()>0)combatantInfoDialog(combatant);
                    else{
                        JSONObject c=db.findCombatantByName(name);
                        if(c.length()>0)combatantInfoDialog(c);
                        else toast("Combatente não encontrado.");
                    }
                }else{
                    toast("Toque na casa de destino para traçar a rota.");
                }
            }
        });
        b.setNegativeButton("Fechar",null);
        b.show();
    }

    private boolean hasPendingPortraitTarget(){
        if(prefs==null)return false;String type=prefs.getString("pending_image_target_type","");long id=prefs.getLong("pending_image_target_id",0);
        if(id>0&&("HERO".equals(type)||"NPC".equals(type)||"COMBATANT".equals(type)||"MONSTER".equals(type)))return true;
        return prefs.getLong("pending_npc_portrait_id",0)>0;
    }
    private void clearPendingPortraitTarget(){if(prefs!=null)prefs.edit().remove("pending_image_target_type").remove("pending_image_target_id").remove("pending_image_target_stable_id").remove("pending_image_target_name").remove("pending_npc_portrait_id").remove("pending_npc_portrait_stable_id").remove("pending_npc_portrait_name").apply();}
    private Uri storeHeroAvatar(Uri source,long characterId){try{return ImageStorageManager.importImage(this,source,"character_avatars","hero_"+characterId,80);}catch(Exception e){AppLog.e("ImageImport","Falha ao armazenar avatar do herói "+characterId,e);return null;}}
    private Uri storeCombatantAvatar(Uri source,long combatantId){try{return ImageStorageManager.importImage(this,source,"combatant_avatars","combatant_"+combatantId,80);}catch(Exception e){AppLog.e("ImageImport","Falha ao armazenar avatar do combatente "+combatantId,e);return null;}}
    private void importReceivedPortraitAsync(final Uri source){
        String type=prefs.getString("pending_image_target_type","");long genericId=prefs.getLong("pending_image_target_id",0);
        if((type==null||type.length()==0||genericId<=0)&&prefs.getLong("pending_npc_portrait_id",0)>0){type="NPC";genericId=prefs.getLong("pending_npc_portrait_id",0);}
        final String targetType=type;final long id=genericId;final String expectedStable=prefs.getString("pending_image_target_stable_id",prefs.getString("pending_npc_portrait_stable_id",""));final String name=prefs.getString("pending_image_target_name",prefs.getString("pending_npc_portrait_name","personagem"));
        if(id<=0||(!"HERO".equals(targetType)&&!"NPC".equals(targetType)&&!"COMBATANT".equals(targetType)&&!"MONSTER".equals(targetType))){clearPendingPortraitTarget();return;}
        setStatus("Salvando retrato persistente de "+name+"…");
        AppExecutors.io().execute(new Runnable(){public void run(){String failure="";Uri stored=null;try{
            if("HERO".equals(targetType)){
                JSONObject hero=db.getCharacter(id);if(hero.length()==0)throw new Exception("A ficha do herói não existe mais.");
                stored=storeHeroAvatar(source,id);if(stored==null)throw new Exception("A imagem do herói não pôde ser armazenada.");
                db.setCharacterToken(id,stored.toString());
                db.setCombatantVisualIdentity(id,"character",id,stored.toString());
            }else if("COMBATANT".equals(targetType)||"MONSTER".equals(targetType)){
                stored=storeCombatantAvatar(source,id);if(stored==null)throw new Exception("A imagem do combatente não pôde ser armazenada.");
                db.setCombatantVisualIdentity(id,"combatant",id,stored.toString());
                try{ContentValues cv=new ContentValues();cv.put("token_uri",stored.toString());db.getWritableDatabase().update("tactical_tokens",cv,"combatant_id=? AND world_profile=?",new String[]{String.valueOf(id),db.getActiveMapProfile()});}catch(Exception ignored){}
            }else{
                JSONObject npc=db.getNpcMemory(id);JSONObject stats;try{stats=new JSONObject(npc.optString("stats_json","{}"));}catch(Exception parse){stats=new JSONObject();}
                boolean dead=stats.optBoolean("dead",false)||"dead".equalsIgnoreCase(stats.optString("status"))||"morto".equalsIgnoreCase(stats.optString("status"));
                PersistentPortraitImportPolicy.Result admission=PersistentPortraitImportPolicy.validate("NPC",id,expectedStable,npc.optString("stable_id"),npc.length()>0&&npc.optInt("active",1)!=0,dead);
                if(!admission.accepted)throw new Exception(admission.message);
                stored=storeNpcAvatar(source,id);if(stored==null)throw new Exception("A imagem do NPC não pôde ser armazenada.");
                db.setNpcToken(id,stored.toString());
                db.setCombatantVisualIdentity(id,"npc",id,stored.toString());
            }
        }catch(Exception e){failure=String.valueOf(e.getMessage());}final String error=failure;ui.post(new Runnable(){public void run(){
            if(error.length()>0){toast("Retrato: "+error);setStatus("Retrato não importado.");return;}
            try{db.addAuditEvent("retrato","Retrato persistente vinculado",name,"{}",new JSONObject().put("target_type",targetType).put("target_id",id).put("receipt","portrait:"+targetType+":"+id+":"+expectedStable).toString(),true);}catch(Exception audit){AppLog.w("PortraitImport","Retrato salvo, mas o recibo de auditoria não pôde ser gravado.",audit);}
            clearPendingPortraitTarget();screenCache.remove("Mestre IA");screenCache.remove("Combate");
            synchronizeVisualSceneCast();
            if(tacticalBoardView!=null)tacticalBoardView.refresh();
            toast("Retrato de "+name+" salvo e aplicado ao token!");
            setStatus("Retrato persistente de "+name+" atualizado.");
            if("Mestre IA".equals(currentScreen))showNarrator();
            else if("Combate".equals(currentScreen))showCombat();
            else if(isStrixhavenAdventure())showStrixhavenSession();
        }});}});
    }

    private Uri storeNpcAvatar(Uri source,long npcId){try{return ImageStorageManager.importImage(this,source,"npc_avatars","npc_"+npcId,80);}catch(Exception e){AppLog.e("ImageImport","Falha ao armazenar avatar do NPC "+npcId,e);return null;}}


    private void editSceneStateDialog(final JSONObject scene){
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));final EditText location=labeledField(form,"Local",scene.optString("location"),false),hex=labeledField(form,"Hex",scene.optString("hex_id"),false),time=labeledField(form,"Horário",scene.optString("time_of_day"),false),weather=labeledField(form,"Clima",scene.optString("weather"),false),lighting=labeledField(form,"Iluminação",scene.optString("lighting"),false),danger=labeledField(form,"Perigo",scene.optString("danger"),false),objective=labeledField(form,"Objetivo",scene.optString("objective"),true),clues=labeledField(form,"Pistas em JSON",scene.optString("clues_json","[]"),true),pending=labeledField(form,"Consequências em JSON",scene.optString("pending_consequences_json","[]"),true);ScrollView scroll=new ScrollView(this);scroll.addView(form);
        new AlertDialog.Builder(this).setTitle("Editar estado persistente").setView(scroll).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{safety.beforeDestructiveChange("editar estado da cena");JSONObject next=new JSONObject(scene.toString()).put("location",value(location)).put("hex_id",value(hex)).put("time_of_day",value(time)).put("weather",value(weather)).put("lighting",value(lighting)).put("danger",value(danger)).put("objective",value(objective)).put("clues",new JSONArray(value(clues).length()==0?"[]":value(clues))).put("pending_consequences",new JSONArray(value(pending).length()==0?"[]":value(pending)));db.saveSceneState(next);db.addAuditEvent("cena","Estado editado pelo Mestre",value(location),scene.toString(),next.toString(),true);toast("Estado da cena atualizado.");}catch(Exception e){toast("Estado da cena: "+e.getMessage());}}}).show();
    }

