    private void handleIncomingIntent(Intent intent){
        String action=intent==null?"":intent.getAction();
        if(PendingImageImportStore.ACTION_CONSUME.equals(action)){
            String token=intent.getStringExtra(PendingImageImportStore.EXTRA_TOKEN);
            String error=intent.getStringExtra(PendingImageImportStore.EXTRA_ERROR);
            consumeIncomingIntent(intent);
            if(error!=null&&error.trim().length()>0){setStatus("A imagem recebida não foi importada.");toast(error);return;}
            Uri stored=PendingImageImportStore.claim(this,token);
            if(stored!=null){if(hasPendingPortraitTarget()){importReceivedPortraitAsync(stored);return;}applyReceivedSceneImage(stored);return;}
        }
        // Recupera uma cópia que tenha sido concluída antes de o processo ou a
        // Activity anterior serem encerrados.
        if(!Intent.ACTION_SEND.equals(action)){Uri recovered=PendingImageImportStore.claim(this,"");if(recovered!=null){if(hasPendingPortraitTarget()){importReceivedPortraitAsync(recovered);return;}applyReceivedSceneImage(recovered);return;}}
        if(intent==null)return;
        String type=intent.getType();if(!Intent.ACTION_SEND.equals(action)||type==null||!type.startsWith("image/"))return;
        final Uri source=incomingImageUri(intent);consumeIncomingIntent(intent);if(source==null)return;
        SceneImageImportPolicy.Result admission=SceneImageImportPolicy.validate(action,type,true,prefs.getString(PREF_PENDING_IMAGE_FINGERPRINT,""),currentSceneVisualFingerprint());
        if(!admission.accepted){setStatus("A imagem recebida não foi importada.");toast(admission.message);return;}
        if(hasPendingPortraitTarget()){importReceivedPortraitAsync(source);return;}
        // Compatibilidade com remetentes que contornam a Activity dedicada.
        setStatus("Validando e salvando a imagem recebida…");AppExecutors.io().execute(new Runnable(){public void run(){try{final Uri stored=ImageStorageManager.importImage(MainActivity.this,source,"scene_images","shared_scene",12);ui.post(new Runnable(){public void run(){applyReceivedSceneImage(stored);}});}catch(final Exception e){AppLog.e("ImageImport","Imagem compartilhada rejeitada.",e);ui.post(new Runnable(){public void run(){setStatus("A imagem recebida não foi importada.");toast(e.getMessage()==null?"Imagem inválida.":e.getMessage());}});}}});
    }
    private Uri incomingImageUri(Intent intent){if(intent==null)return null;Uri source=null;if(Build.VERSION.SDK_INT>=33)source=intent.getParcelableExtra(Intent.EXTRA_STREAM,Uri.class);else source=(Uri)intent.getParcelableExtra(Intent.EXTRA_STREAM);if(source==null&&intent.getClipData()!=null&&intent.getClipData().getItemCount()>0)source=intent.getClipData().getItemAt(0).getUri();return source;}
    private void consumeIncomingIntent(Intent intent){if(intent!=null){intent.setAction(null);intent.removeExtra(Intent.EXTRA_STREAM);intent.removeExtra(PendingImageImportStore.EXTRA_TOKEN);intent.removeExtra(PendingImageImportStore.EXTRA_ERROR);intent.setClipData(null);}setIntent(new Intent(this,MainActivity.class));}
    private void applyReceivedSceneImage(Uri stored){if(stored==null||!ImageStorageManager.isReadable(this,stored)){setStatus("A cópia recebida não está mais disponível.");return;}String current=currentSceneVisualFingerprint(),pending=prefs.getString(PREF_PENDING_IMAGE_FINGERPRINT,"");if(pending.length()>0&&!pending.equals(current)){setStatus("A imagem recebida pertence a uma cena anterior e não foi vinculada.");toast("A cena mudou depois que o Gemini foi aberto. Gere ou compartilhe novamente a imagem atual.");prefs.edit().remove(PREF_PENDING_IMAGE_FINGERPRINT).apply();return;}sharedImageUri=stored;prefs.edit().putString(PREF_SCENE_IMAGE_URI,stored.toString()).putString(PREF_SCENE_IMAGE_FINGERPRINT,current).putInt("scene_image_aspect_w",16).putInt("scene_image_aspect_h",9).remove("scene_image_fill").remove(PREF_PENDING_IMAGE_FINGERPRINT).apply();try{db.addAuditEvent("imagem","Imagem de cena vinculada","Importação validada; proporção 16:9; fingerprint="+current,"{}",new JSONObject().put("uri",stored.toString()).put("fingerprint",current).put("receipt","scene-image:"+current).toString(),true);}catch(Exception audit){AppLog.w("SceneImage","Imagem salva, mas o recibo de auditoria não pôde ser gravado.",audit);}if(isStrixhavenAdventure()){screenCache.remove("Mestre IA");showStrixhavenSession();}else{navigate("Mestre IA");}displaySceneImage(stored);setStatus("Imagem recebida, validada, salva e vinculada à cena atual.");toast("Imagem adicionada à cena atual.");}
    private void addSceneImageCard(LinearLayout parent){
        final LinearLayout imageCard=card();
        LinearLayout header=new LinearLayout(this);header.setOrientation(LinearLayout.HORIZONTAL);header.setGravity(Gravity.CENTER_VERTICAL);
        header.addView(text("IMAGEM DA CENA",13,GOLD,true),new LinearLayout.LayoutParams(0,-2,1));
        if(sharedImageUri!=null){
            Button open=smallButton("ABRIR",PANEL2);open.setTextSize(9);open.setContentDescription("Abrir a imagem panorâmica da cena em tela cheia");open.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showSceneImageFullscreen();}});
            header.addView(open,new LinearLayout.LayoutParams(dp(72),dp(40)));
        }
        imageCard.addView(header);
        sceneImage=new ImageView(this);sceneImage.setAdjustViewBounds(false);sceneImage.setBackground(makeBg(PANEL2,CARD_STROKE,12));sceneImage.setClipToOutline(true);sceneImage.setContentDescription("Imagem panorâmica 16 por 9 da cena atual. Toque para abrir em tela cheia.");applySceneImageScale();
        sceneImage.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(sharedImageUri!=null)showSceneImageFullscreen();}});
        if(sharedImageUri!=null){displaySceneImage(sharedImageUri);imageCard.addView(sceneImage,sceneImagePreviewLayoutParams());}
        else{sceneImage.setImageBitmap(null);imageCard.addView(sceneImage,new LinearLayout.LayoutParams(-1,dp(130)));}
        if(sharedImageUri==null){TextView no=text("Gere a cena pelo Gemini em proporção panorâmica 16:9 usando somente o prompt visual limpo.",13,MUTED,false);no.setGravity(Gravity.CENTER);imageCard.addView(no);}
        else{TextView caption=text("Imagem 16:9 recebida, salva e vinculada a esta cena. Toque para visualizar em tela cheia.",11,MUTED,false);caption.setGravity(Gravity.CENTER_HORIZONTAL);imageCard.addView(caption);}
        parent.addView(imageCard);
    }

    private LinearLayout.LayoutParams sceneImagePreviewLayoutParams(){
        int viewport=getResources().getDisplayMetrics().widthPixels;
        int available=Math.max(dp(180),viewport-dp(64));
        int width=SceneImageLayoutPolicy.previewWidth(available,available,dp(180));
        int height=SceneImageLayoutPolicy.heightForWidth(width);
        LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(width,height);
        params.gravity=Gravity.CENTER_HORIZONTAL;params.topMargin=dp(6);params.bottomMargin=dp(6);
        return params;
    }

    private void applySceneImageScale(){if(sceneImage!=null)sceneImage.setScaleType(ImageView.ScaleType.CENTER_CROP);}

    private void showSceneImageFullscreen(){
        if(sharedImageUri==null){toast("Nenhuma imagem vinculada à cena.");return;}
        try{
            final ImageView full=new ImageView(this);full.setBackgroundColor(Color.BLACK);full.setScaleType(ImageView.ScaleType.FIT_CENTER);full.setAdjustViewBounds(true);full.setImageBitmap(ImageStorageManager.decodeSampled(this,sharedImageUri,2048,2048));full.setPadding(dp(4),dp(4),dp(4),dp(4));
            final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Imagem completa da cena").setView(full).setNegativeButton("Fechar",null).setNeutralButton("Alternar enquadramento",null).create();
            dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){Window w=dialog.getWindow();if(w!=null)w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT);dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(new View.OnClickListener(){public void onClick(View v){full.setScaleType(full.getScaleType()==ImageView.ScaleType.FIT_CENTER?ImageView.ScaleType.CENTER_CROP:ImageView.ScaleType.FIT_CENTER);}});}});dialog.show();
        }catch(Throwable error){AppLog.e("SceneImage","Falha ao abrir a imagem completa.",error);toast("Não foi possível abrir a imagem completa.");}
    }

    private void displaySceneImage(final Uri uri){if(sceneImage==null||uri==null)return;final long generation=++sceneImageDecodeGeneration;AppExecutors.io().execute(new Runnable(){public void run(){try{final android.graphics.Bitmap bitmap=ImageStorageManager.decodeSampled(MainActivity.this,uri,1920,1080);ui.post(new Runnable(){public void run(){if(generation!=sceneImageDecodeGeneration||sceneImage==null){if(bitmap!=null)bitmap.recycle();return;}sceneImage.setImageBitmap(bitmap);applySceneImageScale();}});}catch(final Throwable e){AppLog.e("SceneImage","Falha ao exibir imagem da cena.",e);ui.post(new Runnable(){public void run(){if(generation!=sceneImageDecodeGeneration)return;try{if(sceneImage!=null)sceneImage.setImageDrawable(null);}catch(Throwable ignored){AppLog.ignored("SceneImage","Falha ao limpar imagem inválida.",ignored);}if(prefs!=null)clearSceneImageReference();sharedImageUri=null;}});}}});}

    private void openFile(String type,int req,boolean multiple){Intent x=new Intent(Intent.ACTION_OPEN_DOCUMENT);x.addCategory(Intent.CATEGORY_OPENABLE);x.setType(type);x.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,multiple);x.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(x,req);}
    private void persist(Uri uri,Intent data){try{int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getContentResolver().takePersistableUriPermission(uri,flags);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}}
    private void beginCharacterExport(JSONObject source,boolean active){try{JSONObject sheet=new JSONObject(source==null?"{}":source.toString());sheet.put("active",active);JSONObject envelope=new JSONObject();envelope.put("format","braseiro-character-sheet");envelope.put("format_version",2);envelope.put("app_version",APP_VERSION);envelope.put("rules_profile",sheet.optString("system",sheet.optString("rules_profile","")));envelope.put("language","pt-BR");envelope.put("exported_at",dateNow());envelope.put("character",sheet);pendingCharacterExport=envelope;String name=sheet.optString("name","heroi").trim();String safe=java.text.Normalizer.normalize(name,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").replaceAll("[^A-Za-z0-9_-]+","_").replaceAll("^_+|_+$","");if(safe.length()==0)safe="heroi";Intent x=new Intent(Intent.ACTION_CREATE_DOCUMENT);x.addCategory(Intent.CATEGORY_OPENABLE);x.setType("application/json");x.putExtra(Intent.EXTRA_TITLE,"Ficha_"+safe+".json");x.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION);startActivityForResult(x,REQ_EXPORT_CHARACTER);}catch(Exception e){pendingCharacterExport=new JSONObject();toast("Não foi possível preparar a ficha: "+e.getMessage());}}
