    public AdventureEngine getAdventureEngine(){if(adventureEngine==null&&masterOrchestrator!=null)adventureEngine=masterOrchestrator.getAdventureEngine();return adventureEngine;}
    public JSONObject installAdventureModule(com.braseiro.dnd5e.adventure.AdventureModule module){JSONObject out=new JSONObject();try{boolean ok=getAdventureEngine()!=null&&getAdventureEngine().installModule(module);out.put("installed",ok).put("auto_rolls",false);}catch(Exception ignored){}return out;}
    public void startOrResumeAdventure(String moduleId){if(getAdventureEngine()!=null){JSONObject r=getAdventureEngine().loadOrStart(moduleId);setStatus("success".equals(r.optString("status"))||"started".equals(r.optString("status"))||"resumed".equals(r.optString("status"))?"Aventura carregada: "+moduleId:"Aventura não carregada: "+r.optString("error","módulo não instalado"));JSONObject persisted=r.optJSONObject("state");if(persisted!=null){final JSONObject pending=persisted.optJSONObject("pending_manual_adjudication");if(pending!=null&&pending.length()>0)runOnUiThread(new Runnable(){@Override public void run(){showManualAdjudicationDialog(pending);}});}}}
    public JSONObject executeAdventureAction(String actionId,JSONObject params){
        final JSONObject result=getAdventureEngine()!=null?getAdventureEngine().processAction(actionId,params):new JSONObject();
        if("requires_manual_result".equals(result.optString("status"))){
            runOnUiThread(new Runnable(){@Override public void run(){showManualAdjudicationDialog(result.optJSONObject("pending"));}});
        }
        return result;
    }

    /** UI nativa mínima; resultado é gravado pelo AdventureEngine, nunca pelo diálogo. */
    /** Functional multiplayer-rule solo flow: Tome identity -> Gemini -> dice/adjudication
      * -> Loreweaver outcome -> SQLite AdventureState. Uses its own persistent party. */
    private AdventureEngine universalLiveEngine(){
        AdventureEngine engine=new AdventureEngine(db,masterOrchestrator,worldStateEngine);
        JSONObject opened=engine.loadOrStartAdventure(
            com.braseiro.dnd5e.adventure.UniversalLiveSession.module(),
            com.braseiro.dnd5e.adventure.UniversalLiveSession.PARTY_ID);
        if(engine.getActiveState()==null)throw new IllegalStateException("Mesa Universal não carregou: "+opened);
        return engine;
    }

    /** Resume any previously registered Tome entity; never overwrite a saved sheet. */
    private void showUniversalLiveSetup(){
        try{
            JSONObject current=universalLiveEngine().processUniversal(new JSONObject().put("action","status"))
                .optJSONObject("state");
            JSONObject pending=current==null?null:current.optJSONObject("pending");
            if(pending!=null&&pending.length()>0){
                showUniversalLiveScene(pending.optString("character_id"),pending.optString("system_id"));
                return;
            }
            JSONObject entities=current==null?null:current.optJSONObject("entities");
            final ArrayList<String> ids=new ArrayList<String>();
            final ArrayList<String> systems=new ArrayList<String>();
            final ArrayList<String> options=new ArrayList<String>();
            if(entities!=null){
                JSONArray keys=entities.names();
                for(int i=0;keys!=null&&i<keys.length();i++){
                    String id=keys.optString(i);JSONObject entity=entities.optJSONObject(id);
                    JSONObject meta=entity==null?null:entity.optJSONObject("meta");
                    JSONObject identity=entity==null?null:entity.optJSONObject("identity");
                    String profile=meta==null?"":meta.optString("system");
                    if(!com.braseiro.dnd5e.adventure.UniversalRpgEngine.supported(profile))continue;
                    ids.add(id);systems.add(profile);
                    JSONObject name=identity==null?null:identity.optJSONObject("name");
                    options.add((name==null?id:name.optString("primary",id))+" · "+profile);
                }
            }
            options.add("CRIAR OUTRO PERSONAGEM");
            new AlertDialog.Builder(this).setTitle("Mesa Universal · Escolha o personagem")
                .setItems(options.toArray(new String[0]),new DialogInterface.OnClickListener(){
                    public void onClick(DialogInterface d,int which){
                        if(which>=ids.size())showUniversalLiveCreateCharacter();
                        else showUniversalLiveScene(ids.get(which),systems.get(which));
                    }
                }).setNegativeButton("Cancelar",null).show();
        }catch(Exception e){toast("Mesa não disponível: "+safeMessage(e));}
    }

    private void showUniversalLiveCreateCharacter(){
        final Spinner system=spinner(new String[]{"Forbidden Lands / Year Zero","Star Wars narrativo","D&D 5e"},"Forbidden Lands / Year Zero");
        final EditText name=new EditText(this);name.setSingleLine(true);name.setHint("Nome do personagem");
        final EditText attributes=new EditText(this);attributes.setSingleLine(false);attributes.setText("{}");
        final EditText resources=new EditText(this);resources.setSingleLine(false);resources.setText("{}");
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);
        form.addView(text("Sistema de regras",13,GOLD,true));form.addView(system);
        form.addView(text("Personagem",13,GOLD,true));form.addView(name);
        form.addView(text("Atributos em JSON (sem dados inventados)",12,MUTED,false));form.addView(attributes);
        form.addView(text("Recursos em JSON; exemplo: {\"vida\":{\"current\":3,\"maximum\":5}}",12,MUTED,false));form.addView(resources);
        final ScrollView scroll=new ScrollView(this);scroll.addView(form);
        new AlertDialog.Builder(this).setTitle("Mesa Universal · Repositórios GitHub")
            .setView(scroll).setNegativeButton("Cancelar",null)
            .setPositiveButton("Entrar na mesa",new DialogInterface.OnClickListener(){
                @Override public void onClick(DialogInterface d,int which){
                    try{
                        int selected=system.getSelectedItemPosition();
                        String profile=selected==1?com.braseiro.dnd5e.adventure.UniversalRpgEngine.STAR_WARS:
                            selected==2?com.braseiro.dnd5e.adventure.UniversalRpgEngine.DND:
                            com.braseiro.dnd5e.adventure.UniversalRpgEngine.YZE;
                        String actor="live-"+java.util.UUID.randomUUID().toString();
                        AdventureEngine engine=universalLiveEngine();
                        JSONObject state=engine.processUniversal(new JSONObject().put("action","status")).optJSONObject("state");
                        JSONObject entities=state==null?null:state.optJSONObject("entities");
                        if(entities==null||entities.optJSONObject(actor)==null){
                            if(name.getText().toString().trim().isEmpty()){
                                toast("Informe o nome do personagem para iniciar.");return;
                            }
                            JSONObject created=engine.processUniversal(new JSONObject().put("action","register")
                                .put("character_id",actor).put("system_id",profile)
                                .put("name",name.getText().toString().trim())
                                .put("attributes",new JSONObject(attributes.getText().toString().trim()))
                                .put("resources",new JSONObject(resources.getText().toString().trim())));
                            if(!created.optBoolean("committed",false)){
                                toast("Ficha não registrada: "+created.optString("error"));return;
                            }
                        }
                        showUniversalLiveScene(actor,profile);
                    }catch(Exception e){toast("Não foi possível abrir a mesa: "+safeMessage(e));}
                }
            }).show();
    }

    private void showUniversalLiveScene(final String actor,final String profile){
        try{
            AdventureEngine engine=universalLiveEngine();
            JSONObject state=engine.processUniversal(new JSONObject().put("action","status")).optJSONObject("state");
            if(state==null){toast("A sessão não está acessível.");return;}
            JSONObject pending=state.optJSONObject("pending");
            if(pending!=null&&pending.length()>0){
                String pendingActor=pending.optString("character_id",actor);
                String pendingSystem=pending.optString("system_id",profile);
                showUniversalLiveCheck(pendingActor,pendingSystem,pending);return;
            }
            // Resume unapplied Gemini-suggested effects from the durable journal.
            // Never continue to a fresh scene without letting the player choose.
            JSONArray history=state.optJSONArray("history");
            for(int i=history==null?-1:history.length()-1;i>=0;i--){
                JSONObject receipt=history.optJSONObject(i);
                JSONArray proposal=receipt==null?null:receipt.optJSONArray("proposed_effects");
                if(receipt!=null && actor.equals(receipt.optString("character_id"))
                    && proposal!=null && proposal.length()>0
                    && !receipt.optBoolean("effects_applied",false)
                    && !receipt.optBoolean("effects_declined",false)){
                    showUniversalProposedEffects(actor,profile,receipt);return;
                }
            }
            JSONArray scenes=state.optJSONArray("scenes");
            String last="A mesa está pronta. Descreva a primeira ação.";
            if(scenes!=null&&scenes.length()>0){JSONObject tail=scenes.optJSONObject(scenes.length()-1);
                if(tail!=null)last=tail.optString("narration",last);}
            final EditText action=new EditText(this);action.setHint("O que seu personagem faz?");
            action.setSingleLine(false);action.setMinLines(2);
            LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);
            form.addView(text(last,14,TEXT,false));
            form.addView(text("Histórico salvo: "+(scenes==null?0:scenes.length())+" cena(s).",12,MUTED,false));
            form.addView(text("Tempo registrado: "+state.optInt("elapsed_minutes",0)+" minuto(s); "
                +"fatos confirmados: "+(state.optJSONArray("world_facts")==null?0:state.optJSONArray("world_facts").length()),
                12,MUTED,false));
            Button editEffects=button("ALTERAR FICHA · INVENTÁRIO · TEMPO · MUNDO",PANEL2);
            editEffects.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                showUniversalLiveEffects(actor,profile);
            }});
            form.addView(editEffects);
            form.addView(action);
            ScrollView scroll=new ScrollView(this);scroll.addView(form);
            new AlertDialog.Builder(this).setTitle("Braseiro Universal · "+profile)
                .setView(scroll).setNegativeButton("Voltar",null)
                .setNeutralButton("Ficha / estado",new DialogInterface.OnClickListener(){
                    public void onClick(DialogInterface d,int which){
                        try {
                            JSONObject fresh=universalLiveEngine().processUniversal(new JSONObject().put("action","status"));
                            new AlertDialog.Builder(MainActivity.this).setTitle("Estado persistido")
                                .setMessage(fresh.optJSONObject("state").toString(2))
                                .setPositiveButton("Fechar",null).show();
                        } catch (Exception e) { toast("Estado indisponível: "+safeMessage(e)); }
                    }
                })
                .setPositiveButton("Pedir cena ao Gemini",new DialogInterface.OnClickListener(){
                    public void onClick(DialogInterface d,int which){
                        String move=action.getText().toString().trim();
                        if(move.isEmpty()){toast("Descreva sua ação.");return;}
                        requestUniversalLiveNarration(actor,profile,move);
                    }
                }).show();
        }catch(Exception e){toast("Mesa não disponível: "+safeMessage(e));}
    }

    /** Player sees the AI proposal before any value changes. No implicit commit. */
    private void showUniversalProposedEffects(final String actor,final String profile,final JSONObject receipt){
        final JSONArray effects=receipt.optJSONArray("proposed_effects");
        if(effects==null||effects.length()==0){showUniversalLiveScene(actor,profile);return;}
        final String requestId=receipt.optString("request_id","");
        final String formattedEffects;
        try { formattedEffects=effects.toString(2); }
        catch (Exception e) { toast("Proposta indisponível: "+safeMessage(e)); return; }
        final String summary="Resultado: "+receipt.optString("consequence","")
            +"\n\nEfeitos sugeridos pelo Mestre (ainda NÃO aplicados):\n"
            +formattedEffects+"\n\nConfirme somente se esses valores estão corretos.";
        new AlertDialog.Builder(this).setTitle("Consequências · Aprovação do jogador")
            .setMessage(summary)
            .setPositiveButton("Aplicar",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
                try{
                    JSONObject state=universalLiveEngine().processUniversal(new JSONObject().put("action","status"))
                        .optJSONObject("state");
                    JSONObject entity=state==null?null:state.optJSONObject("entities").optJSONObject(actor);
                    if(entity==null){toast("Ficha não encontrada.");return;}
                    JSONObject approved=universalLiveEngine().processUniversal(new JSONObject()
                        .put("action","apply_effects")
                        .put("event_id","player."+java.util.UUID.randomUUID().toString())
                        .put("character_id",actor).put("request_id",requestId)
                        .put("expected_revision",entity.optInt("braseiro_revision",-1))
                        .put("effects",new JSONArray(effects.toString())));
                    if(!approved.optBoolean("committed",false)){
                        toast("Consequência recusada: "+approved.optString("error","alteração não confirmada"));
                        showUniversalProposedEffects(actor,profile,receipt);return;
                    }
                    setStatus("Consequências aplicadas e persistidas no Braseiro.");
                    showUniversalLiveScene(actor,profile);
                }catch(Exception e){toast("Não foi possível aplicar: "+safeMessage(e));}
            }})
            .setNegativeButton("Recusar",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
                try {
                    JSONObject declined=universalLiveEngine().processUniversal(new JSONObject()
                        .put("action","decline_effects").put("request_id",requestId)
                        .put("character_id",actor));
                    if(!declined.optBoolean("committed",false))toast("Recusa não gravada: "+declined.optString("error","erro"));
                    else{setStatus("Efeitos mecânicos recusados; decisão salva.");showUniversalLiveScene(actor,profile);}
                } catch (Exception e) { toast("Recusa não gravada: "+safeMessage(e)); }
            }})
            .setNeutralButton("Decidir depois",null).show();
    }

    /** Explicit player-authorized operations; Gemini narration cannot call this dialog. */
    private void showUniversalLiveEffects(final String actor,final String profile){
        try{
            JSONObject snapshot=universalLiveEngine().processUniversal(new JSONObject().put("action","status"))
                .optJSONObject("state");
            JSONObject entities=snapshot==null?null:snapshot.optJSONObject("entities");
            JSONObject hero=entities==null?null:entities.optJSONObject(actor);
            if(hero==null){toast("Ficha não encontrada.");return;}
            final int expectedRevision=hero.optInt("braseiro_revision",-1);
            final Spinner type=spinner(new String[]{"Recurso (somar ou subtrair)","Inventário (quantidade)",
                "Avançar tempo (minutos)","Registrar fato do mundo"},"Recurso (somar ou subtrair)");
            final EditText identifier=new EditText(this);identifier.setSingleLine(true);
            identifier.setHint("ID existente do recurso / ID do item ou fato");
            final EditText amount=new EditText(this);amount.setSingleLine(true);
            amount.setHint("Quantidade: -2, +1 ou minutos (1..1440)");
            amount.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);
            final EditText label=new EditText(this);label.setSingleLine(false);
            label.setHint("Nome do item novo / texto do fato do mundo");
            LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);
            form.addView(text("Escolha uma operação. Ela só será registrada após confirmação e validação.",13,TEXT,false));
            form.addView(type);form.addView(identifier);form.addView(amount);form.addView(label);
            form.addView(text("Ficha (leitura): "+hero.toString(),11,MUTED,false));
            ScrollView scroll=new ScrollView(this);scroll.addView(form);
            new AlertDialog.Builder(this).setTitle("Braseiro · Aplicar consequência")
                .setView(scroll).setNegativeButton("Cancelar",null)
                .setPositiveButton("Confirmar mudança",new DialogInterface.OnClickListener(){public void onClick(DialogInterface dialog,int which){
                    try{
                        int selected=type.getSelectedItemPosition();
                        String id=identifier.getText().toString().trim();
                        String value=amount.getText().toString().trim();
                        String textValue=label.getText().toString().trim();
                        JSONObject effect=new JSONObject();
                        if(selected==0)effect.put("kind","resource").put("key",id).put("delta",Integer.parseInt(value));
                        else if(selected==1)effect.put("kind","item").put("item_id",id)
                            .put("name",textValue).put("delta",Integer.parseInt(value));
                        else if(selected==2)effect.put("kind","time").put("minutes",Integer.parseInt(value));
                        else effect.put("kind","world_fact").put("fact_id",id).put("text",textValue);
                        JSONObject accepted=universalLiveEngine().processUniversal(new JSONObject()
                            .put("action","apply_effects").put("event_id","player."+java.util.UUID.randomUUID().toString())
                            .put("character_id",actor).put("expected_revision",expectedRevision)
                            .put("effects",new JSONArray().put(effect)));
                        if(!accepted.optBoolean("committed",false)){
                            toast("Alteração recusada: "+accepted.optString("error","sem confirmação"));return;
                        }
                        setStatus("Consequência confirmada e gravada na campanha.");
                        showUniversalLiveScene(actor,profile);
                    }catch(Exception e){toast("Nada foi alterado: "+safeMessage(e));}
                }}).show();
        }catch(Exception e){toast("Editor de estado indisponível: "+safeMessage(e));}
    }

    private void requestUniversalLiveNarration(final String actor,final String profile,final String playerMove){
        final String key=geminiKey().trim();
        if(key.length()<20){toast("Configure uma chave Gemini em Ajustes.");return;}
        if(aiQuotaGovernor!=null&&!aiQuotaGovernor.canCall()){
            toast("Limite de chamadas Gemini atingido. Estado anterior preservado.");return;
        }
        final JSONObject state;
        try {
            AdventureEngine engine=universalLiveEngine();
            state=engine.processUniversal(new JSONObject().put("action","status")).optJSONObject("state");
        } catch (Exception e) { toast("Cena não iniciada: "+safeMessage(e)); return; }
        final String prompt=com.braseiro.dnd5e.adventure.UniversalLiveSession.prompt(profile,actor,state,playerMove);
        final String system="BRAS_SINGLE_CALL. Responda em PT-BR. Siga rigorosamente o formato JSON solicitado; "
            +"nunca execute mudanças de ficha ou declare dados rolados pelo jogador.";
        setStatus("Mesa Universal: Gemini criando cena e proposta de teste...");
        gemini.generateText(key,prefs.getString("text_model","gemini-3.5-flash-lite"),system,prompt,
            new GeminiService.TextCallback(){
                public void onSuccess(final String response){ui.post(new Runnable(){public void run(){
                    try {
                    if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(system.length()+prompt.length(),response==null?0:response.length());
                    JSONObject accepted=universalLiveEngine().processUniversal(new JSONObject()
                        .put("action","accept_ai_scene").put("event_id","gemini."+java.util.UUID.randomUUID())
                        .put("character_id",actor).put("raw_response",response));
                    if(!accepted.optBoolean("committed",false)){
                        setStatus("Proposta do Gemini recusada. Campanha preservada.");
                        new AlertDialog.Builder(MainActivity.this).setTitle("Ação não confirmada")
                            .setMessage(accepted.optString("error","Formato do Gemini inválido."))
                            .setPositiveButton("OK",null).show();return;
                    }
                    setStatus("Cena salva no Braseiro e teste verificado pelos módulos GitHub.");
                    JSONObject pending=accepted.optJSONObject("pending");
                    if(pending!=null)showUniversalLiveCheck(actor,profile,pending);
                    else showUniversalLiveScene(actor,profile);
                    } catch (Exception e) {
                        setStatus("Resposta do Gemini não registrada.");
                        toast("Falha ao registrar cena: "+safeMessage(e));
                    }
                }});}
                public void onError(final String error){ui.post(new Runnable(){public void run(){
                    if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(system.length()+prompt.length(),0);
                    setStatus("Gemini falhou. A mesa e suas fichas foram preservadas.");
                    toast("Gemini: "+error);
                }});}
            });
    }

    private void showUniversalLiveCheck(final String actor,final String profile,final JSONObject pending){
        String detail="SITUAÇÃO: "+pending.optString("situation")
            +"\nSUCESSO: "+pending.optString("on_success")
            +"\nFRACASSO: "+pending.optString("on_failure")
            +"\nPOOL / CD: "+pending.optJSONObject("spec");
        new AlertDialog.Builder(this).setTitle("Teste · "+profile).setMessage(detail)
            .setItems(new String[]{"Informar SUCESSO","Informar FRACASSO","Informar dados em JSON","Decidir depois"},
                new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int selection){
                    if(selection==3)return;
                    if(selection==2){
                        final EditText dice=new EditText(MainActivity.this);
                        dice.setHint(profile.equals("dnd5e")?"{\"d20\":14}":
                            profile.equals("forbidden-lands")?"{\"dice\":{\"attribute\":[6,2],\"skill\":[3],\"gear\":[]}}":
                            "{\"dice\":[{\"die\":\"ability\",\"face\":4}]}");
                        new AlertDialog.Builder(MainActivity.this).setTitle("Dados resolvidos pelo jogador")
                            .setView(dice).setNegativeButton("Cancelar",null)
                            .setPositiveButton("Confirmar",new DialogInterface.OnClickListener(){public void onClick(DialogInterface dialog,int w){
                                try{confirmUniversalLiveCheck(actor,profile,pending,
                                    new JSONObject().put("mode","dice")
                                        .put("submission",new JSONObject(dice.getText().toString())));}
                                catch(Exception e){toast("JSON de dados inválido; resultado não salvo.");}
                            }}).show();
                    }else{
                        try {
                            confirmUniversalLiveCheck(actor,profile,pending,new JSONObject().put("mode","manual")
                                .put("outcome",selection==0?"success":"failure"));
                        } catch (Exception e) { toast("Resultado não salvo: "+safeMessage(e)); }
                    }
                }}).show();
    }

    private void confirmUniversalLiveCheck(String actor,String profile,JSONObject pending,JSONObject resolution){
        try{
            resolution.put("action","resolve_check").put("request_id",pending.optString("request_id"));
            JSONObject accepted=universalLiveEngine().processUniversal(resolution);
            if(!accepted.optBoolean("committed",false)){
                toast("Rolagem rejeitada: "+accepted.optString("error","dados não conferem"));return;
            }
            setStatus("Resultado confirmado e salvo; o Mestre seguirá a consequência na próxima ação.");
            showUniversalLiveScene(actor,profile);
        }catch(Exception e){toast("Resultado não salvo: "+safeMessage(e));}
    }

    private void showManualAdjudicationDialog(final JSONObject proposal){
        if(proposal==null)return;
        final String requestId=proposal.optString("request_id","");
        String message=proposal.optString("situation","")
          +(proposal.optString("check","").isEmpty()?"":"\n\nTeste: "+proposal.optString("check"))
          +"\n\nSUCESSO: "+proposal.optString("on_success","")
          +"\n\nFRACASSO: "+proposal.optString("on_failure","");
        new AlertDialog.Builder(this).setTitle("Resolver teste manual")
          .setMessage(message)
          .setItems(new String[]{"Sucesso","Fracasso","Sucesso parcial...","Personalizado..."},new DialogInterface.OnClickListener(){
              @Override public void onClick(DialogInterface dialog,int which){
                  final String outcome=which==0?"success":which==1?"failure":which==2?"mixed":"custom";
                  if(which<2){submitManualAdjudication(requestId,outcome,"");return;}
                  final EditText notes=new EditText(MainActivity.this);
                  notes.setHint("Descreva o resultado aplicado pelo Mestre");
                  notes.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);
                  new AlertDialog.Builder(MainActivity.this).setTitle("Descrever resultado")
                    .setView(notes).setNegativeButton("Cancelar",null)
                    .setPositiveButton("Confirmar",new DialogInterface.OnClickListener(){
                        @Override public void onClick(DialogInterface d,int button){
                            submitManualAdjudication(requestId,outcome,notes.getText().toString());
                        }
                    }).show();
              }
          }).setNegativeButton("Decidir depois",null).show();
    }

    private void submitManualAdjudication(String requestId,String outcome,String notes){
        try{
            JSONObject selection=new JSONObject().put("request_id",requestId).put("outcome",outcome).put("notes",notes);
            JSONObject result=getAdventureEngine().resolveManualAdjudication(selection);
            if("resolved_manual".equals(result.optString("status"))){
                setStatus("Resultado manual registrado: "+(outcome.equals("success")?"sucesso":outcome.equals("failure")?"fracasso":"especial"));
                JSONObject resolved=result.optJSONObject("resolution");
                if(resolved!=null){
                    String continuity="O jogador já resolveu e confirmou manualmente um teste. "
                        +"ID do recibo: "+resolved.optString("request_id")+". "
                        +"Situação: "+resolved.optString("situation")+". "
                        +"Resultado: "+resolved.optString("outcome")+". "
                        +"Consequência confirmada: "+resolved.optString("narrative_consequence")+". "
                        +"Detalhes informados pelo jogador: "+resolved.optString("notes")+". "
                        +"Continue a narrativa a partir desse resultado já registrado. "
                        +"Não role novamente, não deduza HP, inventário, tempo ou condições que não estejam confirmados.";
                    sendAi("Narrador",continuity);
                }
            }else{
                toast(result.optString("error","Não foi possível registrar resultado manual."));
            }
        }catch(Exception e){AppLog.e("ManualAdjudication","Falha ao registrar resultado",e);toast("Falha ao confirmar resultado manual.");}
    }
    public JSONObject executeOfficialBookRule(String bookId,String actionId,JSONObject input){return masterOrchestrator==null?new JSONObject():masterOrchestrator.executeOfficialBookRule(bookId,actionId,input);}

    private JSONObject decodeCharacterJson(String json)throws Exception{if(json==null||json.trim().length()==0)throw new Exception("O arquivo está vazio.");JSONObject root=new JSONObject(json);String format=root.optString("format");if(format.length()>0&&!"braseiro-character-sheet".equals(format))throw new Exception("Este JSON não é uma ficha individual do Braseiro.");JSONObject sheet=root.optJSONObject("character");if(sheet==null)sheet=root;if(!sheet.has("name")||!sheet.has("class_name"))throw new Exception("A ficha precisa conter name e class_name.");JSONObject clean=new JSONObject(sheet.toString());/* Retain export ID as an untrusted lookup hint; UI confirmation is mandatory. */clean.remove("token_uri");String system=clean.optString("system",root.optString("rules_profile"));if(MystaraRulesEngine.SYSTEM_ID.equals(system)||MystaraRulesEngine.SYSTEM_LABEL.equals(system)){throw new Exception("Ficha Mystara recusada: este projeto é exclusivamente D&D.");}if(!clean.has("species"))throw new Exception("A ficha de D&D precisa conter species.");if(clean.has("personality_profile")){JSONObject pp=clean.optJSONObject("personality_profile");if(pp==null)throw new Exception("personality_profile precisa ser objeto JSON.");clean.put("personality_profile",BraseiroPersonalityProfile.checked(pp));}return DndPtBrLocalizer.localizeCharacterSheet(clean);}

