    private String fieldKeyForLabel(String label){
        String n=label==null?"":label.toLowerCase(new Locale("pt","BR"));if(n.equals("nome"))return "name";if(n.contains("apelido"))return "nickname";if(n.contains("título"))return "title";if(n.contains("conceito"))return "concept";if(n.contains("papel principal"))return "role";if(n.startsWith("aparência"))return "appearance";if(n.startsWith("personalidade"))return "personality";if(n.equals("ideal"))return "ideal";if(n.contains("vínculo"))return "bond";if(n.equals("medo"))return "fear";if(n.contains("defeito"))return "flaw";if(n.equals("contato"))return "contact";if(n.equals("rival"))return "rival";if(n.startsWith("dívida"))return "debt";if(n.equals("motivação"))return "motivation";if(n.contains("entrada na classe"))return "class_entry";if(n.equals("história"))return "history";if(n.contains("maneirismos"))return "mannerisms";if(n.contains("falas"))return "quotes";if(n.contains("subir de nível"))return "level_up";if(n.contains("anotações"))return "extra_notes";if(n.contains("história de vida"))return "life_path";return n.replace(' ','_');
    }

