    private void interpretMythicFieldWithAi(final String fieldLabel,final EditText target,final MythicOracle.Result result,final CharacterFormRefs refs,final String profile,final AlertDialog dialog){
        final String fieldKey=fieldKeyForLabel(fieldLabel);
        final String key=geminiKey().trim();if(key.length()<20){appendOracleReference(refs,fieldLabel,result,"referência salva; interpretação não executada por falta de chave Gemini");toast("Sem chave Gemini: a referência foi salva na auditoria, sem substituir o conteúdo do campo.");dialog.dismiss();return;}
        final JSONObject sheet=collectCharacterSheet(refs,profile);if(aiQuotaGovernor!=null&&!aiQuotaGovernor.canCall()){appendOracleReference(refs,fieldLabel,result,"referência salva; interpretação local sem IA por economia de cota");toast("O resultado Mythic foi preservado sem consumir outra chamada.");dialog.dismiss();return;}setStatus("Interpretando o oráculo Mythic para "+fieldLabel+" em uma chamada...");String system="BRAS_SINGLE_CALL. Você interpreta dois resultados já consultados localmente nas tabelas do Mythic GME 2e. Não alegue que abriu ou leu o PDF nesta chamada. Responda obrigatoriamente em português do Brasil. Baseie a resposta estritamente nos dois termos fornecidos, preserve exatamente espécie, classe, antecedente e regras e não invente bônus mecânicos. Responda somente com o conteúdo do campo solicitado, sem título, citação, JSON ou markdown; o aplicativo acrescentará a referência verificável separadamente.";String fieldConstraint="nickname".equals(fieldKey)?" Para apelido, combine os dois termos em uma alcunha composta natural de 2 a 4 palavras; não devolva apenas o primeiro termo e não reduza a uma única palavra.":"";String prompt="Campo: "+fieldLabel+". Resultados auditáveis: "+mythicOracle.originalLabel(result.tableA)+", d100 "+result.rollA+" = "+result.wordA+"; "+mythicOracle.originalLabel(result.tableB)+", d100 "+result.rollB+" = "+result.wordB+". Interprete esses dois termos numa opção criativa, específica e coerente, somente em PT-BR."+fieldConstraint+" Contexto da ficha: "+sheet.toString();gemini.generateText(key,prefs.getString("text_model","gemini-3.5-flash-lite"),system,prompt,new GeminiService.TextCallback(){public void onSuccess(final String raw){ui.post(new Runnable(){public void run(){if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(system.length()+prompt.length(),raw==null?0:raw.length());String clean=GeneratedTextSanitizer.scalar(raw,fieldKey);if(clean.length()>0){target.setText(characterGenerator.sanitizeSpeciesCoherence(clean,sheet.optString("species")));appendOracleReference(refs,fieldLabel,result,"interpretação da IA aplicada ao campo");}setStatus("Oráculo Mythic interpretado em PT-BR com referência salva.");dialog.dismiss();}});}public void onError(final String error){ui.post(new Runnable(){public void run(){if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(system.length()+prompt.length(),0);appendOracleReference(refs,fieldLabel,result,"referência salva; a IA não respondeu");setStatus("Referência Mythic preservada sem interpretação.");toast("A IA não respondeu; o campo foi mantido e a referência verificável foi salva.");dialog.dismiss();}});}});
    }

    private String mythicReferencePtBr(MythicOracle.Result result){if(result==null)return "Referência do oráculo indisponível";return "FONTE VERIFICÁVEL\n"+mythicOracle.sourceReference(result.tableA)+"\nRolagem: d100 "+result.rollA+" = termo original ‘"+result.wordA+"’\n\n"+mythicOracle.sourceReference(result.tableB)+"\nRolagem: d100 "+result.rollB+" = termo original ‘"+result.wordB+"’";}

    private void appendOracleReference(CharacterFormRefs refs,String fieldLabel,MythicOracle.Result result,String outcome){if(refs==null||refs.oracleReferences==null||result==null)return;String entry="Campo: "+fieldLabel+"\n"+mythicReferencePtBr(result)+(outcome==null||outcome.trim().length()==0?"":"\nAplicação: "+outcome.trim());String current=value(refs.oracleReferences);if(!current.contains(entry))refs.oracleReferences.setText(current.length()==0?entry:current+"\n\n"+entry);refs.oracleReferences.setSelection(refs.oracleReferences.getText().length());}

    private void applyLifeDetailsToForm(CharacterFormRefs f,JSONObject details){if(details==null)return;if(details.optString("contact").length()>0)f.contact.setText(details.optString("contact"));if(details.optString("rival").length()>0)f.rival.setText(details.optString("rival"));if(details.optString("debt").length()>0)f.debt.setText(details.optString("debt"));if(details.optString("motivation").length()>0)f.motivation.setText(details.optString("motivation"));if(details.optString("class_entry").length()>0)f.classEntry.setText(details.optString("class_entry"));}

    private void ensureBundledMythicManualAsync(){
        if(prefs!=null&&prefs.getBoolean("bundled_mythic_manual_suppressed",false))return;
        AppExecutors.io().execute(new Runnable(){public void run(){try{
            File dir=new File(getFilesDir(),"bundled_manuals");if(!dir.exists())dir.mkdirs();File pdf=new File(dir,"Mythic_2e.pdf");
            if(!pdf.exists()||pdf.length()<1000000){InputStream in=getAssets().open("manuals/Mythic 2e.pdf");FileOutputStream out=new FileOutputStream(pdf);byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))>0)out.write(buffer,0,n);in.close();out.close();}
            if(prefs!=null&&prefs.getBoolean("bundled_mythic_manual_suppressed",false))return;
            db.upsertManual("bundled:mythic-2e","Mythic 2e","Ferramenta narrativa / Oráculos","Sistema neutro",true,"application/pdf",pdf.length(),"2.4.1",Uri.fromFile(pdf).toString(),"Incluído no app; tabelas locais com páginas verificáveis; interpretação em PT-BR");
            ui.post(new Runnable(){public void run(){setStatus("Mythic 2e disponível. A indexação só começa quando você solicitar na aba Manuais.");if("Manuais".equals(currentScreen))showManuals(manualVisibleFilter);}});
        }catch(Exception e){AppLog.w("ManualBundled","Não foi possível preparar o PDF integrado.",e);}}});
    }

