    private void performMythicConsult(final EditText rollA,final EditText rollB,final Runnable consult,final ScrollView scroll,final TextView result,boolean reroll){if(reroll){rollA.setText(String.valueOf(mythicOracle.rollD100()));rollB.setText(String.valueOf(mythicOracle.rollD100()));}final int a=Math.max(1,Math.min(100,num(rollA,1))),b=Math.max(1,Math.min(100,num(rollB,1)));rollA.setText(String.valueOf(a));rollB.setText(String.valueOf(b));consult.run();result.setBackground(makeBg(PANEL2,INPUT_STROKE,8));View focused=getCurrentFocus();android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(keyboard!=null&&focused!=null)keyboard.hideSoftInputFromWindow(focused.getWindowToken(),0);result.postDelayed(new Runnable(){public void run(){scroll.smoothScrollTo(0,Math.max(0,result.getTop()-dp(8)));result.announceForAccessibility("Consulta Mythic atualizada para d100 "+a+" e "+b);}},120);toast((reroll?"2d100 rolados automaticamente: ":"Valores digitados consultados: ")+a+" e "+b+". Resultado atualizado abaixo.");}
    private Button button(String label,int color){Button b=new Button(this);b.setText(label);b.setTextColor(themedButtonTextColor(color));b.setTextSize(14);b.setTypeface(isMystaraWorld()?Typeface.SERIF:Typeface.DEFAULT,Typeface.BOLD);if(isMystaraWorld())b.setLetterSpacing(.045f);b.setBackground(makeBg(color,isMystaraWorld()?GOLD:color,isMystaraWorld()?2:9));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(54));lp.setMargins(0,dp(5),0,dp(5));b.setLayoutParams(lp);return b;}
