    private String dateNow(){return new SimpleDateFormat("dd/MM/yyyy HH:mm",new Locale("pt","BR")).format(new Date());}private String formatDate(long t){return new SimpleDateFormat("dd/MM/yyyy HH:mm",new Locale("pt","BR")).format(new Date(t));}
    private String humanSize(long n){if(n<=0)return "tamanho desconhecido";if(n>1024L*1024L)return String.format(Locale.US,"%.1f MB",n/1048576.0);if(n>1024)return String.format(Locale.US,"%.1f KB",n/1024.0);return n+" B";}
    private String displayName(Uri uri){Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null);try{if(c!=null&&c.moveToFirst())return c.getString(0);}finally{if(c!=null)c.close();}return uri.getLastPathSegment()==null?"arquivo.pdf":uri.getLastPathSegment();}
    private long sizeOf(Uri uri){Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.SIZE},null,null,null);try{if(c!=null&&c.moveToFirst())return c.getLong(0);}finally{if(c!=null)c.close();}return 0;}
    private String readAll(InputStream in)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(in,"UTF-8"));StringBuilder b=new StringBuilder();String line;while((line=r.readLine())!=null)b.append(line).append('\n');return b.toString();}
    private String getSigningSha1(){try{PackageInfo pi=getPackageManager().getPackageInfo(getPackageName(),PackageManager.GET_SIGNATURES);Signature[] sigs=pi.signatures;if(sigs==null||sigs.length==0)return "indisponível";MessageDigest md=MessageDigest.getInstance("SHA-1");byte[] d=md.digest(sigs[0].toByteArray());StringBuilder b=new StringBuilder();for(int i=0;i<d.length;i++){if(i>0)b.append(':');b.append(String.format(Locale.US,"%02X",d[i]));}return b.toString();}catch(Exception e){return "indisponível";}}
    private static class DiceResult{final int total,natural,physicsMs;final long physicsSeed;final String detail,critical,rollsJson,physicalFacesJson,renderMode,themeIdentity,mode,integritySignature;DiceResult(int t,String d,String c,int n){this(t,d,c,n,"[]","[]","math",0,0,"","Normal","");}DiceResult(int t,String d,String c,int n,String rolls,String faces,String render,int ms,long seed,String theme,String resolvedMode,String integrity){total=t;detail=d;critical=c;natural=n;rollsJson=rolls==null?"[]":rolls;physicalFacesJson=faces==null?"[]":faces;renderMode=render==null?"math":render;physicsMs=Math.max(0,ms);physicsSeed=seed;themeIdentity=theme==null?"":theme;mode=resolvedMode==null?"Normal":resolvedMode;integritySignature=integrity==null?"":integrity;}}
